.sidebar-brand-text{min-width:0}
.sidebar-brand-name{font-family:var(--display);font-size:20px;font-weight:500;letter-spacing:-.02em;display:block;line-height:1.2;color:var(--t0)}
.sidebar-brand-sub{font-size:9px;font-weight:600;color:var(--t2);letter-spacing:.1em;text-transform:uppercase;display:block;margin-top:3px}

/* Navigation */
.sidebar-nav{flex:1;overflow-y:auto;overflow-x:hidden;padding:0 10px 12px;display:flex;flex-direction:column;gap:3px}
.nav-more-section{margin-top:12px;padding-top:12px;border-top:1px solid var(--border);display:flex;flex-direction:column;gap:3px}

/* Nav Items */
.nav-item{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:var(--radius-s);font-size:13px;font-weight:450;color:var(--t1);text-decoration:none!important;cursor:pointer;border:none;background:none;width:100%;text-align:left;font-family:var(--font);transition:all var(--t);position:relative}
.nav-item:hover{background:var(--hvr);color:var(--t0)}
.nav-item.active{color:var(--accent-strong);font-weight:600;background:var(--accent-bg);border-radius:var(--radius-s)}
.nav-item-sub{padding:7px 12px;font-size:12px}
.nav-icon{width:18px;height:18px;flex-shrink:0;opacity:.45}
.nav-item:hover .nav-icon{opacity:.7}
.nav-item.active .nav-icon{opacity:1;color:var(--accent)}
.nav-item-label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nav-item-footer{margin-bottom:2px}

/* Pinned quick-access group */
.nav-pinned{display:flex;flex-direction:column;gap:1px;margin:6px 0 8px;padding-bottom:8px;border-bottom:1px solid var(--border);border-radius:var(--radius-s);transition:background var(--dur-1) var(--ease-standard),box-shadow var(--dur-1) var(--ease-standard)}
.nav-pinned.drop-active{background:var(--hvr);box-shadow:inset 0 0 0 1.5px var(--bh)}
.nav-pinned-label{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--t3);padding:4px 14px 6px}
.nav-pinned-empty{margin:0 8px 4px;padding:10px 12px;border:1.5px dashed var(--border);border-radius:var(--radius-s);font-size:10.5px;font-weight:500;color:var(--t3);text-align:center;letter-spacing:.02em}
.nav-pinned.drop-active .nav-pinned-empty{border-color:var(--bh);color:var(--t3)}
.nav-item-pinned{font-size:12.5px;padding:8px 14px;cursor:grab}
.nav-item-pinned.dragging{opacity:.4}
.nav-item-pinned.drag-over{border-top:2px solid var(--accent);padding-top:6px}
.nav-item-pin{display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-left:auto;color:var(--accent);opacity:.45;background:none;border:none;cursor:pointer;padding:4px;border-radius:var(--radius-s);transition:all var(--t)}
.nav-item-pin:hover{opacity:1;background:var(--hvr)}
.nav-item-pinned:hover .nav-item-pin{opacity:.8}

/* Alpha badge */
.nav-alpha-badge{font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:1px 5px;border-radius:3px;background:var(--accent-bg);color:var(--accent-strong);margin-left:auto;flex-shrink:0}

/* Admin group in footer */
.nav-admin-group{border-top:1px solid var(--border);padding-top:4px;margin-top:4px}

/* Right-click context menu */
.nav-ctx-menu{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--warm-shadow-lg);padding:4px;min-width:180px;max-width:calc(100vw - 16px);animation:cp-rise var(--dur-2) var(--ease-entrance)}
.nav-ctx-menu button{display:flex;align-items:center;gap:10px;width:100%;padding:8px 12px;background:none;border:none;cursor:pointer;font-family:var(--font);font-size:12px;font-weight:500;color:var(--t0);border-radius:var(--radius-s);transition:background var(--t);text-align:left}
.nav-ctx-menu button:hover{background:var(--hvr)}

/* Collapsible Categories */
.nav-cat{display:flex;flex-direction:column;margin-top:2px}
.nav-cat+.nav-cat{margin-top:4px;padding-top:4px}
.nav-cat-header{display:flex;align-items:center;gap:2px;width:100%}
.nav-cat-toggle{display:flex;align-items:center;justify-content:center;width:32px;height:36px;background:none;border:none;cursor:pointer;color:var(--t2);padding:0;flex-shrink:0;border-radius:var(--radius-s);transition:all var(--t)}
.nav-cat-toggle:hover{background:var(--hvr);color:var(--t0)}
.nav-cat-arr{width:11px;height:11px;transition:transform var(--dur-2) var(--ease-standard)}
.nav-cat-arr.open{transform:rotate(90deg)}
.nav-cat-link{flex:1;display:flex;align-items:center;gap:8px;padding:8px 10px 8px 4px;border-radius:var(--radius-s);font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t1);text-decoration:none!important;transition:all var(--t);min-width:0}
.nav-cat-link:hover{background:var(--hvr);color:var(--t0)}
.nav-cat-link.active{color:var(--accent-strong);background:var(--accent-bg)}
.nav-cat-link .nav-icon{width:16px;height:16px;opacity:.55;flex-shrink:0}
.nav-cat-link.active .nav-icon{opacity:1;stroke:var(--accent)}
.nav-cat-num{font-family:var(--mono);font-size:9px;font-weight:700;color:var(--t3);min-width:12px}
.nav-cat-link.active .nav-cat-num{color:var(--accent-strong)}
.nav-cat-label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1}
.nav-cat.active>.nav-cat-header .nav-cat-toggle{color:var(--accent-strong)}
.nav-cat-body{max-height:0;overflow:hidden;transition:max-height var(--dur-2) var(--ease-standard);display:flex;flex-direction:column;gap:1px;padding-left:24px}
.nav-cat-body.open{max-height:800px;padding-top:2px;padding-bottom:6px}
.nav-cat-body .nav-item{padding:6px 10px;font-size:12px;font-weight:450;border-left:2px solid var(--border);border-radius:0 var(--radius-s) var(--radius-s) 0;position:relative}
.nav-cat-body .nav-item.active{border-left:2px solid var(--accent);background:var(--accent-bg);color:var(--accent-strong)}
[data-theme="light"] .nav-cat-body .nav-item.active{color:var(--accent-strong);background:var(--accent-bg)}
[data-theme="dark"] .nav-cat-body .nav-item.active{color:var(--accent-strong);background:var(--accent-bg)}
.nav-item-num{font-family:var(--mono);font-size:9px;font-weight:600;color:var(--t3);margin-right:6px;min-width:22px}
.nav-cat-body .nav-item.active .nav-item-num{color:var(--accent-strong)}
.nav-icon-sub{width:15px;height:15px;opacity:.5;flex-shrink:0;margin-right:2px}
.nav-item-sub:hover .nav-icon-sub{opacity:.8}
.nav-item-sub.active .nav-icon-sub{opacity:1;color:var(--accent)}

/* Sidebar Footer */
.sidebar-footer{margin-top:auto;padding:8px 10px 14px;border-top:1px solid var(--border);flex-shrink:0;display:flex;flex-direction:column;gap:2px}

/* User Profile */
.sidebar-user{display:flex;align-items:center;gap:6px;padding:10px;border-radius:var(--radius);background:var(--bg-2);border:1px solid var(--border);margin-top:4px}
.sidebar-user-link{display:flex;align-items:center;gap:10px;flex:1;min-width:0;text-decoration:none!important;color:inherit;border-radius:var(--radius-s);transition:opacity var(--t)}
.sidebar-user-link:hover{opacity:.8}
.sidebar-user-avatar{width:34px;height:34px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;background:var(--avatar-grad);color:#fff;font-weight:700;font-size:14px;flex-shrink:0}
.sidebar-user-avatar img{width:100%;height:100%;object-fit:cover}
.sidebar-user-info{flex:1;min-width:0}
.sidebar-user-name{font-size:12px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:1.3}
.sidebar-user-action{background:none;border:none;color:var(--t2);cursor:pointer;padding:8px;border-radius:var(--radius-s);transition:all var(--t);display:flex;align-items:center;justify-content:center;min-width:36px;min-height:36px}
.sidebar-user-action:hover{color:var(--t0);background:var(--bg-3)}
.sidebar-user-action .nav-icon{width:16px;height:16px;opacity:.6}
.sidebar-user-action:hover .nav-icon{opacity:1}
.sidebar-login-btn{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:10px;border-radius:var(--radius-l);font-size:13px;font-weight:600;font-family:var(--font);cursor:pointer;border:1px solid var(--border);background:var(--bg-2);color:var(--t0);transition:all var(--dur-2) var(--ease-standard);text-decoration:none!important;margin-top:8px}
.sidebar-login-btn:hover{background:var(--bg-3);border-color:var(--bh)}

/* ─── Shared Utilities (used by Settings + Sidebar) ─── */
.toggle-row{display:flex;align-items:center;justify-content:space-between;padding:8px 10px}
.toggle-row span{font-size:13px;color:var(--t1)}
.avatar-circle{width:34px;height:34px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;background:var(--accent-bg);color:var(--accent-strong);font-weight:700;font-size:14px;flex-shrink:0}
.avatar-circle img{width:100%;height:100%;object-fit:cover}

/* ─── Main ─── */
.main{flex:1;min-width:0;padding:0 clamp(16px,5vw,64px) 0;width:100%;overflow-y:auto;overflow-x:hidden;scrollbar-gutter:stable;display:flex;flex-direction:column}
.main>*:not(.app-footer){flex-shrink:0}
.app-footer{margin-top:auto}
.sec{max-width:1400px;margin-left:auto;margin-right:auto;width:100%}
.main>*:first-child{padding-top:clamp(20px,4vw,56px)}
.sec-h{margin-bottom:48px;position:relative;padding-left:0;border-left:none}
.sec-h h1{font-family:var(--display);font-size:clamp(32px,5vw,52px);font-weight:500;letter-spacing:-.025em;line-height:1.3;margin-bottom:14px;color:var(--t0);padding-bottom:.1em}
.sec-h h1 em{font-style:italic;font-weight:400;color:var(--t1);padding-right:.06em}
.sec-h p{font-size:15px;color:var(--t1);max-width:640px;line-height:1.65;font-weight:400}
.sec-h-eyebrow{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:10px;font-weight:600;color:var(--t2);text-transform:uppercase;letter-spacing:.14em;margin-bottom:16px}
.sec-h-eyebrow::before{content:'';width:24px;height:1px;background:var(--t3)}
.sub{margin-bottom:48px}

/* ─── Merged Icon + Emoji library — the library switch and its status ─── */
/* The masthead itself is now the shared .dgh-hero (see DiscoverGalleryHero);
   this surface's own header rules — .lib-head, .lib-head-copy, .lib-eyebrow —
   went with it. What is left is genuinely local: the tablist that flips between
   the two libraries, and the connection status.

   THESE COLOURS ARE WRITTEN FOR THE MASTHEAD'S GROUND, NOT THE THEME'S.
   The switch renders inside .dgh-aside, and .dgh-hero is a fixed dark surface
   in BOTH themes — so --bg-2 / --border / --t0..t3 would drop out of contrast
   on it in light mode, exactly as the comment on .dgh-action .btn describes.
   The dot colours are the --ok / --warn values from the dark palette, stated
   literally for the same reason. */
.lib-switch{display:grid;grid-template-columns:1fr;gap:4px;width:100%;padding:4px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:var(--radius-l)}
.lib-switch-btn{appearance:none;display:flex;align-items:center;gap:10px;min-height:56px;padding:9px 13px;border:1px solid transparent;border-radius:var(--radius);background:none;color:rgba(255,255,255,.62);font-family:var(--font);text-align:left;cursor:pointer;transition:color var(--t),background var(--t),border-color var(--t)}
.lib-switch-btn:hover{color:#fff;background:rgba(255,255,255,.07)}
/* The active library is marked by a persistent raised thumb, not by hover —
   on a touch screen there is no hover state to reveal which one you are in. */
.lib-switch-btn.is-active{color:#fff;background:rgba(255,255,255,.13);border-color:rgba(255,255,255,.22)}
.lib-switch-btn:focus-visible{outline:2px solid #fff;outline-offset:2px}
.lib-switch-btn>svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.lib-switch-emoji{font-size:22px;line-height:1}
.lib-switch-btn>span:last-child{display:flex;flex-direction:column;gap:2px;min-width:0}
.lib-switch-btn strong{font-size:var(--fs-body-s);font-weight:700;color:inherit}
.lib-switch-btn small{font-size:var(--fs-micro);color:rgba(255,255,255,.5)}
.lib-switch-btn.is-active small{color:rgba(255,255,255,.66)}
.lib-head-status{display:flex;flex-direction:column;align-items:flex-start;gap:6px;font-family:var(--mono);font-size:var(--fs-micro);color:rgba(255,255,255,.55)}
.lib-net{display:inline-flex;align-items:center;gap:7px}
.lib-net i{width:7px;height:7px;border-radius:50%;background:#facc15;flex:none}
.lib-net.is-online i{background:#4ade80}
/* .48 not lower: at 11px this needs 4.5:1 against the masthead ground, and it
   measures 4.99. It was .38 (3.51) for one commit — the dark hero is a much
   darker ground than the page this text used to sit on. */
.lib-keyhint{color:rgba(255,255,255,.48)}
.lib-loading{display:flex;min-height:280px;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;color:var(--t2)}
.lib-loading strong{font-size:var(--fs-body);color:var(--t0)}
.lib-loading span{font-size:var(--fs-caption)}
/* Below the masthead's own 720px stack point the aside spans the full width,
   so the two libraries sit side by side again; on a phone they stack back. */
@media(max-width:720px){.lib-switch{grid-template-columns:1fr 1fr}.lib-head-status{flex-direction:row;align-items:center;justify-content:space-between;width:100%}}
@media(max-width:480px){.lib-switch{grid-template-columns:1fr}.lib-keyhint{display:none}}

/* ─── Color Studio Nav & Sections ─── */
/* Pill-nav (CS#1/2/2.1): glass panel + absolutely-positioned sliding thumb whose
   x/width are JS-measured from the active button (--cs-thumb-x/--cs-thumb-w set
   imperatively on the thumb ref — never a JSX inline-style attribute). */
.cs-pillnav{position:sticky;top:var(--s-3);z-index:40;display:inline-flex;align-items:center;gap:2px;margin:0 auto var(--s-5);padding:5px;max-width:fit-content;border-radius:var(--radius-pill);background:color-mix(in srgb,var(--bg-1) 72%,transparent);border:1px solid var(--border);box-shadow:var(--shadow-m),var(--ring);-webkit-backdrop-filter:blur(16px) saturate(1.4);backdrop-filter:blur(16px) saturate(1.4);isolation:isolate}
.cs-pillnav-item{position:relative;z-index:1;padding:8px 16px;min-height:36px;border:none;background:none;cursor:pointer;font-family:var(--font);font-size:13px;font-weight:600;letter-spacing:-.01em;white-space:nowrap;color:var(--t2);transition:color var(--dur-2) var(--ease-standard)}
.cs-pillnav-item:hover{color:var(--t0)}
.cs-pillnav-item:active{transform:translateY(.5px)}
.cs-pillnav-item.active{color:var(--accent-fg);font-weight:700}
/* No radius hoisted to rest for this one: #348 left the block with no JSX
   consumer, so there is no rendered shape to preserve and a new rule here
   would be dead CSS added on top of dead CSS. The geometry override is just
   dropped. */
.cs-pillnav-item:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
