/* transform stays at --dur-1: it is :active-only press feedback, not a hover lift. */
.cs-pb-tool{width:24px;height:24px;display:grid;place-items:center;border:none;border-radius:50%;cursor:pointer;color:#fff;background:color-mix(in srgb,#000 42%,transparent);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);transition:background var(--dur-1) var(--ease-standard),transform var(--dur-1) var(--ease-standard)}
