.cs-pb-tool--drag{cursor:grab}

/* Gap-insert ×1–3 (CS#3.5) */
.cs-pb-gap{position:relative;flex:0 0 var(--s-2);align-self:stretch;display:grid;place-items:center;cursor:pointer}
.cs-pb-gap-btn{width:26px;height:26px;border-radius:50%;background:var(--accent-strong);color:var(--accent-fg);border:2px solid var(--bg-0);display:grid;place-items:center;opacity:0;transform:scale(.6);transition:opacity var(--dur-1) var(--ease-standard),transform var(--dur-2) var(--ease-spring);box-shadow:var(--shadow-s)}
