.cs-pb-adjust{display:grid;grid-template-columns:repeat(4,1fr);gap:var(--s-4);padding:var(--s-4) var(--s-5);background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);box-shadow:var(--warm-shadow);margin-bottom:var(--s-3)}
