.cs-pro-lock{position:relative}
.cs-pro-lock-glyph{margin-left:6px;color:var(--accent);flex-shrink:0;vertical-align:-1px}

@keyframes cs-shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}

/* State preset label: full name on desktop, abbreviation on mobile */
.state-preset-short{display:none}
@media(max-width:640px){.state-preset-full{display:none}.state-preset-short{display:inline}}
.cs-chevron{color:var(--t2);transition:transform var(--dur-2) var(--ease-standard);flex-shrink:0}

/* (The old .cs-add-menu dropdown + Pick-Colour/Extract overlay CSS was removed
   in Slice 3 — replaced by the Colour System popup, .cs-csys-* below.) */
.cs-chevron.open{transform:rotate(90deg)}
.cs-tint-strip>div{transition:transform var(--dur-3) var(--ease-out),opacity var(--dur-3) var(--ease-standard)}
.cs-next-step{padding:48px 0 16px;display:flex;justify-content:center}
.cs-next-link{display:inline-flex;align-items:center;gap:12px;padding:14px 28px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-2);color:var(--t0);text-decoration:none!important;transition:all var(--t)}
