.cs-next-link strong{font-size:15px;font-weight:700;letter-spacing:-.01em}
.cs-next-link svg{color:var(--brand);flex-shrink:0}
/* More colour tools — cross-link footer at the bottom of every colour tool */
.cs-tools-footer{margin-top:56px;padding-top:32px;border-top:1px solid var(--border)}
.cs-tools-footer-title{font-size:13px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);margin:0 0 6px}
/* The sequencing line inherited from the removed `.stc-next` block. It is the
   reason this footer is a workflow step and not just a list of siblings. */
.cs-tools-footer-lead{max-width:620px;margin:0 0 18px;font-size:14px;line-height:1.6;color:var(--t1)}
.cs-tools-footer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.cs-tools-footer-link{display:flex;flex-direction:column;gap:2px;text-align:left;padding:14px 16px;border-radius:var(--radius);border:1px solid var(--border);background:var(--bg-2);color:var(--t0);cursor:pointer;text-decoration:none;transition:all var(--t)}
.cs-tools-footer-link:hover{border-color:var(--brand);background:var(--brand-bg)}
