.sub h2{font-family:var(--display);font-size:24px;font-weight:500;letter-spacing:-.018em;margin-bottom:6px;color:var(--t0)}
.sub-meta{font-size:13px;color:var(--t2);margin-bottom:18px;line-height:1.6;max-width:560px}

/* ─── Cards ─── */
.card{background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);padding:28px;box-shadow:var(--warm-shadow),var(--ring);transition:all var(--dur-2) var(--ease-out);position:relative;overflow:hidden}
.card:hover{border-color:var(--bh)}
.card-i{background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius);padding:22px;transition:all var(--dur-2) var(--ease-out);box-shadow:var(--warm-shadow);position:relative;overflow:hidden}
.card-i:hover{border-color:var(--bh)}
