.tool-mini-pin:hover,.tool-mini-pin.pinned{opacity:1;color:var(--accent)}

/* ─── Section label ─── */
.sl{font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--t1);margin-bottom:12px;display:flex;align-items:center;gap:8px}
