:where(input[type="color"]):hover{border-color:var(--bh)}
/* Strip the native swatch chrome so the colour well reads as one clean, rounded
   chip on every picker in the app (Colour Studio, Box-Shadow, UI Builder, …), not
   just the icon editor — a single, consistent colour control everywhere. */
:where(input[type="color"])::-webkit-color-swatch-wrapper{padding:0}
:where(input[type="color"])::-webkit-color-swatch{border:none;border-radius:var(--radius-xs)}
:where(input[type="color"])::-moz-color-swatch{border:none;border-radius:var(--radius-xs)}
:where(input[type="range"]){-webkit-appearance:none;width:100%;height:32px;border-radius:2px;background:transparent;outline:none;cursor:pointer;padding:0;border:none}
:where(input[type="range"])::-webkit-slider-runnable-track{height:4px;border-radius:2px;background:var(--bg-4)}
:where(input[type="range"])::-moz-range-track{height:4px;border-radius:2px;background:var(--bg-4)}
:where(input[type="range"])::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;border-radius:50%;background:#fff;border:3px solid var(--accent);cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.15);margin-top:-8px;position:relative;z-index:2}
:where(input[type="range"])::-moz-range-thumb{width:20px;height:20px;border-radius:50%;background:#fff;border:3px solid var(--accent);cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.15)}
.seg-label{font-size:8.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--t2);margin-bottom:6px}

/* ─── Code ─── */
.code{background:var(--cbg);border:1px solid var(--border);border-radius:var(--radius);padding:16px;font-family:var(--mono);font-size:12px;line-height:1.7;color:var(--t0);overflow-x:auto;white-space:pre;cursor:pointer}
.code:hover{border-color:var(--bh)}

/* ─── Toggle pills ─── */
.pt-t{display:inline-flex;align-items:center;padding:9px 14px;border-radius:var(--radius-s);font-size:11px;border:1px solid var(--border);color:var(--t2);cursor:pointer;transition:all var(--t);font-weight:500;background:none;font-family:var(--font);min-height:36px}
.pt-t:hover{background:var(--bg-2);color:var(--t0)}
.pt-t.on{background:var(--accent-bg);border-color:var(--accent);color:var(--accent-strong);font-weight:600}

/* ─── Custom semantic-hue slider (ColorStudio States) ─── */
.cs-hue{display:flex;flex-direction:column;gap:8px;margin-top:10px;padding:12px 14px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1)}
.cs-hue-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.cs-hue-name{font-size:11px;font-weight:600;color:var(--t1)}
.cs-hue-val{font-family:var(--mono);font-size:10px;color:var(--t3)}
/* `input.` prefix: must outrank the global input[type="range"] reset above */
input.cs-hue-slider{-webkit-appearance:none;appearance:none;width:100%;height:14px;border-radius:var(--radius-pill);background:var(--arc-grad,var(--bg-3));outline:none;cursor:pointer;border:1px solid var(--border)}
input.cs-hue-slider::-webkit-slider-runnable-track{height:12px;border-radius:var(--radius-pill);background:transparent}
input.cs-hue-slider::-moz-range-track{height:12px;border-radius:var(--radius-pill);background:transparent}
input.cs-hue-slider::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:18px;height:18px;margin-top:-3px;border-radius:50%;background:#fff;border:2px solid var(--t0);box-shadow:var(--shadow-xs)}
input.cs-hue-slider::-moz-range-thumb{width:16px;height:16px;border-radius:50%;background:#fff;border:2px solid var(--t0);box-shadow:var(--shadow-xs)}
input.cs-hue-slider:focus-visible{box-shadow:0 0 0 3px var(--accent-bg)}
.cs-hue-ends{display:flex;justify-content:space-between;font-size:9px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--t3)}
.cs-hue-hex{width:96px;padding:5px 8px;border:1px solid var(--border);border-radius:var(--radius-xs);background:var(--bg-0);color:var(--t0);font-family:var(--mono);font-size:11px;text-transform:uppercase}
.cs-hue-hex::placeholder{color:var(--t3);text-transform:none;letter-spacing:0}
.cs-hue-hex:focus-visible{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}

/* ─── UI State Colours section (ColorStudio States) ─── */
/* ── The solo Semantic Colours tool header ──────────────────────────────────
   The four colour tools shipped TWO hero languages. `.tt-hero` (Tint) and
   `.ggn-head` (Gradient) both open with an eyebrow, a large serif title, a
   description and the tool's own actions, then a status strip of four live
   facts. Semantic Colours and the Contrast Checker were on `.sec-h`, the
   site-wide section header, which carries none of that.

   These metrics are taken from `.tt-hero` rather than invented: the same
   clamp() on the title, the same eyebrow treatment, the same status row as
   `.ggn-status`. `.sec-h` is deliberately NOT touched - it is site-wide. */
.stc-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--s-6);flex-wrap:wrap;margin-bottom:var(--s-5)}
.stc-hero-id{max-width:680px;min-width:0}
.stc-hero-eyebrow{display:inline-flex;align-items:center;gap:8px;margin-bottom:14px;font-family:var(--mono);font-size:10px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--t2)}
.stc-hero-eyebrow::before{content:'';width:24px;height:1px;background:var(--t3)}
.stc-hero h1{margin:0;font-family:var(--display);font-size:clamp(38px,5vw,64px);font-weight:500;line-height:1.04;letter-spacing:-.035em;color:var(--t0)}
.stc-hero-id>p{max-width:600px;margin:12px 0 0;font-size:15px;line-height:1.65;color:var(--t1)}
.stc-hero-actions{display:flex;align-items:center;gap:10px;flex-shrink:0}
/* The action is already a button with its own metrics; the hero must not also
   push it right with `margin-left:auto`, which is what `.stc-copy-btn` does for
   the section-header context it was written for. */
.stc-hero-actions .stc-copy-btn{margin-left:0}

/* Four live facts about what the tool currently holds - the same row the
   Gradient Generator carries as `.ggn-status`. It is `aria-live=polite` in the
   markup: changing bundle changes the first cell, and that is worth announcing
   once rather than on every swatch hover. */
.stc-status{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:var(--s-6);border-block:1px solid var(--border)}
.stc-status span{display:flex;align-items:baseline;gap:6px;min-width:0;padding:12px 16px;font-size:11px;color:var(--t2)}
.stc-status span+span{border-left:1px solid var(--border)}
.stc-status strong{font-family:var(--mono);font-size:12px;color:var(--t0);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.stc-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;cursor:pointer}
.stc-head.solo{cursor:default}
.stc-head-title{display:flex;align-items:center;gap:12px}
.stc-toolbar{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-left:auto}
.stc-head.solo .stc-toolbar{margin-left:0;width:100%}
.stc-kicker{font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.stc-copy-btn{margin-left:auto;padding:7px 14px;border:none;border-radius:var(--radius-s);background:var(--t0);color:var(--bg-0);font-family:var(--font);font-size:11px;font-weight:700;cursor:pointer;transition:opacity var(--t)}
.stc-copy-btn:hover{opacity:.85}
.stc-copy-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.stc-role{margin-bottom:22px}
.stc-role-head{display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap}
.stc-dot{width:10px;height:10px;border-radius:3px;flex:none}
.stc-role-name{font-size:13px;font-weight:700;text-transform:capitalize}
.stc-role-presets{display:flex;gap:4px;margin-left:auto;flex-wrap:wrap;justify-content:flex-end}
.stc-role-presets .pt-t{padding:4px 10px;font-size:10px;min-height:0}
.stc-ramp{display:flex;border-radius:var(--radius-s);overflow:hidden;border:1px solid var(--border)}
.stc-cell{flex:1;min-height:64px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;cursor:pointer;transition:filter var(--dur-1) var(--ease-standard);min-width:0}
.stc-cell:hover{filter:brightness(1.06)}
.stc-cell:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.stc-cell-tone{font-size:11px;font-weight:700;font-family:var(--mono)}
.stc-cell-hex{font-size:9px;font-family:var(--mono);opacity:.75}
.stc-hue{margin:0 0 10px}
.stc-hue-row{display:flex;align-items:center;gap:12px}
.stc-hue-row .cs-hue-slider{flex:1;width:auto}
.stc-hue-val{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--t1);min-width:34px;text-align:right}
@media(max-width:640px){.stc-cell{min-height:52px}}

/* Semantic colour workbench */
.stc-head.solo{padding-bottom:var(--s-5);border-bottom:1px solid var(--border)}
.stc-head.solo .stc-toolbar{align-items:center}
.stc-toolbar-copy{display:flex;min-width:0;flex-direction:column;gap:3px}
.stc-toolbar-copy>span:last-child{font-size:11px;color:var(--t2)}
.stc-bundles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:0 0 var(--s-6)}
/* THE TRAY LISTS EVENLY (founder, 2026-08-08: "so the premade packs list
   evenly"). Measured before it was touched: seven cards is a PRIME number, so
   it was ragged at every width the suite checks - rows of 4,3 at 1280 and
   2,2,2,1 at 390/640/834. No column count fixes that; only the cell count does.
   The extra cell goes to the FIRST card rather than to an invented eighth pack,
   because the first card is Balanced - the default, selected on load, and the
   one whose description ("Familiar, calm defaults for most product UI") is the
   start-here advice. 7 cards + a 2-cell lead = 8 cells, which fills a 4-column
   grid in exactly 2 rows and a 2-column grid in exactly 4. The emphasis is
   TRUE - it marks the recommended option - which a stretched last card or a
   filler eighth pack would not be. Weighting one card deliberately rather than
   forcing a uniform row is the same call #340 took from Tines on the Discover
   grid. IF AN 8TH PACK IS EVER ADDED the arithmetic changes: 9 cells leaves one
   over at 4 columns, so drop this rule rather than adding a 9th. */
.stc-bundle:first-child{grid-column:span 2}
.stc-bundle{display:flex;min-width:0;min-height:128px;flex-direction:column;gap:10px;padding:14px;text-align:left;color:var(--t1);background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;transition:border-color var(--t),background var(--t),color var(--t),box-shadow var(--t)}
.stc-bundle:hover{color:var(--t0);border-color:var(--bh);background:var(--hvr)}
.stc-bundle--on{color:var(--t0);border-color:color-mix(in srgb,var(--accent) 45%,var(--border));background:var(--accent-bg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent) 16%,transparent)}
.stc-bundle:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.stc-bundle-top{display:flex;align-items:center;justify-content:space-between;gap:8px}
.stc-bundle-top strong{font-size:12px;font-weight:650}
.stc-bundle-top>span{font-family:var(--mono);font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t3)}
.stc-bundle--on .stc-bundle-top>span{color:var(--accent-strong)}
.stc-bundle-swatches{display:flex;height:12px;overflow:hidden;border:1px solid color-mix(in srgb,var(--t0) 10%,transparent);border-radius:var(--radius-xs)}
.stc-bundle-swatches i{flex:1;background:var(--stc-bundle-c)}
.stc-bundle small{font-size:10.5px;line-height:1.45;color:var(--t2)}
.stc-role{margin-bottom:0;padding:var(--s-5);background:var(--card);border:1px solid var(--border);border-radius:var(--radius-l)}
.stc-role+.stc-role{margin-top:12px}
.stc-role-head{align-items:flex-start;margin-bottom:14px}
.stc-role-id{display:flex;align-items:center;gap:10px;min-width:210px}
.stc-role-id>span:last-child{display:flex;flex-direction:column;gap:3px}
.stc-role-id small{font-size:10px;color:var(--t2)}
.stc-role-cue{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;flex:0 0 auto;font-family:var(--mono);font-size:14px;font-weight:750;color:var(--t0);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-xs)}
.stc-role-name{font-size:13px;font-weight:700;text-transform:none}
.stc-ramp{overflow-x:auto;scrollbar-width:thin}
.stc-cell{flex:1 0 64px}
.stc-preview-section{margin-top:var(--s-8);padding-top:var(--s-6);border-top:1px solid var(--border)}
.stc-subhead{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--s-5);margin-bottom:var(--s-5)}
.stc-subhead h2,.stc-handoff h2{margin:5px 0 5px;font-size:22px;font-weight:650;letter-spacing:-.025em;color:var(--t0)}
.stc-subhead p,.stc-handoff p{max-width:650px;margin:0;font-size:12px;line-height:1.55;color:var(--t2)}
.stc-preview-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));overflow:hidden;border:1px solid var(--border);border-radius:var(--radius-l)}
.stc-preview{padding:var(--s-5);color:#172033;background:#f7f8fa}
.stc-preview+.stc-preview{border-left:1px solid var(--border)}
.stc-preview--dark{color:#f3f5f7;background:#111318}
.stc-preview-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid color-mix(in srgb,currentColor 14%,transparent)}
.stc-preview-head strong{font-size:12px}
.stc-preview-head span{font-size:9px;letter-spacing:.04em;text-transform:uppercase;opacity:.6}
/* ── SEMANTIC USAGE EXAMPLES (.stc-sc-*) ──────────────────────────────────
   Replaces .stc-example, which was five identical captioned circles. Every
   colour below resolves from the six --stc-* custom properties set per scene in
   ColorStudio.jsx from the user's own ramp; there is not one fixed sample hex in
   this block, so the demo cannot drift from the pack it claims to show.

   The panels are FIXED light (#f7f8fa) and dark (#111318) grounds on purpose -
   they are a picture of two interfaces, not of this page - so both are painted
   here regardless of the app theme, and both were contrast-measured. Type is
   var(--font) only: --display in this project resolves to Manrope, the same face
   and is filed as [serif-token-is-not-a-serif]. */
.stc-scene-list{display:flex;flex-direction:column;gap:10px}
.stc-scene{min-width:0}
.stc-scene-ico{flex:0 0 auto}
.stc-scene-ico--spin{animation:stc-sc-spin 1.1s linear infinite;transform-origin:50% 50%}
@keyframes stc-sc-spin{to{transform:rotate(360deg)}}

/* Shared row shell: icon / two-line lead / trailing control. */
.stc-sc-row,.stc-sc-alert{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;padding:11px 12px;border-radius:var(--radius-s);border:1px solid var(--stc-border);background:var(--stc-soft);color:var(--stc-ink)}
.stc-sc-row{grid-template-columns:minmax(0,1fr) auto}
.stc-sc-row:has(.stc-sc-act-ico){grid-template-columns:auto minmax(0,1fr) auto}
.stc-sc-lead{display:flex;min-width:0;flex-direction:column;gap:2px}
.stc-sc-lead strong{font-size:11.5px;font-weight:650;line-height:1.25}
.stc-sc-lead small{font-size:9.5px;line-height:1.35;opacity:.78}

/* SUCCESS - a switch. The track is the 600 so the control reads as filled. */
.stc-sc-switch{position:relative;display:inline-flex;flex:0 0 auto;width:34px;height:20px;padding:2px;border-radius:999px;background:color-mix(in srgb,var(--stc-ink) 22%,transparent)}
.stc-sc-switch--on{background:var(--stc-solid);justify-content:flex-end}
.stc-sc-switch i{width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.3)}

/* WARNING - an advisory field. The border carries it and the action stays live. */
.stc-sc-field{display:flex;flex-direction:column;gap:5px;padding:11px 12px;border-radius:var(--radius-s);border:1px solid var(--stc-border);background:var(--stc-soft);color:var(--stc-ink)}
.stc-sc-label{font-size:9.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;opacity:.72}
.stc-sc-input{width:100%;padding:7px 9px;font-family:var(--mono);font-size:11px;color:var(--stc-ink);background:#fff;border:1.5px solid var(--stc-strong);border-radius:var(--radius-xs);pointer-events:none}
.stc-sc-help{display:flex;align-items:center;gap:6px;font-size:10px;line-height:1.3;color:var(--stc-ink)}
.stc-sc-ghost{margin-left:auto;padding:3px 8px;font-family:var(--font);font-size:9.5px;font-weight:650;color:var(--stc-ink);background:transparent;border:1px solid var(--stc-strong);border-radius:var(--radius-xs);cursor:default}

/* ERROR - the alert, and the only solid fill in the set. */
.stc-sc-alert-ico{display:inline-flex;color:var(--stc-strong)}
.stc-sc-solid{flex:0 0 auto;padding:6px 11px;font-family:var(--font);font-size:10px;font-weight:700;color:#fff;background:var(--stc-solid);border:1px solid var(--stc-solid);border-radius:var(--radius-xs);cursor:default;white-space:nowrap}

/* INFO - the quietest object here, deliberately. No fill, a hairline only. */
.stc-sc-note{display:flex;align-items:center;gap:8px;padding:10px 12px;font-size:10.5px;line-height:1.4;border-radius:var(--radius-s);border:1px solid var(--stc-border);background:transparent;color:var(--stc-onpanel)}
.stc-sc-note .stc-scene-ico{color:var(--stc-onpanel)}
.stc-sc-link{margin-left:auto;padding:0;font-family:var(--font);font-size:10px;font-weight:700;color:var(--stc-onpanel);background:none;border:0;text-decoration:underline;text-underline-offset:2px;cursor:default;white-space:nowrap}

/* PENDING - an activity row with a turning icon and a status badge. */
.stc-sc-act-ico{display:inline-flex;color:var(--stc-strong)}
.stc-sc-badge{flex:0 0 auto;padding:3px 9px;font-family:var(--font);font-size:9.5px;font-weight:700;color:var(--stc-ink);background:var(--stc-tint);border:1px solid var(--stc-border);border-radius:999px;white-space:nowrap}

/* THE DARK PANEL. Not a filter over the light one: a dark interface inverts
   which end of the ramp does which job. The fill becomes a deep mix of the 800
   with the panel ground, the ink becomes the 50, and anything that was the 600
   moves to the 400 - the 600 is a mid-tone that was chosen to sit on white and
   loses separation against #111318. Measured, not assumed. */
.stc-preview--dark .stc-sc-row,
.stc-preview--dark .stc-sc-alert,
.stc-preview--dark .stc-sc-field{color:var(--stc-inkd);background:color-mix(in srgb,var(--stc-strong) 15%,#111318);border-color:color-mix(in srgb,var(--stc-liftd) 38%,#111318)}
.stc-preview--dark .stc-sc-help,
.stc-preview--dark .stc-sc-label{color:var(--stc-inkd)}
.stc-preview--dark .stc-sc-note{color:var(--stc-onpaneld);border-color:color-mix(in srgb,var(--stc-liftd) 38%,#111318)}
.stc-preview--dark .stc-sc-note .stc-scene-ico{color:var(--stc-onpaneld)}
.stc-preview--dark .stc-sc-act-ico,
.stc-preview--dark .stc-sc-alert-ico{color:var(--stc-liftd)}
.stc-preview--dark .stc-sc-link{color:var(--stc-onpaneld)}
.stc-preview--dark .stc-sc-input{color:var(--stc-inkd);background:color-mix(in srgb,var(--stc-strong) 10%,#111318);border-color:var(--stc-liftd)}
.stc-preview--dark .stc-sc-ghost{color:var(--stc-inkd);border-color:var(--stc-liftd)}
.stc-preview--dark .stc-sc-badge{color:var(--stc-inkd);background:color-mix(in srgb,var(--stc-strong) 26%,#111318);border-color:color-mix(in srgb,var(--stc-liftd) 45%,#111318)}
.stc-preview--dark .stc-sc-switch{background:color-mix(in srgb,var(--stc-inkd) 22%,transparent)}
.stc-preview--dark .stc-sc-switch--on{background:var(--stc-solidd)}
.stc-preview--dark .stc-sc-switch i{background:#111318}
.stc-preview--dark .stc-sc-solid{color:#111318;background:var(--stc-solidd);border-color:var(--stc-solidd)}
.stc-handoff{display:grid;grid-template-columns:minmax(260px,.75fr) minmax(0,1.25fr);gap:var(--s-6);align-items:start;margin-top:var(--s-5);padding:var(--s-6);background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-l)}
.stc-handoff-copy{display:flex;align-items:flex-start;flex-direction:column}
.stc-handoff p code{font-family:var(--mono);font-size:10px;color:var(--t1)}
.stc-handoff .stc-copy-btn{margin:var(--s-5) 0 0}
.stc-code{max-height:360px;margin:0;padding:16px;font-family:var(--mono);font-size:10px;line-height:1.65;color:var(--t1);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);overflow:auto}
.stc-code:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
/* `.stc-next` retired (#323): its nav offered contrast, tint and palette, a
   strict subset of the `.cs-tools-footer` block ~200px below it. The
   sequencing sentence it carried moved to `.cs-tools-footer-lead`. */
@media(max-width:980px){
  .stc-bundles{grid-template-columns:repeat(2,minmax(0,1fr))}
  .stc-handoff{grid-template-columns:1fr}
}
@media(max-width:768px){
  /* S1: the ten tone cells WRAP instead of scrolling off the side. As a single
     row they were `flex:1 0 64px`, and that 0 flex-shrink pinned a 640px floor
     under a container measured at 252px on a 320px phone - 3 of 10 cells
     visible, 28 of 40 tones across the four ramps unreachable without
     discovering a swipe there was no cue for. There was no cue: overlay
     scrollbars render nothing under touch, and .stc-ramp's border-radius draws
     the right edge ROUNDED AND CLOSED, so the control actively signalled "this
     is the end of the scale" while the toolbar said "40 canonical tokens".
     Five columns, two rows, every tone on screen and none below 24px.
     overflow stays `hidden` rather than becoming `visible`: this element also
     sets overflow-y, and `visible` on one axis beside a clipping value on the
     other computes to `auto` - which would leave the scroller behind, i.e. the
     defect, while looking like the fix. See css-conventions.md. */
  .stc-ramp{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));overflow:hidden}
  .stc-cell{flex:none;min-width:0}
  .stc-preview-grid{grid-template-columns:1fr}
  .stc-preview+.stc-preview{border-left:0;border-top:1px solid var(--border)}
}
@media(max-width:560px){
  .stc-head.solo .stc-toolbar{align-items:flex-start;flex-direction:column}
  .stc-copy-btn{width:100%;margin-left:0}
  /* S2: the bundle picker keeps the two-column grid it already uses at
     561-980px instead of becoming a seven-wide scroller. As a scroller it
     measured scrollWidth 1518 against clientWidth 288 on a 320px phone: ONE of
     seven presets fully visible, 79% of the control off-screen, and the seventh
     bundle 1160px away. Choosing a starting bundle is the first decision this
     page asks for, so six of the seven options being undiscoverable is the
     whole task failing, not a rough edge. scroll-snap was present, so the
     scroller was intended - what was never there is any indication that it
     scrolls. Wrapping needs no indication.
     Deliberately NOT replaced with a scroll cue: seven cards wrap into four
     rows on the narrowest phone, which costs height on a page that already
     scrolls vertically, and buys every option being seen without a gesture. */
  .stc-bundles{grid-template-columns:repeat(2,minmax(0,1fr))}
  .stc-bundle{min-height:0}
  /* Four facts in four columns is ~80px each on a phone, which truncates the
     bundle name - the one cell whose value is a word rather than a number. */
  .stc-status{grid-template-columns:repeat(2,minmax(0,1fr))}
  .stc-status span:nth-child(-n+2){border-bottom:1px solid var(--border)}
  .stc-status span:nth-child(odd){border-left:0}
  .stc-role{padding:16px}
  /* Wraps, like .stc-bundles above and for the same reason (S3,
     mobile-audit-2026-08). The base rule at the top of this section already
     says flex-wrap:wrap; this override used to replace it with
     nowrap + overflow-x:auto, which turned each role's 7 preset chips into a
     scroller with no affordance. Measured at 320px: 11 chips across the four
     role rows sat outside their box, the worst row showing 4 of 7, and "Custom"
     — the last chip, and the only one that opens the free-choice path — was
     always one of the hidden ones. Wrapping costs a row of height per role and
     needs no gesture to discover. */
  .stc-role-presets{width:100%;margin-left:0;justify-content:flex-start}
  .stc-preview{padding:16px}
  /* Narrow: the trailing control drops under the lead rather than squeezing
     it. The switch and the badge stay on the row - they are small and they are
     the state, so putting them on a second line would separate the state from
     the thing it describes. */
  .stc-sc-alert{grid-template-columns:auto minmax(0,1fr)}
  .stc-sc-solid{grid-column:2;justify-self:start}
  .stc-sc-note{flex-wrap:wrap}
  .stc-sc-link{margin-left:0}
  .stc-handoff{padding:16px}
}

/* ─── Harmony radio ─── */
.harm-opt{display:flex;align-items:center;padding:11px 14px;border-radius:var(--radius-s);border:1px solid var(--border);color:var(--t2);font-size:13px;cursor:pointer;width:100%;font-family:var(--font);transition:all var(--t);background:none}
.harm-opt:hover{background:var(--bg-2);color:var(--t0)}
.harm-opt.on{background:var(--accent-bg);border-color:var(--accent);color:var(--accent-strong);font-weight:600;border-left:3px solid var(--accent)}

/* ─── Palette swatches ─── */
.pal-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(130px,100%),1fr));gap:8px}
.pal-swatch{min-height:180px;border-radius:var(--radius);padding:18px;display:flex;flex-direction:column;justify-content:flex-end;cursor:pointer;transition:transform var(--dur-2) var(--ease-standard)}
.pal-swatch:hover{transform:translateY(-2px)}
.pal-swatch .role{font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;opacity:.65;margin-bottom:3px}
.pal-swatch .hex{font-family:var(--mono);font-size:13px;font-weight:600}

/* ─── Tint swatches ─── */
.tint-swatch{aspect-ratio:1;border-radius:var(--radius-s);display:flex;align-items:flex-end;justify-content:center;padding-bottom:10px;cursor:pointer;transition:transform var(--dur-2) var(--ease-standard)}
.tint-swatch:hover{transform:scale(1.05)}
.tint-swatch .stop-label{font-size:11px;font-family:var(--mono);font-weight:700}
.tint-info{text-align:center;margin-top:6px}
.tint-info .hex{font-family:var(--mono);font-size:10px;color:var(--t1)}
.tint-info .lval{font-family:var(--mono);font-size:9px;color:var(--t2)}
.tint-base-tag{font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent-strong)}

/* ─── Contrast ─── */
.cr-val{font-size:clamp(24px,4vw,36px);font-weight:700;font-family:var(--mono);letter-spacing:-.02em}
.comp-row{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;background:var(--bg-2);border-radius:var(--radius-s);margin-bottom:6px;flex-wrap:wrap;gap:8px}
.comp-row .label{font-size:13px;font-weight:700}
.comp-row .sublabel{font-size:10px;color:var(--t2)}
.suggest-bar{display:flex;flex-wrap:wrap;align-items:center;gap:16px;padding:18px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);margin-top:16px}
.suggest-sw{width:36px;height:36px;border-radius:var(--radius-s);cursor:pointer;border:2px solid transparent;transition:all var(--dur-2) var(--ease-standard)}
.suggest-sw:hover{border-color:var(--accent);transform:scale(1.1)}

/* ─── Gradient ─── */
.grad-big{height:clamp(80px,12vw,160px);border-radius:var(--radius);border:1px solid var(--border);margin-bottom:20px;position:relative;overflow:hidden}
.grad-tags{position:absolute;top:10px;left:10px;display:flex;gap:5px}
.grad-tag{padding:4px 12px;border-radius:var(--radius-s);font-size:9px;font-weight:700;background:rgba(0,0,0,.35);color:#fff;letter-spacing:.04em;text-transform:uppercase}
.grad-presets{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
.grad-p{display:flex;flex-direction:column;border-radius:var(--radius);overflow:hidden;border:1px solid var(--border);cursor:pointer;transition:all var(--t)}
.grad-p:hover{border-color:var(--accent);box-shadow:var(--warm-shadow)}
.grad-p-preview{height:80px}
.grad-p-info{padding:10px 12px;background:var(--card)}

/* ─── Icons ─── */
/* 112px, not 88. The old value gave the SAME ~85px cell at tablet and phone, so
   tablet's extra 444px of width bought eight columns of illegible labels rather
   than a readable grid. A wider cell is what makes a two-line 11px name fit;
   below ~336px `calc(100%/3)` still takes over and holds three columns. */
.ig{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(112px,calc(100%/3)),1fr));gap:4px}
.ic{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:16px 6px 12px;border-radius:var(--radius-s);cursor:pointer;border:1px solid transparent;min-height:80px;min-width:0;overflow:hidden;transition:all var(--t)}
.ic:hover{background:var(--bg-2);border-color:var(--border)}
.ic:active{transform:scale(.95)}
.ic svg,.ic img{width:24px;height:24px;flex-shrink:0}
.ic svg{stroke:var(--t0);fill:none;stroke-width:1.75;stroke-linecap:round;stroke-linejoin:round}
/* Long icon names must stay inside the cell — otherwise they paint past the
   hover background and look clipped against neighbouring cells. */
/* THE LABEL EXISTS TO TELL TWO NEIGHBOURING ICONS APART. It was 8.5px dropping
   to 8px below 480, single-line with an ellipsis, in a cell that is ~85px at
   BOTH tablet and phone (`minmax(min(88px,calc(100%/3)),1fr)` gives 8 columns
   at 834 and 4 at 390 — the same cell either way). At 834px that produced six
   consecutive cells all reading "align-horizonta…", which is a label that has
   stopped doing the only job it has.
   Two lines at 11px rather than one at 8: the fix is not more characters, it is
   the DISCRIMINATING characters. "align-horizontal-" / "distribute-cen…" tells
   you which of the six you are looking at; "align-horizonta…" does not. 11px is
   also the floor the rest of this stylesheet holds to for mono caption text.
   Icon browsers worth copying mostly do not label cells at all — Skiff, Pitch's
   Icons8 picker and Adobe Express's icon chooser are all bare glyph grids that
   lean on search and the glyph itself. UIL4B keeps the name because the name is
   the thing you copy, but that is the reason it has to be legible rather than
   decorative. */
.ic span{max-width:100%;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere;font-size:11px;color:var(--t2);text-align:center;font-family:var(--mono);line-height:1.25}

/* ─── Icon Detail popup ─── */
.il-detail{position:relative;background:var(--bg-0);border:1px solid var(--border);border-radius:var(--radius-l);max-width:560px;width:100%;padding:40px;box-shadow:var(--warm-shadow-lg);animation:fg-rise var(--dur-3) var(--ease-entrance)}
.il-detail-preview{display:flex;align-items:center;justify-content:center;padding:32px;margin-bottom:20px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius);min-height:140px;background-image:radial-gradient(circle,color-mix(in srgb,var(--border) 60%,transparent) .5px,transparent .5px);background-size:12px 12px}
.il-detail-preview img,.il-detail-preview svg{transition:all var(--dur-2) var(--ease-standard)}
.il-detail-controls{display:flex;flex-direction:column;gap:14px}
.il-detail-row{display:flex;align-items:center;gap:10px}
.il-detail-row>label{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);min-width:52px;flex-shrink:0}
.il-detail-row input[type="range"]{flex:1;accent-color:var(--accent)}
.il-detail-row input[type="color"]{width:28px;height:28px;border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;padding:1px;background:var(--bg-1);flex-shrink:0}
.il-detail-value{font-family:var(--mono);font-size:11px;color:var(--t2);min-width:36px;text-align:right;flex-shrink:0}
.il-detail-color-input{flex:1;font-family:var(--mono);font-size:12px;padding:6px 10px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);color:var(--t0)}
.il-detail-reset{width:24px;height:24px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);color:var(--t2);cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:all var(--t)}
.il-detail-reset:hover{background:var(--bg-2);color:var(--t0)}
.il-detail-seg{display:flex;gap:2px;flex:1}
.il-detail-seg button{font-family:var(--mono);font-size:10px;font-weight:600;padding:6px 10px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);color:var(--t2);cursor:pointer;transition:all var(--t);flex:1;text-align:center}
.il-detail-seg button.active{background:var(--accent-strong);color:var(--accent-fg);border-color:var(--accent-strong)}
.il-detail-seg button:hover:not(.active){background:var(--bg-2);color:var(--t0)}
.il-detail-code-tabs{display:flex;gap:2px;margin-bottom:8px}
.il-detail-code-tabs button{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);color:var(--t2);cursor:pointer;transition:all var(--t)}
.il-detail-code-tabs button.active{background:var(--accent);color:#fff;border-color:var(--accent)}
.il-detail-code{position:relative;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-s);padding:14px 14px 14px 14px;font-family:var(--mono);font-size:11px;line-height:1.6;color:var(--t1);max-height:120px;overflow:auto;word-break:break-all;white-space:pre-wrap;cursor:pointer;transition:border-color var(--t)}
.il-detail-code:hover{border-color:var(--accent)}
.il-detail-code-hint{position:absolute;top:6px;right:8px;font-size:9px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--t3);pointer-events:none;transition:color var(--t)}
.il-detail-code:hover .il-detail-code-hint{color:var(--accent-strong)}

/* ─── Type scale ─── */
.ts-row{display:flex;align-items:baseline;gap:14px;padding:12px 0;border-bottom:1px solid var(--border);flex-wrap:wrap}
.ts-row:last-child{border-bottom:none}
.ts-meta{min-width:70px;font-size:10px;font-family:var(--mono);color:var(--t2)}

/* ─── Button catalogue ─── */
.btn-cat{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(200px,100%),1fr));gap:10px}
.btn-cell{display:flex;flex-direction:column;align-items:center;gap:10px;padding:24px 14px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius)}
.btn-cell .bn{font-size:10px;font-weight:600;color:var(--t2);letter-spacing:.03em;text-transform:uppercase}

/* ─── Layouts ─── */
.lp{background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);padding:14px;min-height:80px}
.lph{background:var(--bg-3);border:1px dashed var(--bh);border-radius:var(--radius-s)}

/* ─── Image Converter ─── */
.img-drop-zone{border:2px dashed var(--border);border-radius:var(--radius);padding:40px 20px;text-align:center;cursor:pointer;transition:border-color var(--t)}
.img-drop-zone:hover{border-color:var(--accent)}
.img-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(200px,100%),1fr));gap:10px}

/* ─── Prompt Library (gallery style) ─── */
.pl-tabs{display:flex;gap:4px;margin-bottom:20px;border-bottom:1px solid var(--border);padding-bottom:0}
.pl-tab{display:inline-flex;align-items:center;gap:8px;padding:12px 18px;border:none;background:none;color:var(--t2);font-family:var(--font);font-size:13px;font-weight:500;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px;transition:all var(--t)}
.pl-tab:hover{color:var(--t0)}
.pl-tab.active{color:var(--accent-strong);border-bottom-color:var(--accent);font-weight:600}
.pl-tab-count{font-size:10px;font-weight:700;background:var(--bg-3);color:var(--t2);padding:2px 7px;border-radius:10px;min-width:20px;text-align:center}
.pl-tab.active .pl-tab-count{background:var(--accent-bg);color:var(--accent-strong)}
.pl-card-author{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:11px;color:var(--t2)}
.pl-card-saves{font-family:var(--mono);font-size:10px;color:var(--t3);background:var(--bg-2);padding:2px 8px;border-radius:var(--radius-s)}
/* Sticky library command bar. It used to carry a negative-margin bleed sized to
   the page gutter, but every page that uses it nests it inside .sec (max-width
   1400) — so the bleed could never reach the viewport edge and simply
   overhung the content column by whatever the gutter was. The bar now spans its
   own container and lines up with the grid it filters. */
/* `top:var(--nav-clear)`, not `top:0`. This bar is `position:sticky` at
   z-index 30 and `.pnav` is `position:fixed;top:0` at z-index 120, so with a
   zero offset the bar pins itself UNDERNEATH the floating nav the moment the
   page is scrolled. Measured on /discover/prompts, scrolled, hit-testing each
   control at its own centre:

     1440px   10 of 10 covered — search, both sort buttons, all six category
              chips and "Submit prompt". The bar is 80px tall and the nav is
              60px, so almost none of it is left.
      834px    3 of 10
      390px    1 of 10

   WORST AT DESKTOP, which is why two mobile audits walked past it: the taller
   the bar wraps, the more of it escapes below the nav, so the narrow widths
   that get audited are the widths that hide it.

   The offset itself is not new — `--nav-clear` is what `.lbry-toolbar` and
   `.plb-toolbar` already use, and there was a `.rail-content .pl-toolbar`
   override carrying exactly this value. That override matched NOTHING:
   `.rail-content` is rendered only by CreateTool.jsx and the sole consumer of
   `.pl-toolbar` is PromptLibrary, which is not inside it. A correct rule
   scoped to a selector that never matches is the shape this defect had. */
/* RETIRED (#323). `.pl-toolbar` and `.pl-search-*` were the last one-off
   browse toolbar in the app — the Prompt Library was the only consumer, and
   it is now on the shared `LibraryToolbar` / `.lbry-toolbar` like every
   other browse surface. The sticky-offset reasoning above is preserved
   because it is why `--nav-clear` exists on the shared toolbar too. */
/* The category row WRAPS (S4, mobile-audit-2026-08). It was
   `flex-wrap:nowrap; overflow-x:auto` with the scrollbar suppressed on both
   `scrollbar-width` and `::-webkit-scrollbar`, which under touch emulation
   renders no affordance at all — the same "hidden scroller" shape as S1, S2, S3
   and S8, and the fifth instance of it in this stylesheet.

   Measured chips sitting outside their own box, before → after, per consumer of
   this shared class (it is not only the Emoji Library, which is all S4 records):

     /emoji              320px  9 of 12 → 0     390px  9 of 12 → 0
     /icons              320px  4 of 7  → 0     768px  5 of 7  → 0
     /discover/prompts   320px  3 of 6  → 0     768px  4 of 6  → 0
     /discover/gradients 320px  4 of 8  → 0     390px  3 of 8  → 0

   The Emoji Library was still hiding 5 of 12 at 1180px, so this was never only
   a phone defect. Category is the primary navigation for a 1,655-item library.

   The cost is height and it is the largest this sweep has spent: the emoji row
   goes 29px → 169px at 320px wide, 29 → 134 at 390, 29 → 64 at 1180. That is
   accepted on the same reasoning PR #271 recorded for .stc-bundles — a page
   that already scrolls vertically can afford rows; an undiscoverable gesture
   costs the option entirely. .grg-chips already wraps at ≥821px, so this is the
   established look on one of the four surfaces rather than a new one. */
.pl-chips{display:flex;gap:6px;flex-wrap:wrap;flex:1;min-width:0}
.pl-chip{padding:6px 14px;border-radius:var(--radius);font-size:11px;font-weight:600;letter-spacing:.02em;border:1px solid var(--border);background:transparent;color:var(--t2);cursor:pointer;font-family:var(--font);transition:all var(--t);white-space:nowrap;flex-shrink:0}
.pl-chip:hover{color:var(--t0);border-color:var(--bh);background:var(--hvr)}
.pl-chip.active{background:var(--accent-bg);border-color:var(--accent);color:var(--accent-strong)}
.pl-add-btn{flex-shrink:0;margin-left:auto}
/* PATTERN B (the tablet band) is now handled for this surface by the shared
   toolbar: #318 gave `.lbry-toolbar` a 641-980 layout of its own and #323
   moved the Prompt Library onto it, so the bespoke band rule that used to
   sit here — uncapping `.pl-search-wrap` so `.pl-chips` could take a full
   row — has no selectors left to act on. The deliberate cost it recorded
   ("Submit prompt lands on a third row") is gone with it: the shared
   toolbar puts the action in `.lbry-toolbar-action`. */
/* Native select, styled to sit in a .pl-toolbar next to the search field */

/* Add prompt panel */
.pl-add-panel{max-height:0;overflow:hidden;transition:max-height var(--dur-3) var(--ease-out),opacity var(--dur-2) var(--ease-standard);opacity:0;margin-bottom:0}
.pl-add-panel.open{max-height:600px;opacity:1;margin-bottom:28px}
.pl-add-inner{background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);padding:24px;box-shadow:var(--warm-shadow)}
.pl-add-fields{display:flex;flex-direction:column;gap:12px}
/* The two !important here were a workaround for the bare-type-selector trap,
   not a real override. The reset is :where()-wrapped now, so the class wins. */
.pl-input-title{font-size:16px;font-weight:600;padding:12px 16px}
.pl-textarea{min-height:100px;resize:vertical;font-size:13px;line-height:1.7}
.pl-add-row{display:flex;gap:12px;flex-wrap:wrap;align-items:stretch}
.pl-add-field{flex:1;min-width:180px;display:flex;flex-direction:column;gap:6px}
.pl-add-field label{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.pl-drop-zone{flex:0 0 180px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;border:2px dashed var(--border);border-radius:var(--radius);padding:16px;cursor:pointer;transition:all var(--t);color:var(--t3);font-size:11px;font-weight:500}
.pl-drop-zone:hover,.pl-drop-zone.over{border-color:var(--accent);color:var(--accent-strong);background:var(--accent-bg)}
.pl-add-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:16px}

/* Gallery grid — masonry-like with varying heights */
.pl-gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(300px,100%),1fr));--pl-gap:16px;gap:var(--pl-gap);margin-top:8px}
/* The locked tease continues the gallery, so its seam is the ROW GAP, not
   the 8px that separates the first grid from the toolbar. --pl-gap is read
   rather than repeated: the 720px band retunes it and the seam follows. */
.pl-gallery--continues{margin-top:var(--pl-gap)}

/* Card */
.pl-card{border-radius:var(--radius-l);overflow:hidden;cursor:pointer;transition:all var(--dur-3) var(--ease-out);position:relative;background:var(--card);border:1px solid var(--border)}
.pl-card:hover{transform:translateY(-4px);box-shadow:var(--warm-shadow-lg);border-color:var(--bh)}
.pl-card:hover .pl-card-overlay{opacity:1}
.pl-card:hover .pl-card-img img{transform:scale(1.04)}

/* Card image */
.pl-card-img{position:relative;overflow:hidden;aspect-ratio:16/10}
.pl-card-img img{width:100%;height:100%;object-fit:cover;transition:transform var(--dur-5) var(--ease-out)}
.pl-card-overlay{position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.85) 0%,rgba(0,0,0,.1) 50%,transparent 100%);display:flex;flex-direction:column;justify-content:flex-end;padding:20px;opacity:0;transition:opacity var(--dur-3) var(--ease-standard)}
.pl-card-title{font-size:15px;font-weight:600;color:#fff;line-height:1.35;margin-bottom:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

/* No-image card */
.pl-card.no-img{background:var(--card-grad)}
.pl-card-text-hero{padding:22px 22px;min-height:132px;display:flex;flex-direction:column;justify-content:flex-end;position:relative}
/* The 40x40 accent-tinted square that used to sit here was EMPTY — `content:''`
   with `display:flex;align-items:center;justify-content:center`, i.e. centring
   rules for a glyph that was never added. On a text-only card it read as a
   thumbnail that had failed to load, on all 20 cards at once, and it competed
   with the Pro lock badge for the same corner. Removed rather than filled: the
   card's categories are TAG_CATEGORIES, which has no glyph set, and the shared
   CategoryGlyph is keyed to the unrelated discoverCategories taxonomy. */
.pl-card.no-img .pl-card-title{color:var(--t0)}
.pl-card.no-img:hover .pl-card-title{color:var(--accent-strong)}

/* Tags */
.pl-card-tags{display:flex;gap:5px;flex-wrap:wrap}
.pl-tag{padding:3px 10px;border-radius:var(--radius);font-size:9px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;background:rgba(255,255,255,.12);color:rgba(255,255,255,.8);backdrop-filter:blur(4px);transition:background var(--dur-2) var(--ease-standard)}
/* --accent is #0F6FFF in light theme: 4.43:1 on the white card, 3.82:1 on the
   page ground - under AA at these sizes, and this page renders ~80 tags at once.
   --accent-strong is the same blue at 5.84 / 5.03. See [accent-small-text-contrast]. */
.pl-card.no-img .pl-tag{background:var(--accent-bg);color:var(--accent-strong)}

/* Card date inline */
