/* ─── Docs sticky TOC ─── */
.docs-toc{position:sticky;top:0;z-index:50;margin:-12px -16px 36px;padding:10px 16px 12px;background:color-mix(in srgb,var(--bg-1) 92%,transparent);backdrop-filter:saturate(160%) blur(14px);-webkit-backdrop-filter:saturate(160%) blur(14px);border-bottom:1px solid var(--border);opacity:0;transform:translateY(-8px);pointer-events:none;transition:opacity var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
.docs-toc.visible{opacity:1;transform:translateY(0);pointer-events:auto}
.docs-toc-eyebrow{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--t2);margin-bottom:8px;padding-left:2px}
.docs-toc-track{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;padding-bottom:2px}
.docs-toc-track::-webkit-scrollbar{display:none}
.docs-toc-item{display:inline-flex;align-items:center;gap:8px;flex-shrink:0;padding:7px 12px;border-radius:999px;background:var(--bg-2);border:1px solid var(--border);text-decoration:none!important;color:var(--t1);font-size:12px;font-weight:500;transition:all var(--dur-2) var(--ease-standard);cursor:pointer;white-space:nowrap}
.docs-toc-item:hover{background:var(--hvr);color:var(--t0);border-color:var(--bh)}
.docs-toc-item.active{background:var(--accent-bg);border-color:var(--accent-soft);color:var(--accent-strong);font-weight:600}
.docs-toc-num{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.04em;color:var(--t3);transition:color var(--dur-2) var(--ease-standard)}
.docs-toc-item.active .docs-toc-num{color:var(--accent-strong)}
.docs-toc-label{letter-spacing:-.01em}
@media(max-width:640px){
  .docs-toc{margin:-8px -12px 28px;padding:8px 12px 10px}
  .docs-toc-item{padding:6px 10px;font-size:11px}
}

/* ─── ColorStudio UI Preview bento ─── */
.cs-bento .cs-b-2{grid-column:span 2}
.cs-bento .cs-b-3{grid-column:span 3}
.cs-bento .cs-b-6{grid-column:span 6}
@media(max-width:980px){
  .cs-bento{grid-template-columns:repeat(4,1fr)!important}
  .cs-bento .cs-b-2{grid-column:span 2}
  .cs-bento .cs-b-3{grid-column:span 4}
  .cs-bento .cs-b-6{grid-column:span 4}
}
@media(max-width:640px){
  .cs-bento{grid-template-columns:1fr!important;gap:10px!important}
  .cs-bento .cs-b-2,.cs-bento .cs-b-3,.cs-bento .cs-b-6{grid-column:span 1}
}

/* ─── Hero (Dashboard) ─── */
.hero-section{position:relative;margin-bottom:40px;padding:8px 0 0}
.hero-eyebrow{display:inline-flex;align-items:center;gap:8px;font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:.06em;color:var(--t2);text-transform:uppercase;margin-bottom:20px;position:relative;z-index:1}
.hero-eyebrow .dot{width:6px;height:6px;border-radius:50%;background:var(--ok)}
.hero-title{font-size:clamp(40px,6vw,72px);font-weight:800;letter-spacing:-.045em;line-height:1.1;color:var(--t0);margin-bottom:18px;position:relative;z-index:1}
.hero-title em{font-style:normal;color:var(--accent)}
.hero-sub{font-size:18px;color:var(--t1);max-width:580px;line-height:1.7;position:relative;z-index:1}

/* ─── Section header ─── */
.section-h{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:20px;padding-bottom:14px;border-bottom:1px solid var(--border)}
.section-h h2{font-size:14px;font-weight:600;color:var(--t0);letter-spacing:-.005em;display:flex;align-items:center;gap:10px}
.section-h h2 .num{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--accent-strong);background:var(--accent-bg);padding:3px 8px;border-radius:var(--radius-s);border:1px solid rgba(124,92,252,.1)}
.section-h .meta{font-family:var(--mono);font-size:10px;font-weight:600;color:var(--t2);letter-spacing:.06em;text-transform:uppercase}

/* ─── Tool tile (card grid for dashboard) ─── */
.tile-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(240px,100%),1fr));gap:12px;margin-bottom:36px}
.tool-tile{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:20px;cursor:pointer;text-decoration:none!important;color:inherit;transition:all var(--dur-2) var(--ease-standard);position:relative;min-height:136px;overflow:hidden;box-shadow:var(--warm-shadow)}
.tool-tile:hover{transform:translateY(-3px);box-shadow:var(--warm-shadow-lg);border-color:var(--bh)}
.tool-tile-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;gap:8px}
.tool-tile-icon{width:34px;height:34px;border-radius:var(--radius-s);background:var(--bg-2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--t1);transition:all var(--dur-2) var(--ease-standard)}
.tool-tile:hover .tool-tile-icon{background:var(--accent-bg);border-color:var(--accent-glow);color:var(--accent)}
.tool-tile-icon svg{width:15px;height:15px}
.tool-tile-pin{background:none;border:none;cursor:pointer;color:var(--t3);padding:8px;border-radius:var(--radius-s);display:flex;align-items:center;justify-content:center;transition:all var(--t);min-width:32px;min-height:32px}
.tool-tile-pin:hover{color:var(--t1);background:var(--bg-3)}
.tool-tile-pin.pinned{color:var(--accent)}
.tool-tile-pin.pinned svg{fill:var(--accent)}
.tool-tile-label{font-size:14px;font-weight:600;color:var(--t0);margin-bottom:5px;letter-spacing:-.01em}
.tool-tile-desc{font-size:12px;color:var(--t2);line-height:1.55;flex:1}
.tool-tile-cat{font-family:var(--mono);font-size:9px;font-weight:600;color:var(--t3);letter-spacing:.06em;text-transform:uppercase;margin-top:12px}

@keyframes cardIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}

/* ─── Command Palette ─── */
.cp-overlay{position:fixed;inset:0;background:var(--scrim);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);z-index:9998;display:flex;justify-content:center;align-items:flex-start;padding-top:max(10vh,80px);animation:cp-fade var(--dur-1) var(--ease-entrance)}
@keyframes cp-fade{from{opacity:0}to{opacity:1}}
@keyframes cp-rise{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
.cp-panel{background:var(--card);border:1px solid var(--border);border-radius:var(--radius-xl);width:min(640px,calc(100vw - 32px));max-height:70vh;display:flex;flex-direction:column;box-shadow:var(--warm-shadow-lg);overflow:hidden;animation:cp-rise var(--dur-2) var(--ease-entrance)}
.cp-input-wrap{display:flex;align-items:center;gap:12px;padding:18px 22px;border-bottom:1px solid var(--border)}
.cp-input-wrap svg{color:var(--t2);flex-shrink:0}
.cp-input{flex:1;background:none;border:none;outline:none;color:var(--t0);font-family:var(--font);font-size:17px;font-weight:400;letter-spacing:-.01em;padding:0}
.cp-input::placeholder{color:var(--t3)}
.cp-kbd{font-family:var(--mono);font-size:10px;color:var(--t2);background:var(--bg-2);padding:3px 7px;border-radius:var(--radius-s);border:1px solid var(--border)}
.cp-results{flex:1;overflow-y:auto;padding:8px}
.cp-section-label{font-family:var(--mono);font-size:10px;font-weight:600;color:var(--t3);letter-spacing:.08em;text-transform:uppercase;padding:10px 14px 4px}
.cp-item{display:flex;align-items:center;gap:12px;width:100%;padding:10px 14px;background:none;border:none;cursor:pointer;text-align:left;font-family:var(--font);border-radius:var(--radius-s);color:var(--t1);transition:all var(--t)}
.cp-item:hover,.cp-item.active{background:var(--hvr);color:var(--t0)}
.cp-item.active{outline:none;box-shadow:inset 0 0 0 1px var(--accent-glow)}
.cp-item-icon{width:30px;height:30px;border-radius:var(--radius-s);background:var(--bg-2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--t1);flex-shrink:0;transition:all var(--t)}
.cp-item.active .cp-item-icon{background:var(--accent-bg);border-color:var(--accent-glow);color:var(--accent)}
.cp-item-icon svg{width:13px;height:13px}
.cp-item-body{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.cp-item-label{font-size:13px;font-weight:500;color:var(--t0);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cp-item-desc{font-size:11px;color:var(--t2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cp-item-cat{font-family:var(--mono);font-size:9px;font-weight:600;color:var(--t3);letter-spacing:.06em;text-transform:uppercase;flex-shrink:0;padding:3px 8px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.cp-empty{padding:48px 20px;text-align:center;font-size:13px;color:var(--t2)}
.cp-footer{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-top:1px solid var(--border);background:var(--bg-2);font-size:11px;color:var(--t2);gap:12px;flex-wrap:wrap}
.cp-footer-keys{display:flex;gap:14px}
.cp-footer-keys span{display:inline-flex;align-items:center;gap:6px}

/* ─── Cmd+K hint button (TopBar) ─── */
.cmdk-hint{display:inline-flex;align-items:center;gap:8px;background:var(--bg-0);border:1px solid var(--border);border-radius:var(--radius);padding:7px 16px;color:var(--t2);font-size:13px;font-family:var(--font);cursor:pointer;transition:all var(--dur-2) var(--ease-out);min-width:320px;flex:1;max-width:520px}
.cmdk-hint:hover{border-color:var(--bh);color:var(--t1);background:var(--bg-2)}
.cmdk-hint svg{flex-shrink:0;color:var(--t3)}
.cmdk-hint-text{flex:1;text-align:left}
.cmdk-hint-keys{display:inline-flex;gap:3px;flex-shrink:0}
.cmdk-hint-keys kbd{font-family:var(--mono);font-size:10px;font-weight:600;color:var(--t2);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);padding:2px 6px;line-height:1}

/* ─── Section switcher (top bar) ─── */
.nav-switch{position:relative;flex-shrink:0}
.nav-switch-trigger{display:inline-flex;align-items:center;gap:var(--s-2);background:var(--bg-0);border:1px solid var(--border);border-radius:var(--radius-pill);padding:6px 10px 6px 12px;color:var(--t0);font-family:var(--font);font-size:13px;font-weight:600;cursor:pointer;transition:border-color var(--t),background var(--t),color var(--t)}
.nav-switch-trigger:hover{border-color:var(--bh);background:var(--bg-2)}
.nav-switch-icon{width:16px;height:16px;flex-shrink:0;color:var(--brand)}
.nav-switch-trigger-label{white-space:nowrap}
.nav-switch-chev{width:13px;height:13px;flex-shrink:0;color:var(--t2);transition:transform var(--t)}
.nav-switch-chev.open{transform:rotate(180deg)}
.nav-switch-menu{position:absolute;top:calc(100% + 6px);left:0;min-width:288px;max-width:calc(100vw - 16px);background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--warm-shadow-lg);z-index:200;padding:6px;animation:cp-rise var(--dur-2) var(--ease-entrance)}
.nav-switch-item{display:flex;align-items:center;gap:var(--s-3);width:100%;padding:9px 10px;background:none;border:none;cursor:pointer;font-family:var(--font);border-radius:var(--radius-s);transition:background var(--t);text-align:left;color:var(--t0)}
.nav-switch-item:hover{background:var(--hvr)}
.nav-switch-item.is-current{background:var(--accent-bg)}
.nav-switch-item.is-current:hover{background:color-mix(in srgb,var(--accent) 14%,transparent)}
.nav-switch-item-icon{width:18px;height:18px;flex-shrink:0;color:var(--t0);align-self:center}
.nav-switch-item.is-current .nav-switch-item-icon{color:var(--accent)}
.nav-switch-item-text{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1}
.nav-switch-item-label{font-size:13px;font-weight:600;color:var(--t0);line-height:1.2}
.nav-switch-desc{font-size:11px;font-weight:400;color:var(--t1);line-height:1.35}
.nav-switch-check{width:16px;height:16px;flex-shrink:0;color:var(--accent);align-self:center}
.nav-switch-divider{height:1px;background:var(--border);margin:6px 4px}
.nav-switch-link{display:flex;align-items:center;gap:var(--s-3);width:100%;padding:9px 10px;background:none;border:none;cursor:pointer;font-family:var(--font);font-size:13px;font-weight:500;color:var(--t0);border-radius:var(--radius-s);transition:background var(--t);text-align:left}
.nav-switch-link:hover{background:var(--hvr)}
.nav-switch-link-icon{width:16px;height:16px;flex-shrink:0;color:var(--t1)}

/* ═══════════════════════════════════════
   RESPONSIVE — clean cascade, mobile parity
   Breakpoints: 1024 / 860 / 640 / 480 / 380
   ═══════════════════════════════════════ */

/* Universally prevent horizontal scroll. `clip` (not `hidden`) so we never spawn
   a scroll container that would break descendant position:sticky — the in-tool
   left rail and sticky tool toolbars depend on this. */
html,body{max-width:100vw;overflow-x:clip}
img,svg,video{max-width:100%;height:auto}

/* Tablet landscape (≤1024px) — split panels stack */
@media(max-width:1024px){
  .split>.side{flex:0 0 100%}
  .split{gap:16px}
  :root{--sw:220px}
  .sec-h{margin-bottom:36px}
}

/* Medium breakpoint (≤980px) — content stacking and breathing room */
@media(max-width:980px){
  .split>*{flex:0 1 100%}
  .sec-h h1{line-height:1.25}
  .cat-bento-hero{padding:80px 26px 26px;min-height:260px}
  .cat-bento-hero-icon{top:22px;left:26px}
  .pl-gallery{grid-template-columns:repeat(auto-fill,minmax(min(260px,100%),1fr));--pl-gap:14px}
}

/* Tablet portrait → mobile transition (≤860px) — sidebar drawer */
@media(max-width:860px){
  .sidebar{position:fixed;left:0;top:0;width:min(280px,85vw);height:100vh;transform:translateX(-101%);transition:transform var(--dur-3) var(--ease-out);z-index:1000;box-shadow:0 0 60px rgba(0,0,0,.4)}
  .sidebar.open{transform:translateX(0)}
  .sidebar-overlay{z-index:999}
  .topbar-hamburger{display:flex!important;width:44px;height:44px;justify-content:center}
  .topbar-tabs{display:none}
  html:has(body.menu-open){overflow:hidden}
  body.menu-open{overflow:hidden}
  .main{padding:0 clamp(14px,4vw,32px) clamp(40px,8vw,80px);max-width:100%}
  .main>*:first-child{padding-top:clamp(20px,4vw,40px)}
  .sec-h{margin-bottom:32px}
  .sec-h h1{font-size:clamp(28px,7vw,40px)}
  .sec-h p{font-size:14px}
  .sub h2{font-size:20px}
  .card{padding:22px}
  .card-i{padding:18px}
  /* Modals: full-width on mobile */
  .export-dropdown{position:fixed!important;top:auto!important;bottom:0!important;left:0!important;right:0!important;border-radius:var(--radius-l) var(--radius-l) 0 0!important;min-width:0!important;max-width:none!important;width:100%!important;padding:14px 12px 28px!important;box-shadow:0 -8px 32px rgba(0,0,0,.35)!important;animation:slideUp var(--dur-2) var(--ease-entrance)!important}
  .export-dropdown::before{content:'';display:block;width:36px;height:4px;background:var(--bg-4);border-radius:2px;margin:0 auto 12px}
  .export-dropdown-item{padding:14px 16px!important;font-size:13px!important;min-height:44px}
  /* Section switcher — icon-only pill; the label folds into the bottom sheet */
  .nav-switch-trigger{padding:0;width:44px;height:44px;justify-content:center;gap:0}
  .nav-switch-trigger-label,.nav-switch-chev{display:none}
  .nav-switch-icon{width:18px;height:18px}
  .nav-switch-menu{position:fixed;top:auto;bottom:0;left:0;right:0;border-radius:var(--radius-l) var(--radius-l) 0 0;min-width:0;max-width:none;width:100%;padding:14px 12px 28px;box-shadow:0 -8px 32px rgba(0,0,0,.35);animation:slideUp var(--dur-2) var(--ease-entrance)}
  .nav-switch-menu::before{content:'';display:block;width:36px;height:4px;background:var(--bg-4);border-radius:2px;margin:0 auto 12px}
  .nav-switch-item,.nav-switch-link{min-height:44px}
}
@keyframes slideUp{from{transform:translateY(100%)}to{transform:translateY(0)}}

/* Compact desktop / large phone (≤640px) */
@media(max-width:640px){
  /* Topbar — collapse cmdk-hint to icon-only button */
  .topbar{padding:0 12px;gap:6px}
  .topbar-left{gap:6px;flex:1;min-width:0}
  .cmdk-hint{min-width:0!important;max-width:none!important;flex:0 0 auto;padding:8px;width:40px;height:40px;justify-content:center;background:transparent;border-color:transparent}
  .cmdk-hint:hover{background:var(--bg-2);border-color:var(--border)}
  .cmdk-hint-text,.cmdk-hint-keys{display:none}
  .topbar-brand{flex:1;min-width:0}
  .topbar-title{font-size:14px;overflow:hidden;text-overflow:ellipsis}
  .topbar-btn-export,.topbar-preview-btn{padding:7px 10px;font-size:11px}
  .topbar-btn-export span,.topbar-btn-export-label{display:none}
  .topbar-icon-btn{width:40px;height:40px;justify-content:center;padding:0}
  .topbar-avatar{width:34px;height:34px;font-size:12px}

  /* Section headers */
  .sec-h{margin-bottom:28px}
  .sec-h h1{font-size:clamp(26px,8vw,36px);line-height:1.25}
  .sec-h p{font-size:13.5px}
  .sub{margin-bottom:32px}
  .sub h2{font-size:19px}

  /* Cards & buttons */
  .card{padding:18px;border-radius:var(--radius)}
  .card-i{padding:16px}
  .btn{padding:10px 16px;font-size:12px;min-height:44px}
  .btn-s{padding:7px 12px;font-size:11px;min-height:38px}

  /* Touch targets — minimum 44px on mobile */
  .pt-t{min-height:44px;padding:10px 14px}
  .tool-mini-pin{min-width:44px;min-height:44px;padding:10px}
  .sidebar-user-action{min-width:44px;min-height:44px}
  .nav-item{min-height:44px}
  .nav-cat-toggle{min-width:44px;min-height:44px}
  .dash-tool-pin{min-width:44px;min-height:44px}
  .tool-tile-pin{min-width:44px;min-height:44px}
  .auth-links button{min-height:44px}

  /* Grids stack */
  .dash-tools-grid{grid-template-columns:1fr}
  .pal-grid{grid-template-columns:repeat(auto-fill,minmax(min(140px,100%),1fr))}
  .pal-swatch{min-height:140px;padding:14px}
  /* 104px, not 72. Fewer, wider cells is the whole point: 72px could not hold a
     legible icon name at any font size, so the grid was dense with labels that
     all read the same. The name also gets a third line down here, because a
     phone cell is narrow enough that two lines still cut the `align-horizontal-
     distribute-*` family in the same place. */
  .ig{grid-template-columns:repeat(auto-fill,minmax(104px,1fr))}
  .ic>span:not(.ic-pack){-webkit-line-clamp:3;line-clamp:3}
  .grad-presets{grid-template-columns:repeat(auto-fill,minmax(min(180px,100%),1fr))}
  .img-grid{grid-template-columns:repeat(auto-fill,minmax(min(140px,100%),1fr))}
  .pl-gallery{grid-template-columns:1fr}
  .pl-add-btn{width:100%}
  .pl-drop-zone{flex:1 1 100%}
  .btn-cat{grid-template-columns:repeat(auto-fill,minmax(min(160px,100%),1fr))}

  /* Forms / inputs. Split deliberately: the 16px floor is POLICY — iOS zooms
     the viewport when a focused field is under 16px — so it keeps element-level
     strength and outranks component classes. The padding is only a DEFAULT, so
     it sits in :where() and a component's own padding wins. See the note on the
     reset at the top of the Inputs section. */
  input[type="text"],input[type="number"],input[type="email"],input[type="password"],select,textarea{font-size:16px}
  :where(input[type="text"],input[type="search"],input[type="number"],input[type="email"],input[type="password"],select,textarea){padding:11px 14px}

  /* Color Studio */
  .tint-grid-responsive{grid-template-columns:repeat(auto-fill,minmax(min(56px,calc((100% - 32px)/4)),1fr))!important}
  .tint-controls-grid{grid-template-columns:1fr!important;gap:12px!important}
  /* Pill-nav → horizontal scroll-snap rail on tablet/phone (keeps glass + thumb). */
  .cs-pillnav{display:flex;max-width:100%;overflow-x:auto;flex-wrap:nowrap;-webkit-overflow-scrolling:touch;scrollbar-width:none;scroll-snap-type:x proximity}
  .cs-pillnav::-webkit-scrollbar{display:none}
  .cs-pillnav-item{flex-shrink:0;min-height:44px;scroll-snap-align:center}
  /* Global-adjust strip → 2 columns. */
  .cs-pb-adjust{grid-template-columns:repeat(2,1fr)}

  /* Font matcher cards */
  .fp{min-width:0!important;flex:1 1 100%!important}

  /* Type scale */
  .ts-row{gap:8px;flex-wrap:wrap;align-items:flex-start}
  .ts-meta{min-width:50px;font-size:9px;flex-shrink:0}

  /* Compare row stack */
  .comp-row{flex-direction:column;align-items:flex-start;padding:14px;gap:10px}

  /* Suggest bar stack */
  .suggest-bar{flex-direction:column;align-items:stretch;gap:12px;padding:14px}

  /* Auth card */
  .auth-card{margin:0;padding:24px;border-radius:var(--radius-l)}
  .auth-container{padding-top:20px;padding:20px}

  /* Settings */
  .settings-grid{grid-template-columns:1fr;gap:20px}
  /* .settings-nav / .settings-nav-item moved: see the block after the base rule. */
  .settings-section-h h2{font-size:24px}
  .settings-card-h,.settings-card-body,.settings-profile{padding-left:18px!important;padding-right:18px!important}
  .settings-profile{flex-wrap:wrap;gap:14px}
  .settings-profile-info{flex:1 1 calc(100% - 78px);min-width:0}
  .plan-grid{grid-template-columns:1fr}
  .plan-card{padding:22px}
  .plan-card-price-num{font-size:36px}
  .lang-grid{grid-template-columns:1fr}

  /* Privacy storage table → card list. MOVED: the whole stacked-card block now
     lives immediately after the base `.storage-table` rules, because those
     appear LATER in this stylesheet and were silently winning `padding` and
     `border-bottom` at equal specificity. See the note there — and the
     identical trap already recorded on `.settings-nav`. */

  /* Section headers */
  .section-h{flex-wrap:wrap}
  .seg-cell{min-width:100px}

  /* Toast */
  .toast{left:12px;right:12px;bottom:12px;max-width:none}

  /* Hide tab labels in admin filters */
  .admin-tabs{flex-wrap:wrap}
}

/* Small phone (≤480px) */
@media(max-width:480px){
  .seg-bar{flex-direction:column}
  .seg-cell{border-right:none;border-bottom:1px solid var(--border)}
  .seg-cell:last-child{border-bottom:none}
  .topbar-title{display:none}
  .topbar-avatar{width:32px;height:32px;font-size:11px}
  .topbar-btn-export{display:none}
  .pal-grid{grid-template-columns:repeat(auto-fill,minmax(min(120px,calc((100% - 8px)/2)),1fr))!important}
  .pal-swatch{min-height:120px;padding:12px}
  /* Three, not four. At 390px four columns give an 87px cell, which clipped 24
     of the 120 visible names; three give ~118px and clip none. */
  .ig{grid-template-columns:repeat(3,1fr)}
  .ic{padding:14px 4px 10px;min-height:72px}
  /* The 8px override is gone — see the `.ic span` note by the base rule. */
  .img-grid{grid-template-columns:1fr}
  .grad-presets{grid-template-columns:1fr}
  .btn-cat{grid-template-columns:1fr}
  .tint-grid-responsive{grid-template-columns:repeat(auto-fill,minmax(min(48px,calc((100% - 18px)/4)),1fr))!important}
  .tint-swatch{padding-bottom:6px}
  .tint-swatch .stop-label{font-size:10px}
  .main{padding:0 12px 40px}
  .main>*:first-child{padding-top:16px}
  .sec-h{margin-bottom:24px}
  .sec-h h1{font-size:clamp(24px,9vw,32px)}
  .auth-card{padding:22px 18px}
  .auth-header h1{font-size:24px}
  .settings-section-h h2{font-size:22px}
  .plan-card-price-num{font-size:32px}
  .nav-cat-toggle{width:28px;height:36px}
  .nav-item{padding:11px 12px;min-height:42px}
  .nav-cat-link{padding:11px 10px;min-height:40px}
  /* Pill-nav: tighter type/padding, pin closer to top. */
  .cs-pillnav{top:var(--s-2)}
  .cs-pillnav-item{font-size:12.5px;padding:7px 13px}
  /* Palette builder: 2 cards per row, shorter; adjust → single column. */
  .cs-pb-swatch,.cs-pb-add{flex:1 1 calc(50% - var(--s-2));min-height:128px}
  .cs-pb-adjust{grid-template-columns:1fr}
}

/* Tiny screens (≤380px) — last-resort tightening */
@media(max-width:380px){
  .topbar{padding:0 8px;gap:4px}
  .topbar-icon-btn,.cmdk-hint{width:36px;height:36px}
  .topbar-avatar{width:34px;height:34px}
  .topbar-logo{width:22px;height:22px}
  .main{padding:0 10px 36px}
  .main>*:first-child{padding-top:14px}
  .card{padding:16px}
