.landing-highlight{display:flex;flex-direction:column;gap:16px;padding:28px;border-radius:var(--radius-l);background:var(--card);border:1px solid var(--border);transition:border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-out)}
.landing-highlight:hover{border-color:color-mix(in srgb,var(--accent) 28%,var(--border));box-shadow:0 12px 32px -8px color-mix(in srgb,var(--accent) 12%,transparent);transform:translateY(-2px)}
.landing-highlight-icon{width:52px;height:52px;border-radius:14px;background:var(--brand-bg);border:1px solid color-mix(in srgb,var(--brand) 18%,transparent);color:var(--brand);display:flex;align-items:center;justify-content:center;margin-bottom:4px;transition:background var(--dur-2) var(--ease-standard),border-color var(--dur-2) var(--ease-standard)}
.landing-highlight:hover .landing-highlight-icon{background:color-mix(in srgb,var(--brand) 14%,transparent);border-color:color-mix(in srgb,var(--brand) 28%,transparent)}
.landing-highlight-icon svg{width:24px;height:24px}
.landing-highlight h3{font-size:16px;font-weight:700;letter-spacing:-.01em;line-height:1.3}
.landing-highlight p{font-size:13.5px;color:var(--t1);line-height:1.75}

/* Pricing tiers */
.landing-pricing{display:flex;flex-direction:column;gap:32px}
.landing-pricing-head{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;max-width:640px;margin:0 auto}
.landing-pricing-head h2{font-family:var(--landing-serif);font-optical-sizing:auto;font-size:clamp(24px,3vw,34px);font-weight:500;letter-spacing:-.025em;line-height:1.2}
.landing-pricing-head p{font-size:14px;color:var(--t1);line-height:1.65}
.landing-pricing-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;max-width:840px;width:100%;margin:0 auto;align-items:stretch}
.landing-tier{position:relative;display:flex;flex-direction:column;gap:14px;padding:28px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-l);box-shadow:var(--ring)}
.landing-tier-free{opacity:.85}
.landing-tier-featured{border-color:color-mix(in srgb,var(--accent) 28%,var(--border));background:var(--bg-1);box-shadow:var(--ring),0 0 0 1px color-mix(in srgb,var(--accent) 12%,transparent),0 -40px 80px -60px var(--accent-glow)}
.landing-tier-featured::before{content:'';position:absolute;inset:0;border-radius:inherit;padding:1px;background:linear-gradient(180deg,color-mix(in srgb,var(--accent) 50%,transparent),color-mix(in srgb,var(--accent) 12%,transparent) 35%,transparent 65%);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;pointer-events:none}
.landing-tier-badge{position:absolute;top:-11px;left:28px;padding:4px 10px;border-radius:999px;background:var(--accent-strong);color:var(--accent-fg);font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;display:inline-flex;align-items:center;gap:4px}
.landing-tier-badge svg{flex-shrink:0}
.landing-tier-name{font-size:13px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--t2)}
.landing-tier-price{display:flex;align-items:baseline;gap:8px}
.landing-tier-amount{font-size:clamp(32px,4vw,42px);font-weight:800;letter-spacing:-.03em;color:var(--t0)}
.landing-tier-period{font-size:13px;color:var(--t2);font-weight:500}
.landing-tier-note{font-size:12px;color:var(--accent-strong);font-weight:600;margin-top:-8px}
.landing-tier-tagline{font-size:13.5px;color:var(--t1);line-height:1.55}
.landing-tier-features{display:flex;flex-direction:column;gap:9px;margin:0;padding:0;list-style:none;flex:1}
.landing-tier-features li{display:flex;align-items:flex-start;gap:9px;font-size:13.5px;color:var(--t1);line-height:1.45}
.landing-tier-features li svg{color:var(--accent);flex-shrink:0;margin-top:2px}
.landing-tier-feature-head{font-weight:700;color:var(--t0)!important;margin-top:2px}
.landing-tier-cta{width:100%;justify-content:center;margin-top:4px}
.landing-tier-cta:disabled{opacity:.6;cursor:default}
.landing-pricing-foot{text-align:center;font-size:12px;color:var(--t3);font-family:var(--mono);letter-spacing:.02em}
@media(max-width:680px){
  .landing-pricing-grid{grid-template-columns:1fr}
}

/* Interactive icon search */
.landing-icontool{display:flex;flex-direction:column;gap:24px}
.landing-icontool-head{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;max-width:600px;margin:0 auto}
.landing-icontool-head h2{font-family:var(--landing-serif);font-optical-sizing:auto;font-size:clamp(24px,3vw,34px);font-weight:500;letter-spacing:-.025em;line-height:1.2}
.landing-icontool-head p{font-size:14px;color:var(--t1);line-height:1.65}
.landing-icontool-panel{display:flex;flex-direction:column;gap:16px;max-width:760px;width:100%;margin:0 auto;padding:20px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius-l);box-shadow:var(--warm-shadow)}
.landing-icontool-search{display:flex;align-items:center;gap:12px;padding:0 18px;border:1px solid var(--border);border-radius:999px;background:var(--bg-1);color:var(--t2);transition:border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
.landing-icontool-search:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 14%,transparent);color:var(--accent)}
.landing-icontool-search svg{flex-shrink:0;transition:color var(--dur-2) var(--ease-standard)}
.landing-icontool-search input{flex:1;border:none;background:none;padding:14px 0;font-size:15px;color:var(--t0);font-family:var(--font);min-width:0}
.landing-icontool-search input:focus{outline:none}
.landing-icontool-search input::placeholder{color:var(--t3)}
.landing-icontool-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(64px,1fr));gap:8px}
.landing-icontool-cell{position:relative;aspect-ratio:1;display:flex;align-items:center;justify-content:center;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-0);color:var(--t1);cursor:pointer;transition:all var(--dur-2) var(--ease-out)}
.landing-icontool-cell:hover{border-color:var(--accent);color:var(--accent);transform:translateY(-2px);box-shadow:var(--warm-shadow)}
.landing-icontool-cell.is-copied{border-color:var(--ok);color:var(--ok-strong)}
.landing-icontool-copied{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:color-mix(in srgb,var(--ok) 16%,var(--bg-0));color:var(--ok-strong);border-radius:var(--radius-s)}
.landing-icontool-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding-top:4px}
.landing-icontool-hint{font-size:12px;color:var(--t3);font-family:var(--mono);letter-spacing:.02em}
.landing-icontool-cta{display:inline-flex;align-items:center;gap:8px;padding:10px 20px;font-size:13px;font-weight:600;border-radius:var(--radius-l)}
.landing-icontool-cta svg{transition:transform var(--dur-2) var(--ease-out)}
.landing-icontool-cta:hover svg{transform:translateX(3px)}
@media(max-width:560px){.landing-icontool-footer{flex-direction:column-reverse;align-items:stretch;text-align:center}.landing-icontool-cta{justify-content:center}}

/* Closing CTA */
.landing-closing{display:flex;flex-direction:column;align-items:center;text-align:center;gap:18px;padding:clamp(48px,8vw,80px) clamp(24px,5vw,48px);background:color-mix(in srgb,var(--accent) 4%,var(--bg-0));border:1px solid color-mix(in srgb,var(--accent) 10%,var(--border));border-radius:var(--radius-xl);position:relative;overflow:hidden}
.landing-closing::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse 60% 70% at 50% 100%,color-mix(in srgb,var(--accent) 9%,transparent),transparent 70%);pointer-events:none}
.landing-closing h2{font-family:var(--landing-serif);font-optical-sizing:auto;font-size:clamp(30px,4vw,48px);font-weight:500;letter-spacing:-.02em;line-height:1.1;position:relative}
.landing-closing p{font-size:15px;color:var(--t1);line-height:1.65;max-width:520px;position:relative}
.landing-closing .landing-cta-row{position:relative}
.landing-closing-badge{width:48px;height:48px;border-radius:var(--radius-l);background:var(--accent-bg);border:1px solid color-mix(in srgb,var(--accent) 14%,transparent);color:var(--accent);display:flex;align-items:center;justify-content:center;position:relative}

/* Hero screenshot */
.landing-screenshot-hero{position:relative;border-radius:var(--radius-l);overflow:hidden;border:1px solid var(--border);box-shadow:0 24px 48px -12px rgba(0,0,0,.18);margin-top:-20px}
.landing-screenshot-hero img{display:block;width:100%;height:auto}

/* Footer */
.landing-footer{padding:56px clamp(20px,5vw,64px) 32px;border-top:1px solid var(--border)}
.landing-footer-inner{max-width:1100px;margin:0 auto;display:flex;flex-direction:column;gap:32px}
.landing-footer-inner>:first-child{display:flex;align-items:flex-start;justify-content:space-between;gap:32px;flex-wrap:wrap}
.landing-footer-brand{display:flex;flex-direction:column;gap:4px}
.landing-footer-mark{font-family:var(--display);font-size:18px;font-weight:600;letter-spacing:-.02em;color:var(--t0)}
.landing-footer-tagline{font-size:12px;color:var(--t3)}
.landing-footer-cols{display:flex;gap:48px;flex-wrap:wrap}
.landing-footer-col{display:flex;flex-direction:column;gap:8px;min-width:120px}
.landing-footer-col-title{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t3);margin-bottom:4px}
.landing-footer-col a,.landing-footer-link-btn{font-size:13px;color:var(--t2);text-decoration:none;font-weight:500;transition:color var(--dur-1) var(--ease-standard);background:none;border:none;cursor:pointer;font-family:var(--font);text-align:left;padding:0}
.landing-footer-col a:hover,.landing-footer-link-btn:hover{color:var(--accent-strong)}
.landing-footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:24px;border-top:1px solid var(--border);flex-wrap:wrap}
.landing-footer-copy{font-size:12px;color:var(--t3);font-family:var(--mono);letter-spacing:.02em}
.landing-footer-copy a{color:var(--t2);text-decoration:none;font-weight:600}
.landing-footer-copy a:hover{color:var(--accent-strong)}
.landing-footer-donate{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--t2);text-decoration:none;font-weight:500;transition:color var(--dur-1) var(--ease-standard)}
.landing-footer-donate:hover{color:var(--accent-strong)}
@media(max-width:640px){.landing-footer-cols{flex-direction:column;gap:24px}.landing-footer-bottom{flex-direction:column;text-align:center}}

/* ci-fade — retained: the Slice-1 colour-info popup CSS (.ci-*) was removed in
   Slice 2 (replaced by .cs-ctx / .cs-sw), but .cs-undo-toast below still
   animates with this keyframe, so it stays. */
@keyframes ci-fade{from{opacity:0}to{opacity:1}}

/* Undo toast */
.cs-undo-toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:1000;display:flex;align-items:center;gap:12px;padding:10px 16px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:0 8px 32px rgba(0,0,0,.25);animation:ci-fade var(--dur-1) var(--ease-entrance)}
.cs-undo-toast span{font-size:13px;font-weight:500;color:var(--t0)}
.cs-undo-toast button{border:none;background:none;font-family:var(--font);font-size:12px;font-weight:700;color:var(--accent-strong);cursor:pointer;padding:4px 10px;border-radius:6px;transition:background var(--dur-1) var(--ease-standard)}
.cs-undo-toast button:hover{background:var(--bg-2)}
.cs-undo-dismiss{font-size:16px!important;color:var(--t3)!important;padding:4px 6px!important}

/* Brand palettes horizontal scroll on hover */
.cs-brand-scroll{display:flex;gap:8px;overflow-x:auto;padding-bottom:8px;scroll-behavior:smooth;scrollbar-width:thin}
.cs-brand-scroll::-webkit-scrollbar{height:6px}
.cs-brand-scroll::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}

/* Gradient bento grid */
.grad-bento{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px;grid-auto-flow:dense}
.grad-bento-card{border-radius:var(--radius);overflow:hidden;border:1px solid var(--border);cursor:pointer;transition:all var(--t);display:flex;flex-direction:column}
.grad-bento-card:hover{border-color:var(--accent);box-shadow:var(--warm-shadow)}
.grad-bento-card.wide{grid-column:span 2}
.grad-bento-preview{height:90px;transition:height var(--dur-2) var(--ease-standard)}
.grad-bento-card.wide .grad-bento-preview{height:110px}
.grad-bento-info{padding:10px 12px;background:var(--card);flex:1}
.grad-bento-name{font-size:12px;font-weight:600;color:var(--t0);margin-bottom:6px}
.grad-bento-stops{display:flex;gap:4px;align-items:center;flex-wrap:wrap}
.grad-bento-stop{display:inline-flex;align-items:center;gap:3px}
.grad-bento-dot{width:10px;height:10px;border-radius:3px;border:1px solid var(--border);flex-shrink:0}
.grad-bento-hex{font-family:var(--mono);font-size:8px;font-weight:600;color:var(--t2)}
.grad-bento-pos{font-family:var(--mono);font-size:7px;color:var(--t3)}
.grad-bento-arrow{color:var(--t3);font-size:9px}
@media(max-width:700px){.grad-bento-card.wide{grid-column:span 1}.grad-bento{grid-template-columns:1fr}}

/* Landing button hover states */
/* Match button corners to the panel/card radius for a cohesive look. */
.landing .btn{border-radius:var(--radius-l)}
.landing .btn-accent:hover{opacity:1;background:var(--brand-soft);box-shadow:0 4px 16px var(--brand-glow)}

/* Monthly / yearly billing toggle — animated sliding thumb */
.landing-billing-toggle{position:relative;display:inline-flex;align-self:center;padding:4px;background:var(--bg-2);border:1px solid var(--border);border-radius:999px;gap:2px}
.landing-billing-thumb{position:absolute;top:4px;left:4px;bottom:4px;width:calc(50% - 4px);background:var(--accent);border-radius:999px;transition:transform var(--dur-3) var(--ease-out);z-index:0}
.landing-billing-toggle[data-interval="yearly"] .landing-billing-thumb{transform:translateX(100%)}
.landing-billing-opt{position:relative;z-index:1;border:none;background:none;cursor:pointer;font-family:var(--font);font-size:13px;font-weight:600;padding:8px 22px;border-radius:999px;color:var(--t2);transition:color var(--dur-2) var(--ease-standard);white-space:nowrap;display:inline-flex;align-items:center;gap:6px}
.landing-billing-opt.is-active{color:var(--accent-fg)}
.landing-billing-save{font-size:10px;font-weight:700;letter-spacing:.02em;padding:2px 7px;border-radius:999px;background:color-mix(in srgb,var(--ok) 18%,transparent);color:var(--ok-strong)}
.landing-billing-opt.is-active .landing-billing-save{background:color-mix(in srgb,var(--accent-fg) 22%,transparent);color:var(--accent-fg)}
.landing .btn:not(.btn-accent):hover{border-color:var(--accent);color:var(--accent-strong);background:var(--accent-bg);transform:translateY(-1px)}
.landing .landing-signin:hover{background:var(--accent-strong);color:var(--accent-fg);border-color:var(--accent-strong)}

/* Landing interactive demos */
.landing-demo{padding:20px;min-height:200px;display:flex;flex-direction:column;gap:12px}
.landing-demo-palette{display:flex;flex-direction:column;gap:8px}
.landing-demo-icons{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:20px}
.landing-demo-icon{aspect-ratio:1;border-radius:var(--radius-s);background:var(--bg-2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--t2);transition:all var(--dur-3) var(--ease-out);cursor:default;animation:landing-icon-pulse 3s ease-in-out infinite}
@keyframes landing-icon-pulse{0%,100%{opacity:.85;transform:scale(1)}50%{opacity:1;transform:scale(1.04)}}
html[data-reduced-motion="true"] .landing-demo-icon{animation:none}
@media(prefers-reduced-motion:reduce){html:not([data-reduced-motion="false"]) .landing-demo-icon{animation:none}}
.landing-demo-icon:hover{background:var(--accent-bg);border-color:color-mix(in srgb,var(--accent) 20%,transparent);color:var(--accent);transform:scale(1.05)}
.landing-demo-icon svg{width:22px;height:22px}
.landing-demo-tokens{padding:20px;display:flex;flex-direction:column;gap:10px}
.landing-demo-palette-head{display:flex;align-items:center;justify-content:space-between}
.landing-demo-tag{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.landing-demo-shuffle{display:inline-flex;align-items:center;gap:5px;padding:4px 9px;border-radius:999px;border:1px solid var(--border);background:transparent;color:var(--t2);font-size:10px;font-weight:600;font-family:var(--font);cursor:pointer;transition:all var(--dur-2) var(--ease-standard)}
.landing-demo-shuffle:hover{border-color:var(--accent);color:var(--accent-strong)}
.landing-demo-shuffle:active{transform:scale(.95)}
.landing-demo-input{padding:8px 11px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2);color:var(--t0);font-size:13px;font-family:var(--font);width:100%}
.landing-demo-input:focus{outline:none;border-color:var(--accent)}

/* Palette demo — static presentational styling (dynamic flex/colour/opacity
   stay inline in PaletteDemo). */
.landing-demo-pal-row{display:flex;border-radius:var(--radius);overflow:hidden;height:120px}
.landing-demo-pal-swatch{display:flex;align-items:flex-end;justify-content:center;padding-bottom:10px;transition:flex var(--dur-3) var(--ease-out);cursor:pointer}
.landing-demo-pal-hex{font-family:var(--mono);font-size:9px;font-weight:700;color:rgba(255,255,255,.92);transition:opacity var(--dur-2) var(--ease-standard);background:rgba(0,0,0,.36);padding:3px 7px;border-radius:4px;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);white-space:nowrap}
.landing-demo-pal-labels{display:flex;gap:6px}
.landing-demo-pal-label{flex:1;text-align:center;font-size:9px;font-family:var(--mono);font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--t3)}
.landing-demo-pal-tints{display:flex;gap:4px;margin-top:4px}
.landing-demo-pal-tint{flex:1;height:24px;border-radius:3px;transition:background var(--dur-4) var(--ease-standard)}
.landing-demo-pal-caption{font-size:9px;font-family:var(--mono);color:var(--t3);font-weight:600;letter-spacing:.08em;text-transform:uppercase;text-align:center}

/* Token demo — static presentational styling (dynamic colour/width/radius stay
   inline in TokenDemo). */
.landing-demo-tok-head{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--t3);margin-bottom:4px}
.landing-demo-tok-row{display:flex;align-items:center;gap:10px;cursor:default}
.landing-demo-tok-label{font-family:var(--mono);font-size:10px;font-weight:600;min-width:28px;transition:color var(--dur-2) var(--ease-standard)}
.landing-demo-tok-bar{height:6px;border-radius:3px;min-width:8px;transition:all var(--dur-3) var(--ease-out)}
.landing-demo-tok-px{font-family:var(--mono);font-size:9px;color:var(--t3);font-weight:600}
.landing-demo-tok-radius{display:flex;gap:6px;margin-top:8px}
.landing-demo-tok-chip{width:28px;height:28px;background:var(--bg-2);border:1px solid var(--border);transition:all var(--dur-2) var(--ease-standard)}
.landing-demo-tok-caption{font-family:var(--mono);font-size:9px;color:var(--t3);font-weight:600;letter-spacing:.04em}

/* Typography pairing demo — labelled heading/body so visitors see what each
   font does and why the pair works. */
.landing-demo-type{gap:14px}
.landing-type-tabs{display:flex;gap:6px;flex-wrap:wrap}
.landing-type-tab{display:inline-flex;align-items:center;gap:5px;padding:5px 12px;border-radius:999px;border:1px solid var(--border);background:transparent;color:var(--t2);font-size:11px;font-weight:600;font-family:var(--font);cursor:pointer;transition:all var(--dur-2) var(--ease-standard)}
.landing-type-tab span{color:var(--t3);font-weight:500}
.landing-type-tab:hover{border-color:var(--bh);color:var(--t1)}
.landing-type-tab.is-active{border-color:var(--accent);background:var(--accent-bg);color:var(--accent-strong)}
.landing-type-tab.is-active span{color:var(--accent-strong)}
.landing-type-stage{flex:1;display:flex;flex-direction:column;justify-content:center;gap:16px;min-height:140px}
.landing-type-row{display:flex;flex-direction:column;gap:5px}
.landing-type-role{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong)}
.landing-type-h{font-size:clamp(28px,3.6vw,42px);line-height:1.05;color:var(--t0);transition:font-family var(--dur-3) var(--ease-standard);word-break:break-word}
.landing-type-b{font-size:14px;line-height:1.65;color:var(--t1);transition:font-family var(--dur-3) var(--ease-standard);margin:0}
.landing-type-note{display:flex;align-items:center;gap:7px;font-size:11.5px;color:var(--t2);line-height:1.45}
.landing-type-note::before{content:"";flex-shrink:0;width:6px;height:6px;border-radius:50%;background:var(--t2)}

/* Scroll reveal */
.landing-reveal{opacity:0;transform:translateY(22px);transition:opacity var(--dur-5) var(--ease-out),transform var(--dur-5) var(--ease-out)}
.landing-reveal.is-shown{opacity:1;transform:none}

/* Staggered reveal — grouped children cascade in (~70ms steps) rather than
   popping in unison. The group container carries .landing-reveal; its direct
   children fade in once the parent gains .is-shown. Opacity-only so the per-tile
   hover transform stays snappy and isn't fought by the reveal transition. */
.landing-bento .landing-bento-tile,
.landing-highlights .landing-highlight{opacity:0;transition:opacity var(--dur-5) var(--ease-out),transform var(--dur-2) var(--ease-standard),border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
.landing-bento.is-shown .landing-bento-tile,
.landing-highlights.is-shown .landing-highlight{opacity:1}
.landing-bento.is-shown .landing-bento-tile:nth-child(2),
.landing-highlights.is-shown .landing-highlight:nth-child(2){transition-delay:70ms,0s,0s,0s}
.landing-bento.is-shown .landing-bento-tile:nth-child(3),
.landing-highlights.is-shown .landing-highlight:nth-child(3){transition-delay:140ms,0s,0s,0s}
.landing-bento.is-shown .landing-bento-tile:nth-child(4){transition-delay:210ms,0s,0s,0s}
.landing-bento.is-shown .landing-bento-tile:nth-child(5){transition-delay:280ms,0s,0s,0s}
.landing-bento.is-shown .landing-bento-tile:nth-child(6){transition-delay:350ms,0s,0s,0s}

html[data-reduced-motion="true"] .landing-reveal{opacity:1;transform:none;transition:none}
html[data-reduced-motion="true"] .landing-bento .landing-bento-tile,
html[data-reduced-motion="true"] .landing-highlights .landing-highlight{opacity:1;transition:border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
html[data-reduced-motion="true"] .landing-bento.is-shown .landing-bento-tile,
html[data-reduced-motion="true"] .landing-highlights.is-shown .landing-highlight{transition-delay:0ms}
@media(prefers-reduced-motion:reduce){
  html:not([data-reduced-motion="false"]) .landing-reveal{opacity:1;transform:none;transition:none}
  html:not([data-reduced-motion="false"]) .landing-bento .landing-bento-tile,
  html:not([data-reduced-motion="false"]) .landing-highlights .landing-highlight{opacity:1;transition:border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
  html:not([data-reduced-motion="false"]) .landing-bento.is-shown .landing-bento-tile,
  html:not([data-reduced-motion="false"]) .landing-highlights.is-shown .landing-highlight{transition-delay:0ms}
}

/* ─── Landing: Stats Counter ─── */
.landing-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--border);border-radius:var(--radius-l);overflow:hidden;border:1px solid var(--border)}
.landing-stat{display:flex;flex-direction:column;align-items:center;gap:4px;padding:clamp(20px,3vw,32px) 16px;background:var(--card)}
.landing-stat-num{font-size:clamp(28px,4vw,42px);font-weight:650;letter-spacing:-.03em;color:var(--t0);line-height:1;font-variant-numeric:tabular-nums}
.landing-stat-label{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--t2)}

/* ─── Landing: Sticky Scroll Features ─── */
.landing-sticky-head{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;max-width:600px;margin:0 auto 48px}
.landing-sticky-head h2{font-family:var(--landing-serif);font-optical-sizing:auto;font-size:clamp(30px,4vw,46px);font-weight:500;letter-spacing:-.02em;line-height:1.1}
.landing-sticky-head p{font-size:14px;color:var(--t1);line-height:1.65}
.landing-sticky-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(32px,5vw,64px);align-items:start}
.landing-sticky-steps{display:flex;flex-direction:column}
.landing-sticky-step{min-height:60vh;display:flex;flex-direction:column;justify-content:center;gap:14px;padding:24px 0;opacity:.2;transition:opacity var(--dur-5) var(--ease-out)}
.landing-sticky-step.is-active{opacity:1}
.landing-sticky-step:last-child{min-height:40vh}
.landing-sticky-num{font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.1em;color:var(--accent-strong)}
.landing-sticky-step h3{font-family:var(--landing-serif);font-optical-sizing:auto;font-size:clamp(22px,2.8vw,30px);font-weight:500;letter-spacing:-.02em;line-height:1.2}
.landing-sticky-step p{font-size:14px;color:var(--t1);line-height:1.7;max-width:400px}
.landing-sticky-visual{align-self:start}
.landing-sticky-visual-card{position:sticky;top:96px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius-l);box-shadow:var(--warm-shadow-lg);overflow:hidden;height:min(560px,70vh)}
.landing-sticky-demo{position:absolute;inset:0;opacity:0;transition:opacity var(--dur-5) var(--ease-out);pointer-events:none}
html[data-reduced-motion="true"] .landing-sticky-demo{transition:none}
@media(prefers-reduced-motion:reduce){html:not([data-reduced-motion="false"]) .landing-sticky-demo{transition:none}}
.landing-sticky-demo.is-active{position:relative;opacity:1;pointer-events:auto}

@media(max-width:880px){
  .landing-highlights{grid-template-columns:1fr;gap:28px}
  .landing-sticky-grid{grid-template-columns:1fr}
  .landing-sticky-visual{margin-bottom:32px}
  .landing-sticky-visual-card{position:relative;top:auto;height:auto}
  .landing-sticky-step{min-height:auto;padding:32px 0;opacity:1}
  .landing-sticky-step:last-child{min-height:auto}
  .landing-sticky-demo{position:relative;opacity:1;pointer-events:auto}
  .landing-sticky-demo:not(.is-active){display:none}
}
@media(max-width:520px){
  .landing-cta-row{flex-direction:column;align-items:stretch;width:100%}
  .landing-cta-primary,.landing-cta-secondary{justify-content:center;width:100%}
  .landing-stats{grid-template-columns:repeat(2,1fr)}
}

/* ─── Onboarding ─── */
.onb{display:flex;align-items:center;justify-content:center;min-height:100dvh;padding:24px;background:var(--bg-0)}
.onb-card{width:100%;max-width:640px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius-l);box-shadow:var(--warm-shadow-lg);padding:36px;position:relative;overflow:hidden}
.onb-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}
.onb-brand{font-family:var(--display);font-size:18px;font-weight:600;letter-spacing:-.02em;color:var(--t0)}


.onb-step{animation:onb-fade var(--dur-3) var(--ease-entrance)}
@keyframes onb-fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}

.onb-greeting{font-size:14px;color:var(--t2);margin-bottom:6px}
.onb-greeting em{font-style:normal;color:var(--t0);font-weight:600}
.onb-q{font-family:var(--display);font-size:clamp(22px,3vw,28px);font-weight:500;letter-spacing:-.02em;line-height:1.2;margin-bottom:6px;color:var(--t0)}
.onb-sub{font-size:13px;color:var(--t2);margin-bottom:20px}

.onb-options{display:flex;flex-direction:column;gap:8px}
.onb-option{display:flex;align-items:center;justify-content:space-between;width:100%;padding:14px 16px;border:1px solid var(--border);border-radius:var(--radius);background:var(--card);color:var(--t0);font-family:var(--font);font-size:14px;font-weight:500;cursor:pointer;transition:all var(--dur-2) var(--ease-out);text-align:left}
.onb-option:hover{border-color:var(--bh);background:var(--hvr);transform:translateX(3px)}
.onb-option-arrow{color:var(--t3);transition:color var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
.onb-option:hover .onb-option-arrow{color:var(--accent);transform:translateX(3px)}

.onb-back{display:inline-flex;align-items:center;gap:6px;margin-top:18px;background:none;border:none;color:var(--t2);font-size:13px;font-family:var(--font);cursor:pointer;padding:8px 0;transition:color var(--dur-2) var(--ease-standard)}
.onb-back:hover{color:var(--t0)}
.onb-back:disabled{opacity:.4;cursor:default}

/* The first-win step, where the pricing table used to be. Three real
   starting points; picking one ends onboarding and opens that tool. The
   two-column tier grid and the billing toggle went with the step. */
.onb-firstwin-step .onb-q{margin-bottom:6px}
.onb-firstwin-options{gap:10px}
.onb-firstwin-option{align-items:flex-start;padding:16px}
.onb-firstwin-text{display:flex;flex-direction:column;gap:4px;min-width:0}
.onb-firstwin-label{font-size:15px;font-weight:600;color:var(--t0);letter-spacing:-.01em}
.onb-firstwin-blurb{font-size:12.5px;font-weight:400;line-height:1.5;color:var(--t2)}
.onb-firstwin-option .onb-option-arrow{flex:none;margin-top:3px}
/* The tier truth, kept as one line rather than a table in front of someone
   who has not made anything yet. */
.onb-firstwin-foot{margin:18px 0 0;font-size:12px;color:var(--t3)}
.onb-firstwin-foot a{color:var(--t1);text-decoration:underline;text-underline-offset:2px}
.onb-firstwin-foot a:hover{color:var(--accent-strong)}


@media(max-width:520px){
  .onb-card{padding:24px 20px}
}

/* ─── UI Builder: Code tabs ─── */
.uib-code-tabs{display:flex;align-items:center;gap:2px;padding:4px 0 0;margin-bottom:-1px}
.uib-code-tab{padding:5px 14px;border:none;background:none;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);cursor:pointer;border-bottom:2px solid transparent;transition:all var(--t)}
.uib-code-tab:hover{color:var(--t0)}
.uib-code-tab.active{color:var(--accent-strong);border-bottom-color:var(--accent)}
.uib-palette-row{display:flex;gap:5px;flex-wrap:wrap;margin:2px 0 6px}
.uib-palette-swatch{width:24px;height:24px;border-radius:6px;border:1px solid var(--border);cursor:pointer;padding:0;transition:transform var(--t),box-shadow var(--t)}
.uib-palette-swatch:hover{transform:scale(1.1)}
.uib-palette-swatch.active{box-shadow:0 0 0 2px var(--bg-1),0 0 0 4px var(--brand)}
.uib-alpha-tag{display:inline-flex;align-items:center;padding:2px 8px;border-radius:var(--radius-s);font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;background:var(--brand-bg);color:var(--accent-strong);border:1px solid var(--brand);margin-left:8px;vertical-align:middle}
.uib-intro{display:flex;align-items:center;gap:12px;padding:12px 16px;border-radius:var(--radius);background:var(--brand-bg);border:1px solid rgba(59,130,246,.2);margin-bottom:20px;font-size:12px;color:var(--t0);line-height:1.5}
.uib-intro a{color:var(--accent-strong);font-weight:600}
.uib-intro-close{margin-left:auto;background:none;border:none;color:var(--t2);cursor:pointer;padding:4px;border-radius:var(--radius-s);flex-shrink:0}
.uib-intro-close:hover{color:var(--t0);background:var(--hvr)}

/* ─── Projects: Folder chips ─── */
.proj-folders{display:flex;gap:4px;margin-bottom:12px;flex-wrap:wrap}
.proj-folder-chip{padding:5px 14px;border-radius:999px;font-size:11px;font-weight:600;font-family:var(--font);border:1px solid var(--border);background:transparent;color:var(--t2);cursor:pointer;transition:all var(--t)}
.proj-folder-chip:hover{color:var(--t0);border-color:var(--bh)}
.proj-folder-chip.active{background:var(--accent-bg);border-color:var(--accent);color:var(--accent-strong)}
.proj-folder-note{margin-left:auto;align-self:center;font-size:11px;color:var(--t2)}
.proj-folder-note a{color:var(--accent-strong);font-weight:600;text-decoration:none}
.proj-folder-note a:hover{text-decoration:underline}
.proj-detail{max-width:520px}
.proj-detail-swatches{display:grid;grid-template-columns:repeat(auto-fill,minmax(84px,1fr));gap:10px}
.proj-detail-swatch{display:flex;flex-direction:column;gap:6px}
.proj-detail-swatch-chip{height:48px;border-radius:var(--radius-s);border:1px solid var(--border)}
.proj-detail-swatch-hex{font-family:var(--mono);font-size:10px;color:var(--t2);text-align:center}
.proj-detail-meta{display:flex;flex-direction:column;gap:8px}
.proj-detail-meta-row{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px}
.proj-detail-meta-row span{color:var(--t2)}
.proj-detail-meta-row strong{color:var(--t0);font-weight:600}

/* ─── Projects: Tabs ─── */
.proj-tabs{display:flex;gap:4px;margin-bottom:20px;border-bottom:1px solid var(--border)}
.proj-tab{padding:8px 16px;font-size:13px;font-weight:600;font-family:var(--font);border:none;background:transparent;color:var(--t2);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px;transition:all var(--t)}
.proj-tab:hover{color:var(--t0)}
.proj-tab.active{color:var(--accent-strong);border-bottom-color:var(--accent)}

/* ─── Projects: Cards ─── */
.proj-card{transition:transform var(--dur-2) var(--ease-standard),box-shadow var(--dur-1) var(--ease-standard)}
.proj-card:hover{transform:translateY(-2px);box-shadow:var(--warm-shadow-lg)}
.proj-card-active{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}
.proj-card-icon{position:absolute;top:12px;right:12px;width:28px;height:28px;border-radius:6px;object-fit:contain;background:rgba(255,255,255,.9);padding:3px;box-shadow:0 1px 6px rgba(0,0,0,.2)}
.proj-detail-icon{width:32px;height:32px;border-radius:6px;object-fit:contain;border:1px solid var(--border);background:var(--bg-2);padding:2px}
.proj-detail-icon-lg{width:56px;height:56px;border-radius:8px;object-fit:contain;border:1px solid var(--border);background:var(--bg-2);padding:4px}
.proj-detail-icon-empty{display:flex;align-items:center;justify-content:center;color:var(--t2);font-size:20px}

/* New project modal */
.proj-new-modal{max-width:460px}
.proj-new-folders{display:flex;flex-wrap:wrap;gap:6px}
.proj-new-start{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.proj-new-start-opt{display:flex;flex-direction:column;gap:4px;text-align:left;padding:12px 14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-1);cursor:pointer;transition:border-color var(--dur-1) var(--ease-standard),background var(--dur-1) var(--ease-standard)}
.proj-new-start-opt:hover{border-color:var(--brand)}
.proj-new-start-opt.active{border-color:var(--brand);background:var(--brand-bg)}
.proj-new-start-opt strong{font-size:13px;font-weight:700;color:var(--t0)}
.proj-new-start-opt span{font-size:11px;color:var(--t2);line-height:1.4}
@media(max-width:520px){.proj-new-start{grid-template-columns:1fr}}

/* ─── Admin Dashboard ─── */
.adm{max-width:1200px}
.adm-header{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px;margin-bottom:24px}
.adm-header-left h1{font-family:var(--display);font-size:clamp(28px,5vw,36px);font-weight:500;letter-spacing:-.03em;margin-bottom:4px}
.adm-status{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--ok-strong)}
.adm-status-dot{width:6px;height:6px;border-radius:50%;background:var(--ok);animation:adm-pulse 2s infinite}
@keyframes adm-pulse{0%,100%{opacity:1}50%{opacity:.4}}
.adm-actions{display:flex;gap:6px;flex-wrap:wrap}

/* Admin tabs */
.adm-tabs{display:flex;gap:2px;padding:3px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius);margin-bottom:28px;flex-wrap:wrap}
.adm-tab{padding:8px 16px;font-size:12px;font-weight:600;font-family:var(--font);border:none;background:transparent;color:var(--t2);cursor:pointer;border-radius:var(--radius-s);transition:all var(--dur-2) var(--ease-standard);position:relative;white-space:nowrap}
.adm-tab:hover{color:var(--t0);background:var(--hvr)}
.adm-tab.active{color:var(--t0);background:var(--card);box-shadow:0 1px 3px rgba(0,0,0,.08)}
.adm-tab-badge{margin-left:6px;padding:1px 7px;border-radius:10px;font-size:10px;font-weight:700;background:var(--accent-strong);color:var(--accent-fg)}

/* Time filter */
.adm-time-filter{display:flex;gap:2px;padding:2px;background:var(--bg-2);border-radius:var(--radius-s)}
.adm-time-btn{padding:5px 12px;font-size:11px;font-weight:600;font-family:var(--font);border:none;background:transparent;color:var(--t2);cursor:pointer;border-radius:var(--radius-xs,4px);transition:all var(--dur-2) var(--ease-standard)}
.adm-time-btn:hover{color:var(--t0)}
.adm-time-btn.active{color:var(--t0);background:var(--card);box-shadow:0 1px 2px rgba(0,0,0,.06)}

/* Section header */
.adm-section{margin-bottom:32px}
.adm-section-h{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px;flex-wrap:wrap}
.adm-section-title{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700;letter-spacing:-.01em;color:var(--t0)}
.adm-section-bar{width:20px;height:2px;border-radius:1px;background:var(--accent)}

/* Stat cards */
.adm-stats{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px}
.adm-stat{padding:18px 20px;border-radius:var(--radius);background:var(--card-grad);border:1px solid var(--border);box-shadow:var(--warm-shadow);transition:border-color var(--dur-1) var(--ease-standard)}
.adm-stat:hover{border-color:color-mix(in srgb,var(--accent) 30%,var(--border))}
.adm-stat-value{font-size:28px;font-weight:800;letter-spacing:-.03em;line-height:1;color:var(--t0)}
.adm-stat-label{font-size:11px;font-weight:600;color:var(--t2);margin-top:8px;letter-spacing:.02em}
.adm-stat-sub{font-size:10px;color:var(--t3);margin-top:3px}
.adm-stat-delta{display:inline-flex;align-items:center;gap:3px;font-size:10px;font-weight:700;padding:2px 6px;border-radius:4px;margin-left:8px}
.adm-stat-delta.up{color:var(--ok-strong);background:rgba(16,185,129,.1)}
.adm-stat-delta.down{color:var(--err-strong);background:rgba(239,68,68,.1)}
.adm-stat-delta.neutral{color:var(--t3);background:var(--bg-2)}

/* Grid layouts */
.adm-grid-2{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(360px,100%),1fr));gap:14px}
.adm-grid-3{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(280px,100%),1fr));gap:14px}

/* Card variants */
.adm-card{background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--warm-shadow);overflow:hidden}
.adm-card-header{padding:16px 20px 12px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:8px}
.adm-card-title{font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--t2)}
.adm-card-body{padding:16px 20px}
.adm-card-body.compact{padding:12px 16px}

/* Chart wrapper */
.adm-chart{width:100%;position:relative}
.adm-chart svg{display:block;width:100%;overflow:visible}

/* Bar chart */
.adm-bar{display:flex;flex-direction:column;gap:10px}
.adm-bar-row{display:flex;align-items:center;gap:10px}
.adm-bar-label{font-size:11px;font-weight:500;color:var(--t1);width:100px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex-shrink:0;font-family:var(--mono)}
.adm-bar-track{flex:1;height:8px;border-radius:4px;background:var(--bg-2);overflow:hidden}
.adm-bar-fill{height:100%;border-radius:4px;background:var(--accent);transition:width var(--dur-4) var(--ease-standard)}
.adm-bar-value{font-size:11px;font-weight:700;color:var(--t2);width:40px;text-align:right;flex-shrink:0;font-family:var(--mono)}

/* Donut chart */
.adm-donut-wrap{display:flex;align-items:center;gap:20px;flex-wrap:wrap}
.adm-donut-legend{display:flex;flex-direction:column;gap:6px;flex:1;min-width:120px}
.adm-donut-item{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--t1)}
.adm-donut-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0}
.adm-donut-count{margin-left:auto;font-weight:700;font-family:var(--mono);color:var(--t0)}

/* Data list */
.adm-list{display:flex;flex-direction:column}
.adm-list-row{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid var(--border);gap:10px}
.adm-list-row:last-child{border-bottom:none}
.adm-list-rank{width:20px;font-size:10px;font-weight:700;color:var(--t3);text-align:center;flex-shrink:0}
.adm-list-name{font-size:12px;font-weight:500;color:var(--t0);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.adm-list-name.mono{font-family:var(--mono)}
.adm-list-value{font-size:12px;font-weight:700;color:var(--accent-strong);font-family:var(--mono);flex-shrink:0}

/* Activity feed */
.adm-feed{display:flex;flex-direction:column;gap:0}
.adm-feed-item{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)}
.adm-feed-item:last-child{border-bottom:none}
.adm-feed-dot{width:8px;height:8px;border-radius:50%;margin-top:5px;flex-shrink:0}
.adm-feed-body{flex:1;min-width:0}
.adm-feed-text{font-size:12px;color:var(--t0);font-weight:500}
.adm-feed-meta{font-size:10px;color:var(--t3);margin-top:2px}

/* Badge */
.adm-badge{display:inline-flex;align-items:center;font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;padding:2px 8px;border-radius:4px;white-space:nowrap}

/* Table */
.adm-table{width:100%;border-collapse:collapse;min-width:fit-content}
.adm-table-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch}
.adm-table thead th{text-align:left;font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2);padding:10px 14px;border-bottom:1px solid var(--border);background:var(--bg-1)}
.adm-table tbody td{font-size:12px;padding:10px 14px;border-bottom:1px solid var(--border);color:var(--t0)}
.adm-table tbody tr:last-child td{border-bottom:none}
.adm-table tbody tr:nth-child(even){background:var(--bg-1)}
.adm-table .mono{font-family:var(--mono)}
.adm-table .bold{font-weight:600}
.adm-table .accent{color:var(--accent-strong);font-weight:700}

/* Checklist */
.adm-checklist{display:flex;flex-direction:column;gap:0}
.adm-check-row{display:flex;align-items:flex-start;gap:12px;padding:12px 0;border-bottom:1px solid var(--border)}
.adm-check-row:last-child{border-bottom:none}
.adm-check-icon{width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px}
.adm-check-icon.done{background:rgba(16,185,129,.1)}
.adm-check-icon.pending{background:color-mix(in srgb,var(--pending) 12%,transparent)}
.adm-check-label{font-size:12px;font-weight:600;color:var(--t0)}
.adm-check-note{font-size:11px;color:var(--t2);margin-top:2px;line-height:1.5}

/* Colour swatch list */
.adm-swatch-row{display:flex;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--border)}
.adm-swatch-row:last-child{border-bottom:none}
.adm-swatch{width:24px;height:24px;border-radius:var(--radius-s);border:1px solid var(--border);flex-shrink:0}
.adm-swatch-grid{display:flex;flex-wrap:wrap;gap:4px}
.adm-swatch-grid .adm-swatch{cursor:default;transition:transform var(--dur-2) var(--ease-standard)}
.adm-swatch-grid .adm-swatch:hover{transform:scale(1.15)}

/* Empty state */
.adm-empty{padding:32px 16px;text-align:center;font-size:13px;color:var(--t3)}

/* Pipeline tab */
.adm-pipe-bar{height:5px;border-radius:var(--radius-pill);background:var(--bg-2);overflow:hidden}
.adm-pipe-bar-fill{display:block;height:100%;border-radius:var(--radius-pill);transition:width var(--t)}
.adm-pipe-todo{display:flex;align-items:flex-start;gap:12px;padding:12px 14px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius-s);transition:border-color var(--dur-1) var(--ease-standard)}
.adm-pipe-todo:hover{border-color:color-mix(in srgb,var(--accent) 30%,var(--border))}
.adm-pipe-prio{flex-shrink:0;font-size:10px;font-weight:800;letter-spacing:.04em;font-family:var(--mono);padding:3px 7px;border:1px solid;border-radius:var(--radius-xs,4px);line-height:1}
.adm-pipe-status{font-size:10px;font-weight:700;letter-spacing:.03em;padding:3px 9px;border-radius:var(--radius-pill);white-space:nowrap}

/* Submission cards */
.adm-submission{border-left:3px solid var(--border);transition:opacity var(--dur-2) var(--ease-standard)}
.adm-submission.done{opacity:.7}
.adm-submission-head{padding:14px 16px;cursor:pointer;display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.adm-submission-badges{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:6px}
.adm-submission-title{font-size:14px;font-weight:600;color:var(--t0);margin-bottom:2px}
.adm-submission-preview{font-size:12px;color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.adm-submission-preview.expanded{white-space:normal}
.adm-submission-body{padding:0 16px 16px;border-top:1px solid var(--border);padding-top:14px}
.adm-submission-msg{font-size:13px;line-height:1.7;color:var(--t0);margin-bottom:12px;white-space:pre-wrap}
.adm-submission-notes{background:var(--bg-2);border-radius:var(--radius-s);padding:12px;margin-bottom:12px}
.adm-submission-notes-title{font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);margin-bottom:8px}
.adm-submission-actions{display:flex;gap:6px;flex-wrap:wrap}

/* Prompt admin cards */
.adm-prompt{border-left:3px solid var(--border);margin-bottom:8px}
.adm-prompt-header{display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap}
.adm-prompt-tags{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:8px}
.adm-prompt-tag{font-size:10px;padding:2px 8px;border-radius:4px;background:var(--bg-2);color:var(--t2);font-weight:600}
.adm-prompt-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;border-top:1px solid var(--border);padding-top:10px}

/* Sparkline */
.adm-sparkline{display:flex;align-items:end;gap:2px;height:32px}
.adm-sparkline-bar{flex:1;border-radius:2px 2px 0 0;background:var(--accent);opacity:.6;transition:opacity var(--dur-1) var(--ease-standard),height var(--dur-3) var(--ease-standard)}
.adm-sparkline-bar:hover{opacity:1}

/* Verify error banner */
.adm-verify-error{padding:16px;border-left:3px solid var(--err);margin-bottom:20px}

/* Lock screen */
.adm-lock{max-width:400px;margin:80px auto;text-align:center}
.adm-lock-eyebrow{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong);margin-bottom:16px;font-family:var(--mono)}
.adm-lock h1{font-size:28px;font-weight:800;letter-spacing:-.03em;margin-bottom:8px}
.adm-lock p{font-size:14px;color:var(--t1);margin-bottom:24px}
.adm-lock form{display:flex;gap:8px}
.adm-lock input{flex:1;text-align:center;font-size:14px;letter-spacing:.04em}

/* Stripe panel */
.adm-stripe-desc{font-size:13px;color:var(--t1);line-height:1.7;margin-bottom:4px}
.adm-stripe-tip{font-size:11px;color:var(--t3);margin-bottom:16px}
.adm-stripe-table{width:100%;border-collapse:collapse;min-width:360px}
.adm-stripe-table th{text-align:left;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);padding:8px 10px;border-bottom:1px solid var(--border)}
.adm-stripe-table td{padding:8px 10px;border-bottom:1px solid var(--border)}
.adm-stripe-input{display:flex;align-items:center;gap:4px}
.adm-stripe-input span{font-size:11px;color:var(--t3);min-width:24px}
.adm-stripe-input input{width:90px;font-size:12px;font-family:var(--mono)}
.adm-stripe-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:16px}
.adm-stripe-env{font-size:12px;font-family:var(--mono);line-height:2.2;color:var(--t1)}
.adm-stripe-env span{color:var(--t3)}
.adm-stripe-autofill{display:flex;align-items:center;gap:8px;margin-top:14px;font-size:12px;color:var(--t1);cursor:pointer;line-height:1.5}
.adm-stripe-autofill input{accent-color:var(--accent);flex-shrink:0}

/* Overview category blocks */
.adm-cat{padding:20px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--card-grad);margin-bottom:24px;display:flex;flex-direction:column;gap:16px}
.adm-cat-head{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;padding-bottom:12px;border-bottom:1px solid var(--border)}
.adm-cat-title{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:700;letter-spacing:-.01em;color:var(--t0)}
.adm-cat-desc{font-size:11px;color:var(--t3)}

/* Users tab — masked emails, flags, sorting, filters */
.adm-mask{display:inline-flex;align-items:center;gap:6px;max-width:100%}
.adm-mask-text{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.adm-mask-blur{filter:blur(4px);user-select:none;-webkit-user-select:none;opacity:.8}
.adm-eye-btn{display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;padding:0;border:none;background:none;border-radius:var(--radius-s);color:var(--t3);cursor:pointer;flex-shrink:0;transition:color var(--dur-1) var(--ease-standard),background var(--dur-1) var(--ease-standard)}
.adm-eye-btn:hover{color:var(--t0);background:var(--bg-2)}
.adm-user-sub{font-size:11px;color:var(--t3);margin-top:3px}
.adm-flag{font-size:15px;line-height:1}
.adm-flag-cell{display:inline-flex;align-items:center;gap:6px;cursor:default;font-family:var(--mono);font-size:11px}
.adm-th-sort{display:inline-flex;align-items:center;gap:4px;padding:0;border:none;background:none;font-family:var(--font);font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2);cursor:pointer;transition:color var(--dur-1) var(--ease-standard)}
.adm-th-sort:hover{color:var(--t0)}
.adm-th-sort.active{color:var(--accent-strong)}
.adm-th-arrow{font-size:10px;opacity:.75}
.adm-country-chips{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}
.adm-country-chip{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border:1px solid var(--border);border-radius:var(--radius-pill);background:transparent;font-family:var(--font);font-size:11px;font-weight:600;color:var(--t2);cursor:pointer;transition:color var(--dur-1) var(--ease-standard),border-color var(--dur-1) var(--ease-standard),background var(--dur-1) var(--ease-standard)}
.adm-country-chip:hover{color:var(--t0);background:var(--bg-2)}
.adm-country-chip.active{color:var(--t0);border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,transparent)}
.adm-users-toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}
.adm-search{flex:1 1 220px;min-width:180px;font-size:12px}
.adm-users-table td{vertical-align:top}
.adm-plan-pro{background:rgba(16,185,129,.12);color:var(--ok-strong)}
.adm-plan-free{background:var(--bg-2);color:var(--t2)}

/* Submissions toolbar */
.adm-sub-summary{display:flex;align-items:center;gap:14px;flex-wrap:wrap;font-size:11px;font-weight:600}
.adm-sub-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:16px}

@media(max-width:768px){
  .adm-stats{grid-template-columns:repeat(auto-fill,minmax(140px,1fr))}
  .adm-stat-value{font-size:24px}
  .adm-grid-2{grid-template-columns:1fr}
  .adm-tabs{gap:1px}
  .adm-tab{padding:6px 12px;font-size:11px}
  .adm-bar-label{width:70px;font-size:10px}
}
@media(max-width:480px){
  .adm-stats{grid-template-columns:repeat(2,1fr)}
  .adm-stat{padding:14px}
  .adm-stat-value{font-size:20px}
}

/* ─── File Converter (fc-) ─── */
/* Mode tabs — a segmented switch (matches the Aspect Ratio tool's .rc-tabs). */
.fc-tabs{display:inline-flex;flex-wrap:wrap;gap:2px;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-pill);margin-bottom:24px}
.fc-tab{position:relative;display:inline-flex;align-items:center;gap:6px;padding:7px 15px;border:none;background:none;border-radius:var(--radius-pill);font-family:var(--font);font-size:12px;font-weight:600;color:var(--t2);cursor:pointer;transition:background var(--t),color var(--t)}
.fc-tab:hover{color:var(--t0)}
.fc-tab.on{background:var(--card);color:var(--t0);box-shadow:var(--ring)}
.fc-soon{font-size:8px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;padding:1px 6px;border-radius:999px;background:var(--bg-3);color:var(--t3)}
/* Alpha badge — token-driven accent pill (no hardcoded colours). */
.fc-alpha{font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;padding:2px 8px;border-radius:var(--radius-s);background:var(--accent-strong);color:var(--accent-fg);margin-left:10px;vertical-align:middle}
.fc-drop{cursor:pointer;transition:border-color var(--t),background var(--t),transform var(--dur-2) var(--ease-out),box-shadow var(--dur-2) var(--ease-out)}
.fc-drop:hover{transform:translateY(-2px);box-shadow:var(--warm-shadow-lg)}
.fc-drop-ico{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;margin-bottom:12px;border-radius:var(--radius);background:var(--accent-bg);color:var(--accent)}
.fc-drop-ico svg{width:22px;height:22px}
.fc-drop-hint{font-size:14px;font-weight:600;color:var(--t0);margin-bottom:4px}
.fc-drop-sub{font-size:11px;color:var(--t2)}
.fc-drop-on{border-color:var(--brand)!important;background:var(--brand-bg)!important;transform:translateY(-2px);box-shadow:var(--warm-shadow-lg)}
.fc-card{display:flex;flex-direction:column;gap:8px;padding:12px;position:relative;align-items:stretch}
.fc-remove{position:absolute;top:8px;right:8px;width:24px;height:24px;display:flex;align-items:center;justify-content:center;border:none;border-radius:50%;background:var(--bg-3);color:var(--t1);font-size:16px;line-height:1;cursor:pointer;transition:all var(--t);z-index:2}
.fc-remove:hover{background:var(--err);color:var(--err-fg)}
.fc-remove:disabled{opacity:.4;cursor:not-allowed}
.fc-thumb{width:100%;aspect-ratio:16/10;border-radius:var(--radius-s);overflow:hidden;background:var(--bg-2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center}
.fc-thumb img{width:100%;height:100%;object-fit:contain}
.fc-name{font-size:12px;font-weight:600;color:var(--t0);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fc-dl{width:100%;justify-content:center;margin-top:auto}
.fc-video{width:100%;max-height:380px;border-radius:var(--radius);background:#000;display:block}
.fc-status{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--t2);margin-top:10px}
.fc-status-err{color:var(--err-strong)}
.fc-progress{height:8px;background:var(--bg-3);border-radius:999px;overflow:hidden;margin-top:10px}
.fc-progress-bar{height:100%;background:var(--brand);border-radius:999px;transition:width var(--dur-2) var(--ease-out)}
.fc-soon-card{padding:36px 28px;text-align:left;border-style:dashed}
.fc-soon-badge{display:inline-block;font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;padding:4px 12px;border-radius:999px;background:linear-gradient(135deg,var(--brand),var(--brand-soft));color:var(--accent-fg);margin-bottom:14px}
.fc-spinner{display:inline-block;width:14px;height:14px;border:2px solid var(--border);border-top-color:var(--brand);border-radius:50%;animation:fc-spin .7s linear infinite;flex-shrink:0}
@keyframes fc-spin{to{transform:rotate(360deg)}}
.fc-settings{display:flex;gap:16px;margin-top:10px;flex-wrap:wrap;align-items:flex-start}
.fc-actions{display:flex;align-items:center;gap:8px;margin-top:14px;flex-wrap:wrap}
.fc-note{font-size:10px;color:var(--t2);margin-top:2px}
/* States what a homepage output draft actually became here — including the part
   this converter cannot honour. Never a success claim: nothing is converted yet. */
.fc-draft-note{margin-top:12px;padding:10px 14px;border:1px solid color-mix(in srgb,var(--accent) 32%,var(--border));border-radius:var(--radius-s);background:color-mix(in srgb,var(--accent) 7%,var(--bg-1));font-size:var(--fs-caption);line-height:1.5;color:var(--t1)}
.fc-draft-note strong{color:var(--t0);font-weight:650}
.fc-field-grow{flex:1;min-width:200px}
.fc-bg-pick{width:42px;height:30px;padding:2px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2);cursor:pointer}

@media(max-width:768px){
  .fc-tabs{gap:4px}
  .fc-tab{padding:6px 12px;font-size:12px}
  .fc-video{max-height:260px}
  .fc-soon-card{padding:24px 18px}
  .fc-soon-card h2{font-size:20px}
  .fc-soon-card p{font-size:13px}
}
@media(max-width:480px){
  .fc-tabs{gap:2px}
  .fc-tab{padding:5px 10px;font-size:11px}
  .fc-card{padding:10px}
  .fc-video{max-height:200px}
  .fc-soon-card{padding:20px 14px}
  .fc-soon-card h2{font-size:18px}
  .fc-drop{padding:28px 14px}
}

/* ── Keyboard Shortcuts Overlay ─────────────────────────────── */
.kbd-overlay{position:fixed;inset:0;background:var(--scrim);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);z-index:9999;display:flex;justify-content:center;align-items:center;animation:cp-fade var(--dur-1) var(--ease-entrance)}
.kbd-panel{background:var(--card);border:1px solid var(--border);border-radius:var(--radius-xl);width:min(420px,calc(100vw - 32px));box-shadow:var(--warm-shadow-lg);overflow:hidden;animation:cp-rise var(--dur-2) var(--ease-entrance)}
.kbd-header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px 14px;border-bottom:1px solid var(--border)}
.kbd-header h3{margin:0;font-size:15px;font-weight:600;color:var(--t0)}
.kbd-close{background:none;border:none;cursor:pointer;color:var(--t2);font-size:16px;padding:4px 6px;border-radius:var(--radius-s);line-height:1}
.kbd-close:hover{background:var(--bg-2);color:var(--t0)}
.kbd-list{list-style:none;margin:0;padding:10px 22px 18px}
.kbd-row{display:flex;align-items:center;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--border)}
.kbd-row:last-child{border-bottom:none}
.kbd-keys{display:flex;align-items:center;gap:4px;flex-shrink:0}
.kbd-key{font-family:var(--mono);font-size:11px;color:var(--t1);background:var(--bg-2);padding:3px 8px;border-radius:var(--radius-s);border:1px solid var(--border);white-space:nowrap}
.kbd-plus{color:var(--t3);font-size:11px;margin:0 1px}
.kbd-desc{color:var(--t1);font-size:13px;text-align:right}
@media(max-width:480px){
  .kbd-panel{width:calc(100vw - 24px)}
  .kbd-header{padding:14px 16px 10px}
  .kbd-list{padding:8px 16px 14px}
  .kbd-desc{font-size:12px}
}

/* Aspect Ratio Calculator */
.rc-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start}
.rc-panel{padding:20px;overflow:visible}
/* Preset category tabs — a compact segmented switch above the chip grid. */
.rc-tabs{display:inline-flex;gap:2px;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-pill);margin-bottom:14px}
.rc-tab{padding:6px 14px;border:none;background:none;border-radius:var(--radius-pill);font-family:var(--font);font-size:11px;font-weight:600;color:var(--t2);cursor:pointer;transition:background var(--t),color var(--t)}
.rc-tab:hover{color:var(--t0)}
.rc-tab.on{background:var(--card);color:var(--t0);box-shadow:var(--ring)}
.rc-presets{display:flex;flex-wrap:wrap;gap:6px}
.rc-field{margin-top:18px}
.rc-known{display:flex;flex-direction:column;gap:8px}
.rc-known input{width:100%}
.rc-ratio-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.rc-ratio-row input{width:88px}
.rc-flip{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;flex-shrink:0;border:1px solid var(--border);background:var(--bg-1);color:var(--t2);border-radius:var(--radius-s);cursor:pointer;transition:all var(--t)}
.rc-flip svg{width:15px;height:15px}
.rc-flip:hover{background:var(--accent-bg);border-color:var(--accent);color:var(--accent)}
.rc-colon{font-weight:700;color:var(--t2)}
.rc-simplified{font-family:var(--mono);font-size:13px;color:var(--accent-strong);margin-left:6px}
.rc-out{margin-top:18px;padding-top:16px;border-top:1px solid var(--border)}
.rc-out-size{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:6px;flex-wrap:wrap}
.rc-result-dims{display:flex;align-items:center;gap:10px}
.rc-dim{display:inline-flex;align-items:baseline;gap:3px;font-family:var(--mono);font-size:22px;font-weight:700;color:var(--t0);background:none;border:none;cursor:pointer;padding:4px 8px;border-radius:var(--radius-s)}
.rc-dim:hover{background:var(--accent-bg);color:var(--accent)}
.rc-dim small{font-size:11px;color:var(--t3);font-weight:500}
.rc-times{color:var(--t3);font-size:18px}
.rc-vis-panel{display:flex;flex-direction:column}
/* The visualiser STICKS while the controls scroll past it. Measured at 834px:
   the control column is 1225px tall and this panel 343px, so 882px of the right
   rail was empty — and the thing left behind at the top was the preview of the
   ratio the controls below it are editing. Sticky turns the dead rail into the
   reason the two columns exist: you can see the shape change while you change
   it. `.tt-config` and `.fpr-config` are the same decision on the same shape of
   page, so this is the house pattern rather than a new one.
   Only above 760px, where the grid is genuinely two columns — stacked, a sticky
   panel would cover the controls it is meant to be previewing. */
@media(min-width:761px){
  .rc-vis-panel{position:sticky;top:calc(var(--nav-clear) + var(--s-4))}
}
.rc-vis-head{display:flex;align-items:center;justify-content:space-between}
.rc-vis-tag{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2);background:var(--bg-2);border:1px solid var(--border);padding:2px 8px;border-radius:var(--radius-pill)}
.rc-vis-stage{flex:1;display:flex;align-items:center;justify-content:center;min-height:280px;padding:20px}
.rc-vis-box{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;border:2px solid var(--accent);background:var(--accent-bg);border-radius:var(--radius-s);transition:width var(--dur-3) var(--ease-out),height var(--dur-3) var(--ease-out)}
.rc-vis-diag{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.rc-vis-diag line{stroke:var(--accent);stroke-width:1;stroke-dasharray:4 4;opacity:.45}
.rc-vis-ratio{font-family:var(--mono);font-size:14px;font-weight:700;color:var(--accent-strong)}
.rc-vis-dims{font-family:var(--mono);font-size:10px;font-weight:500;color:var(--accent-strong);opacity:.7}
.rc-vis-empty{color:var(--t3);font-size:13px}

/* Aspect & Resolution Calculator — preset dropdowns, stats, ratio grid */
.arc-select{position:relative}
.arc-select-btn{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;padding:10px 12px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-s);font-family:var(--font);text-align:left;cursor:pointer;transition:border-color var(--t)}
.arc-select-btn:hover{border-color:var(--accent)}
.arc-select-ph{font-size:13px;color:var(--t3)}
.arc-select-chev{width:14px;height:14px;flex-shrink:0;color:var(--t3)}
.arc-select-pop{position:absolute;top:calc(100% + 6px);left:0;right:0;z-index:30;max-height:320px;overflow:auto;padding:6px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow-l)}
.arc-opt{display:block;width:100%;padding:8px 10px;border:none;background:none;border-radius:var(--radius-s);font-family:var(--font);text-align:left;cursor:pointer;transition:background var(--t)}
.arc-opt:hover{background:var(--bg-2)}
.arc-opt.on{background:var(--accent-bg)}
.arc-opt-row{display:flex;align-items:center;gap:10px;min-width:0}
.arc-opt-text{display:flex;flex-direction:column;gap:1px;min-width:0}
.arc-opt-name{font-size:13px;font-weight:600;color:var(--t0);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.arc-opt-meta{font-family:var(--mono);font-size:10.5px;color:var(--t3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.arc-thumb{display:inline-flex;align-items:center;justify-content:center;width:26px;height:18px;flex-shrink:0}
.arc-thumb-big{width:48px;height:34px}
.arc-thumb-box{border:1.5px solid var(--accent);background:var(--accent-bg);border-radius:2px}
.arc-note{margin:8px 0 0;font-size:11.5px;color:var(--t3)}
.arc-ratio-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:8px;margin-top:12px}
.arc-ratio-card{display:flex;flex-direction:column;align-items:center;gap:4px;padding:12px 8px 10px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-s);font-family:var(--font);cursor:pointer;transition:border-color var(--t),background var(--t)}
.arc-ratio-card:hover{border-color:var(--accent)}
.arc-ratio-card.on{border-color:var(--accent);background:var(--accent-bg)}
.arc-ratio-card-name{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--t0)}
/* --t2, not --t3: at 10px on the card ground this measured 4.32:1 in dark
   (#8e8e88 on #232b38), just under AA. --t2 takes it to 5.35:1 and light
   improves with it. --t3 is the FAINTEST ink and is sized for larger text. */
.arc-ratio-card-use{font-size:10px;color:var(--t2);text-align:center;line-height:1.3}
.arc-ppi-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.arc-ppi-field{display:inline-flex;align-items:center;gap:6px}
.arc-ppi-field input{width:88px}
.arc-ppi-field span{font-family:var(--mono);font-size:11px;color:var(--t3)}
.arc-ppi-or{font-size:11.5px;color:var(--t3)}
.arc-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-top:14px}
.arc-stat{display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:8px 10px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-s);font-family:var(--font);text-align:left;cursor:pointer;transition:border-color var(--t)}
.arc-stat:hover{border-color:var(--accent)}
.arc-stat-k{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t3)}
.arc-stat-v{font-family:var(--mono);font-size:13.5px;font-weight:600;color:var(--t0)}
.arc-stat-sub{font-family:var(--mono);font-size:10px;color:var(--accent-strong)}
@media(max-width:760px){.rc-grid{grid-template-columns:1fr}.rc-vis-stage{min-height:200px}.rc-tabs{display:flex;flex-wrap:wrap}}

/* Future Plans — admin roadmap board */
.fp-wrap{max-width:920px;margin:0 auto;display:flex;flex-direction:column;gap:24px}
.fp-head-eyebrow{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--accent-strong);margin-bottom:8px}
.fp-head-title{font-size:30px;font-weight:700;letter-spacing:-.02em;color:var(--t0);margin:0 0 6px}
.fp-head-sub{font-size:13.5px;color:var(--t2);line-height:1.6;margin:0;max-width:560px}
.fp-filters{display:flex;flex-wrap:wrap;gap:6px}
.fp-filter{padding:6px 14px;border-radius:var(--radius-pill);font-size:12px;font-weight:600;font-family:var(--font);cursor:pointer;border:1px solid var(--border);background:var(--bg-2);color:var(--t1);transition:all var(--t)}
.fp-filter:hover{border-color:var(--bh);color:var(--t0)}
.fp-filter.is-active{background:var(--accent-strong);border-color:var(--accent-strong);color:var(--accent-fg)}
.fp-group{display:flex;flex-direction:column;gap:12px}
.fp-group-head{display:flex;align-items:center;gap:10px}
.fp-group-label{font-size:13px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--t1);margin:0}
.fp-group-count{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--t3);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-pill);padding:1px 9px}
.fp-dot{width:9px;height:9px;border-radius:50%;flex-shrink:0}
.fp-dot-progress{background:var(--accent)}
.fp-dot-planned{background:var(--t2)}
.fp-dot-exploring{background:var(--warn)}
.fp-dot-shipped{background:var(--ok)}
.fp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px}
.fp-card{background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);padding:18px;box-shadow:var(--warm-shadow);transition:border-color var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
.fp-card:hover{border-color:var(--bh);transform:translateY(-2px)}
.fp-card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:8px}
.fp-card-title{font-size:14px;font-weight:650;color:var(--t0);margin:0;line-height:1.35}
.fp-card-tag{flex-shrink:0;font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent-strong);background:var(--accent-bg);border-radius:var(--radius-s);padding:3px 8px}
.fp-card-desc{font-size:12.5px;color:var(--t2);line-height:1.6;margin:0}
@media(max-width:560px){.fp-grid{grid-template-columns:1fr}.fp-head-title{font-size:24px}}

/* Community Hub */
.ch-wrap{max-width:1080px;margin:0 auto;display:flex;flex-direction:column;gap:20px}
.ch-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap}
.ch-title{font-size:28px;font-weight:700;letter-spacing:-.02em;color:var(--t0);margin:0 0 6px}
.ch-sub{font-size:13.5px;color:var(--t2);line-height:1.6;margin:0;max-width:560px}
.ch-submit-btn{flex-shrink:0}
.ch-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.ch-filters{display:flex;flex-wrap:wrap;gap:6px}
.ch-filter{padding:6px 14px;border-radius:var(--radius-pill);font-size:12px;font-weight:600;font-family:var(--font);cursor:pointer;border:1px solid var(--border);background:var(--bg-2);color:var(--t1);transition:all var(--t)}
.ch-filter:hover{border-color:var(--bh);color:var(--t0)}
.ch-filter.is-active{background:var(--accent-strong);border-color:var(--accent-strong);color:var(--accent-fg)}
.ch-sort{display:flex;gap:2px;background:var(--bg-2);border-radius:var(--radius-pill);padding:3px;flex-shrink:0}
.ch-sort-btn{padding:5px 14px;border-radius:var(--radius-pill);font-size:12px;font-weight:600;border:none;cursor:pointer;background:transparent;color:var(--t2);font-family:var(--font);transition:all var(--dur-2) var(--ease-standard)}
.ch-sort-btn.is-active{background:var(--accent-strong);color:var(--accent-fg)}
.ch-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px}
.ch-card{position:relative;background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);overflow:hidden;box-shadow:var(--warm-shadow);transition:border-color var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
.ch-card:hover{border-color:var(--bh);transform:translateY(-3px)}
.ch-thumb{display:flex;align-items:center;justify-content:center;height:150px;text-decoration:none!important;position:relative;background:linear-gradient(135deg,var(--c1,var(--accent)),var(--c2,var(--accent-strong)))}
/* Ink and glow are set PER CARD by CommunityCard.jsx from that card's own
   gradient — the ground is per-item data, so no fixed ink clears 3:1 on all
   of them. The colour is OPAQUE now: the old .92 alpha composited toward the
   ground and cost about 0.1-0.2:1 for nothing. Fallbacks match the rule's own
   --c1/--c2 accent fallback above. See tests/unit/community-monogram-ink. */
.ch-thumb-mono{font-family:var(--mono);font-size:30px;font-weight:700;color:var(--mono-ink,#FFFFFF);letter-spacing:.04em;text-shadow:0 1px 8px var(--mono-glow,rgba(0,0,0,.25))}
/* Visible at rest; the hover reveal is an enhancement for devices that have a
   hover, exactly as .grg-like does it. It used to hide for everyone and come
   back on .ch-card:hover or its own :focus-visible — one of which never fires on
   a phone and the other of which is keyboard-only, so the surface's ONLY
   engagement action was invisible on every touch device at every width
   (S14, mobile-audit-2026-08: 12 buttons, one per card, measured opacity 0 with
   pointer-events:auto at 320x568 through 1180x820). */
.ch-heart{position:absolute;top:10px;right:10px;display:inline-flex;align-items:center;gap:5px;padding:5px 10px;border-radius:var(--radius-pill);border:none;cursor:pointer;background:rgba(0,0,0,.5);color:#fff;font-family:var(--font);font-size:12px;font-weight:600;transition:opacity var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard),background var(--dur-1) var(--ease-standard);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px)}
@media(hover:hover){
  .ch-heart{opacity:0;transform:translateY(-2px)}
  .ch-card:hover .ch-heart,.ch-heart:focus-visible,.ch-heart.is-saved{opacity:1;transform:translateY(0)}
}
.ch-heart.is-saved{color:#fb7185}
.ch-heart:hover{background:rgba(0,0,0,.7)}
.ch-heart-count{font-variant-numeric:tabular-nums;line-height:1}
.ch-card-body{padding:12px 14px 14px}
.ch-card-name{font-size:13.5px;font-weight:650;color:var(--t0);margin-bottom:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-card-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;color:var(--t2)}
.ch-card-tag{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--accent-strong);background:var(--accent-bg);border-radius:var(--radius-s);padding:2px 7px;flex-shrink:0}
.ch-empty{padding:48px 24px;text-align:center;font-size:13.5px;color:var(--t2);border:1.5px dashed var(--border);border-radius:var(--radius-l)}
/* Two columns are kept — this is a browse grid and one column turns 12 cards
   into a 12-screen list — but at 390px that makes each card ~171px, and a
   `white-space:nowrap` title inside ~145px of text width truncated 10 of the 12
   names mid-word: "Dashboard & analyti…", "Award-winning landi…", "Portfolio &
   folio desi…". A browse grid where you cannot read what anything is has
   stopped being a browse grid. The name wraps to two lines instead; two is
   enough for every name in the set and the reserved `min-height` keeps the meta
   rows of adjacent cards on the same baseline, which is what the single-line
   rule was really buying.
   The tag goes 9px → 11px. 9px is below the smallest type used anywhere else in
   this stylesheet and it is a mono uppercase label, which is the least legible
   combination there is at that size. */
@media(max-width:560px){
  .ch-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}
  .ch-toolbar{align-items:stretch}
  .ch-card-name{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:2.6em;line-height:1.3}
  .ch-card-tag{font-size:11px;padding:2px 6px;letter-spacing:.02em}
  .ch-card-meta{gap:6px}
}

/* Information Centre */
.ic-wrap{max-width:820px;margin:0 auto;display:flex;flex-direction:column;gap:20px}
.ic-head-eyebrow{display:inline-flex;align-items:center;gap:6px;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--accent-strong);margin-bottom:10px}
.ic-head-title{font-size:30px;font-weight:700;letter-spacing:-.02em;color:var(--t0);margin:0 0 8px;line-height:1.15}
.ic-head-sub{font-size:14px;color:var(--t2);line-height:1.6;margin:0;max-width:600px}
.ic-intro{display:flex;align-items:flex-start;gap:12px;padding:14px 16px;background:var(--accent-bg);border:1px solid color-mix(in srgb,var(--accent) 30%,transparent);border-radius:var(--radius-l)}
.ic-intro-emoji{font-size:20px;line-height:1.4;flex-shrink:0}
.ic-intro-body{font-size:13px;color:var(--t1);line-height:1.55;flex:1}
.ic-intro-close{flex-shrink:0;width:28px;height:28px;display:flex;align-items:center;justify-content:center;border:none;background:transparent;color:var(--t2);cursor:pointer;border-radius:var(--radius-s);transition:all var(--t)}
.ic-intro-close:hover{background:var(--hvr);color:var(--t0)}
.ic-toc{display:flex;flex-wrap:wrap;gap:6px;padding:14px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-l)}
.ic-toc-link{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:var(--radius-pill);font-size:12px;font-weight:600;color:var(--t1);background:var(--card);border:1px solid var(--border);text-decoration:none!important;transition:all var(--t)}
.ic-toc-link:hover{border-color:var(--accent);color:var(--accent-strong)}
.ic-sections{display:flex;flex-direction:column;gap:10px}
.ic-acc{background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);overflow:hidden;box-shadow:var(--warm-shadow);scroll-margin-top:72px}
.ic-acc-h{margin:0;font-size:inherit;font-weight:inherit;line-height:inherit}
.ic-acc-head{display:flex;align-items:center;gap:12px;width:100%;padding:16px 18px;background:none;border:none;cursor:pointer;font-family:var(--font);text-align:left;transition:background var(--t)}
.ic-acc-head:hover{background:var(--hvr)}
.ic-acc-emoji{font-size:19px;line-height:1;flex-shrink:0}
.ic-acc-title{font-size:15px;font-weight:650;color:var(--t0);margin:0;flex:1}
.ic-acc-chevron{color:var(--t2);transition:transform var(--dur-2) var(--ease-standard);flex-shrink:0}
.ic-acc-head.is-open .ic-acc-chevron{transform:rotate(180deg)}
.ic-acc-body{display:grid;grid-template-rows:0fr;transition:grid-template-rows var(--dur-3) var(--ease-out)}
.ic-acc-body.is-open{grid-template-rows:1fr}
.ic-acc-body-inner{overflow:hidden;min-height:0}
.ic-acc-body.is-open .ic-acc-body-inner{padding:0 18px 18px;border-top:1px solid var(--border)}
.ic-acc-body-inner p{font-size:13.5px;color:var(--t1);line-height:1.7;margin:14px 0 0}
.ic-acc-body-inner ul{margin:12px 0 0;padding-left:18px;display:flex;flex-direction:column;gap:7px}
.ic-acc-body-inner li{font-size:13.5px;color:var(--t1);line-height:1.6}
.ic-acc-body-inner a{color:var(--accent-strong);font-weight:500}
.ic-acc-body-inner kbd{font-family:var(--mono);font-size:11px;padding:2px 6px;border-radius:4px;background:var(--bg-3);border:1px solid var(--border);color:var(--t1)}
.ic-kbd-list{list-style:none;padding-left:0!important}
/* display:block is the fix for S6, and it is not cosmetic. `.ic-stats` is also
   the class of an orphaned Image Converter component further up this file
   (search "Image converter stats", whose .ic-stat-val / .ic-stat-label are in no
   markup any more), and THAT rule declares display:grid. This section is the
   only `.ic-stats` left in the app, so it was silently inheriting a 4-column
   (2-column below 600px) grid it was never meant to have: measured at 320px,
   section.ic-stats laid out as two 116px columns and put .ic-stats-grid inside
   ONE of them, which then subdivided 116px into two 53px cards. A bare `1fr`
   track floors at min-content, so those columns could not shrink and the whole
   page was forced to 341px inside a 288px content box - 37px thrown away, not
   scrolled, because body carries overflow-x:clip.
   The audit diagnoses this as .ic-stats-grid's bare 1fr and proposes
   minmax(0,1fr). That does remove the overflow, but it treats the symptom: with
   the phantom grid still in place the cards then collapse instead, and their own
   text escapes the card box (measured +23px at 320px, +43px at 768px). Taking
   the section out of grid layout removes the cause, and .ic-stats-grid gets the
   full width it was always supposed to have. */
.ic-stats{display:block;background:var(--card-grad);border:1px solid var(--border);border-radius:var(--radius-l);padding:22px;box-shadow:var(--warm-shadow);scroll-margin-top:72px}
.ic-stats-head h2{display:flex;align-items:center;gap:8px;font-size:16px;font-weight:700;color:var(--t0);margin:0 0 4px}
.ic-stats-head p{font-size:13px;color:var(--t2);line-height:1.55;margin:0 0 18px}
.ic-stats-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:20px}
.ic-stat{background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius);padding:14px}
.ic-stat-num{font-size:24px;font-weight:700;color:var(--accent);font-variant-numeric:tabular-nums;line-height:1}
.ic-stat-num span{font-size:13px;color:var(--t3);font-weight:500;margin-left:2px}
/* Carries the colour as well as the size: .ic-stat-num is 24px, which only
   needs 3:1, but 16px bold needs 4.5 and --accent measures 4.06 on --bg-2. */
.ic-stat-sm{font-size:16px;color:var(--accent-strong)}
.ic-stat-lbl{font-size:10px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--t3);margin-top:8px}
.ic-bp-current{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:650;color:var(--t0);margin-bottom:30px}
.ic-bp-ruler{position:relative;height:3px;background:var(--bg-3);border-radius:2px;margin:0 8px 26px}
/* The 380 and 480 ticks sit ~27px apart on a 390px phone while their labels are
   absolutely-positioned, `white-space:nowrap` and need ~25px and ~38px — so
   "TINY" and "PHONE" ran together and the ruler read "TINYPHONE", which is not a
   breakpoint. The labels alternate height instead of being dropped: the whole
   point of this ruler is to name the band you are currently in, so losing a name
   costs more than a row of padding. The marker is `.ic-bp-ruler`'s first child,
   so the ticks are children 2..n and even/odd alternates cleanly across them. */
@media(max-width:640px){
  .ic-bp-ruler{margin-top:18px}
  .ic-bp-tick:nth-child(even) .ic-bp-tick-lbl{top:-38px}
}
.ic-bp-marker{position:absolute;top:50%;width:14px;height:14px;border-radius:50%;background:var(--accent);border:2px solid var(--card);box-shadow:0 0 0 1px var(--accent);transform:translate(-50%,-50%);transition:left var(--dur-2) var(--ease-standard);z-index:2}
.ic-bp-tick{position:absolute;top:50%;width:2px;height:8px;background:var(--border);transform:translate(-50%,-50%)}
