/* ── Theme-direction primitives (Phase 0.5) ─────────────────── */
/* Glass — the floating-panel blur/border/shadow recipe, one source of truth
   so every panel that wants this treatment pulls from the same tokens
   instead of hand-tuning its own blur. */
.glass{background:var(--glass-bg);backdrop-filter:saturate(160%) blur(14px);-webkit-backdrop-filter:saturate(160%) blur(14px);border:1px solid var(--glass-border);border-radius:var(--radius-l);box-shadow:var(--glass-shadow),var(--ring)}
@supports not (backdrop-filter:blur(1px)){
  [data-theme="dark"] .glass{--glass-bg:color-mix(in srgb,var(--bg-1) 94%,transparent)}
  [data-theme="light"] .glass{--glass-bg:color-mix(in srgb,#fff 94%,transparent)}
}


/* Pro-locked overlay shell (placeholder is server-gated; we style the shell only) */
.pro-lock{position:relative;border-radius:var(--radius-l);overflow:hidden;isolation:isolate}
.pro-lock-veil{position:absolute;inset:0;background:var(--scrim);backdrop-filter:blur(10px) saturate(120%);-webkit-backdrop-filter:blur(10px) saturate(120%)}
.pro-lock-cta{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:12px;padding:32px 28px;text-align:center;max-width:360px;margin:0 auto;min-height:200px;justify-content:center}
.pro-lock-badge{display:inline-flex;align-items:center;gap:6px;font:700 10px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--accent-fg);background:var(--accent-strong);padding:4px 10px;border-radius:var(--radius-pill)}
.pro-lock-title{font:600 18px/1.3 var(--font);letter-spacing:-.02em;color:var(--t0)}
.pro-lock-sub{font:400 13px/1.6 var(--font);color:var(--t1);max-width:42ch}
.pro-lock-cta .btn-primary{margin-top:4px}
/* Non-revealing teaser background — generic shimmer tiles, freeze under reduced motion */
.pro-lock-skeleton{position:absolute;inset:0;z-index:0;background:linear-gradient(100deg,var(--bg-2) 30%,var(--bg-3) 50%,var(--bg-2) 70%);background-size:200% 100%;animation:pl-shimmer 1.4s linear infinite}
@keyframes pl-shimmer{from{background-position:200% 0}to{background-position:-200% 0}}

/* ═══════════════════════════════════════════════════════════════════════
   COLOUR STUDIO — SLICE 2: per-swatch interaction layer
   cs-ctx (context menu) · cs-sw (swatch popup) · cs-cb (CB overlay) · cs-sw-edit
   All dynamic colour/position is set via CSS custom props on a ref (the Slice-1
   nav-thumb pattern) — no inline styles in new JSX.
   ═══════════════════════════════════════════════════════════════════════ */

/* ── A. Context menu (right-click / long-press fast path) ── */
.cs-ctx{
  position:fixed; z-index:1200;
  left:var(--cs-ctx-x,0); top:var(--cs-ctx-y,0);
  min-width:208px; max-width:256px; padding:6px;
  background:color-mix(in srgb, var(--bg-1) 90%, transparent);
  -webkit-backdrop-filter:blur(20px) saturate(1.4);
  backdrop-filter:blur(20px) saturate(1.4);
  border:1px solid var(--border);
  border-radius:var(--radius-l);
  box-shadow:var(--shadow-l), var(--ring);
  transform-origin:var(--cs-ctx-origin, top left);
  animation:cs-ctx-in var(--dur-2) var(--ease-entrance) both;
}
@keyframes cs-ctx-in{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.cs-ctx-head{display:flex;align-items:center;gap:8px;padding:7px 9px 9px;margin-bottom:4px;border-bottom:1px solid var(--border)}
.cs-ctx-chip{width:16px;height:16px;border-radius:5px;border:1px solid var(--border);flex:0 0 auto;background:var(--cs-ctx-chip,#000)}
.cs-ctx-role{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.1em;color:var(--t2);text-transform:uppercase}
.cs-ctx-hex{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--t0);margin-left:auto}
.cs-ctx-item{display:flex;align-items:center;gap:10px;width:100%;padding:8px 9px;min-height:36px;border:none;background:none;cursor:pointer;text-align:left;font-family:var(--font);font-size:13px;font-weight:500;color:var(--t1);border-radius:var(--radius-s);transition:background var(--dur-1) var(--ease-standard),color var(--dur-1) var(--ease-standard)}
.cs-ctx-item:hover,.cs-ctx-item.cs-ctx-active{background:var(--hvr);color:var(--t0)}
.cs-ctx-item:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.cs-ctx-item svg{flex:0 0 16px;opacity:.7}
.cs-ctx-kbd{margin-left:auto;font-family:var(--mono);font-size:10px;color:var(--t3);font-weight:600}
.cs-ctx-arrow{margin-left:auto;opacity:.5}
.cs-ctx-sep{height:1px;background:var(--border);margin:4px 6px}
.cs-ctx-danger{color:var(--err-strong)}
.cs-ctx-danger svg{opacity:.85}
.cs-ctx-danger:hover{background:color-mix(in srgb, var(--err) 12%, transparent);color:var(--err-strong)}

/* ── B. Swatch popup (deep path; replaces ColorInfoPopup/ci-*) ── */
/* Desktop: the overlay is a non-interactive positioning layer for the floating
   anchored card — it must NOT swallow clicks to the rail/toolbar/nav behind it.
   Only the card itself (and its descendants, via inheritance) captures pointer
   events. The ≤480 block below re-enables the overlay so the mobile scrim taps. */
.cs-sw-overlay{position:fixed;inset:0;z-index:1100;display:flex;pointer-events:none}
.cs-sw-overlay .cs-sw{pointer-events:auto}
.cs-sw{
  position:fixed;z-index:1150;
  width:340px;max-width:calc(100vw - 24px);max-height:min(560px, calc(100vh - 24px));
  left:var(--cs-sw-x,12px);top:var(--cs-sw-y,12px);
  display:flex;flex-direction:column;overflow:hidden;
  background:var(--bg-1);border:1px solid var(--border);
  border-radius:var(--radius-xl);
  box-shadow:var(--shadow-l), var(--ring);
  animation:cs-sw-in var(--dur-2) var(--ease-entrance) both;
}
@keyframes cs-sw-in{from{opacity:0;transform:translateY(6px) scale(.985)}to{opacity:1;transform:none}}
.cs-sw-hero{position:relative;padding:var(--s-5) var(--s-5) var(--s-4);display:flex;flex-direction:column;gap:2px;flex:0 0 auto;background:var(--cs-sw-bg,#000);color:var(--cs-sw-fg,#fff)}
.cs-sw-role{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;opacity:.7}
.cs-sw-name{font-size:13px;font-weight:700;letter-spacing:-.01em;opacity:.85}
.cs-sw-hex{font-family:var(--mono);font-size:26px;font-weight:700;letter-spacing:-.01em}
.cs-sw-edit-pill{position:absolute;top:var(--s-3);right:var(--s-3);display:inline-flex;align-items:center;gap:5px;font-size:11px;font-weight:700;padding:5px 10px;border-radius:var(--radius-pill);background:color-mix(in srgb,currentColor 0%,transparent);border:1.5px solid currentColor;color:currentColor;cursor:pointer}
.cs-sw-edit-pill:hover{background:color-mix(in srgb,currentColor 14%,transparent)}
.cs-sw-close{position:absolute;top:var(--s-3);left:var(--s-3);width:30px;height:30px;border:none;border-radius:50%;background:color-mix(in srgb,#000 30%,transparent);color:#fff;font-size:18px;line-height:1;cursor:pointer;display:grid;place-items:center;z-index:2}
.cs-sw-close:hover{background:color-mix(in srgb,#000 48%,transparent)}
.cs-sw-tabs{display:flex;position:relative;border-bottom:1px solid var(--border);background:var(--bg-2);flex:0 0 auto}
.cs-sw-tab{flex:1;padding:11px 6px;border:none;background:none;font-family:var(--font);font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--t2);cursor:pointer;transition:color var(--dur-1) var(--ease-standard)}
.cs-sw-tab:hover{color:var(--t0)}
.cs-sw-tab.active{color:var(--accent-strong)}
.cs-sw-tab-underline{position:absolute;bottom:-1px;left:0;height:2px;background:var(--accent);width:var(--cs-sw-tab-w,0);transform:translateX(var(--cs-sw-tab-x,0));transition:transform var(--dur-3) var(--ease-spring),width var(--dur-3) var(--ease-spring)}
.cs-sw-body{padding:var(--s-4) var(--s-5) var(--s-5);overflow-y:auto;flex:1 1 auto;overscroll-behavior:contain}

/* Values tab */
.cs-sw-values{display:flex;flex-direction:column;gap:2px;margin-bottom:var(--s-4)}
.cs-sw-val-row{display:flex;align-items:center;gap:12px;padding:9px 12px;border:none;background:var(--bg-2);border-radius:var(--radius-s);cursor:pointer;color:var(--t1);transition:background var(--dur-1) var(--ease-standard);text-align:left}
.cs-sw-val-row:hover{background:var(--bg-3)}
.cs-sw-val-row svg{margin-left:auto;color:var(--t3);flex:0 0 auto}
.cs-sw-val-label{font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--t3);width:40px;text-align:left;flex:0 0 auto}
.cs-sw-val-text{font-family:var(--mono);font-size:13px;font-weight:600;color:var(--t0)}
.cs-sw-val-copied{margin-left:auto;font-size:10px;font-weight:700;color:var(--ok-strong)}
.cs-sw-quick{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.cs-sw-qc{padding:12px;border-radius:var(--radius);border:1px solid var(--border);display:flex;align-items:center;gap:8px;background:var(--cs-qc-bg,#fff)}
.cs-sw-qc-aa{font-size:22px;font-weight:800;font-family:var(--font);line-height:1;color:var(--cs-qc-fg,#000)}
.cs-sw-qc-ratio{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--cs-qc-tx,var(--t1))}

/* Contrast tab */
.cs-sw-contrast{display:flex;flex-direction:column;gap:var(--s-3)}
.cs-sw-group-label{font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--t3);text-transform:uppercase;margin:4px 0 2px}
.cs-sw-cc-pair{display:grid;grid-template-columns:1fr 1fr;gap:var(--s-2)}
.cs-sw-cc{padding:var(--s-3);border-radius:var(--radius);border:1px solid var(--border);display:flex;flex-direction:column;align-items:center;gap:4px;background:var(--cs-cc-bg,#fff)}
.cs-sw-cc-aa{font-size:26px;font-weight:800;line-height:1;color:var(--cs-cc-fg,#000)}
.cs-sw-cc-ratio{font-family:var(--mono);font-size:13px;font-weight:700;color:var(--cs-cc-tx,var(--t1))}
.cs-sw-badges{display:flex;gap:4px}
.cs-sw-badge{font-size:9px;font-weight:700;letter-spacing:.04em;padding:2px 6px;border-radius:5px}
.cs-sw-badge.pass{background:color-mix(in srgb,var(--ok) 16%,transparent);color:var(--ok-strong)}
.cs-sw-badge.warn{background:color-mix(in srgb,var(--warn) 16%,transparent);color:var(--warn-strong)}
.cs-sw-badge.fail{background:color-mix(in srgb,var(--err) 16%,transparent);color:var(--err-strong)}
.cs-sw-fix{margin-top:6px;font-size:11px;font-weight:700;color:var(--accent-strong);background:none;border:1px solid var(--border);border-radius:var(--radius-s);padding:5px 10px;cursor:pointer}
.cs-sw-fix:hover{border-color:var(--bh);background:var(--hvr)}
.cs-sw-siblings{display:flex;flex-direction:column;gap:2px}
.cs-sw-sib-row{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:var(--radius-s)}
.cs-sw-sib-chip{width:18px;height:18px;border-radius:5px;border:1px solid var(--border);flex:0 0 auto;background:var(--cs-sib,#000)}
.cs-sw-sib-role{font-family:var(--mono);font-size:10px;color:var(--t2);letter-spacing:.06em}
.cs-sw-sib-ratio{margin-left:auto;font-family:var(--mono);font-size:12px;font-weight:700;color:var(--t1)}

/* Shades tab */
.cs-sw-helper{font-size:11px;color:var(--t2);margin-bottom:var(--s-3);line-height:1.5}
.cs-sw-shade-strip{display:flex;height:40px;border-radius:var(--radius-s);overflow:hidden;border:1px solid var(--border);margin-bottom:var(--s-3)}
.cs-sw-shade-seg{flex:1;cursor:pointer;border:none;padding:0;background:var(--cs-seg,#000);transition:flex var(--dur-2) var(--ease-out)}
.cs-sw-shade-seg:hover{flex:1.6}
.cs-sw-shade-row{display:flex;align-items:center;gap:10px;width:100%;padding:8px;border:none;background:none;cursor:pointer;border-radius:var(--radius-s);transition:background var(--dur-1) var(--ease-standard)}
.cs-sw-shade-row:hover{background:var(--hvr)}
.cs-sw-shade-row[aria-current="true"]{box-shadow:inset 0 0 0 2px var(--accent)}
.cs-sw-shade-dot{width:22px;height:22px;border-radius:6px;border:1px solid var(--border);flex:0 0 auto;background:var(--cs-dot,#000)}
.cs-sw-shade-tone{font-family:var(--mono);font-size:10px;color:var(--t3);width:24px;text-align:left}
.cs-sw-shade-hex{font-family:var(--mono);font-size:12px;font-weight:700;color:var(--t1)}
.cs-sw-shade-ratio{margin-left:auto;font-family:var(--mono);font-size:10px;color:var(--t3)}
.cs-sw-shade-copy{flex:0 0 auto;padding:4px;border:none;background:none;color:var(--t3);cursor:pointer;border-radius:4px;display:grid;place-items:center}
.cs-sw-shade-copy:hover{color:var(--t0);background:var(--hvr)}

/* D. Edit tab (manual per-swatch set) */
.cs-sw-edit-label{font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--t3);text-transform:uppercase;margin-bottom:8px}
.cs-sw-edit-field{display:flex;gap:8px;align-items:center;margin-bottom:var(--s-3)}
/* Sizing only now. The chip used to BE this element (a --cs-edit-chip ground
   under an invisible native input); it is now the shared trigger's own chip,
   so a background here would paint over it. */
.cs-sw-edit-chip{width:40px;height:40px;flex:0 0 auto}
.cs-sw-edit-hex{flex:1 1 auto;font-family:var(--mono);font-size:15px;font-weight:700;letter-spacing:.04em;padding:0 12px;height:40px;background:var(--inp);border:1px solid var(--border);border-radius:var(--radius-s);color:var(--t0);min-width:0}
.cs-sw-edit-hex:focus-visible{outline:2px solid var(--accent);outline-offset:1px;border-color:var(--accent)}
.cs-sw-edit-hex.invalid{border-color:var(--err)}
.cs-sw-edit-err{font-size:11px;color:var(--err-strong);display:flex;align-items:center;gap:5px;margin-bottom:var(--s-3)}
.cs-sw-edit-note{font-size:11px;color:var(--t2);line-height:1.5;margin-bottom:var(--s-3)}
.cs-sw-edit-note button{font:inherit;font-weight:700;color:var(--accent-strong);background:none;border:none;cursor:pointer;padding:0;text-decoration:underline}
.cs-sw-edit-sub{font-family:var(--mono);font-size:11px;color:var(--t2);margin-bottom:var(--s-3)}
.cs-sw-edit-sep{height:1px;background:var(--border);margin:0 0 var(--s-3)}
.cs-sw-recent{display:flex;gap:6px;margin-bottom:var(--s-3);flex-wrap:wrap}
.cs-sw-recent-chip{width:24px;height:24px;border-radius:6px;border:1px solid var(--border);cursor:pointer;background:var(--cs-recent,#000)}

/* ── C. Colour-blindness overlay (palette-wide lens) ── */
.cs-cb-wrap{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.cs-cb-title{font-size:12px;font-weight:600;color:var(--t2);white-space:nowrap}
.cs-cb-toggle{display:inline-flex;position:relative;padding:3px;gap:0;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-pill)}
.cs-cb-seg-full{display:inline}
.cs-cb-seg-abbr{display:none}
.cs-cb-select-wrap{display:none;align-items:center;gap:8px}
.cs-cb-select-label{font-size:12px;font-weight:600;color:var(--t2)}
.cs-cb-seg{position:relative;z-index:1;padding:6px 12px;min-height:32px;border:none;background:none;cursor:pointer;font-family:var(--font);font-size:12px;font-weight:600;color:var(--t2);white-space:nowrap;transition:color var(--dur-2) var(--ease-standard)}
.cs-cb-seg:hover{color:var(--t0)}
.cs-cb-seg.active{color:var(--accent-fg)}
.cs-cb-thumb{position:absolute;top:3px;left:3px;z-index:0;height:calc(100% - 6px);border-radius:var(--radius-pill);background:var(--brand);box-shadow:0 2px 8px -2px var(--brand-glow);transform:translateX(var(--cs-cb-x,0));width:var(--cs-cb-w,0);transition:transform var(--dur-4) var(--ease-spring),width var(--dur-4) var(--ease-spring)}
.cs-cb-select{height:34px;padding:0 30px 0 12px;font-family:var(--font);font-size:12px;font-weight:600;color:var(--t1);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-pill);cursor:pointer}
.cs-cb-banner{display:flex;align-items:center;gap:10px;margin-bottom:var(--s-3);padding:9px var(--s-4);border-radius:var(--radius);background:color-mix(in srgb,var(--brand) 8%,var(--bg-2));border:1px solid color-mix(in srgb,var(--brand) 24%,var(--border));font-size:12px;color:var(--t1)}
.cs-cb-banner-icon{flex:0 0 auto;color:var(--brand)}
.cs-cb-banner-exit{margin-left:auto;font-weight:700;color:var(--accent-strong);background:none;border:none;cursor:pointer;font-size:12px;white-space:nowrap}
.cs-cb-tag{position:absolute;top:6px;right:6px;font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:2px 5px;border-radius:4px;background:color-mix(in srgb,#000 38%,transparent);color:#fff;z-index:3}
.cs-pb-rail.cb-on .cs-pb-swatch{cursor:default}
.cs-pb-rail.cb-on .cs-pb-tools,
.cs-pb-rail.cb-on .cs-pb-tints,
.cs-pb-rail.cb-on .cs-pb-gap{pointer-events:none;opacity:.4}
.cs-pb-rail.cb-on .cs-pb-swatch.cs-cb-clash{box-shadow:inset 0 0 0 2px var(--warn)}

/* Bottom-sheet variants (≤480) for the menu and popup */
@media (max-width:480px){
  .cs-sw-overlay{background:var(--scrim, rgba(8,9,11,.62));align-items:flex-end;pointer-events:auto}
  .cs-sw{position:relative;left:auto;top:auto;width:100%;max-width:100%;max-height:85vh;border-radius:var(--radius-2xl) var(--radius-2xl) 0 0;animation:cs-sheet-up var(--dur-2) var(--ease-entrance) both}
  .cs-sw::before{content:'';display:block;width:36px;height:4px;border-radius:2px;background:var(--t3);margin:10px auto 2px}
  .cs-ctx{position:fixed;left:0!important;right:0;bottom:0;top:auto!important;width:100%;min-width:0;max-width:100%;border-radius:var(--radius-2xl) var(--radius-2xl) 0 0;padding:8px 8px max(8px,env(safe-area-inset-bottom));animation:cs-sheet-up var(--dur-2) var(--ease-entrance) both}
  .cs-ctx-item{min-height:48px;font-size:15px}
}
@keyframes cs-sheet-up{from{transform:translateY(100%)}to{transform:none}}

/* ──────────────────────────────────────────────────────────────────────────
   Colour System popup (CS#3.14, Slice 3). Replaces the old cs-add-menu dropdown.
   Inherits Slice 2's cs-sw chrome/positioner/keyframes verbatim for seam-free
   consistency — only the wider shell (canvas needs room) and the per-tab surfaces
   are new. Dynamic values (point coords, sampled colour, loupe transform, tab
   underline) arrive via custom properties set on refs — no inline styles.
   ────────────────────────────────────────────────────────────────────────── */

/* Trigger — the 2×2 swatch-grid glyph replaces the bare "+". */
.cs-csys-trigger svg{flex:0 0 auto}

/* Shell — same recipe as .cs-sw, wider (380 vs 340) for the canvas. */
.cs-csys-popup{
  position:fixed;z-index:1150;
  left:var(--cs-csys-x,12px);top:var(--cs-csys-y,12px);
  width:380px;max-width:calc(100vw - 24px);max-height:min(620px, calc(100vh - 24px));
  display:flex;flex-direction:column;overflow:hidden;
  background:var(--bg-1);border:1px solid var(--border);
  border-radius:var(--radius-xl);
  box-shadow:var(--shadow-l), var(--ring);
  animation:cs-sw-in var(--dur-2) var(--ease-entrance) both;
}
.cs-csys-grabber{display:none}

/* Head */
.cs-csys-head{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:var(--s-3) var(--s-4);border-bottom:1px solid var(--border);flex:0 0 auto}
.cs-csys-title{font-size:16px;line-height:1.2;font-weight:600;letter-spacing:-.01em;color:var(--t0);margin:0}
.cs-csys-close{width:32px;height:32px;flex:0 0 auto;border:none;border-radius:var(--radius-s);background:none;color:var(--t2);font-size:20px;line-height:1;cursor:pointer;display:grid;place-items:center;transition:background var(--t-fast),color var(--t-fast)}
.cs-csys-close:hover{background:var(--hvr);color:var(--t0)}
.cs-csys-close:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}

/* Tabs — sliding underline echoes cs-sw-tab-underline. */
.cs-csys-tabs{display:flex;position:relative;border-bottom:1px solid var(--border);background:var(--bg-1);flex:0 0 auto}
.cs-csys-tab{flex:1;min-height:44px;padding:11px 6px;border:none;background:none;font-family:var(--font);font-size:13px;font-weight:550;color:var(--t2);cursor:pointer;transition:color var(--dur-1) var(--ease-standard)}
.cs-csys-tab:hover{color:var(--t0)}
.cs-csys-tab.active{color:var(--accent-strong)}
.cs-csys-tab:focus-visible{outline:none;box-shadow:inset 0 0 0 2px var(--brand)}
.cs-csys-tab-underline{position:absolute;bottom:-1px;left:0;height:2px;background:var(--brand);width:var(--cs-csys-tab-w,0);transform:translateX(var(--cs-csys-tab-x,0));transition:transform var(--dur-3) var(--ease-spring),width var(--dur-3) var(--ease-spring)}

/* Body / panel */
.cs-csys-body{padding:var(--s-4);overflow-y:auto;flex:1 1 auto;overscroll-behavior:contain}
.cs-csys-panel{display:flex;flex-direction:column}

/* Eyebrow labels (Slice 1 rhythm) */
.cs-csys-eyebrow{display:flex;align-items:center;gap:8px;font-size:11px;line-height:1;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);margin-bottom:var(--s-2)}
.cs-csys-eyebrow + .cs-csys-eyebrow,.cs-csys-auto + .cs-csys-eyebrow{margin-top:var(--s-5)}
.cs-csys-free-badge{font-family:var(--mono);font-size:9px;font-weight:600;letter-spacing:.02em;color:var(--ok-strong);background:color-mix(in srgb,var(--ok) 14%,transparent);padding:2px 6px;border-radius:var(--radius-pill);text-transform:none}

/* Foot — contextual action bar. */
.cs-csys-foot{display:flex;align-items:center;gap:var(--s-3);margin-top:var(--s-5);padding-top:var(--s-4);border-top:1px solid var(--border)}
.cs-csys-add{flex:1;min-height:40px;padding:10px 16px;border:none;border-radius:var(--radius-s);background:var(--accent-strong);color:var(--accent-fg);font-family:var(--font);font-size:13px;font-weight:600;cursor:pointer;transition:filter var(--t-fast),opacity var(--t-fast)}
.cs-csys-add:hover:not(:disabled){filter:brightness(1.08)}
.cs-csys-add:disabled{opacity:.45;cursor:not-allowed}
.cs-csys-add:focus-visible{outline:none;box-shadow:0 0 0 3px var(--brand-glow)}
.cs-csys-ghost{flex:0 0 auto;min-height:40px;padding:10px 12px;border:none;background:none;color:var(--t2);font-family:var(--font);font-size:12px;font-weight:550;cursor:pointer;border-radius:var(--radius-s);transition:background var(--t-fast),color var(--t-fast)}
.cs-csys-ghost:hover{background:var(--hvr);color:var(--t0)}
.cs-csys-ghost:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}
.cs-csys-foot-note{font-size:12px;line-height:1.45;color:var(--t2)}

/* Shared lock glyph slot (chips reuse LockGlyph) */
.cs-csys-lock{position:absolute;top:6px;right:6px;color:var(--t3);display:inline-flex;transition:color var(--t-fast)}

/* Visually-hidden aria-live */
.cs-csys-live{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

/* ── Generate tab ── */
.cs-csys-auto{display:flex;border-radius:var(--radius);overflow:hidden}
.cs-csys-auto-tile{flex:1;height:40px;background:var(--cs-csys-tile,var(--bg-3))}
.cs-csys-harm{display:grid;grid-template-columns:1fr 1fr;gap:var(--s-2)}
.cs-csys-harm-chip{position:relative;display:flex;align-items:center;gap:8px;min-height:44px;padding:8px 10px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2);color:var(--t1);font-family:var(--font);font-size:12px;font-weight:550;cursor:pointer;text-align:left;transition:background var(--dur-1) var(--ease-entrance),border-color var(--dur-1) var(--ease-entrance)}
.cs-csys-harm-chip:hover{background:var(--bh)}
.cs-csys-harm-chip:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}
.cs-csys-harm-chip.is-selected{border-color:var(--brand);box-shadow:inset 0 0 0 1px var(--brand),0 0 0 3px var(--brand-glow);transition:box-shadow var(--dur-2) var(--ease-out)}
.cs-csys-harm-chip.is-locked{color:var(--t2);padding-right:22px}
.cs-csys-harm-chip.is-locked:hover .cs-csys-lock{color:var(--t1)}
.cs-csys-harm-diagram{flex:0 0 auto;color:var(--t2)}
.cs-csys-harm-label{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* ── Image tab ── */
.cs-csys-drop{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;width:100%;min-height:240px;padding:var(--s-5);border:2px dashed var(--border);border-radius:var(--radius-l);background:var(--bg-2);color:var(--t2);cursor:pointer;font-family:var(--font);transition:border-color var(--dur-1) var(--ease-standard),background var(--dur-1) var(--ease-standard),color var(--dur-1) var(--ease-standard)}
.cs-csys-drop:hover{border-color:var(--bh);color:var(--t1)}
.cs-csys-drop:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}
.cs-csys-drop.is-dragover{border-color:var(--brand);background:color-mix(in srgb,var(--brand) 8%,var(--bg-2));color:var(--t0)}
.cs-csys-drop.is-error{border-color:var(--err);animation:cs-csys-shake .32s cubic-bezier(.36,.07,.19,.97)}
.cs-csys-drop svg{color:var(--t3);margin-bottom:2px}
.cs-csys-drop-title{font-size:13px;font-weight:600;color:var(--t1)}
.cs-csys-drop-sub{font-size:12px;color:var(--t3)}
.cs-csys-drop-err{margin-top:6px;font-size:12px;font-weight:550;color:var(--err-strong);text-align:center}
.cs-csys-file{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);border:0}
@keyframes cs-csys-shake{10%,90%{transform:translateX(-1px)}20%,80%{transform:translateX(2px)}30%,50%,70%{transform:translateX(-3px)}40%,60%{transform:translateX(3px)}}

.cs-csys-zoom{display:inline-flex;align-self:flex-start;gap:2px;margin-bottom:var(--s-3);padding:2px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.cs-csys-zoom-seg{min-width:34px;min-height:28px;padding:4px 10px;border:none;border-radius:var(--radius-xs);background:none;color:var(--t2);font-family:var(--mono);font-size:11px;font-weight:600;cursor:pointer;transition:background var(--t-fast),color var(--t-fast)}
.cs-csys-zoom-seg:hover{color:var(--t0)}
.cs-csys-zoom-seg.active{background:var(--accent-strong);color:var(--accent-fg)}
.cs-csys-zoom-seg:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}

.cs-csys-stage{--cs-csys-stage-h:300px;position:relative;width:100%;border-radius:var(--radius);overflow:hidden;background:var(--bg-0);touch-action:none}
.cs-csys-stage:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}
.cs-csys-canvas{display:block;width:100%;height:var(--cs-csys-stage-h);background:var(--bg-0)}

/* Eyedropper point — coordinate + sampled colour via custom properties. */
.cs-csys-pt{position:absolute;left:var(--cs-x);top:var(--cs-y);transform:translate(-50%,-50%);width:44px;height:44px;padding:8px;box-sizing:border-box;cursor:grab;touch-action:none}
.cs-csys-pt.is-dragging{cursor:grabbing;z-index:3}
.cs-csys-pt:focus-visible{outline:none}
.cs-csys-pt-ring{display:block;width:100%;height:100%;border-radius:50%;background:var(--cs-c,#000);box-shadow:0 0 0 1px #000,0 0 0 2px #fff;transition:transform var(--dur-2) var(--ease-entrance)}
.cs-csys-pt:hover .cs-csys-pt-ring,.cs-csys-pt.is-active .cs-csys-pt-ring{transform:scale(1.08)}
.cs-csys-pt:focus-visible .cs-csys-pt-ring{box-shadow:0 0 0 1px #000,0 0 0 2px #fff,0 0 0 4px var(--brand)}
.cs-csys-pt-del{position:absolute;top:0;right:0;width:24px;height:24px;border:none;border-radius:50%;background:var(--bg-4);color:var(--t0);font-size:12px;line-height:1;cursor:pointer;display:none;place-items:center;box-shadow:var(--shadow-s)}
.cs-csys-pt:hover .cs-csys-pt-del,.cs-csys-pt:focus-within .cs-csys-pt-del,.cs-csys-pt.is-active .cs-csys-pt-del{display:grid}

/* Live readout chip — follows the active handle. */
.cs-csys-readout{position:absolute;left:var(--cs-x);top:var(--cs-y);transform:translate(-50%,calc(-100% - 26px));display:inline-flex;align-items:center;gap:6px;padding:4px 8px;border-radius:var(--radius-s);background:var(--bg-1);border:1px solid var(--border);box-shadow:var(--shadow-m);pointer-events:none;white-space:nowrap;z-index:4}
.cs-csys-readout-sw{width:14px;height:14px;flex:0 0 auto;border-radius:4px;background:var(--cs-c,#000);box-shadow:inset 0 0 0 1px rgba(0,0,0,.2)}
.cs-csys-readout-hex{font-family:var(--mono);font-size:12px;font-weight:500;color:var(--t0)}
.cs-csys-readout-badge{font-family:var(--mono);font-size:10px;font-weight:600;padding:1px 5px;border-radius:var(--radius-pill)}
.cs-csys-readout-badge.pass{color:var(--ok-strong);background:color-mix(in srgb,var(--ok) 16%,transparent)}
.cs-csys-readout-badge.warn{color:var(--warn-strong);background:color-mix(in srgb,var(--warn) 18%,transparent)}
.cs-csys-readout-badge.fail{color:var(--err-strong);background:color-mix(in srgb,var(--err) 16%,transparent)}

/* Magnifier loupe — function, not decoration. */
.cs-csys-loupe{position:absolute;left:var(--cs-loupe-x,0);top:var(--cs-loupe-y,0);width:var(--cs-loupe-size,96px);height:var(--cs-loupe-size,96px);border-radius:50%;overflow:hidden;border:2px solid var(--bg-1);box-shadow:0 0 0 1px var(--border),var(--shadow-m);pointer-events:none;opacity:0;transition:opacity var(--dur-1) var(--ease-entrance);z-index:5}
.cs-csys-stage:hover .cs-csys-loupe,.cs-csys-pt:focus-within ~ .cs-csys-loupe,.cs-csys-pt.is-dragging ~ .cs-csys-loupe{opacity:1}
.cs-csys-loupe-canvas{display:block;width:100%;height:100%;image-rendering:pixelated}
.cs-csys-loupe-cross{position:absolute;inset:0;pointer-events:none}
.cs-csys-loupe-cross::before,.cs-csys-loupe-cross::after{content:'';position:absolute;background:rgba(255,255,255,.7);box-shadow:0 0 0 .5px rgba(0,0,0,.6)}
.cs-csys-loupe-cross::before{left:50%;top:0;bottom:0;width:1px;transform:translateX(-.5px)}
.cs-csys-loupe-cross::after{top:50%;left:0;right:0;height:1px;transform:translateY(-.5px)}

/* Murphy state overlay (loading/error/offline) */
.cs-csys-state{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;background:color-mix(in srgb,var(--bg-0) 82%,transparent);color:var(--t1);font-size:13px;font-weight:550;z-index:6}
.cs-csys-state.is-loading{background:var(--bg-2)}
.cs-csys-spinner{width:22px;height:22px;border-radius:50%;border:2.5px solid var(--border);border-top-color:var(--brand);animation:cs-csys-spin .7s linear infinite}
@keyframes cs-csys-spin{to{transform:rotate(360deg)}}

.cs-csys-hint{margin:var(--s-3) 0 0;font-size:12px;line-height:1.45;color:var(--t2)}
.cs-csys-tray{display:flex;flex-wrap:wrap;gap:var(--s-2);margin-top:var(--s-3)}
.cs-csys-tray-tile{position:relative;width:36px;height:36px;flex:0 0 auto;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--cs-c,var(--bg-3));cursor:pointer;padding:0;transition:transform var(--t-fast),box-shadow var(--t-fast)}
.cs-csys-tray-tile:hover{transform:translateY(-1px);box-shadow:var(--shadow-s)}
.cs-csys-tray-tile.is-active{box-shadow:0 0 0 2px var(--brand)}
.cs-csys-tray-tile:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}
.cs-csys-tray-x{position:absolute;top:-5px;right:-5px;width:16px;height:16px;border-radius:50%;background:var(--bg-4);color:var(--t0);font-size:11px;line-height:16px;text-align:center;opacity:0;box-shadow:var(--shadow-xs);transition:opacity var(--t-fast)}
.cs-csys-tray-tile:hover .cs-csys-tray-x,.cs-csys-tray-tile:focus-visible .cs-csys-tray-x{opacity:1}

/* ── Brands tab ── */
.cs-csys-brand-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--s-2)}
.cs-csys-brand{display:flex;flex-direction:column;gap:8px;padding:10px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2);cursor:pointer;transition:transform var(--dur-2) var(--ease-entrance),box-shadow var(--dur-1) var(--ease-entrance),border-color var(--dur-1) var(--ease-entrance)}
.cs-csys-brand:hover{transform:translateY(-1px);box-shadow:var(--shadow-s)}
.cs-csys-brand:focus-visible{outline:none;box-shadow:0 0 0 2px var(--brand)}
.cs-csys-brand.is-selected{border-color:var(--brand);box-shadow:inset 0 0 0 1px var(--brand)}
.cs-csys-brand-name{font-size:13px;font-weight:550;color:var(--t1)}
.cs-csys-brand-bar{display:flex;height:24px;border-radius:var(--radius-xs);overflow:hidden}
.cs-csys-brand-sw{flex:1;border:none;padding:0;background:var(--cs-c,var(--bg-3));cursor:pointer;transition:flex var(--t-fast)}
.cs-csys-brand-sw:hover{flex:1.6}
.cs-csys-brand-sw:focus-visible{outline:none;box-shadow:inset 0 0 0 2px var(--brand)}

/* ── Mobile bottom-sheet (≤480) — mirror Slice 2 exactly ── */
@media (max-width:768px){
  .cs-csys-canvas{height:260px}
  .cs-csys-stage{--cs-csys-stage-h:260px}
}
@media (max-width:480px){
  .cs-csys-sheet-overlay{background:var(--scrim, rgba(8,9,11,.62));align-items:flex-end;pointer-events:auto}
  .cs-csys-popup{position:relative;left:auto;top:auto;width:100%;max-width:100%;max-height:85vh;border-radius:var(--radius-xl) var(--radius-xl) 0 0;animation:cs-sheet-up var(--dur-2) var(--ease-entrance) both}
  .cs-csys-grabber{display:block;width:36px;height:4px;border-radius:2px;background:var(--t3);margin:10px auto 2px;flex:0 0 auto}
  .cs-csys-tabs{position:sticky;top:0;z-index:2}
  .cs-csys-canvas{height:44vh}
  .cs-csys-stage{--cs-csys-stage-h:44vh}
}
@media (max-width:380px){
  .cs-csys-tab{font-size:12px}
  .cs-csys-harm{gap:var(--s-1)}
  .cs-csys-brand-grid{grid-template-columns:1fr}
}
@media (max-width:320px){
  .cs-csys-foot{flex-wrap:wrap}
  .cs-csys-add,.cs-csys-ghost{flex:1 1 100%}
  .cs-csys-tray-tile{width:32px;height:32px}
}

/* Reduced motion — loupe/readout stay functional, only the fade is removed. */
[data-reduced-motion] .cs-csys-loupe{transition:none}
[data-reduced-motion] .cs-csys-drop.is-error{animation:none}

/* ═══════════════════════════════════════════════════════════════════════════
   COLOUR STUDIO — "SEE IT SHIPPED" PREVIEWS (cs-pv-, Slice 4)
   Four full vector UI scenes that recolour from the live palette via per-scene
   --pv-* custom properties (set imperatively on .cs-pv-canvas; never inline).
   Two free (hero/app) + two Pro-locked (mobile/article). The locked scenes show
   ONLY a palette-free wireframe — no --pv-* var is ever set on them (§9).
   ═══════════════════════════════════════════════════════════════════════════ */
.cs-pv{margin-bottom:var(--s-7);scroll-margin-top:100px}
.cs-pv-header{cursor:pointer;display:flex;align-items:center;gap:12px;margin-bottom:14px}
.cs-pv-header.is-collapsed{margin-bottom:0}
.cs-pv-header h2{font-size:18px;font-weight:700}
.cs-pv-sublabel{font-size:10px;line-height:1.4;letter-spacing:.06em;text-transform:uppercase;font-weight:600;color:var(--t2)}
.cs-pv-body{max-width:1280px;margin-inline:auto}

/* ── Role legend (teaches the palette→role mapping) ── */
.cs-pv-legend{display:flex;flex-wrap:wrap;align-items:center;gap:8px 18px;margin-bottom:var(--s-5);
  padding:10px 14px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-1)}
.cs-pv-legend-item{display:inline-flex;align-items:center;gap:7px}
.cs-pv-legend-dot{width:14px;height:14px;border-radius:var(--radius-pill);border:1px solid var(--bh);flex-shrink:0;
  transition:transform var(--t-fast)}
.cs-pv-legend-item:hover .cs-pv-legend-dot{transform:scale(1.15)}
.cs-pv-legend-dot[data-role="bg"]{background:var(--pv-bg)}
.cs-pv-legend-dot[data-role="surface"]{background:var(--pv-surface)}
.cs-pv-legend-dot[data-role="primary"]{background:var(--pv-primary)}
.cs-pv-legend-dot[data-role="accent"]{background:var(--pv-accent)}
.cs-pv-legend-dot[data-role="text"]{background:var(--pv-text)}
.cs-pv-legend-name{font-size:10px;line-height:1;letter-spacing:.04em;text-transform:uppercase;font-weight:700;color:var(--t1)}
.cs-pv-legend-hex{font-family:var(--mono);font-size:10px;line-height:1;font-weight:500;color:var(--t2)}
.cs-pv-legend-hint{font-size:10px;color:var(--t2);font-style:italic;margin-left:auto}

/* ── Grid + scene chrome ── */
.cs-pv-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:var(--s-4)}
.cs-pv-scene{background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-l);
  overflow:hidden;box-shadow:var(--warm-shadow),var(--ring);
  animation:cs-deal var(--dur-3) var(--ease-entrance) backwards;
  transition:transform var(--t),box-shadow var(--t)}
.cs-pv-scene:nth-child(2){animation-delay:.05s}
.cs-pv-scene:nth-child(3){animation-delay:.1s}
.cs-pv-scene:nth-child(4){animation-delay:.15s}
.cs-pv-scene:hover{transform:translateY(-2px);box-shadow:var(--warm-shadow-lg),var(--ring)}
.cs-pv-scene-head{display:flex;align-items:center;justify-content:space-between;gap:8px;
  padding:9px 14px;border-bottom:1px solid var(--border)}
.cs-pv-scene-tag{font-size:10px;line-height:1;letter-spacing:.08em;text-transform:uppercase;font-weight:700;color:var(--t2)}
.cs-pv-scene-mode{font-size:9px;line-height:1;letter-spacing:.06em;text-transform:uppercase;font-weight:600;
  color:var(--t3);padding:3px 7px;border:1px solid var(--border);border-radius:var(--radius-pill)}
.cs-pv-canvas{aspect-ratio:16/10;background:var(--pv-bg);color:var(--pv-text);
  padding:var(--s-4);position:relative;overflow:hidden;container-type:inline-size;
  container-name:pv-canvas;font-family:var(--font)}

/* ── Recoloured atoms — read ONLY from --pv-* (no inline style) ── */
.cs-pv-btn{display:inline-flex;align-items:center;justify-content:center;
  background:var(--pv-primary);color:var(--pv-on-primary);border:1px solid var(--pv-primary-border, transparent);
  border-radius:var(--radius-pill);font-size:11px;line-height:1;font-weight:650;padding:7px 13px;white-space:nowrap}
.cs-pv-btn.is-ghost{background:transparent;color:var(--pv-text);border:1px solid var(--pv-border)}
.cs-pv-tag{display:inline-flex;align-items:center;font-size:10px;line-height:1;font-weight:600;padding:4px 10px;
  border-radius:var(--radius-pill);color:var(--pv-accent);background:color-mix(in srgb,var(--pv-accent) 12%,transparent)}
.cs-pv-headline{color:var(--pv-text);font-weight:800;letter-spacing:-.02em;font-size:clamp(22px,4cqi,30px);line-height:1.1;margin:0}
.cs-pv-sub{color:var(--pv-muted);max-width:60ch;font-size:12px;line-height:1.55;font-weight:450;margin:0}
.cs-pv-glow{position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(60% 50% at 50% 28%,color-mix(in srgb,var(--pv-primary) 18%,transparent),transparent 70%)}

/* Scene A — Marketing Hero (dark) */
.cs-pv-nav{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:var(--s-5)}
.cs-pv-wordmark{display:inline-flex;align-items:center;gap:7px;color:var(--pv-text);font-weight:700;font-size:13px}
.cs-pv-dot{width:14px;height:14px;border-radius:var(--radius-s);background:var(--pv-primary);display:inline-block}
.cs-pv-nav-links{display:inline-flex;align-items:center;gap:14px}
.cs-pv-link{color:var(--pv-muted);font-size:11px;font-weight:500}
.cs-pv-hero{position:relative;z-index:1;display:flex;flex-direction:column;align-items:flex-start;gap:var(--s-3)}
.cs-pv-cta-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:2px}
.cs-pv-logos{display:flex;gap:16px;margin-top:var(--s-3);opacity:.5}
.cs-pv-logos span{width:48px;height:9px;border-radius:var(--radius-pill);background:var(--pv-muted)}

/* Scene B — App Dashboard (light) */
.cs-pv-app{display:flex;gap:0;margin:calc(var(--s-4) * -1);height:calc(100% + var(--s-4) * 2)}
.cs-pv-side{flex-shrink:0;width:54px;background:var(--pv-surface);border-right:1px solid var(--pv-border);
  display:flex;flex-direction:column;align-items:center;gap:10px;padding:14px 0}
.cs-pv-side-mark{width:22px;height:22px;border-radius:var(--radius-s);background:var(--pv-primary)}
.cs-pv-side-item{width:30px;height:30px;border-radius:var(--radius-s);display:flex;align-items:center;justify-content:center}
.cs-pv-side-item i{width:15px;height:15px;border-radius:5px;background:var(--pv-muted);opacity:.55}
.cs-pv-side-item.is-active{background:color-mix(in srgb,var(--pv-primary) 14%,transparent)}
.cs-pv-side-item.is-active i{background:var(--pv-primary);opacity:1}
.cs-pv-app-main{flex:1;min-width:0;padding:14px;display:flex;flex-direction:column;gap:12px}
.cs-pv-topbar{display:flex;align-items:center;justify-content:space-between;gap:10px}
.cs-pv-topbar-title{color:var(--pv-text);font-weight:700;font-size:15px}
.cs-pv-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.cs-pv-kpi{background:var(--pv-surface);border:1px solid var(--pv-border);border-radius:var(--radius-s);
  padding:10px;display:flex;flex-direction:column;gap:3px}
.cs-pv-kpi-label{color:var(--pv-muted);font-size:9px;line-height:1.3;font-weight:500;text-transform:uppercase;letter-spacing:.04em}
.cs-pv-kpi-num{color:var(--pv-primary);font-size:22px;line-height:1;font-weight:800}
.cs-pv-kpi-chip{align-self:flex-start;color:var(--pv-accent);font-size:9px;font-weight:700;
  padding:2px 6px;border-radius:var(--radius-pill);background:color-mix(in srgb,var(--pv-accent) 14%,transparent)}
.cs-pv-chart{flex:1;min-height:0;display:flex;align-items:flex-end;gap:6px;
  background:var(--pv-surface);border:1px solid var(--pv-border);border-radius:var(--radius-s);padding:12px}
.cs-pv-bar{flex:1;border-radius:3px 3px 0 0;background:var(--pv-primary);opacity:.45}
.cs-pv-bar:nth-child(1){height:42%}.cs-pv-bar:nth-child(2){height:68%}.cs-pv-bar:nth-child(3){height:55%}
.cs-pv-bar:nth-child(4){height:80%}.cs-pv-bar:nth-child(5){height:62%}.cs-pv-bar:nth-child(6){height:95%}
.cs-pv-bar:nth-child(7){height:58%}.cs-pv-bar:nth-child(8){height:74%}
.cs-pv-bar.is-peak{background:var(--pv-accent);opacity:1}

/* Scene C — Mobile Feed (light) */
.cs-pv-mobile{display:flex;align-items:center;justify-content:center;height:100%}
.cs-pv-phone{width:46cqi;max-width:170px;aspect-ratio:9/16;background:var(--pv-bg);border:3px solid var(--pv-border);
  border-radius:22px;box-shadow:0 8px 24px rgba(0,0,0,.18);overflow:hidden}
.cs-pv-screen{position:relative;height:100%;background:var(--pv-surface);padding:10px;display:flex;flex-direction:column;gap:8px}
.cs-pv-status{display:flex;align-items:center;justify-content:space-between}
.cs-pv-status>span:first-child{width:26px;height:5px;border-radius:var(--radius-pill);background:var(--pv-muted);opacity:.5}
.cs-pv-status-dots{display:inline-flex;gap:3px}
.cs-pv-status-dots i{width:4px;height:4px;border-radius:50%;background:var(--pv-muted);opacity:.5}
.cs-pv-feed-head{display:flex;align-items:center;gap:8px}
.cs-pv-avatar{width:26px;height:26px;border-radius:50%;background:var(--pv-accent)}
.cs-pv-feed-title{color:var(--pv-text);font-weight:700;font-size:13px}
.cs-pv-feed-card{background:var(--pv-bg);border:1px solid var(--pv-border);border-radius:var(--radius-s);
  padding:8px;display:flex;flex-direction:column;gap:5px}
.cs-pv-feed-img{height:34px;border-radius:5px;
  background:linear-gradient(135deg,color-mix(in srgb,var(--pv-primary) 55%,transparent),color-mix(in srgb,var(--pv-accent) 45%,transparent))}
.cs-pv-feed-line{height:5px;border-radius:var(--radius-pill);background:var(--pv-text);opacity:.78}
.cs-pv-feed-line.is-short{width:55%;background:var(--pv-muted);opacity:.6}
.cs-pv-feed-actions{display:inline-flex;gap:8px;margin-top:1px}
.cs-pv-feed-actions i{width:11px;height:11px;border-radius:3px;background:var(--pv-muted);opacity:.5}
.cs-pv-feed-actions i.is-active{background:var(--pv-primary);opacity:1}
.cs-pv-fab{position:absolute;right:12px;bottom:42px;width:30px;height:30px;border-radius:50%;
  background:var(--pv-primary);color:var(--pv-on-primary);display:flex;align-items:center;justify-content:center;
  font-size:18px;font-weight:600;line-height:1;box-shadow:0 4px 10px rgba(0,0,0,.2)}
.cs-pv-tabbar{margin-top:auto;display:flex;align-items:center;justify-content:space-around;
  padding:8px 0 2px;border-top:1px solid var(--pv-border)}
.cs-pv-tabbar i{width:14px;height:14px;border-radius:4px;background:var(--pv-muted);opacity:.5}
.cs-pv-tabbar i.is-active{background:var(--pv-primary);opacity:1}

/* Scene D — Editorial Article (light) */
.cs-pv-article{display:flex;flex-direction:column;gap:var(--s-2);max-width:66ch;margin-inline:auto;height:100%;overflow:hidden}
.cs-pv-kicker{color:var(--pv-accent);font-size:10px;line-height:1;letter-spacing:.1em;text-transform:uppercase;font-weight:700}
.cs-pv-art-headline{color:var(--pv-text);font-weight:750;letter-spacing:-.015em;font-size:clamp(18px,5cqi,24px);line-height:1.15;margin:0}
.cs-pv-byline{color:var(--pv-muted);font-size:11px;font-weight:500}
.cs-pv-rule{height:2px;border-radius:var(--radius-pill);background:var(--pv-primary);width:42px}
.cs-pv-cols{columns:2;column-gap:var(--s-4);color:var(--pv-text);font-size:11.5px;line-height:1.7;font-weight:450}
.cs-pv-cols p{margin:0 0 8px}
.cs-pv-a{color:var(--pv-accent);text-decoration:underline;text-underline-offset:2px}
.cs-pv-quote{margin:0;padding:8px 12px;background:var(--pv-surface);border-left:3px solid var(--pv-primary);
  border-radius:0 var(--radius-s) var(--radius-s) 0;color:var(--pv-text);font-size:14px;line-height:1.4;font-weight:600}

/* ── Locked scene — the ONLY thing rendered for non-Pro. Palette-free. ── */
.cs-pv-scene.is-locked .cs-pv-canvas{background:var(--bg-2);color:var(--t3)}
.cs-pv-lock-art{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:var(--s-5);
  filter:grayscale(1);opacity:.5}
.cs-pv-lock-phone{width:90px;display:flex;flex-direction:column;gap:7px;padding:12px;
  border:2px solid var(--t3);border-radius:14px}
.cs-pv-lock-phone .cs-pv-lock-bar{height:18px;border-radius:5px;background:var(--border)}
.cs-pv-lock-phone .cs-pv-lock-block{height:24px;border-radius:5px;background:var(--border)}
.cs-pv-lock-doc{width:60%;max-width:220px;display:flex;flex-direction:column;gap:8px}
.cs-pv-lock-line{height:7px;border-radius:var(--radius-pill);background:var(--border)}
.cs-pv-lock-line.is-short{width:60%}
.cs-pv-lock-line.is-kicker{width:35%;background:var(--t3)}
.cs-pv-lock-head{height:14px;border-radius:5px;background:var(--t3)}
.cs-pv-lock-rule{height:2px;width:30px;border-radius:var(--radius-pill);background:var(--t3);margin:2px 0}
.cs-pv-lock{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:var(--s-3);text-align:center;padding:var(--s-5);
  background:color-mix(in srgb,var(--bg-2) 72%,transparent)}
.cs-pv-lock-badge{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;border-radius:var(--radius-pill);
  background:var(--brand-bg);color:var(--accent-strong);font-size:11px;font-weight:700}
.cs-pv-lock-label{color:var(--t1);font-size:13px;font-weight:700}
.cs-pv-lock-cta{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 18px;
  border-radius:var(--radius-pill);border:1px solid var(--brand);background:transparent;color:var(--accent-strong);
  font-family:var(--font);font-size:12px;font-weight:650;cursor:pointer;transition:background var(--t),color var(--t)}
.cs-pv-lock-cta:hover{background:var(--accent-strong);color:var(--accent-fg)}

/* ── Closing upsell ── */
.cs-pv-upsell{display:flex;align-items:center;justify-content:space-between;gap:var(--s-4);
  margin-top:var(--s-5);padding:var(--s-5);border-radius:var(--radius-l);
  border:1px solid var(--brand);background:var(--brand-bg)}
.cs-pv-upsell-copy{display:flex;flex-direction:column;gap:3px}
.cs-pv-upsell-copy strong{color:var(--t0);font-size:15px;font-weight:700}
.cs-pv-upsell-copy span{color:var(--t2);font-size:12px}
.cs-pv-upsell-cta{flex-shrink:0;min-height:44px}

/* ── Responsive (320 → 4K) — scenes reflow by their own width via @container ── */
@container pv-canvas (max-width:340px){
  .cs-pv-app .cs-pv-side{display:none}
  .cs-pv-kpis{grid-template-columns:repeat(2,1fr)}
