.icust-paste-input{width:100%;min-height:160px;resize:vertical;padding:14px 16px;background:var(--bg-0);border:1px solid var(--border);border-radius:var(--radius-s);font-family:var(--mono);font-size:var(--fs-caption);line-height:1.6;color:var(--t0);outline:none;transition:border-color var(--dur-2) var(--ease-out),box-shadow var(--dur-2) var(--ease-out)}
.icust-paste-input:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
