/* Controls */
.icust-controls{display:flex;flex-direction:column;gap:14px;padding:18px 24px 4px}
.icust-row{display:flex;align-items:center;gap:12px;min-height:32px}
.icust-row>label{flex:0 0 56px;font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
