.cpk-head-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cpk-chip{flex:0 0 auto;width:20px;height:20px;border-radius:var(--radius-xs);border:1px solid var(--border);background:var(--cpk-chip-color,transparent)}
