.cpk-dropper:hover{color:var(--t0);border-color:var(--bh)}
.cpk-dropper:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.cpk-hex{flex:1 1 auto;min-width:0;height:32px;padding:0 8px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--inp);color:var(--t0);font-family:var(--mono);font-size:var(--fs-body-s);transition:border-color var(--dur-2) var(--ease-out)}
