/* The notation select. Sized to its widest option (HEX/RGB/HSL are all three
   characters) so switching never reflows the row under the pointer. */
.cpk-format{flex:0 0 auto;height:32px;padding:0 4px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--inp);color:var(--t1);font-family:var(--mono);font-size:11px;font-weight:600;cursor:pointer}
.cpk-format:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
/* Each swatch group is headed. An unheaded second grid is indistinguishable
   from the first — to the eye, and to a screen reader, which is why the label
   IS the listbox's accessible name rather than a decoration beside it. */
.cpk-section{display:grid;gap:var(--s-1)}
.cpk-section-label{margin:0;font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.cpk-swatches{display:grid;grid-template-columns:repeat(5,1fr);gap:var(--s-1)}
/* Rounded squares, NOT the circles most of the references use: a colour sample
   is a rounded rectangle everywhere else in this app (.plb-col and
   .cpk-trigger-chip), and matching Canva here would have cost matching ourselves. */
.cpk-swatch{aspect-ratio:1;padding:0;border-radius:var(--radius-xs);border:1px solid var(--border);cursor:pointer;transition:transform var(--dur-2) var(--ease-out),box-shadow var(--dur-1) var(--ease-out)}
.cpk-swatch:hover{transform:scale(1.08)}
.cpk-swatch:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.cpk-swatch.is-active{box-shadow:0 0 0 2px var(--bg-1),0 0 0 4px var(--accent)}
.icust-abs{flex:0 0 auto;padding:6px 12px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.03em;color:var(--t2);cursor:pointer;transition:border-color var(--dur-1) var(--ease-out),background var(--dur-1) var(--ease-out),color var(--dur-1) var(--ease-out)}
.icust-abs:hover{border-color:var(--bh);color:var(--t0)}
.icust-abs.active{background:var(--accent-bg);border-color:var(--accent);color:var(--accent-strong)}
/* Pro-gated line-style controls: buttons preview their own cap/join effect */
.icust-seg--icon button{padding:6px}
.icust-seg--icon svg{display:block;width:22px;height:22px;margin:0 auto;color:var(--t2)}
.icust-seg--icon button:hover svg{color:var(--t0)}
.icust-seg--icon button.active svg{color:var(--t0)}
.icust-pro{display:flex;flex-direction:column;gap:12px;margin-top:2px;padding:14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-1)}
.icust-pro-head{display:flex;align-items:center;justify-content:space-between;font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.icust-pro.is-locked .icust-seg--icon button{cursor:pointer}
.icust-pro.is-locked .icust-seg--icon svg{opacity:.55}
.icust-pro.is-locked .icust-seg--icon button.active svg{opacity:1}
/* Locked panel is fully clickable — any click opens the Pro upgrade modal
   (no hover veil; less disruptive to the flow). */
.icust-pro.is-locked{cursor:pointer}
/* Signed-out upgrade gate — a small alert dialog floated over the customizer
   when a visitor taps a Pro-locked line-style control. (The overlay's
   backdrop-filter makes it the containing block for this fixed backdrop.) */
.icust-gate-backdrop{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:16px;background:var(--scrim);animation:cp-fade var(--dur-1) var(--ease-entrance)}
.icust-gate{display:flex;flex-direction:column;align-items:flex-start;gap:10px;width:min(380px,100%);padding:22px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-xl);box-shadow:var(--warm-shadow-lg);animation:cp-rise var(--dur-2) var(--ease-entrance)}
.icust-gate-title{margin:0;font-size:var(--fs-h5);font-weight:640;color:var(--t0)}
.icust-gate-copy{margin:0;font-size:var(--fs-body-s);line-height:1.55;color:var(--t1)}
.icust-gate-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:6px}
.icust-gate-dismiss{align-self:center;margin-top:2px;padding:6px 12px;border:none;background:none;border-radius:var(--radius-pill);font-family:var(--font);font-size:var(--fs-body-s);font-weight:560;color:var(--t2);cursor:pointer;transition:color var(--dur-1) var(--ease-out),background var(--dur-1) var(--ease-out)}
.icust-gate-dismiss:hover{color:var(--t0);background:var(--hvr)}
/* Save-to-project picker (shares the gate dialog shell) */
.icust-proj-list{display:flex;flex-direction:column;gap:6px;width:100%;max-height:240px;overflow-y:auto;margin-top:2px}
.icust-proj-btn{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:10px 14px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-l);font-family:var(--font);font-size:var(--fs-body-s);font-weight:560;color:var(--t0);cursor:pointer;text-align:left;transition:border-color var(--dur-1) var(--ease-out),background var(--dur-1) var(--ease-out)}
.icust-proj-btn:hover:not(:disabled){border-color:var(--accent);background:var(--hvr)}
.icust-proj-btn:disabled{opacity:.55;cursor:not-allowed}
.icust-proj-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.icust-proj-count{display:inline-flex;align-items:center;gap:6px;flex-shrink:0;font-size:var(--fs-caption);font-weight:600;color:var(--t2);font-variant-numeric:tabular-nums}
.icust-proj-btn--new{background:none;border-style:dashed;color:var(--t1);width:100%}
.icust-proj-btn--new:hover{color:var(--t0)}
/* Inline new-project creation: name first, then the icon is assigned */
.icust-newproj{display:flex;gap:8px;width:100%;margin-top:2px}
.icust-newproj-input{flex:1;min-width:0;height:38px;padding:0 12px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--inp);color:var(--t0);font-family:var(--font);font-size:var(--fs-body-s);transition:border-color var(--dur-2) var(--ease-out)}
.icust-newproj-input:focus{outline:none;border-color:var(--accent)}
.icust-newproj-input::placeholder{color:var(--t3)}
/* Footer extras: saved-in note */
.icust-savedin{margin:0;padding:10px 24px 20px;font-size:var(--fs-caption);color:var(--t2)}
.icust-savedin strong{font-weight:600;color:var(--t1)}
/* Code readout */
.icust-code{margin:12px 24px 0}
.icust-code-label{margin-bottom:8px;font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--t2)}
.icust-code-box{position:relative;display:block;width:100%;text-align:left;padding:26px 16px 14px;background:var(--bg-0);border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;transition:border-color var(--dur-2) var(--ease-out)}
.icust-code-box:hover{border-color:var(--accent)}
.icust-code-hint{position:absolute;top:8px;right:10px;font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.04em;text-transform:uppercase;color:var(--t3);pointer-events:none;transition:color var(--dur-2) var(--ease-out)}
.icust-code-box:hover .icust-code-hint{color:var(--accent-strong)}
/* Copy-only snippet: the text is not selectable, so the Copy button is the one
   way out — keeps the workflow inside UIL4B. */
.icust-code-box code{display:block;max-height:120px;overflow:auto;font-family:var(--mono);font-size:var(--fs-caption);line-height:1.55;color:var(--t1);white-space:pre-wrap;word-break:break-all;-webkit-user-select:none;user-select:none}
/* Footer + Pro save-lock — the four actions share the row width evenly and only
   wrap to a second line when the footer is genuinely too narrow, so none clip. */
.icust-foot{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:8px;padding:18px 24px 24px;border-top:1px solid var(--border)}
.icust-foot .ui-pill{flex:1 1 auto;min-width:max-content;height:40px;padding:0 14px;font-size:var(--fs-body-s);white-space:nowrap}
.icust-reset{margin-left:0}
.icust-save-lock{display:inline-flex;align-items:center;gap:10px;flex-wrap:wrap}
.icust-save--locked{cursor:pointer;opacity:.85}
.icust-save--locked:hover{opacity:1}
.icust-lock-glyph{display:inline-grid;place-items:center}
.icust-upgrade{font-size:var(--fs-caption);font-weight:600;color:var(--accent-strong);white-space:nowrap}
.icust-upgrade:hover{text-decoration:underline}

/* Similar icons — same-pack siblings, a foot-of-popup retention nudge */
.icust-similar{padding:16px 24px 24px;border-top:1px solid var(--border)}
.icust-similar-label{margin-bottom:12px;font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.icust-similar-row{display:flex;flex-wrap:wrap;gap:8px}
.icust-similar-btn{display:grid;place-items:center;width:44px;height:44px;padding:0;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);cursor:pointer;transition:border-color var(--dur-2) var(--ease-out),background var(--dur-2) var(--ease-out),transform var(--dur-2) var(--ease-out)}
.icust-similar-btn:hover{border-color:var(--bh);background:var(--hvr);transform:translateY(-1px)}
.icust-similar-btn img{display:block;width:24px;height:24px}

/* Recents rail */
.ig-rail{margin:8px 0 28px}
.ig-rail-head{display:flex;align-items:center;gap:12px;font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--t2);margin-bottom:10px}
.ig-rail-clear{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border:1px solid transparent;border-radius:var(--radius-s);background:none;font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--t3);cursor:pointer;transition:color var(--dur-2) var(--ease-out),border-color var(--dur-2) var(--ease-out),background var(--dur-2) var(--ease-out)}
.ig-rail-clear:hover{color:var(--accent-strong);border-color:var(--border);background:var(--bg-1)}
.ig-rail-clear svg{width:11px;height:11px}
/* overflow / scrollbar / edge fade come from `.rail-overflow` (see the block by
   the global scrollbar rules). This was the eighth instance of the hidden-
   scroller shape: `overflow-x:auto` with the scrollbar deleted on both
   properties. It is reachable by anyone who has copied an icon — the rail is
   the "recently used" strip — so it is converted rather than only recorded. */
.ig-rail-track{display:flex;gap:8px;padding-bottom:4px}
/* transform stays at --dur-1: it is :active-only press feedback, not a hover lift. */
.ig-rail-item{position:relative;flex:0 0 auto;display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);cursor:pointer;transition:border-color var(--dur-2) var(--ease-out),background var(--dur-2) var(--ease-out),transform var(--dur-1) var(--ease-out)}
.ig-rail-item:hover{border-color:var(--bh);background:var(--bg-2)}
.ig-rail-item:active{transform:scale(.94)}
.ig-rail-item img,.ig-rail-item svg{width:24px;height:24px}
.ig-rail-item svg{color:var(--t0);stroke-width:1.75;stroke-linecap:round;stroke-linejoin:round}
.ig-rail-badge{position:absolute;right:-5px;bottom:-5px;display:grid;place-items:center;width:17px;height:17px;border-radius:50%;border:2px solid var(--bg-0);color:#fff}
.ig-rail-badge svg{width:9px;height:9px}
.ig-rail-badge--edit{background:var(--accent)}
.ig-rail-badge--copy{background:var(--t2)}

/* Toolbar add-icon button (icon-scoped; does not touch shared .pl- toolbar bits) */
.ig-addbtn{flex-shrink:0;display:inline-flex;align-items:center;gap:7px;height:40px;padding:0 16px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-2);color:var(--t0);font-family:var(--font);font-size:13px;font-weight:600;cursor:pointer;white-space:nowrap;transition:border-color var(--dur-2) var(--ease-out),background var(--dur-2) var(--ease-out),color var(--dur-2) var(--ease-out)}
.ig-addbtn:hover{border-color:var(--accent);background:var(--accent-bg);color:var(--accent-strong)}
.ig-addbtn svg{flex-shrink:0}

/* Custom-icons: Pro lock + empty state */
.ig-custom-lock{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;max-width:420px;margin:0 auto;padding:72px 24px}
.ig-custom-lock-glyph{display:grid;place-items:center;width:56px;height:56px;border-radius:var(--radius-l);background:var(--accent-bg);color:var(--accent)}
.ig-custom-lock-title{font-family:var(--display);font-size:var(--fs-h4);font-weight:600;letter-spacing:-.01em;color:var(--t0)}
.ig-custom-lock-sub{max-width:340px;font-size:var(--fs-body-s);color:var(--t2);line-height:1.55}
.ig-custom-empty{max-width:460px;margin:0 auto;padding:56px 24px;text-align:center;font-size:var(--fs-body-s);color:var(--t2);line-height:1.6}

/* My Icons: two stacked, independently-clearable collections (Saved + Copied) */
.ig-myicons{display:flex;flex-direction:column;gap:32px}
.ig-mysec{display:flex;flex-direction:column;gap:14px}
.ig-mysec-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-bottom:10px;border-bottom:1px solid var(--border)}
.ig-mysec-title{font-family:var(--display);font-size:var(--fs-h5);font-weight:600;letter-spacing:-.01em;color:var(--t0)}
.ig-mysec .ig-custom-empty{margin:0;padding:32px 24px;text-align:left}
.ig-mysec .ig-custom-lock{padding:48px 24px}
/* Free-tier allowance hint under the Saved collection (non-Pro only). */
.ig-custom-hint{margin-top:4px;font-size:var(--fs-caption);color:var(--t3)}
.ig-custom-hint-link{font:inherit;color:var(--accent-strong);font-weight:600;background:none;border:0;padding:0;cursor:pointer}
.ig-custom-hint-link:hover{text-decoration:underline}

/* Fetch-fallback notice, skeletons, status line, sentinel, CDN invert, pack tag */
.ig-notice{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px;padding:12px 16px;border:1px solid color-mix(in srgb,var(--warn) 40%,var(--border));border-radius:var(--radius-s);background:color-mix(in srgb,var(--warn) 8%,var(--bg-1));font-size:var(--fs-body-s);color:var(--t1)}
.ig-notice span{flex:1;min-width:180px}
.ig-skel{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-height:80px;padding:16px 6px 12px}
.ig-skel-glyph{width:24px;height:24px;border-radius:var(--radius-xs)}
.ig-skel-label{width:60%;max-width:52px;height:8px;border-radius:var(--radius-pill)}
.ig-sentinel{width:100%;height:1px}
.ig-status{padding:20px 0;text-align:center;font-family:var(--mono);font-size:var(--fs-caption);color:var(--t3)}
.ig-inv{filter:var(--icon-inv)}
/* Brand-glyph contrast chip — colored/brand artwork can't be tinted for contrast,
   so it sits on a miniature of the customizer Stage: the light radial gradient by
   default, flipped to the dark Stage gradient (.ig-chip--dark) when pixel sampling
   finds the artwork itself is near-white. */
.ig-chip{display:flex;align-items:center;justify-content:center;width:36px;height:36px;flex-shrink:0;border-radius:8px;background:radial-gradient(120% 120% at 50% 0%,#FFFFFF 0%,#EDEDF0 72%);box-shadow:inset 0 0 0 1px rgba(10,10,11,.08)}
.ig-chip--dark{background:radial-gradient(120% 120% at 50% 0%,#17171B 0%,#0E0E11 62%);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}
/* object-fit, because the request now asks the API for a HEIGHT rather than a
   box (see BrandGlyph in IconLibrary.jsx). A 4:3 flag therefore arrives with a
   4:3 intrinsic size, and pinning both sides of a 24px box without `contain`
   would squash it. With it, the flag letterboxes to 24 x 18 exactly as before. */
.ig-chip img{width:24px;height:24px;display:block;object-fit:contain}

/* THE WIDE CHIP: a horizontal lockup gets the cell's width, not a 24px square.

   Measured on /create/icons under the Brand logos filter at 1440x900, painted
   glyph height inside the tile:

     logos/aerospike        11.38:1   24 x 2.1px  ->  106 x 9.3px
     logos/active-campaign   9.88:1   24 x 2.4px  ->  106 x 10.7px
     logos/500px             4.00:1   24 x 6.0px  ->  106 x 26.5px
     logos/adobe             3.81:1   24 x 6.3px  ->  106 x 27.8px
     devicon/*-wordmark      square canvas, wide ink: drawn across 106px, not 24

   The slot is the cell's full content width (118px cell less its 6px side
   padding) and stays 36px TALL — the same height as the square chip — so a row
   that contains a wide item is exactly as tall as one that does not and the
   grid rhythm is untouched. No column span, so nothing is re-ordered: #298
   rejected visual re-ordering on this codebase's grids on WCAG 2.4.3 grounds
   and that reasoning holds here.

   overflow:hidden with a centred, full-width image is what reaches devicon's
   `-wordmark` entries. Their canvas is square, so `width:100%` renders them
   106 x 106 with the lockup as a band across the middle; clipping to 36px shows
   that band at its natural size instead of the whole empty canvas shrunk to fit.
   Artwork that is genuinely wide never reaches the clip — at 106px wide it is
   already shorter than 36px — so one rule serves both causes.

   WHY A WIDER CELL RATHER THAN A SQUARE ONE, from the Mobbin pass: Squarespace's
   Asset Library gives a wide logotype a double-width cell in an otherwise
   uniform grid; Air lays assets out at a fixed row height with the cell width
   following each asset's aspect; Google Ads' logo picker keeps a uniform
   landscape thumbnail and fits the art inside it at its natural aspect, naming
   the aspect on the card. Arcade's Brand Kit goes furthest and splits
   "Logotypes" from "Icons" into two sections with different cell shapes. None of
   them letterboxes a lockup into a square. This is the Google Ads answer, which
   is the one that transplants into a dense icon grid without re-ordering it. */
.ig-chip--wide{width:100%;height:36px;overflow:hidden;position:relative}
/* NOTHING IS EVER CROPPED. `--ig-wide-cap` is measured per icon in sampleGlyph:
   how many multiples of this slot height the element may be drawn wide before
   the INK grows taller than the slot. A one-line lockup on a square canvas gets
   the full 100%; a two-line one gets a narrower element instead of losing its
   top and bottom rows; genuinely wide artwork is capped by 100% long before its
   own limit bites. The chip clips only the artwork transparent margins. */
/* Centred by absolute positioning rather than by the flex box: .ig-chip is
   display:flex at its own rule but computes flow-root here, and a top-aligned
   element that is 104px tall in a 36px slot shows its empty top margin instead
   of the lockup. Measured as blank tiles on eleven devicon -wordmark entries
   before this line existed. */
.ig-chip--wide img{position:absolute;left:50%;top:50%;width:min(100%,calc(36px * var(--ig-wide-cap,1)));height:auto;max-height:none;transform:translate(-50%,-50%)}
/* Logo.dev brand marks are raster and already coloured — size a touch larger
   than glyph icons, keep their own colours (no invert), and round the corners. */
.ic img.ig-logo{width:28px;height:28px;object-fit:contain;border-radius:5px}
.ig-chip img.ig-logo{width:28px;height:28px}
.ig-attrib{padding:6px 0 20px;text-align:center;font-size:var(--fs-caption);color:var(--t3);line-height:1.5}
.ig-attrib code{font-family:var(--mono);font-size:.92em;color:var(--t2)}
.ig-attrib a{color:var(--accent-strong);text-decoration:none;font-weight:600}
.ig-attrib a:hover{text-decoration:underline}
/* THE PACK LABEL IS NOW RENDERED ONLY WHEN THE RESULT SET IS MIXED, and the
   decision moved into IconLibrary.jsx because it depends on the results, not
   on the width. Read the note there for the Mobbin evidence.
   What was here before: #298 dropped the label below 980px and kept it above,
   reasoning that a wide cell can afford a third line and that a mixed-pack set
   (logo.dev, custom uploads) is where it earns its place. The first half was a
   width answer to a content question - at 1024px and up it still drew
   "LUCIDE" under all 120 cells of a single-pack grid, saying the same word 120
   times while the icon's own name truncated to make room for it. The second
   half was right, and is the rule now: the label appears when the set holds
   more than one pack and never otherwise.
   The width rule below SURVIVES on top of that. Under 980px the cell cannot
   afford a third line even when the word would tell you something, which is
   the density judgement #298 actually made.
   AND IT GOES 9px -> --fs-micro (11px). 9px is below the smallest size in the
   type scale, and a mono-ish uppercase label with tracking is the least
   legible thing there is at that size - the same argument that took
   `.ch-card-tag` from 9px to 11px. It costs nothing now that the label is
   rare. Contrast was measured on this surface rather than assumed: --t3 is
   4.55:1 in light and 5.77:1 in dark against the icon grid's own #EFEEE9 /
   #101012 ground, so it clears AA and stays. (The 3.70:1 figure recorded
   against --t3 elsewhere in this file is on --bg-3, a darker ground than
   this one.) */
.ic .ic-pack{font-size:var(--fs-micro);letter-spacing:.05em;text-transform:uppercase;color:var(--t3);line-height:1}
@media(max-width:980px){
  .ic .ic-pack{display:none}
}

@media(max-width:560px){
  .icust-overlay{padding:24px 12px 32px}
  .icust-panel{max-height:min(880px,calc(100dvh - 56px))}
  .icust-head{padding:20px 16px 12px}
  .icust-paste{padding:8px 16px 20px}
  .icust-stage{margin:4px 16px 0;padding:20px}
  .icust-meta{padding:12px 16px 0}
  .icust-controls{padding:16px 16px 4px}
  .icust-code{margin:12px 16px 0}
  .icust-foot{padding:16px 16px 20px;flex-wrap:wrap}
  .icust-row{flex-wrap:wrap}
  .icust-row>label{flex-basis:100%}
}

/* ══ Kept-page wrapper (nav clearance + container) ══ */
.page-shell{max-width:1216px;margin:0 auto;padding-inline:clamp(20px,4vw,32px);padding-bottom:var(--s-9);min-height:60vh}

/* ══ App shell — the account / billing / legal / system pages now live under the
   floating PillNav instead of the retired Sidebar + TopBar chrome. The window
   scrolls (no inner scroll pane); .app-page clears the nav and carries the same
   horizontal gutter the old .main had; AppFooter sits full-bleed at the bottom
   of the column, pushed down by .app-page's flex-grow on short pages. ══ */
.app-shell{min-height:100dvh;display:flex;flex-direction:column;background:var(--bg-0)}
.app-page{flex:1 0 auto;display:flex;flex-direction:column;width:100%;padding:var(--nav-clear) var(--page-inline) clamp(48px,6vw,80px)}
.app-page>*{min-width:0}
.app-page>*:first-child{padding-top:clamp(12px,3vw,32px)}

/* ══ Tool-page shell (rail-) ══ */
/* The in-tool left rail is retired — navigation lives entirely in the PillNav
   mega-menus, so the shell is a single full-width content column. */
/* The reserve is `100dvh - 240px`, not `100vh`, and the 240 is measured rather
   than chosen. A full viewport was being held open for content that does not
   need it: on /create/alt-text and /create/file-converter the painted content
   ends at ~545px inside an 1112px tablet viewport, so 567px of bare background
   sat between the tool and the footer (292px at 390px wide).
   The reserve exists so a short tool page does not leave page background BELOW
   the footer, and the footer itself is what makes that affordable — measured on
   `.app-footer--compact`: 254px at 1440, 263px at 834, 609px at 390, 630px at
   320. Subtracting less than the smallest of those (240px) keeps shell + footer
   taller than the viewport at every width, while giving the dead band back:
   567px → 327px at 834, and 292px → 52px at 390.
   `dvh` rather than `vh` so a mobile browser's collapsing URL bar does not add
   its own gap on top of this one.

   SCOPED TO ≤980px, and that is not tidiness either. The full-viewport reserve
   is also the scroll HEADROOM that "scroll this region to the top" depends on:
   the home page's image hand-off routes into the File Converter and scrolls the
   upload queue up under the nav, and with 240px taken off the page there was no
   longer enough scroll range to finish the move — the first uploaded card
   landed 5.4px below the fold, caught by 10-home-chaos-to-calm 11a. The dead
   band was only ever reported at tablet and phone, so desktop keeps its full
   reserve and the hand-off keeps its runway. */
.rail-shell{display:grid;grid-template-columns:1fr;min-height:100dvh;padding-top:var(--nav-clear)}
@media(max-width:980px){
  .rail-shell{min-height:calc(100dvh - 240px)}
}
.rail-content{min-width:0;padding:24px var(--page-inline) var(--s-9)}
/* The `.rail-content .pl-toolbar{top:var(--nav-clear)}` override that used to
   sit here is GONE, and its value is now the base rule instead. It never
   matched anything: `.rail-content` is rendered only by CreateTool.jsx, and the
   one live consumer of `.pl-toolbar` is PromptLibrary, which is not inside it.
   Meanwhile the base rule said `top:0`, so the only bar that used the class
   pinned itself under the floating nav. See `.pl-toolbar` for the measurements. */

/* ══ Coming-soon tool state (soon-) ══ */
.soon{max-width:560px;margin:0 auto;padding:var(--s-9) 0}
.soon .spec-frame{aspect-ratio:16/10;margin-bottom:var(--s-6)}
.soon-mark{margin-bottom:var(--s-4)}
.soon-title{font-size:var(--fs-h2);font-weight:700;letter-spacing:-.02em;line-height:1.12;color:var(--t0);margin-bottom:12px;text-wrap:balance}
.soon-text{font-size:var(--fs-body);color:var(--t1);line-height:1.6;margin-bottom:var(--s-6);max-width:48ch}
.soon-actions{display:flex;gap:12px;flex-wrap:wrap}

/* ══ Surface landing (Discover / Learn) — surface- ══ */
/* `align-items:start` so a card is as tall as what it holds. Stretched, the
   four coming-soon cards were pulled to the height of the preview cards beside
   them and carried 150px of empty white with a Soon badge stranded at the
   bottom. Tines' resource grid on Mobbin varies card weight deliberately —
   it is what stops a grid of one shape reading as a table. */
.surface-grid{display:grid;grid-template-columns:repeat(3,1fr);align-items:start;gap:var(--s-4);margin-top:var(--s-7)}
.surface-card{display:flex;flex-direction:column;gap:8px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-xl);padding:20px;box-shadow:var(--shadow-xs)}
.surface-card-title{display:flex;align-items:center;gap:8px;font-size:var(--fs-h3);font-weight:600;letter-spacing:-.016em;color:var(--t0)}
.surface-card-desc{font-size:var(--fs-body-s);color:var(--t2);line-height:1.5}
.surface-card .soon-badge{align-self:center}
.surface-card--link{text-decoration:none;transition:border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
.surface-card--link:hover{border-color:var(--brand);box-shadow:var(--shadow-s)}
.surface-card-go{font-size:var(--fs-body-s);font-weight:600;color:var(--accent-strong)}

/* ── Discover card previews ─────────────────────────────────────────────────
   A browse surface has to show what there is to browse. These sit above the
   title and are drawn from the real gallery data (see PREVIEWS in
   SurfaceLanding.jsx), with the count as a pill over the corner — the shape
   Webflow's Libraries grid uses. Cards for libraries that have not shipped
   carry no preview, which is what makes live and coming-soon read apart at a
   glance instead of via a badge you have to find. */
.surface-card-preview{position:relative;display:block;overflow:hidden;margin:-4px 0 6px;padding:14px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-2)}
/* The card's bottom rail: the call to action on the left, how much is in there
   on the right. `margin-top:auto` moves here from .surface-card-go, so it is
   the rail that is pushed to the foot and the two stay on one baseline. */
.surface-card-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:auto;padding-top:4px}
.surface-card-meta{font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.06em;color:var(--t3);white-space:nowrap}
/* Palettes — three real systems, each a row of its own swatches. */
.scp-stack{display:flex;flex-direction:column;gap:6px}
.scp-row{display:flex;gap:4px;height:22px}
.scp-chip{flex:1 1 0;min-width:0;border-radius:5px;box-shadow:inset 0 0 0 1px rgb(0 0 0/.06)}
/* Gradients — three real gradients at the angle they are actually stored at. */
.scp-tiles{display:flex;gap:6px;height:78px}
.scp-tile{flex:1 1 0;min-width:0;border-radius:var(--radius-s);box-shadow:inset 0 0 0 1px rgb(0 0 0/.06)}
/* Type — a specimen block in the two families the app actually ships (see the
   note in SurfaceLanding.jsx: --display is Manrope, the same face as --font). */
.scp-type{display:flex;flex-direction:column;justify-content:center;gap:4px;height:78px;color:var(--t0);overflow:hidden}
.scp-type-display{font-size:30px;font-weight:750;letter-spacing:-.03em;line-height:1}
.scp-type-body{font-size:14px;font-weight:400;color:var(--t1);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.scp-type-mono{font-family:var(--mono);font-size:11px;letter-spacing:.02em;color:var(--t2);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.scp-icons{display:flex;align-items:center;justify-content:space-between;gap:8px;height:78px;color:var(--t1)}
.scp-icon svg{width:24px;height:24px}
.scp-lines{display:flex;flex-direction:column;justify-content:center;gap:6px;height:78px}
.scp-line{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:5px 9px;border-radius:var(--radius-s);background:var(--bg-1);border:1px solid var(--border);font-size:var(--fs-micro);color:var(--t2)}
.surface-card--link:hover .surface-card-preview{border-color:var(--brand)}

/* The surface heroes are NOT the homepage hero. See the note in
   SurfaceLanding.jsx: they carry a fraction of the content and inherited a
   min-height that left 401px of the first screen empty at 1440x900.
   Doubled class on purpose: `.home-hero` is declared 100+ lines further down
   the sheet, so at equal specificity IT would win and this rule would be a
   dead letter — which is exactly what happened on the first attempt. */
.home-hero.home-hero--surface{min-height:0;padding-bottom:var(--s-7)}

/* ══ Surface sales — value pillars (sl-) ══ */
.sl-pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--s-4);margin-top:var(--s-7)}
.sl-pillar{display:flex;flex-direction:column;gap:10px;padding:22px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-xl);box-shadow:var(--shadow-xs)}
.sl-pillar-num{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:var(--radius-s);background:var(--accent-bg);color:var(--accent-strong);font-family:var(--mono);font-size:13px;font-weight:600}
.sl-pillar-title{font-size:var(--fs-h3);font-weight:600;letter-spacing:-.016em;color:var(--t0)}
.sl-pillar-desc{font-size:var(--fs-body-s);color:var(--t2);line-height:1.55}

/* ══ Stylized world map (wmap-) — decorative social proof, no user data ══ */
.wmap{margin:var(--s-7) auto 0;max-width:1000px}
.wmap-frame{position:relative;width:100%;aspect-ratio:1000/500}
.wmap-svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.wmap-dot{fill:var(--t3);opacity:.28;transition:opacity var(--dur-3) var(--ease-out)}
.wmap[data-region] .wmap-dot{opacity:.15}
.wmap-hubs{position:absolute;inset:0}
.wmap-blip{position:absolute;display:grid;place-items:center;width:24px;height:24px;transform:translate(-50%,-50%);padding:0;border:none;background:none;cursor:pointer;color:var(--accent-strong);line-height:0}
.wmap-blip-dot{display:block;width:11px;height:11px;border-radius:50%;background:currentColor;box-shadow:0 0 0 4px color-mix(in srgb,currentColor 22%,transparent);position:relative;transition:transform var(--dur-2) var(--ease-out)}
.wmap-blip-dot::after{content:"";position:absolute;inset:0;border-radius:50%;background:currentColor;animation:wmap-ping 2.6s var(--ease-out) infinite}
.wmap-blip:hover{z-index:5}
.wmap-blip:hover .wmap-blip-dot,.wmap-blip:focus-visible .wmap-blip-dot{transform:scale(1.25)}
.wmap-blip:focus-visible{outline:none}
.wmap-blip:focus-visible .wmap-blip-dot{box-shadow:0 0 0 4px var(--accent-bg),0 0 0 6px var(--accent)}
.wmap-blip[data-dim="true"]{opacity:.34;filter:grayscale(.45)}
.wmap-blip.is-on{z-index:4}
.wmap-blip.is-on .wmap-blip-dot{transform:scale(1.3)}
.wmap-blip.is-on .wmap-blip-dot::after{animation-duration:1.6s}
.wmap-blip.is-home{width:auto;min-width:24px;color:var(--t0);z-index:6}
.wmap-pin{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 9px 0 8px;border-radius:var(--radius-pill);background:var(--t0);color:var(--bg-0);box-shadow:var(--warm-shadow-lg,var(--shadow-l));position:relative}
.wmap-pin::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent) 30%,transparent)}
.wmap-pin::after{content:"";position:absolute;left:50%;bottom:-4px;width:9px;height:9px;background:var(--t0);transform:translateX(-50%) rotate(45deg);border-radius:2px}
.wmap-pin-word{font-family:var(--mono);font-size:11px;font-weight:700;letter-spacing:.02em;line-height:1}
.wmap-tip{position:absolute;left:50%;bottom:calc(100% + 6px);transform:translateX(-50%);white-space:nowrap;padding:5px 9px;border-radius:var(--radius-s);background:var(--t0);color:var(--bg-0);font-size:11px;font-weight:600;letter-spacing:.01em;box-shadow:var(--shadow-s);opacity:0;visibility:hidden;transition:opacity var(--dur-2) var(--ease-out);pointer-events:none;z-index:7}
.wmap-blip.is-home .wmap-tip{bottom:calc(100% + 9px)}
.wmap-blip:hover .wmap-tip,.wmap-blip:focus-visible .wmap-tip{opacity:1;visibility:visible}
.wmap-tip::after{content:"";position:absolute;left:50%;top:100%;transform:translateX(-50%);border:4px solid transparent;border-top-color:var(--t0)}
/* N4 (responsive-audit-2026-08): the tip is centred on its blip with
   `left:50%; translateX(-50%)`, so the rightmost blip's tip ran past `.home`,
   which carries `overflow-x:clip` — the last few characters were cut and could
   not be scrolled to. Measured 9px past at 320px, 6px at 360, 4px at 390, 3px at
   400, 1px at 430, clean from 480.

   Clamping the tip to its container is not expressible from here: its containing
   block is the blip, not the map, so no `inset` value can see the map's edge.
   What is available is making the tip narrow enough that being centred cannot
   push it out — letting it take two lines instead of one. Measured after: 0 of
   15 tips past the edge at every width on both /discover and /learn.

   Note `visibility` stays a plain state property on the rule above and is NOT in
   its transition — that pairing is deliberate and is left exactly as it is. */
@media(max-width:480px){
  .wmap-tip{white-space:normal;max-width:min(130px,36vw);text-align:center}
}
.wmap-foot{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:12px 18px;margin-top:var(--s-5);text-align:center;min-height:34px}
.wmap-cap{font-size:var(--fs-caption);color:var(--t3);max-width:56ch;line-height:1.5}
.wmap-callout{display:inline-flex;align-items:center;gap:10px;padding:8px 14px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg-1);box-shadow:var(--shadow-xs)}
.wmap-callout-region{font-size:var(--fs-body-s);font-weight:600;color:var(--t0)}
.wmap-callout-cities{font-size:var(--fs-caption);color:var(--t2)}
.wmap-callout-clear{border:none;background:none;color:var(--accent-strong);font-family:var(--font);font-size:var(--fs-caption);font-weight:600;cursor:pointer;padding:2px 4px;border-radius:var(--radius-xs)}
.wmap-callout-clear:hover{text-decoration:underline}
@keyframes wmap-ping{0%{transform:scale(1);opacity:.5}70%,100%{transform:scale(2.6);opacity:0}}
html[data-reduced-motion="true"] .wmap-blip-dot::after{animation:none}
html[data-reduced-motion="true"] .wmap-dot,html[data-reduced-motion="true"] .wmap-blip-dot,html[data-reduced-motion="true"] .wmap-tip{transition:none}
@media (prefers-reduced-motion:reduce){
  html:not([data-reduced-motion="false"]) .wmap-blip-dot::after{animation:none}
  html:not([data-reduced-motion="false"]) .wmap-dot,html:not([data-reduced-motion="false"]) .wmap-blip-dot,html:not([data-reduced-motion="false"]) .wmap-tip{transition:none}
}
@media (max-width:640px){
  .sl-pillars{grid-template-columns:1fr}
  .wmap-pin-word{font-size:10px}
  .wmap-blip-dot{width:9px;height:9px}
}

/* ══ Sales / home page (home-) ══ */
/* The accent radial wash is GONE. V2's ground is warm bone (--bg-0 #EFEEE9) and
   content floats on white --surf cards above it; the spec is explicit that the
   page is not tinted with the accent hue, and the blue wash over the bone read
   as a colour cast rather than as depth.
   Docs: docs/reference/design-language-v2.md#page-background */
.home{position:relative;overflow-x:clip;background:var(--bg-0)}
.home::before{content:"";position:absolute;inset:0 0 auto;height:760px;pointer-events:none;opacity:.46;background-image:
  linear-gradient(color-mix(in srgb,var(--t0) 4%,transparent) 1px,transparent 1px),
  linear-gradient(90deg,color-mix(in srgb,var(--t0) 4%,transparent) 1px,transparent 1px);
  background-size:48px 48px;mask-image:linear-gradient(to bottom,#000,transparent 82%)}
.home>main,.home>.home-foot{position:relative}
/* The sales-page measure is deliberately capped at 1216px of CONTENT, but its
   gutter is the shared one — below the cap the homepage's content edge lands
   exactly where the nav's and the footer's do. The cap carries the gutter so
   widening the gutter narrows the page instead of the measure. */
.home-container{max-width:calc(1216px + 2*var(--page-inline));margin:0 auto;padding-inline:var(--page-inline)}
.home-section{padding-top:var(--sec-pad);padding-bottom:0}
.home-head{max-width:720px}
.home-head-center{margin:0 auto;text-align:center}
.home-eyebrow{display:inline-flex;align-items:center;gap:12px;font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.14em;text-transform:uppercase;color:var(--t2)}
.home-eyebrow::before{content:"";width:24px;height:1px;background:var(--bh)}
.home-head-center .home-eyebrow{justify-content:center}
.home-h2{font-size:var(--fs-h1);font-weight:700;letter-spacing:-.028em;line-height:1.06;color:var(--t0);text-wrap:balance;margin-top:16px}
.home-lede{font-size:var(--fs-lede);color:var(--t1);line-height:1.5;max-width:60ch;margin-top:16px;text-wrap:pretty}
.home-head-center .home-lede{margin-inline:auto}

/* Hero */
.home-workspace-intro{position:relative;isolation:isolate}
/* The hero owns the first screen. It was a flat 720px, which on any laptop
   taller than that left the workbench sitting in the opening viewport — the
   founder's "the mini tools are visible before scrolling". A fixed pixel height
   cannot answer that, because the fold is a property of the VIEWPORT.
   `100svh` is: the small-viewport unit, so a mobile browser's collapsing URL bar
   cannot make the hero taller than the screen it is measured against. Clamped at
   980px so an ultra-tall monitor does not stretch the copy into a void, and
   floored by the content itself via min-height on a flow element. */
.home-hero{position:relative;isolation:isolate;text-align:center;max-width:1180px;min-height:min(100svh,980px);margin:0 auto;padding:calc(var(--nav-top) + var(--nav-h) + var(--s-7)) 24px var(--s-8)}
/* The 70px top margin here was headroom for the absolutely-positioned satellite
   field, which V2 removed. Keeping it pushed the hero's primary CTA below an
   800px fold once the command bar arrived — see the below-the-fold test. */
/* Wide enough that the 96px headline breaks in two or three lines rather than
   four — the sub-copy and command bar keep their own narrower measures below. */
.home-hero-core{position:relative;z-index:2;max-width:1080px;margin:0 auto}
/* V2 display scale — design-language-v2.md, "Display scale". */
/* LINE-HEIGHT AND THE HIGHLIGHT ARE COUPLED, which is not obvious and cost a
   visible break on a phone. `.home-mark` paints a background on an INLINE
   element, so its box is the line box — and at line-height below 1 the line box
   is shorter than the glyphs it contains, so a marked run on one visual line
   paints over the descenders of the line above it.

   That never showed while the headline was two short lines that did not wrap
   inside a span. The current headline wraps to four visual lines at 390px, both
   marked and unmarked, and the highlight sat on top of the words above it.

   .98 stays where the line cannot collide with itself; anywhere the headline is
   guaranteed to wrap, the line box gets enough height to hold its own
   background. Measured at 390, 768 and 1440. */
.home-hero-h1{font-size:clamp(46px,6.6vw,96px);font-weight:800;letter-spacing:-.045em;line-height:.98;color:var(--t0);text-wrap:balance}
/* Measured at 390x844. Two things were wrong and they compound:
   the clamp floors at 46px, which puts this headline on FOUR lines and fills
   the whole first screen with it; and at line-height 1.08 the descender of
   "stay" reaches into the band where the next line paints its highlight, so
   the mark covered the "y". A smaller floor gives three lines, and the extra
   leading clears the descender. Both verified by screenshot, not by eye. */
@media(max-width:900px){.home-hero-h1{font-size:clamp(34px,9vw,58px);line-height:1.14}}
/* Each headline line is its own block so the two phrases break cleanly instead of
   colliding ("design systembefore"); the inner span is inline-block so GSAP's
   yPercent slide-up reveal (useHomeMotion) has a transformable box to animate. */
/* The reveal is a CLIP-up: the inner span starts fully below its own line box and
   rises into view behind this hidden overflow. Without the clip the two headline
   lines slide THROUGH one another — which is what shipped, because the tween
   said `yPercent:110` and nothing ever masked it. The padding/negative-margin
   pair buys room for descenders (line-height is .98, so `g` and `y` hang below
   the box and would be shaved off) without moving where the line sits. */
/* C5 (founder batch 2026-08-20, spec §2.1 / F-2). The compensation used to be
   BOTTOM ONLY at .14em, so the --hi mark on line 2 — which paints the full
   inline box, not the line box — was sheared by this same overflow:hidden.
   Measured at 1440×900: a 130px painted mark against a 106.44px line box, 19px
   off the top and 4.56px still off the bottom.

   The value is derived, not chosen. `line-height:.98` against Manrope's
   1.368em content area leaves (1.368 − .98) ÷ 2 ≈ .194em of half-leading
   overflowing each edge — .2em covers it, and it is expressed in `em` so it
   holds at every clamp() size (measured 19px needed / 19.01px given at 95.04px,
   13px / 13.52px at 67.58px, 9px / 9.2px at 46px). Mirroring the old .14em
   would have under-delivered by ~6px and the mark would still have clipped.

   .28em, not .2em, because `.home-mark` now also carries `padding-block:.06em`
   (same spec item) and that padding grows the painted box on both edges:
   .194em half-leading + .06em mark padding = .254em. Ship .2em WITH that
   padding and 5.7px shears off again at the 96px cap. Rounded up to .28em
   rather than .26em because .26em was measured at 0.01px of slack — a fit that
   thin is one font-metric rounding difference away from clipping again; .28em
   leaves 1.9px at the 96px cap and stays proportional at every clamp size.

   overflow:hidden STAYS — it is the mask for the `home-hero-clip-up` entrance,
   and without it the two headline lines slide through one another. Widening it
   moves where the mask starts, so the entrance is browser-verified, not just
   measured. Do not relax `line-height` instead: .98 is the V2 display scale and
   the overflow is a function of the font's ascent/descent, not the leading. */
.home-hero-line{display:block;overflow:hidden;padding-block:.28em;margin-block:-.28em}
.home-hero-line-in{display:inline-block}

/* ── Hero entrance ──────────────────────────────────────────────────────────
   Pure CSS, deliberately. This was a GSAP timeline, which meant the headline sat
   at opacity:0 behind `.motion-armed` until a ~40KB dynamic import resolved — on
   a throttled CPU that is ~350ms of blank hero followed by a pop, which is the
   opposite of smooth. A fire-once entrance does not need a timeline: keyframes
   start at first paint, cost no JavaScript, and survive the motion chunk failing
   outright.

   Transform and opacity ONLY. The old version also tweened `filter:blur(12px)`
   across the largest text on the page, which forces a full re-rasterisation
   every frame — measured at 21 dropped frames per load, worst frame 333ms. The
   blur was the expense; the clip-up is what actually reads. */
@keyframes home-hero-clip-up{from{transform:translate3d(0,110%,0)}to{transform:none}}
@keyframes home-hero-rise{from{opacity:0;transform:translate3d(0,18px,0)}to{opacity:1;transform:none}}

/* `both` fill supplies the pre-paint hidden state, so no JS arming class is
   needed to prevent a flash. */
.home-hero-kicker{animation:home-hero-rise .5s var(--ease-entrance) both}
.home-hero-line-in{animation:home-hero-clip-up .92s var(--ease-entrance) .08s both}
.home-hero-line:nth-of-type(2) .home-hero-line-in{animation-delay:.18s}
.home-hero-sub{animation:home-hero-rise .66s var(--ease-entrance) .42s both}
/* The command bar is the hero's primary instrument, so it arrives before the
   buttons do — the visitor can start typing while the CTAs are still settling. */
.hcmd{animation:home-hero-rise .62s var(--ease-entrance) .52s both}
.home-hero-cta>*{animation:home-hero-rise .6s var(--ease-entrance) .64s both}
.home-hero-cta>*+*{animation-delay:.72s}
.home-hero-hint{animation:home-hero-rise .56s var(--ease-entrance) .8s both}

/* Reduced motion settles the hero instantly. Mirrors prefersReducedMotion() in
   useHomeMotion.js exactly: an explicit `data-reduced-motion` attribute wins
   over the OS query in BOTH directions, so a visitor who turned motion back on
   inside the app still gets the entrance. */
@media (prefers-reduced-motion:reduce){
  html:not([data-reduced-motion="false"]) :is(.home-hero-kicker,.home-hero-line-in,.home-hero-sub,.hcmd,.home-hero-cta>*,.home-hero-hint){animation:none}
}
html[data-reduced-motion="true"] :is(.home-hero-kicker,.home-hero-line-in,.home-hero-sub,.hcmd,.home-hero-cta>*,.home-hero-hint){animation:none}
/* V2 body: 54ch measure, --mute, line-height 1.65. */
.home-hero-sub{font-size:var(--fs-lede);font-weight:400;color:var(--t2);line-height:1.6;max-width:54ch;margin:var(--s-5) auto 0;text-wrap:pretty}
/* C5 rhythm: the mark now occupies more of its line box and the headline's
   collapsed bottom margin grew from -.14em to -.28em, so the sub-line needs the
   next spacing step to keep the same optical gap. Declared BEFORE the
   `max-height:900px` block below on purpose — that block's --s-4 override must
   still win on short laptops, where the below-the-fold contract binds. */
@media(min-width:981px){
  .home-hero-sub{margin-top:var(--s-6)}
}
.home-hero-cta{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:var(--s-6)}
.home-hero-hint{font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.08em;text-transform:uppercase;color:var(--t3);margin-top:var(--s-4)}

/* ── TEMPORARY · hero direction explorer ──────────────────────────────────────
   Backlog item `hero-copy-still-reads-ai`. Delete this block together with
   src/components/HomeHeroDirections.jsx when the founder picks a direction.
   Nothing here can affect the shipped hero: every rule is under
   .home-hero--dir, which only exists when ?hero=a|b|c is in the URL. */
.home-hero--dir{position:relative}
.hero-dir-flag{display:block;width:fit-content;max-width:100%;margin:0 auto var(--s-6);padding:6px 14px;border:1px dashed var(--border);border-radius:var(--radius-pill);background:var(--bg-1);color:var(--t3);font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.04em;line-height:1.5;text-align:center}
.hero-dir-flag code{font-family:var(--mono)}

/* A · the bar opens the page. The headline is a caption, so it takes body
   weight and the --t2 ink of supporting copy rather than display treatment;
   the bar is what the eye lands on. */
.home-hero--dir{display:flex;flex-direction:column}
/* `.home-hero-core` carries `margin:0 auto`, and auto inline margins on a flex
   item suppress the cross-axis stretch — so the core, and every bar inside it,
   was shrinking to its own content instead of taking its max-width. Stretch it
   back explicitly and let each variant's own max-width do the constraining. */
.home-hero--dir .home-hero-core{display:flex;flex-direction:column;flex:1 1 auto;align-self:stretch;width:100%}
.home-hero--dir .hcmd{width:100%}
/* Grok's arrangement, which is the reference: input in the optical centre, the
   sentence that explains it at the foot of the fold rather than under the bar.
   The empty space between them is the point — it is what makes the instrument
   read as the subject instead of as one more element in a stack. */
.hero-dir-a{text-align:center;justify-content:center}
.hero-dir-a .hero-a-under{margin-top:var(--s-6)}
@media(min-width:1025px){
  .hero-dir-a .hero-a-under{position:absolute;left:0;right:0;bottom:var(--s-8);margin-top:0}
}
.hero-a-h1{font-size:var(--fs-lede);font-weight:500;line-height:1.5;color:var(--t2);letter-spacing:0;max-width:44ch;margin:0 auto var(--s-5);text-wrap:pretty}
.hero-dir-a .hcmd{max-width:760px;margin-inline:auto;margin-top:0}
.hero-dir-a .hcmd-bar{min-height:84px;border-radius:var(--radius-xl,20px);padding-left:24px}
.hero-dir-a input.hcmd-input{height:80px;font-size:clamp(20px,2.4vw,30px);font-weight:600}
.hero-dir-a .hcmd-prompt{font-size:clamp(20px,2.4vw,30px)}
.hero-a-under{margin-top:var(--s-5);font-size:var(--fs-body-s);color:var(--t3)}
.hero-a-under a{color:var(--t1);text-underline-offset:3px}

/* B · off the centre axis. The right of the fold is left EMPTY on purpose —
   filling it is how the symmetry comes back wearing a different hat. */
.hero-dir-b{text-align:left;max-width:none;justify-content:flex-start}
.hero-b-h1{font-size:clamp(34px,5vw,68px);font-weight:800;letter-spacing:-.04em;line-height:1.06;color:var(--t0);max-width:16ch;text-wrap:balance}
.hero-b-sub{margin-top:var(--s-4);font-size:var(--fs-lede);color:var(--t2);max-width:34ch;line-height:1.55}
.hero-dir-b .hcmd{margin-left:0;margin-right:auto;max-width:560px}
.hero-b-cta{justify-content:flex-start}
@media(min-width:901px){
  .hero-dir-b{align-self:flex-start;max-width:min(100%,62ch);margin-right:auto;margin-left:0}
}

/* C · subtraction. One headline, the bar, one link — and a flag on the
   placeholder line so it cannot be mistaken for proposed copy. */
.hero-dir-c{text-align:center;justify-content:center}
.hero-c-placeholder-flag{font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--accent-strong);margin-bottom:var(--s-3)}
.hero-c-h1{font-size:clamp(32px,4.6vw,62px);font-weight:800;letter-spacing:-.035em;line-height:1.08;color:var(--t0);max-width:20ch;margin:0 auto var(--s-6);text-wrap:balance;opacity:.45}
.hero-dir-c .hcmd{margin-inline:auto;margin-top:0}

@media(max-width:640px){
  .hero-dir-a .hcmd-bar{min-height:64px;padding-left:16px}
  .hero-dir-a input.hcmd-input{height:60px}
  .hero-b-h1{max-width:none}
  .hero-b-sub{max-width:none}
}
/* ── end temporary block ───────────────────────────────────────────────────── */

/* Trust / stat strip (honest — no fabricated logos) */


/* ══ V2 homepage ═══════════════════════════════════════════════════════════════
   Built against docs/reference/design-language-v2.md. Colour comes entirely
   from existing role tokens, so this block inherits the V2 palette the moment
   feat/v2-token-foundation remaps them — nothing here names a hex.

   ⚠️ ACCENT CONTRAST (founder, 2026-08-16): the V2 accent is blue #0F6FFF,
   which measures ≈3.85:1 on the page ground — fine for fills, borders, icons,
   large display text and focus rings, and BELOW the 4.5:1 floor for normal
   text. Every accent-coloured string in this block that is smaller than large
   text therefore uses --accent-strong, never --accent. If you add an accent
   text colour here, check its size first.

   The five V2 tokens this block consumes — --hi, --hi-fg, --radius-3xl,
   --shadow-cmd, --shadow-panel — are owned by feat/v2-token-foundation. */

/* ── Shared V2 section furniture ── */
.hbrow{display:inline-flex;align-items:center;font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong)}
.hh2{margin-top:var(--s-4);font-size:clamp(30px,3.8vw,48px);font-weight:800;letter-spacing:-.04em;line-height:1.04;color:var(--t0);text-wrap:balance}
.hlede{margin-top:var(--s-4);max-width:54ch;font-size:var(--fs-lede);font-weight:400;line-height:1.6;color:var(--t2);text-wrap:pretty}

/* ── Hero ────────────────────────────────────────────────────────────────────
   Composition is the page's existing centred measure; every TYPE and SPACING
   value is the V2 display scale. */
/* The centred stat strip that used to sit above the headline is gone — see the
   note in Home.jsx. What replaces it is a single quiet category line, the way a
   product page names its own category rather than opening with proof. */
.home-hero-kicker{font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--t3);margin:0}
/* The catalogue figures, now beside the toolset grid they describe. A
   definition list because that is what they are: a number and what it counts. */
.htools-facts{display:flex;flex-wrap:wrap;gap:var(--s-6);margin:var(--s-5) 0 0;padding:0}
.htools-facts>div{display:grid;gap:2px}
.htools-facts dt{font-size:var(--fs-h4,22px);font-weight:700;line-height:1;letter-spacing:-.02em;color:var(--t0);font-variant-numeric:tabular-nums}
.htools-facts dd{margin:0;font-size:var(--fs-body-s);color:var(--t2)}

/* The single --hi element on this viewport. It is a marker pen, and the budget
   is one per screen — see design-language-v2.md. `box-decoration-break:clone`
   keeps both halves of a wrapped mark rounded and padded. */
/* `line-height` HERE, not just on the h1. The background of an inline element
   is painted over its INLINE BOX, and by default that box is the font's own
   natural height (~1.3em for Manrope 800) regardless of the tighter line-height
   on the heading. On a headline that wraps, that meant the highlight on one
   visual line painted straight over the descenders of the line above — visible
   as the "y" of "that stay" being sliced off at 390px.
   Setting it on the mark shrinks the painted box without loosening the display
   setting on the heading itself, which is the look this hero is built on.
   `padding-block:.06em` is C5 and a SEPARATE fix from the line-height: it is
   what makes the mark read as a marker pen rather than a tight underlay, and
   it is why `.home-hero-line` compensates .28em rather than .14em. Those two
   values are one decision and must move together. The line-height governs the
   painted box, the padding governs the ink around the glyphs; neither
   substitutes for the other, which is why keeping only one of them left the
   mark clipped at the top on every desktop width. */
.home-mark{background:var(--hi);color:var(--hi-fg);border-radius:var(--radius-xs);line-height:1;padding:0 .1em;padding-block:.06em;margin:0 -.02em;box-decoration-break:clone;-webkit-box-decoration-break:clone}

/* ── Command bar (structural pattern 2) ── */
.hcmd{max-width:660px;margin:var(--s-5) auto 0;text-align:left}
/* Short laptop screens: the hero's own rhythm tightens so the primary CTA and
   the trust line stay above the fold at 1280×800, which is the founder-reported
   condition the below-the-fold test guards. Type sizes are untouched — only the
   gaps between blocks give way. */
@media(max-height:900px){
  .home-hero{padding-top:calc(var(--nav-top) + var(--nav-h) + var(--s-6))}
  .home-hero-sub{margin-top:var(--s-4)}
  .hcmd{margin-top:var(--s-4)}
  .home-hero-cta{margin-top:var(--s-5)}
}
.hcmd-bar{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;min-height:60px;padding:0 10px 0 18px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-1);box-shadow:var(--shadow-cmd);transition:border-color var(--dur-2) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
.hcmd-bar:focus-within{border-color:var(--accent)}
.hcmd-prompt{font-family:var(--mono);font-size:var(--fs-body);font-weight:700;color:var(--accent-strong)}
/* `input.` prefix, the same idiom as input.cs-hue-slider above and for the same
   reason: this MUST outrank the global input[type="text"] reset at the top of
   the file, whose 0,1,1 beats a bare 0,1,0 class no matter which comes later.
   Until it did, the hero's own search box was painting a second white, rounded,
   1px-bordered rectangle inside .hcmd-bar — and on focus a second ring inside
   the bar's — plus taking the reset's 13px over the --fs-body this rule asks
   for. Visible on every viewport since the bar shipped, and unmissable now the
   founder has removed the label and chips that used to flank it. */
input.hcmd-input{min-width:0;height:56px;padding:0;border:0;border-radius:0;background:none;color:var(--t0);font-family:var(--font);font-size:var(--fs-body);font-weight:500}
.hcmd-input::placeholder{color:var(--t3)}
input.hcmd-input:focus{outline:none;box-shadow:none}
.hcmd-kbd{display:inline-flex;align-items:center;min-height:36px;padding:0 12px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg-2);cursor:pointer;transition:background var(--dur-1) var(--ease-standard),border-color var(--dur-1) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
.hcmd-kbd:hover{background:var(--hvr);border-color:var(--bh)}
.hcmd-kbd:active{transform:scale(.96)}
.hcmd-kbd:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.hcmd-kbd kbd{font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.06em;color:var(--t2)}

.hcmd-results{margin-top:var(--s-3);border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-1);box-shadow:var(--shadow-cmd);overflow:hidden}
.hcmd-list{list-style:none}
.hcmd-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:14px;padding:13px 16px;border-top:1px solid var(--border);text-decoration:none;transition:background var(--dur-1) var(--ease-standard)}
.hcmd-list li:first-child .hcmd-row{border-top:0}
.hcmd-row:hover{background:var(--hvr);text-decoration:none}
.hcmd-row:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.hcmd-row-glyph{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-2);color:var(--accent)}
.hcmd-row-glyph svg{width:17px;height:17px}
.hcmd-row-body{display:flex;min-width:0;flex-direction:column;gap:2px}
.hcmd-row-title{font-size:var(--fs-body-s);font-weight:700;letter-spacing:-.01em;color:var(--t0)}
.hcmd-row-desc{font-size:var(--fs-caption);line-height:1.45;color:var(--t2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hcmd-row-cat{flex:0 0 auto;padding:4px 10px;border:1px solid var(--border);border-radius:var(--radius-pill);font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent-strong);white-space:nowrap}
.hcmd-empty{padding:18px 16px;font-size:var(--fs-body-s);line-height:1.55;color:var(--t2)}
.hcmd-empty strong{color:var(--t0)}


/* ── V2 pill treatments ──
   Three, and no others: primary (accent), inverse (ink) and quiet. `ui-pill-hi`
   is the inverted pricing panel's CTA — the panel is ink-on-ink, so its action
   takes the highlight rather than the accent, which would vanish against it. */
.ui-pill-quiet{background:var(--bg-1);color:var(--t0);border-color:var(--border)}
.ui-pill-quiet:hover{border-color:var(--t0);color:var(--t0)}
.ui-pill-hi{background:var(--hi);color:var(--hi-fg);border-color:var(--hi)}
.ui-pill-hi:hover{color:var(--hi-fg);box-shadow:var(--shadow-s)}

/* ── Sticky scroll section (structural pattern 3) ── */
.hsteps{padding-top:var(--sec-pad);scroll-margin-top:calc(var(--nav-clear) + var(--s-4))}
.hsteps-head{max-width:720px}
.hsteps-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--s-7);margin-top:var(--s-8)}
.hsteps-rail{list-style:none;display:flex;flex-direction:column;gap:var(--s-8)}
.hsteps-sticky{min-width:0}

.hstep{max-width:54ch;transition:opacity var(--dur-3) var(--ease-standard)}
.hstep-num{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong)}
.hstep-num-sep{opacity:.5}
.hstep-title{margin-top:var(--s-3);font-size:clamp(26px,2.8vw,36px);font-weight:800;letter-spacing:-.03em;line-height:1.08;color:var(--t0);text-wrap:balance}
.hstep-body{margin-top:var(--s-3);font-size:var(--fs-body);line-height:1.65;color:var(--t2);text-wrap:pretty}
.hstep-points{list-style:none;display:flex;flex-direction:column;gap:9px;margin-top:var(--s-4)}
.hstep-points li{display:flex;align-items:flex-start;gap:10px;font-size:var(--fs-body-s);line-height:1.5;color:var(--t1)}
.hstep-tick{flex:0 0 auto;margin-top:3px;color:var(--accent)}
/* `align-self` matters: the step is a flex column, so an inline-flex child
   stretches to the full measure and the underline becomes a full-width rule
   instead of sitting under the words. */
.hstep-cta{display:inline-flex;align-self:flex-start;align-items:center;gap:8px;margin-top:var(--s-5);font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t0);text-decoration:none;border-bottom:1px solid var(--border);padding-bottom:4px;transition:border-color var(--dur-2) var(--ease-standard),gap var(--dur-2) var(--ease-standard)}
.hstep-cta:hover{border-color:var(--t0);gap:12px;text-decoration:none}
.hstep-cta:focus-visible{outline:2px solid var(--accent);outline-offset:3px}

/* ── Tools grid (structural pattern 7) ── */
.htools{padding-top:var(--sec-pad)}
.htools-head{max-width:720px}
.htools-grid{list-style:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--s-4);margin-top:var(--s-7)}
.htool{position:relative;display:flex;flex-direction:column;padding:26px;border:1px solid var(--border);border-radius:var(--radius-2xl);background:var(--bg-1);transition:border-color var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
/* The V2 hover language: border to ink AND a 3px lift, together. */
.htool:hover{border-color:var(--t0);transform:translateY(-3px)}
.htool:focus-within{border-color:var(--t0)}
.htool-head{display:flex;align-items:center;gap:12px;text-decoration:none}
.htool-head:hover{text-decoration:none}
/* Radius declared at REST, not on :focus-visible — see the note on the
   global :focus-visible rule near the top of this file. This element paints
   no background and no border of its own, so the radius is visually inert
   here; it exists so the focus ring traces a shape the element actually
   has, instead of the ring's own declaration changing the shape to match
   itself. */
.htool-head{border-radius:var(--radius-xs)}
.htool-head:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.htool-glyph{display:grid;place-items:center;width:38px;height:38px;flex:0 0 auto;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2);color:var(--hue,var(--accent-strong))}
.htool-glyph svg{width:19px;height:19px}
.htool-title{font-size:19px;font-weight:800;letter-spacing:-.02em;line-height:1.2;color:var(--t0)}
.htool-desc{margin-top:12px;font-size:var(--fs-body-s);line-height:1.55;color:var(--t2)}
.htool-links{list-style:none;display:flex;flex-wrap:wrap;gap:6px;margin-top:var(--s-4)}
.htool-link{display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:0 12px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg-0);color:var(--t1);font-size:var(--fs-caption);font-weight:500;text-decoration:none;transition:color var(--dur-1) var(--ease-standard),border-color var(--dur-1) var(--ease-standard),background var(--dur-1) var(--ease-standard)}
.htool-link:hover{color:var(--t0);border-color:var(--t0);text-decoration:none}
.htool-link:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
/* 10.5px, not 9. Found by the scroll-aware recapture of the homepage — the
   reveal-gated sections below the hero had never been reviewed, because
   `[data-reveal]{opacity:0}` never fires in a non-scrolling full-page capture
   (measured: 10 of 11 revealed blocks still at opacity 0 without a scroll pass).
   "Soon" is the badge that tells a visitor a tool is not built yet, so it is
   load-bearing copy on a sales page, and at 9px mono uppercase in `--t3` it was
   the smallest text on the site. Same floor already applied to `.ch-card-tag`
   and the icon-grid labels in this pass. */
.htool-soon{display:inline-flex;padding:2px 7px;border:1px solid var(--border);border-radius:var(--radius-pill);font-family:var(--mono);font-size:10.5px;font-style:normal;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t3)}
.htool-open{margin-top:auto;padding-top:var(--s-4);font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t3);transition:color var(--dur-2) var(--ease-standard)}
.htool:hover .htool-open{color:var(--t0)}

/* ── Community strip ── */
.hcomm{padding-top:var(--sec-pad)}
.hcomm-head{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--s-5);flex-wrap:wrap}
.hcomm-note{margin-top:var(--s-4);font-size:var(--fs-caption);line-height:1.5;color:var(--t2)}
.hcomm-grid{list-style:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--s-4);margin-top:var(--s-5)}
.hcomm-card{display:flex}
.hcomm-card-link{display:flex;flex:1;flex-direction:column;border:1px solid var(--border);border-radius:var(--radius-xl);background:var(--bg-1);overflow:hidden;text-decoration:none;transition:border-color var(--dur-2) var(--ease-standard),transform var(--dur-2) var(--ease-standard)}
.hcomm-card-link:hover{border-color:var(--t0);transform:translateY(-3px);text-decoration:none}
.hcomm-card-link:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
/* Generated thumbnails — the two stops arrive as runtime custom properties
   The artefact ITSELF, as one background value on one element — a real
   gradient from GALLERY_GRADIENTS, or a palette's colours as hard-stop bands.
   It used to be a decorative two-stop blend built from --hcomm-c1/--hcomm-c2,
   which stood in for an artefact that was somewhere else entirely. Still no
   external asset and no Storage dependency: the value arrives as a custom
   property set in Home.jsx. */
.hcomm-card-art{display:block;height:132px;background:var(--hcomm-art,linear-gradient(135deg,var(--accent),var(--accent-soft)))}
.hcomm-card-body{display:flex;flex-direction:column;gap:6px;padding:16px 16px 0}
.hcomm-card-name{font-size:var(--fs-body-s);font-weight:700;letter-spacing:-.01em;line-height:1.35;color:var(--t0)}
.hcomm-card-meta{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.05em;text-transform:uppercase;color:var(--t2)}
.hcomm-card-cat{padding:2px 8px;border:1px solid var(--border);border-radius:var(--radius-pill)}
.hcomm-card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding:14px 16px 16px;font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.05em;text-transform:uppercase;color:var(--t3)}
/* The foot says where the card takes you. It replaced a `{saves} saves` count
   that was zero on every card, and a Curated tag that marked the whole set. */
.hcomm-card-opens{color:var(--t3)}
.hcomm-card-go{color:var(--t2);transition:transform var(--dur-2) var(--ease-standard)}
.hcomm-card-link:hover .hcomm-card-go{transform:translateX(3px)}
/* Both halves of the motion contract: the OS preference, and a visitor who
   chose reduced motion in Settings while the OS said nothing. The global clamp
   reaches durations and delays but not transform, so the nudge needs both. */
@media(prefers-reduced-motion:reduce){
  html:not([data-reduced-motion="false"]) .hcomm-card-link:hover .hcomm-card-go{transform:none}
}
html[data-reduced-motion="true"] .hcomm-card-link:hover .hcomm-card-go{transform:none}
.hcomm-cta{margin-top:var(--s-6)}

/* ── Pricing — the inverted panel (structural pattern 6). One per page. ── */
.hprice{padding-top:var(--sec-pad)}
.hprice-panel{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--s-7);padding:clamp(28px,4vw,64px);border-radius:var(--radius-3xl);background:var(--t0);color:var(--bg-0)}
.hprice-eyebrow{color:var(--bg-0);opacity:.72}
.hprice-title{color:var(--bg-0)}
.hprice-hi{color:var(--hi)}
.hprice-lede{margin-top:var(--s-4);max-width:46ch;font-size:var(--fs-body);line-height:1.65;color:var(--bg-0);opacity:.76;text-wrap:pretty}
.hprice-includes{list-style:none;display:flex;flex-direction:column;gap:10px;margin-top:var(--s-5)}
.hprice-includes li{display:flex;align-items:flex-start;gap:10px;font-size:var(--fs-body-s);line-height:1.5;color:var(--bg-0);opacity:.88}
.hprice-includes svg{flex:0 0 auto;margin-top:3px;color:var(--hi)}
.hprice-rows{list-style:none;display:flex;flex-direction:column;gap:8px}
.hprice-row{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"cadence amount" "total note";gap:4px 14px;align-items:baseline;padding:16px 18px;border:1px solid color-mix(in srgb,var(--bg-0) 18%,transparent);border-radius:var(--radius-l);transition:border-color var(--dur-2) var(--ease-standard)}
.hprice-row:hover{border-color:color-mix(in srgb,var(--bg-0) 40%,transparent)}
.hprice-row[data-best]{border-color:var(--hi)}
.hprice-cadence{grid-area:cadence;font-family:var(--mono);font-size:var(--fs-micro);font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--bg-0);opacity:.7}
.hprice-amount{grid-area:amount;display:inline-flex;align-items:baseline;gap:3px;color:var(--bg-0)}
.hprice-amount strong{font-size:28px;font-weight:800;letter-spacing:-.03em}
.hprice-per{font-size:var(--fs-caption);opacity:.62}
.hprice-total{grid-area:total;font-size:var(--fs-caption);color:var(--bg-0);opacity:.66}
.hprice-note{grid-area:note;text-align:right;font-size:var(--fs-caption);color:var(--bg-0);opacity:.66}
.hprice-row[data-best] .hprice-note{color:var(--hi);opacity:1}
.hprice-cta{margin-top:var(--s-5);width:100%}
.hprice-fine{margin-top:var(--s-4);font-size:var(--fs-caption);line-height:1.5;color:var(--bg-0);opacity:.6}

/* ── Responsive ──────────────────────────────────────────────────────────────
   The two-column split is the ONLY place the sticky panel exists. Keep the
   981px floor in step with the matchMedia guard in useHomeMotion.js — below it
   there is no sticky column, so there is nothing for the scroll sync to move. */
@media(min-width:981px){
  .hsteps-grid{grid-template-columns:minmax(0,1fr) minmax(0,1.06fr);gap:var(--s-8);align-items:start}
  .hsteps-rail{gap:var(--s-10)}
  /* Each step gets a screen of its own to sync against. */
  .hstep{min-height:62vh;display:flex;flex-direction:column;justify-content:center;opacity:.4}
  .hstep[data-active="true"]{opacity:1}
  /* ── C3 then C1 (founder batch 2026-08-20, spec §4.1 + §3.1 / F-7),
     rebased onto #341's two-zone panel ────────────────────────────────
     C3 FIRST, because it is the precondition for C1. The panel was top-pinned
     and free to resize, so `.hw-shell` measured 441.28 → 758.47px at 1440×900
     and 466.88 → 917.98px at 1024×768. One tab click moved everything below it
     by up to 451px — that height change, not the transition speed, is the
     founder's "too snappy it looks jumpy", and slowing the transition would not
     have touched it.

     #341 has since landed a CAP on the same box (max-height, so nothing becomes
     unreachable) and stated in its own comment that the SWING was left for this
     change. A cap and a frame are not the same guarantee: the cap says the panel
     never exceeds the screen, the frame says it never CHANGES. The measured
     swing under the cap alone was still 215px. So the outer sizing below is
     #262's frame and the inner zoning is #341's, unchanged.

     --hw-frame is one frame for all five modes: the screen below the nav less a
     --s-8 breathing margin, floored at 420px and capped at 640px. `svh`, not
     `vh`/`dvh`, so a collapsing mobile URL bar cannot resize the pinned box
     mid-scroll — the same reasoning as `.home-hero`. The frame is LAYOUT, not
     motion: it stays in force under reduced motion, because without it a
     reduced-motion visitor would get the 451px jump with no transition at all.

     `align-content:safe center` is load-bearing: it centres while the panel
     fits and falls back to start-alignment if it ever cannot, so the top of the
     panel can never end up above the viewport where it is unreachable. In an
     engine without `safe`, the whole declaration is dropped and the item sits
     at the start of the box — the documented fallback, never plain `center`. */
  .hsteps-sticky{
    /* The upper bound is 760px, not #262's original 640px. 640 was chosen in
       August against a panel that had no internal zoning: it was the whole
       box. Under #341 the box is chrome + tabs + a natural-height stage + a
       scrolling control zone with a 92px STICKY hand-off pinned inside it, and
       at 640 the control zone collapses to 140px — 48px of which is not under
       the foot. Palette's Generate button then renders permanently beneath the
       hand-off: measured at 1440×900, the button occupied 743–783 and the foot
       690.6–783, and `document.elementFromPoint` at the button's own centre
       returned the foot's note. Four user-sim tests fail on the click.
       760 is the smallest bound that leaves every mode at least as much control
       room as main's cap does today (main's natural Palette panel is 756px), so
       the frame buys a constant height without spending reachability to get it.
       The swing is killed by `height` being MODE-independent, not by the bound
       being small — that is why raising it costs nothing this change wanted. */
    --hw-frame:clamp(420px,calc(100svh - var(--nav-clear) - var(--s-8)),760px);
    position:sticky;top:var(--nav-clear);
    height:calc(100svh - var(--nav-clear));
    display:grid;align-content:safe center;
  }
  /* `width:100%` restores what block layout gave for free: a grid item with
     auto inline margins is NOT stretched, so without it `max-width:920px` +
     `margin:0 auto` would shrink the panel to fit its content. `height`, not
     `max-height`: the frame is the point. */
  .hsteps-sticky .hw-shell{width:100%;height:var(--hw-frame);display:flex;flex-direction:column;box-shadow:var(--shadow-panel)}
  .hsteps-sticky .hw-chrome,.hsteps-sticky .hw-tabs{flex:0 0 auto}
  /* ── #341's zoning, kept verbatim ─────────────────────────────────
     THE ARTEFACT IS NEVER SQUEEZED. #341's first attempt let the stage flex down
     and clip, and every measurement passed while the type ladder had quietly
     lost two of its four sizes. The stage takes its natural height and the
     CONTROLS absorb the difference; `.hw-panel` is therefore NOT the scroller,
     which is why #262's `overflow-y:auto` on it is dropped here rather than
     merged. */
  .hsteps-sticky .hw-panel{flex:1 1 auto;min-height:0;overflow:hidden;display:flex;flex-direction:column}
  .hsteps-sticky .hw-body{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
  /* THE ARTEFACT IS NEVER SQUEEZED. The first version of this cap let the stage
     flex down and clip, and every measurement passed — panel inside its budget,
     hand-off on screen, nothing overflowing. Looking at it showed the type
     ladder had lost its caption step and been sliced through the body step: a
     scale preview showing 2.5 of its 4 sizes, still claiming to be the scale.
     A preview that quietly drops content is worse than one that scrolls, so the
     stage takes its natural height and the CONTROLS absorb the difference. */
  .hsteps-sticky .hw-stage{flex:0 0 auto;justify-content:center}
  /* The only zone allowed to scroll, and only when a mode genuinely needs it.
     `scrollbar-gutter:stable` reserves the gutter in every mode, so the modes
     that fit are not a few px narrower than the ones that do not. */
  .hsteps-sticky .hw-controls{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable}
  /* A scrolling flex column still shrinks its own children by default, and the
     ones that carry `overflow:hidden` then clip instead of pushing the scroll.
     Caught in typography: `.hw-type-tools` swallowed its third row (Type Scale)
     while the container reported scrollHeight === clientHeight, so nothing was
     scrollable and a whole hand-off was simply missing. The zone scrolls; its
     children keep their size. */
  .hsteps-sticky .hw-controls>*{flex:0 0 auto}
  /* THE HAND-OFF IS A SIBLING OF THE SCROLLER, NOT A STICKY CHILD OF IT.

     #341 kept the hand-off reachable by making it `position:sticky;bottom:0`
     as the last child of `.hw-controls`. That is the right INTENT — a CTA you
     have to go looking for does not get pressed — reached the wrong way: a
     sticky element inside its own scroller paints over the bottom N px of that
     scroller at EVERY scroll position except the very end, so whatever control
     lands there is covered. Scrolling reveals it, which is why review missed
     it; `scrollIntoView({block:'nearest'})` does NOT, because it stops as soon
     as the element is inside the scrollport and the scrollport includes the
     area under the foot. Playwright scrolls exactly that way, which is how
     #262 met it as four hard click failures rather than a cosmetic note.

     MEASURED ON main AT 1440x900 BEFORE THIS CHANGE, against #262's 760px
     frame — so this was live, not theoretical, and the earlier note saying it
     no longer reproduced was out of date. Typography: "Continue with this live
     scale" occupied 790.2-844.2 with the foot's top at 784, and
     `document.elementFromPoint` at the link's own centre returned the foot.
     Image: the compression segmented control spanned 715.4-755.4 against a
     foot top of 750.6.

     Raising the frame again would only move the boundary — the class comes
     back the moment any mode's controls grow or the viewport shrinks. So the
     foot is out of the scroller entirely: `.hw-controls` scrolls, `.hw-foot`
     is its SIBLING below it in `.hw-body`, and there is no longer a scroll
     position at which the two can overlap. The hand-off is still always
     visible — it is outside the scrolling region rather than pinned over it,
     which is what #341 wanted — and it costs the control zone nothing,
     because the foot's height was already unusable space. */
  .hsteps-sticky .hw-foot{flex:0 0 auto;background:var(--bg-1)}
  /* The reference image is the one stage item that MAY be cut, because it is a
     photograph and not information: the <img> is already absolutely positioned
     with object-fit:cover, so a shorter box crops it centred rather than losing
     a value. Everything else in a stage keeps its natural size. Without this
     the 880x495 ratio alone claims 311px of a 593px column. */
  /* 34vh -> 31vh, 2026-09-05. The reference picker became File Converter's own
     `.fc-tabs` pill group, which is 8px taller than the bespoke `.hw-subtab`
     row it replaced (a 3px padded container with a 1px border around a 12px
     pill, against a bare 36px button). Measured at 1280x660 that pushed this
     mode's control zone from 2.2px to 0 - the wrong direction on a defect this
     change is only allowed to leave alone. The photograph gives the height
     back, which this rule's own note already sanctions: it is the one stage
     item that MAY be cut, because object-fit:cover crops it centred rather
     than losing a value. Net at 1280x660: 2.2px -> 15.8px. */
  .hsteps-sticky .hw-ref{min-height:0;max-height:31vh}
  /* The sticky column is roughly half the page, so the workbench's 118px tab
     floor overflowed its own strip and clipped "Typography". The tabs share the
     width evenly here and the icons carry the recognition. */
  .hsteps-sticky .hw-tab{min-width:0;padding:0 8px;gap:6px}
  .hprice-panel{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:var(--s-8);align-items:center}
}
@media(max-width:1180px){
  .htools-grid,.hcomm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:768px){
  .hcmd-bar{min-height:54px;padding-left:14px}
  .hcmd-input{height:50px}
  .hcmd-row-desc{white-space:normal}
  .hcomm-head{align-items:flex-start}
}
@media(max-width:640px){
  .htools-grid,.hcomm-grid{grid-template-columns:minmax(0,1fr)}
  .hprice-row{grid-template-columns:minmax(0,1fr);grid-template-areas:"cadence" "amount" "total" "note"}
  .hprice-note{text-align:left}
}
@media(max-width:480px){
    .hcmd{margin-top:var(--s-5)}
  .hcmd-bar{grid-template-columns:auto minmax(0,1fr);padding-right:14px}
  /* The keycap names a shortcut a phone has no keyboard for. */
  .hcmd-kbd{display:none}
  .hcmd-row{grid-template-columns:auto minmax(0,1fr);gap:10px;padding:12px 14px}
  .hcmd-row-cat{display:none}
  .hstep-cta{min-height:40px}
}
@media(max-width:380px){
  .htool{padding:20px}
  .hprice-panel{padding:22px}
}

/* ── Reduced motion ──────────────────────────────────────────────────────────
   The global block at the top of this file already clamps all four properties.
   What it cannot do is undo LAYOUT that only makes sense with scroll sync: with
   motion off the step sync never runs, so no step would ever become active and
   every step would sit stranded at opacity .4. Below: full opacity, no sticky,
   no reserved screen height — the same content as a plain readable stack, and
   the workbench's own tablist is the control. Mirrors prefersReducedMotion() in
   useHomeMotion.js — an explicit attribute wins over the OS query both ways.

   C1/C3 addendum: the sticky box also gives up its full-screen height and its
   centring here, so it becomes a plain in-flow block. The FRAME does not go
   with it — `.hw-shell` keeps `height:var(--hw-frame)`, because the fixed frame
   is the anti-jump fix itself and a reduced-motion visitor without it would get
   the worst version of the bug: a 451px jump and no transition to soften it. */
:where(html[data-reduced-motion="true"]) .hstep{opacity:1;min-height:0}
:where(html[data-reduced-motion="true"]) .hsteps-sticky{position:static;height:auto;align-content:start}
@media(prefers-reduced-motion:reduce){
  :where(html:not([data-reduced-motion="false"])) .hstep{opacity:1;min-height:0}
  :where(html:not([data-reduced-motion="false"])) .hsteps-sticky{position:static;height:auto;align-content:start}
}


/* ══ Home mini-workbench (hw-) ═══════════════════════════════════════════════
   The calm half of the hero's chaos → calm story: eight real tools above,
   four ways of WORKING here. Four persistent tabs over one panel region.
   Nothing in this block hides behind motion — the workbench is fully laid out
   and operable whether or not GSAP ever arrives. */
.hw{position:relative;padding-top:var(--s-6);scroll-margin-top:calc(var(--nav-clear) + var(--s-4))}
.hw-head{max-width:660px;margin:0 auto var(--s-6);text-align:center}
.hw-head .home-eyebrow{justify-content:center}
.hw-head .home-h2{font-size:var(--fs-h2)}
.hw-head .home-lede{margin-inline:auto;font-size:var(--fs-body)}
.hw-shell{position:relative;max-width:920px;margin:0 auto;scroll-margin-top:calc(var(--nav-clear) + var(--s-2));border:1px solid var(--border);border-radius:var(--radius-2xl);background:var(--bg-1);box-shadow:var(--shadow-m);overflow:hidden}
/* Type Scale — the two breakpoint ends. Grouped in a fieldset so the base and
   ratio read as one setting for one breakpoint rather than two loose controls,
   which is what makes "there are two ladders here" legible at a glance. */
.tsc-bp{margin:0 0 14px;padding:12px 14px 14px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-1)}
.tsc-bp legend{padding:0 6px;font-family:var(--mono);font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.tsc-bp-row{display:grid;grid-template-columns:1fr minmax(0,190px);gap:12px;align-items:end}
@media(max-width:640px){.tsc-bp-row{grid-template-columns:1fr}}
.tsc-bp-mode{display:flex;gap:6px;margin:0 0 14px}
.tsc-bp-desktop-label{display:block}

/* App chrome — the furniture that makes the shell read as a window into the
   product rather than a marketing widget. Deliberately quiet: it is scenery, so
   it sits a step back from the panel it frames and never competes with the
   controls inside. The dots are a window affordance, not a macOS pastiche —
   they take the border colour, so they read as "this is an application" without
   impersonating one. */
.hw-chrome{display:flex;align-items:center;gap:12px;padding:0 14px;height:38px;border-bottom:1px solid var(--border);background:var(--bg-1)}
.hw-chrome-dots{display:inline-flex;gap:5px;flex-shrink:0}
.hw-chrome-dots i{width:8px;height:8px;border-radius:50%;background:var(--border);border:1px solid var(--bh)}
.hw-chrome-crumb{display:inline-flex;align-items:center;gap:6px;min-width:0;font-family:var(--mono);font-size:11px;letter-spacing:.02em;color:var(--t3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hw-chrome-app{font-weight:700;color:var(--t2)}
.hw-chrome-sep{opacity:.5}
.hw-chrome-here{color:var(--hue-strong,var(--accent-strong));font-weight:600}
.hw-chrome-live{display:inline-flex;align-items:center;gap:6px;margin-left:auto;flex-shrink:0;font-size:10.5px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--t3)}
.hw-chrome-live i{width:6px;height:6px;border-radius:50%;background:var(--hue,var(--accent))}
/* `.hw-chrome-sep:first-of-type` matched NOTHING. Every child of the crumb is a
   span, so `:first-of-type` resolves to the first span — `.hw-chrome-app` — and
   the compound `.hw-chrome-sep:first-of-type` then fails on the class. The
   route was hidden and both separators stayed, so the homepage's flagship panel
   rendered `UIL4B / / Palette`. Sibling-combinator, not position-counting: it
   says what it means (the separator that belongs to the route) and it cannot
   drift if a span is ever added before it. */
@media(max-width:600px){.hw-chrome-crumb .hw-chrome-route,.hw-chrome-crumb .hw-chrome-app+.hw-chrome-sep{display:none}.hw-chrome-live{font-size:0;gap:0}}

/* Tabs — the active one lifts onto the panel surface, so selection is carried
   by shape and border as well as colour. */
/* Scrolling, not wrapping — the one place in this stylesheet where the rail
   doctrine's "wrap first" branch is the wrong answer. The active tab carries
   selection by welding itself to the panel below (lifted surface + border +
   a 2px underline sitting on the panel's own top edge). On a second row that
   weld is impossible: an active tab in row one would draw its underline across
   the middle of the strip against row two's top border — the exact stranded-
   underline artefact once recorded on Type Scale's hero tabs (that control has
   since been removed as a duplicate, but the artefact is real). So it stays one row and
   takes `.rail-overflow`, with the peek forced at ≤480 below. */
.hw-tabs{display:flex;gap:2px;padding:8px 8px 0;background:var(--bg-2);border-bottom:1px solid var(--border)}
/* The transition names border-color as well as colour and background: the
   active tab changes its border, and without it the border snapped while
   the surface faded. */
.hw-tab{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:7px;flex:1 1 0;min-width:118px;height:44px;padding:0 12px;border:1px solid transparent;border-bottom:none;border-radius:var(--radius-l) var(--radius-l) 0 0;background:none;color:var(--t2);font-family:var(--font);font-size:var(--fs-body-s);font-weight:600;cursor:pointer;white-space:nowrap;transition:color var(--dur-2) var(--ease-standard),background var(--dur-2) var(--ease-standard),border-color var(--dur-2) var(--ease-standard)}
.hw-tab-icon{width:16px;height:16px;flex:0 0 auto}
.hw-tab:hover{color:var(--t0);background:color-mix(in srgb,var(--bg-1) 62%,transparent)}
.hw-tab:focus-visible{outline:2px solid var(--hue,var(--accent));outline-offset:-3px}
.hw-tab[data-active="true"]{background:var(--bg-1);border-color:var(--border);color:var(--t0)}
/* C3 (spec §4.2, motion register M7). The indicator is always in the DOM and
   fades rather than appearing, so the selection reads as one thing moving
   between tabs instead of two things blinking. --dur-2/--ease-standard: the
   click is acknowledged at 200ms while the panel content behind it takes
   --dur-3 to arrive, which is the whole separation principle. */
.hw-tab::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--hue,var(--accent));opacity:0;transition:opacity var(--dur-2) var(--ease-standard),background var(--dur-2) var(--ease-standard)}
.hw-tab[data-active="true"]::after{opacity:1}
.hw-panel{padding:20px;background:var(--bg-1)}
.hw-body{display:flex;flex-direction:column;gap:14px}
/* C3 (spec §4.2, motion register M8 + M9). With the frame fixed, the container
   no longer resizes; what was left was a hard content cut. React unmounts the
   outgoing panel, so this is ENTER-ONLY — an exit fade would buy nothing (the
   frame does not move) and cost a double mount. Compositor-only properties;
   `transform`/`opacity` cannot shift layout, so the 0.0000 CLS baseline is
   untouched. The stagger caps at three steps: past ~120ms the tail of a list
   arrives after the eye has already moved on. */
@keyframes hw-panel-in{from{opacity:0;transform:translate3d(0,8px,0)}to{opacity:1;transform:none}}
.hw-body>*{animation:hw-panel-in var(--dur-3) var(--ease-entrance) both}
.hw-body>*:nth-child(2){animation-delay:40ms}
.hw-body>*:nth-child(3){animation-delay:80ms}
.hw-body>*:nth-child(n+4){animation-delay:120ms}
/* Reduced motion, BOTH directions — the explicit in-app attribute wins over
   the OS query either way, mirroring the hero block above. The swap becomes
   instantaneous; the fixed frame stays, because it is layout, not motion. */
:where(html[data-reduced-motion="true"]) .hw-body>*{animation:none}
:where(html[data-reduced-motion="true"]) .hw-tab{transition:none}
:where(html[data-reduced-motion="true"]) .hw-tab::after{transition:none}
@media(prefers-reduced-motion:reduce){
  :where(html:not([data-reduced-motion="false"])) .hw-body>*{animation:none}
  :where(html:not([data-reduced-motion="false"])) .hw-tab{transition:none}
  :where(html:not([data-reduced-motion="false"])) .hw-tab::after{transition:none}
}

/* ── The two zones ───────────────────────────────────────────────────────────
   Founder: "use mobbin to improve our UI preview designs."

   Canvas above, controls below. Every token editor sampled on Mobbin is built
   this way — v0, Lovable, GitBook, Gamma, Stitch, Squarespace — and it is the
   split the rest of this block falls out of: `.hw-stage` holds what a mode
   PRODUCES, `.hw-controls` holds what changes it, and the two are never
   interleaved. Extracted from the parked PR #269 (its C4), minus the parts of
   that slice which depend on #262's unmerged fixed frame: the capping and
   internal scrolling of these zones is only meaningful once `.hw-panel` has a
   height to cap against, so those rules stay with #262 rather than being
   half-landed here. As plain blocks the zones cost nothing and are correct. */
.hw-stage,.hw-controls{display:flex;flex-direction:column;gap:14px;min-width:0}

/* ── The palette mode's artefact: real product UI, not a swatch row ──────────
   The Palette panel's preview WAS its five swatches. Mobbin's answer is
   unanimous and it is the reason this exists: v0 previews tokens on a revenue
   chart, an account form and a payments table; Lovable on a metric card, a
   payment-method chooser and an issue form; GitBook on a whole rendered docs
   site; Gamma on a page with a primary/secondary button pair. Not one of them
   previews a palette as a labelled colour row, because the row cannot answer
   the only question a preview is for — not "what are these five colours" but
   "do they compose".

   EVERY COLOUR IN HERE IS PAINTED FROM derivePreviewRoles() IN THE JSX, not
   from app tokens — the same engine the Palette Builder and Colour Studio
   previews use, so one palette produces one set of roles wherever a visitor
   meets it. That engine derives `text` by contrast rather than ever using a
   swatch for copy, and self-heals every pair to AA before returning, which is
   what keeps the mock legible for any palette in either theme. The rules below
   are geometry only; the fallback colours here are what shows if the roles ever
   fail to arrive. */
.hw-ui{display:flex;flex-direction:column;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-1);box-shadow:var(--shadow-s);overflow:hidden}
.hw-ui-bar{display:flex;align-items:center;gap:8px;padding:9px 12px;border-bottom:1px solid var(--border)}
.hw-ui-mark{display:grid;place-items:center;width:22px;height:22px;flex:0 0 auto;border-radius:6px;font-family:var(--font);font-size:11px;font-weight:800}
.hw-ui-app{font-family:var(--font);font-size:var(--fs-body-s);font-weight:700}
.hw-ui-crumb{font-family:var(--mono);font-size:var(--fs-micro)}
.hw-ui-avatar{display:grid;place-items:center;width:22px;height:22px;flex:0 0 auto;margin-left:auto;border-radius:50%;font-family:var(--font);font-size:10px;font-weight:700}
.hw-ui-main{display:flex;flex-direction:column;gap:12px;padding:14px}
.hw-ui-metric{display:flex;flex-direction:column;gap:2px}
.hw-ui-metric-label{font-family:var(--font);font-size:var(--fs-caption)}
.hw-ui-metric-row{display:flex;align-items:baseline;gap:9px}
.hw-ui-metric-num{font-family:var(--font);font-size:26px;font-weight:800;letter-spacing:-.03em;line-height:1.05}
.hw-ui-delta{padding:2px 8px;border-radius:var(--radius-pill);font-family:var(--mono);font-size:var(--fs-micro);font-weight:700}
/* `vector-effect:non-scaling-stroke` is load-bearing, not polish: the viewBox
   is stretched with preserveAspectRatio="none", so without it a 1.6 stroke is
   scaled by the x and y factors independently and the line arrives thick on one
   axis and hairline on the other. */
.hw-ui-chart{display:block;width:100%;height:52px}
/* Rows, not a swatch strip: same dot size, same gap, a real label beside each.
   Two ramp steps that failed to separate are visible here and nowhere else. */
.hw-ui-rows{display:flex;flex-direction:column;list-style:none;margin:0;padding:0}
.hw-ui-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:9px;padding:7px 0;border-top:1px solid transparent}
.hw-ui-row:first-child{border-top:0}
.hw-ui-dot{width:8px;height:8px;border-radius:50%;flex:0 0 auto}
.hw-ui-row-name{font-family:var(--font);font-size:var(--fs-caption);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hw-ui-row-state{font-family:var(--mono);font-size:var(--fs-micro)}
.hw-ui-acts{display:flex;gap:8px;flex-wrap:wrap}
.hw-ui-btn{display:inline-flex;align-items:center;justify-content:center;min-height:30px;padding:0 14px;border-radius:var(--radius-s);font-family:var(--font);font-size:var(--fs-caption);font-weight:650}
/* Outlined and unfilled, like Gamma's secondary beside its coloured primary.
   A second palette colour as a FILL here would be a second primary and the pair
   would stop reading as a hierarchy, so it takes the derived border and text. */
.hw-ui-btn--ghost{border:1px solid;background:none}

/* Shared panel furniture */
.hw-row{display:flex;align-items:center;gap:14px;flex-wrap:wrap}

/* ── One control language: OPTIONS are rails, PROPERTIES are rows ────────────
   Extracted from the parked PR #269 (its C4). The modes used a stack of
   label+select pairs for everything, which is why they read like a settings
   form rather than like the tools they are a slice of.

   The split, and the Mobbin evidence for it:

   OPTIONS — a small closed set you pick one of — are a rail of pill tiles with
   `aria-pressed`, active one INVERTED. Lovable's payment-method chooser
   (Card / PayPal / Apple) and Stitch's Mode control (Light / Dark) are both
   exactly this. Inverted rather than tinted because at this size a tint is not
   a strong enough selected signal beside four neighbours.

   PROPERTIES — a continuous value — are label-left / control-right rows with an
   EDITABLE numeric readout in a fixed right-hand column. Salesforce prints the
   live value (`58`) at the right end of its Border Radius track; MagicPath
   right-aligns the rem value in mono beside every type-scale step. On a ~471px
   column a slider alone cannot hit 135 degrees, so the number is the real input
   and the slider is the coarse one.

   Rails and rows are never mixed inside one stack. That separation is also what
   buys the vertical space back: two selects with labels cost ~130px, two rails
   ~76px, and every value becomes one click instead of two. */
.hw-prop{display:grid;grid-template-columns:minmax(72px,auto) minmax(0,1fr) auto;align-items:center;gap:10px;min-height:34px}
.hw-prop-label{font-family:var(--font);font-size:var(--fs-caption);font-weight:600;color:var(--t2)}
.hw-prop-select,.hw-prop-text{grid-column:2 / -1;width:100%}
.hw-prop-num{display:inline-flex;align-items:center;justify-content:flex-end;justify-self:end;gap:2px;min-height:32px;padding:0 10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-1)}
.hw-prop-num:focus-within{border-color:var(--hue,var(--accent))}
.hw-prop-num--wide{min-width:96px}
/* `.hw-num`, NOT `input.hw-num`. #269 wrote this qualified and explained why:
   the base reset was a bare `input[type="number"]` at (0,1,1), which beat a
   class, and the readout inherited `padding:9px 14px` — 31px of content box for
   a 42px value, clipping "16" to "1". #331 moved that reset inside `:where()`,
   so it is (0,0,0) now and a plain class wins. The qualification came out with
   its comment; keeping it would have taught the next reader a rule that is no
   longer true. `appearance` stays because the `:where()` block sets only the
   `-moz-` form. Pinned by tests/unit/input-specificity.test.js. */
.hw-num{width:4ch;min-width:0;padding:0;border:0;background:none;color:var(--t0);font-family:var(--mono);font-size:var(--fs-body-s);font-weight:600;text-align:right;appearance:textfield}
.hw-num:focus{outline:none;box-shadow:none;border:0}
.hw-num-unit{font-family:var(--mono);font-size:var(--fs-micro);color:var(--t2)}

.hw-rail-group{display:flex;flex-direction:column;gap:6px;min-width:0}
.hw-rail-label{font-family:var(--font);font-size:var(--fs-caption);font-weight:600;color:var(--t2)}
.hw-rail{display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;padding-bottom:2px}
.hw-rail::-webkit-scrollbar{display:none}
.hw-tile{display:inline-flex;align-items:center;justify-content:center;gap:4px;flex:0 0 auto;min-height:32px;padding:0 12px;border:1px solid var(--border);border-radius:var(--radius-pill);background:var(--bg-1);color:var(--t1);font-family:var(--mono);font-size:var(--fs-body-s);font-weight:600;cursor:pointer;white-space:nowrap;transition:color var(--dur-2) var(--ease-standard),background var(--dur-2) var(--ease-standard),border-color var(--dur-2) var(--ease-standard)}
.hw-tile--wide{font-family:var(--font)}
.hw-tile-unit{font-family:var(--mono);font-size:var(--fs-micro);opacity:.7}
.hw-tile:hover{color:var(--t0);border-color:var(--bh)}
.hw-tile:focus-visible{outline:2px solid var(--hue,var(--accent));outline-offset:2px}
.hw-tile[aria-pressed="true"]{background:var(--t0);border-color:transparent;color:var(--bg-1)}
.hw-tile[aria-pressed="true"] .hw-tile-unit{opacity:.75}
.hw-btn{display:inline-flex;align-items:center;gap:7px;min-height:40px;padding:0 16px;border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-1);color:var(--t0);font-family:var(--font);font-size:var(--fs-body-s);font-weight:580;cursor:pointer;transition:background var(--t),border-color var(--t)}
.hw-btn:hover{background:var(--hvr);border-color:var(--bh)}
.hw-btn:disabled{opacity:.55;cursor:not-allowed}
.hw-btn-go{background:var(--t0);color:var(--bg-1);border-color:transparent}
.hw-btn-go:hover{background:var(--t0);border-color:transparent;filter:brightness(1.12)}
.hw-note{font-size:var(--fs-caption);line-height:1.5;color:var(--t2)}
.hw-limit{margin:0;padding:10px 12px;border:1px solid color-mix(in srgb,var(--warn) 38%,var(--border));border-radius:var(--radius-s);background:color-mix(in srgb,var(--warn) 8%,var(--bg-1));font-size:var(--fs-caption);line-height:1.5;color:var(--t1)}
.hw-alert{margin:0;padding:10px 12px;border:1px solid color-mix(in srgb,var(--err) 40%,var(--border));border-radius:var(--radius-s);background:color-mix(in srgb,var(--err) 8%,var(--bg-1));font-size:var(--fs-caption);line-height:1.5;color:var(--t1)}
.hw-link-btn{font:inherit;color:var(--accent-strong);font-weight:650;background:none;border:0;padding:0;cursor:pointer;text-decoration:underline}
.hw-code-inline{font-family:var(--mono);font-size:.95em;color:var(--t0);user-select:all}
.hw-foot{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding-top:14px;border-top:1px solid var(--border)}
.hw-foot-note{font-size:var(--fs-caption);color:var(--t2)}
.hw-continue{display:inline-flex;align-items:center;gap:8px;min-height:42px;padding:0 18px;border:1px solid color-mix(in srgb,var(--hue,var(--accent)) 42%,var(--border));border-radius:var(--radius-l);background:color-mix(in srgb,var(--hue,var(--accent)) 10%,var(--bg-1));color:color-mix(in srgb,var(--hue,var(--accent)) 45%,var(--t0));font-family:var(--font);font-size:var(--fs-body-s);font-weight:650;text-decoration:none;cursor:pointer;transition:background var(--t),gap var(--t)}
.hw-continue:hover{background:color-mix(in srgb,var(--hue,var(--accent)) 18%,var(--bg-1));gap:11px;text-decoration:none}
.hw-continue:disabled{opacity:.55;cursor:not-allowed}
.hw-continue:disabled:hover{gap:8px}

/* Fields. `.hw-fields` / `.hw-field` / `.hw-label` / `.hw-field-err` and
   `.hw-label-space` went with the Gradient rewrite — the stop rows now use the
   tool's `.ggn-stop` and `.ggn-field` / `.ggn-label` grammar, and an invalid hex
   is reported through the tool's `.ggn-field-error`, which is absolutely
   positioned and so costs the control zone no height. `.hw-select` /
   `.hw-input` stay: the Image panel's two selects and Typography's specimen
   field are ordinary form controls with no counterpart to borrow. */
.hw-select,.hw-input{min-height:40px;padding:0 12px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-1);color:var(--t0);font-family:var(--font);font-size:var(--fs-body-s)}
.hw-select:focus-visible,.hw-input:focus-visible{outline:2px solid var(--hue,var(--accent));outline-offset:1px}

/* 1 · Palette — THE REAL BOARD, NOT A LOOKALIKE OF IT
   Founder, 2026-09-05: the mini tools "don't look like the real tool". This
   panel was the clearest case. PaletteBuilder has 153 `plb-` classes and the
   homepage reused none of them, so a visitor who pressed "Continue in Palette
   Builder" arrived somewhere that shared not one shape with what they had just
   been using.

   THE WHOLE `.hw-pal*` BLOCK IS GONE — a 96px strip of swatches with a hex
   chip and a round lock, invented here and existing nowhere else in the
   product. The markup now renders `.plb-board` / `.plb-col` / `.plb-ramp` /
   `.plb-name` / `.plb-hex` / `.plb-role` directly, so the board on the homepage
   IS the board in the tool: same columns, same tonal ramp, same deterministic
   colour name, same big mono hex, same tracked role eyebrow, and the same
   --plb-c / --plb-ink / --plb-rc ink contract through utils/paletteBoard.js.

   WHAT IS LEFT HERE IS GEOMETRY AND NOTHING ELSE. `.plb-board` is written for a
   page that owns the viewport: `flex:1` in a full-height column, square-
   cornered, full-bleed. Inside a rounded card it needs a height, a radius and a
   clip, and that is all `.hw-board` says. No colour, no type scale, no borders
   — anything past geometry here would be the parallel system starting again. */
/* `.hw-stage .hw-board`, not `.hw-board`. `.plb-board` carries `flex:1` for the
   full-height page it was written for, it is defined LATER in this file, and at
   equal specificity source order wins — so a bare `.hw-board{height:248px}`
   loses its height to a 0% flex-basis and the board renders at whatever the
   content happens to be (measured: 181px, names wrapping to two lines). The
   descendant selector is the smallest thing that outranks it. */
.hw-stage .hw-board{flex:0 0 auto;height:248px;border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow-s)}
/* The column's own padding assumes a tall board. At 248px the tool stack, ramp,
   name, hex and role share that height instead, so the breathing room comes
   down with it. Still geometry. */
.hw-board .plb-col{padding:10px 6px 14px;gap:4px}
.hw-board .plb-ramp{margin-bottom:6px}
.hw-board .plb-ramp-bar{height:24px;width:11px}
/* The lock is this panel's ONLY editing affordance and the step copy beside it
   names it ("Lock and regenerate individual steps"), so it stays visible at
   rest. The full board hides its tools until hover for a reason that does not
   apply here — five columns times seven tools would bury the colours — and
   this board has one tool per column. Same class, same look, one declared
   difference. */
@media(hover:hover){.hw-board .plb-tool{opacity:.55}}
.hw-board .plb-col:hover .plb-tool,.hw-board .plb-col:focus-within .plb-tool,.hw-board .plb-tool--on{opacity:1}

/* The palette preview, demoted. Its equivalent in Palette Builder sits behind a
   Preview button, in a modal, with its later scenes gated to Pro — so on the
   homepage it belongs under the board, not above it. The label is what keeps a
   secondary view from reading as a stray decorative card. */
.hw-prev{display:flex;flex-direction:column;gap:6px}
.hw-prev-label{font-family:var(--mono);font-size:var(--fs-micro);font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--t2)}

/* 2 · Gradient — THE TOOL'S OWN INSPECTOR, SAME REASONING AS THE BOARD ABOVE
   `.hw-grad-preview` (a plain filled rectangle), `.hw-stop` and `.hw-input-hex`
   are gone. The panel renders `.ggn-preview` with the tool's `.ggn-pill`
   overlays, `.ggn-stop` rows, `.ggn-field` / `.ggn-label` inspector grammar,
   the `.ggn-dial` angle control and `.ggn-css` / `.ggn-copy` for the output.
   `.hw-ggn` on `.hw-body` brings the --ggn-* aliases into scope; see the split
   rule in the Gradient Generator block below.

   Geometry only, again. `.ggn-preview` is `aspect-ratio:16/11`, which at this
   panel's width would claim 379px of a stage that has 132px to give — the tool
   owns a page, this owns a slot. Everything else about it (radius, border,
   shadow, the pills) is the tool's. */
.hw-stage .ggn-preview{aspect-ratio:auto;height:132px;border-radius:var(--radius)}
/* The stop rows are a two-column grid on the tool's own narrow-panel
   breakpoint; the mini's control zone is always that narrow, so it takes the
   two-up form at every width. Two stops, side by side, is also the shape that
   says "start and end" without a caption. */
.hw-ggn .ggn-stops{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.hw-ggn .ggn-stop{min-width:0;cursor:default}
/* The tool's dial is 64px in a full-height inspector. 52px here, for the same
   reason the board is 248px rather than the height of a screen. */
.hw-ggn .ggn-dial{width:52px;height:52px}
.hw-ggn .ggn-dial-hand{height:21px}
.hw-ggn .ggn-css{padding:10px 12px}

/* 3 · Image */
/* `.hw-subtabs` / `.hw-subtab` are gone: the reference picker wears File
   Converter's own `.fc-tabs` / `.fc-tab` pill group, which is the first control
   on the converter's page. Geometry only: the shared rule carries a 24px bottom
   margin for a page that has nothing else above the drop zone, and `.hw-stage`
   already supplies its own 14px gap. Left in, the stage grew 27px and took the
   control zone at 1280x660 from 2.2px to 0 - measured, and the reason this line
   exists. */
.hw-stage .fc-tabs{margin-bottom:0}
/* The intrinsic 880×495 ratio is reserved up front, so nothing shifts when a
   thumbnail resolves (CLS) and the neutral placeholder never moves controls. */
/* 3 · Image — THE CONVERTER'S DROP ZONE, WRAPPED ROUND THE REFERENCE
   `.hw-ref` no longer draws a frame of its own. It composes with
   `.img-drop-zone.fc-drop`, the converter's real drop target, and contributes
   only the geometry that box cannot know: the reference's aspect ratio, no
   padding (the shared rule wants 40px, which would show as a band of dashes
   around a photograph), and the clip that keeps a cover-fitted image inside a
   rounded, dashed border. Everything visible - the dashes, the hover lift, the
   `.fc-drop-on` state while a file is over it - is the converter's. */
.hw-ref{position:relative;display:grid;place-items:center;aspect-ratio:880/495;padding:0;overflow:hidden}
/* The hint sits ON the photograph, so it needs its own ground rather than a
   different colour: a reference image is arbitrary and no ink is safe on all of
   them. A scrim is the only honest answer, and it doubles as the affordance
   that says the photo is a target. */
.hw-ref-drop{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:16px 20px;border-radius:var(--radius-s);background:color-mix(in srgb,var(--bg-0) 86%,transparent);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);text-align:center}
.hw-ref-drop .fc-drop-ico{width:34px;height:34px;margin-bottom:6px}
.hw-ref-drop .fc-drop-ico svg{width:17px;height:17px}
.hw-ref-drop .fc-drop-hint{margin:0}
.hw-ref-drop .fc-drop-sub{margin:0;max-width:38ch;line-height:1.45}
.hw-ref-img{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover}
.hw-ref-img[hidden]{display:none}
.hw-ref-msg{position:relative;z-index:1;max-width:44ch;margin:0;padding:16px;text-align:center;font-size:var(--fs-caption);line-height:1.5;color:var(--t2)}
.hw-intent{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin:0;padding:12px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-0)}
.hw-intent-label{font-family:var(--mono);font-size:var(--fs-micro);font-weight:650;letter-spacing:.07em;text-transform:uppercase;color:var(--t2)}
.hw-intent strong{font-size:var(--fs-body-s);font-weight:700;color:var(--t0)}
.hw-intent-note{font-size:var(--fs-caption);color:var(--t2)}
/* The reference sits ABOVE its settings now, not beside them. The three
   per-mode splits were keyed to VIEWPORT width, so in a ~590px sticky column at
   1440 they stayed two-column and every mode felt cramped — the panel is half
   the page, not the page. Canvas over controls is the arrangement every sampled
   editor uses and it needs no breakpoint to be right. */
.hw-controls .hw-intent{flex-direction:column;gap:4px}

/* 4 · Icon — THE EDITOR'S STAGE, THE LIBRARY'S GRID
   `.hw-icon-stage`, `.hw-icon-preview`, `.hw-icon-meta`, `.hw-icon-grid` and
   `.hw-icon-cell` are gone. The panel renders `.icust-stage` +
   `.icust-stage-host` (the editor's dark spotlight, driven by the SAME
   --ig-size / --ig-stroke properties IconCustomizer writes), `.icust-meta` +
   `.icust-tag` for the pack/name/size/stroke chips, `.icust-controls` +
   `.icust-row` + `.icust-seg` for the settings, and the library's own `.ig`
   grid of `.ic` cells for the picker.

   Geometry only below, as with the board and the gradient. */
/* The editor's stage is a 220px-floor spotlight in a 600px modal that can
   scroll; this one lives in a fixed frame beside a grid and a settings block,
   so it takes a shorter, fixed height instead of a floor. */
.hw-icust-stage{min-height:0;height:150px;margin:0}
/* The full editor pads its controls to the modal's 24px gutter. The panel has
   its own. */
.hw-icust-controls{padding:0;gap:10px}
.hw-ggn .ggn-stop-swatch .cpk-trigger,.hw-icust-controls .icust-seg button{white-space:nowrap}
/* Twelve icons, not two hundred thousand: the library's auto-fill grid would
   give this handful of cells a whole row each at panel width. Six across keeps
   the picker two tidy rows and leaves the cell itself - glyph over mono name,
   no card, fill on hover - exactly as the library draws it. */
.hw-ig{grid-template-columns:repeat(6,minmax(0,1fr))}
.hw-ig .ic{min-height:62px;padding:10px 4px 8px}
.hw-ig .ic[aria-pressed="true"]{background:var(--bg-2);border-color:var(--bh)}
.hw-ig .ic[aria-pressed="true"] span{color:var(--t0)}
@media(max-width:640px){.hw-ig{grid-template-columns:repeat(4,minmax(0,1fr))}}

/* 5 · Typography */
.hw-type-preview{min-width:0;padding:10px 14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--bg-0);overflow:hidden}
/* THE LADDER IS `.tsc-row`, TYPE SCALE'S OWN. The meta moved from a caption
   stacked ABOVE each specimen into the generator's fixed left gutter, and it
   carries what the generator carries: the token name in accent mono, px and
   rem, the line height. `.hw-type-meta` is gone with the caption.

   Geometry only below. `.tsc-row` is a button on a full-width page and this is
   a static row in a 240px stage, so it gives up the generator's 14px/16px
   padding and takes a narrower gutter. The specimen keeps its own size variable
   because the mini computes sizes from state rather than from the generator's
   fitted preview ladder. */
.hw-type-row{padding:5px 0;border-top:1px solid var(--border)}
.hw-type-row:first-child{padding-top:0;border-top:0}
.hw-type-row:last-child{padding-bottom:0}
/* The generator's own 116px gutter. Narrower and "28.7px line" wraps, which
   turns a three-line gutter into four and costs more height than the 12px
   saves. */
/* The generator's own 116px gutter, so "31.3px · 1.956rem" stays on one line.
   The tightened line-height is the frame budget: on the two small steps the
   gutter is TALLER than the specimen beside it, so it sets the row height. */
/* row-gap 0, column-gap 8. Below 769px the shared rule turns `.tsc-row-meta`
   into a horizontal wrap (`flex-direction:row`), where a flat `gap:0` printed
   "--text-xl25px · 1.563rem" with no space between the token and its size.
   Naming the two axes separately is correct in both layouts. */
.hw-type-row .tsc-row-meta{flex-basis:116px;row-gap:0;column-gap:8px}
.hw-type-row .tsc-row-name,.hw-type-row .tsc-row-num{line-height:1.35}
.hw-type-sample{display:block;flex:1;min-width:0;max-width:100%;font-size:var(--hw-type-size);font-weight:650;line-height:1.08;letter-spacing:-.025em;color:var(--t0);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* Below 769px the shared rule turns `.tsc-row` into a COLUMN, and both of the
   declarations above are row-layout assumptions that then misfire: `flex:1`
   stretches the specimen down the row instead of across it, and `nowrap`
   ellipsises a 31px specimen that has 358px of phone to sit in. The generator
   answers this for `.tsc-row-text` in the same breakpoint; this is the same
   answer for the one element that could not take its class. */
@media(max-width:768px){
  .hw-type-sample{flex:0 0 auto;white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:anywhere}
  /* AND THE GUTTER MUST GIVE UP ITS BASIS HERE, which is the subtler half.
     `flex-basis` measures along the CONTAINER'S main axis, and the shared rule
     above turns `.tsc-row` into a column at this width - so 116px stops being a
     gutter width and becomes a 116px-TALL meta box, opening a chasm between
     each step's label and its own specimen. The generator already resets this
     (`.tsc-row-meta{flex-basis:auto}` in the same breakpoint); the reset was
     losing to the two-class selector above it, at (0,2,0) against (0,1,0).
     Caught in a 390px screenshot, not by any assertion. */
  .hw-type-row .tsc-row-meta{flex-basis:auto}
}
.hw-type-side{gap:12px}
.hw-type-tools{display:flex;flex-direction:column;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden}
.hw-type-tool{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;width:100%;min-height:54px;padding:8px 11px;border:0;border-top:1px solid var(--border);background:var(--bg-1);color:var(--t1);font-family:var(--font);text-align:left;text-decoration:none;cursor:pointer;transition:background var(--t),color var(--t)}
.hw-type-tool:first-child{border-top:0}
.hw-type-tool:hover{background:var(--hvr);color:var(--t0);text-decoration:none}
.hw-type-tool:focus-visible{position:relative;z-index:1;outline:2px solid var(--hue,var(--accent));outline-offset:-2px}
.hw-type-tool:disabled{opacity:.55;cursor:not-allowed}
.hw-type-tool svg{width:18px;height:18px;color:var(--hue,var(--accent-strong))}
.hw-type-tool>span:nth-child(2){display:flex;min-width:0;flex-direction:column}
.hw-type-tool strong{font-size:var(--fs-body-s);font-weight:650;color:var(--t0)}
.hw-type-tool small{font-size:var(--fs-caption);line-height:1.35;color:var(--t2)}

@media (max-width:640px){
  .hw-panel{padding:16px}
  /* THE BOARD TURNS INTO ROWS HERE, AND THAT IS THE SHARED RULE DOING IT.
     `@media(max-width:768px)` already restacks `.plb-board` into full-width
     rows for Palette Builder, because five vertical columns cannot hold
     "Bauhaus Parchment" and "#E6E0EC" side by side on a phone. The mini board
     inherits that for free — same breakpoint, same layout, same tool row — so
     all this has to do is release the desktop height it was clipping to. Which
     is the whole argument for reusing the classes: the responsive answer was
     already solved once and did not have to be solved again here. */
  .hw-stage .hw-board{height:auto}
  .hw-ui-metric-num{font-size:22px}
  .hw-ui-chart{height:48px}
  .hw-select,.hw-input{width:100%}
  .hw-continue,.hw-btn{width:100%;justify-content:center}
  .hw-foot{gap:10px}
}

/* The @media(max-width:380px) block that used to sit here shrank the hex chip
   twice over, because five vertical swatches sharing ~51px could not hold a
   label. The board is a stack of full-width rows below 768px, so the constraint
   it was defending against no longer exists and the block went with the strip. */

/* The grade badges state a WCAG result, so they had better pass one themselves.
   --ok (#16a34a) on its own 14% tint measured 4.15:1 and --warn (#ca8a04) on a
   16% tint 3.98:1 — both under 4.5:1 for 11px text. Darkened foregrounds only;
   the tints are unchanged, so the colour coding still reads the same. Measured
   on the composited backgrounds: #166534 on #deede4 = 5.89:1,
   #854d0e on #f0e6d7 = 5.55:1. */



/* Reusable final CTA */
.system-cta{position:relative;isolation:isolate;max-width:1180px;min-height:420px;margin:var(--sec-pad) auto var(--s-8);display:grid;place-items:center;overflow:hidden;padding:var(--s-8) 24px;border:1px solid var(--border);border-radius:var(--radius-2xl);background:var(--bg-1)}
.system-cta-grid{position:absolute;z-index:-2;inset:0;opacity:.5;background-image:linear-gradient(color-mix(in srgb,var(--t0) 5%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--t0) 5%,transparent) 1px,transparent 1px);background-size:44px 44px;mask-image:radial-gradient(circle at center,#000,transparent 74%)}
.system-cta-beams{position:absolute;z-index:-1;inset:0;overflow:hidden}
.system-cta-beams i{position:absolute;left:50%;bottom:-58%;width:70px;height:130%;border-radius:var(--radius-pill);background:linear-gradient(to top,color-mix(in srgb,var(--accent) 20%,transparent),transparent 68%);transform-origin:50% 100%}
.system-cta-beams i:nth-child(1){transform:translateX(-50%) rotate(-62deg)}
.system-cta-beams i:nth-child(2){transform:translateX(-50%) rotate(-42deg)}
.system-cta-beams i:nth-child(3){transform:translateX(-50%) rotate(-21deg)}
.system-cta-beams i:nth-child(4){transform:translateX(-50%)}
.system-cta-beams i:nth-child(5){transform:translateX(-50%) rotate(21deg)}
.system-cta-beams i:nth-child(6){transform:translateX(-50%) rotate(42deg)}
.system-cta-beams i:nth-child(7){transform:translateX(-50%) rotate(62deg)}
.system-cta-inner{max-width:690px;text-align:center}
.system-cta-title{margin-top:var(--s-4);font-size:var(--fs-h1);font-weight:720;line-height:1.03;letter-spacing:-.035em;color:var(--t0);text-wrap:balance}
.system-cta-lede{max-width:520px;margin:var(--s-4) auto 0;font-size:var(--fs-body);line-height:1.55;color:var(--t2)}
.system-cta-actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;margin-top:var(--s-6)}
.system-cta-hint{margin-top:var(--s-4);font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}

/* Footer — a row of large feature links above the standard column links, so
   the last thing before the page ends still sells the product, not just
   navigates it. */
.home-foot{background:var(--bg-1);border-top:1px solid var(--border);padding:var(--s-9) 0 var(--s-6);margin-top:var(--sec-pad)}
.home-foot-feat{display:grid;grid-template-columns:repeat(3,1fr);gap:32px 48px}
.home-foot-feat-link{display:block;text-decoration:none}
.home-foot-feat-link:hover{text-decoration:none}
.home-foot-feat-title{display:flex;align-items:center;gap:10px;font-size:var(--fs-h2);font-weight:700;letter-spacing:-.02em;color:var(--t0);transition:color var(--dur-3) var(--ease-out)}
.home-foot-feat-link:hover .home-foot-feat-title{color:var(--hue,var(--accent-strong))}
.home-foot-feat-link:hover .fx-dot{transform:scale(1.25)}
.home-foot-feat-desc{font-size:var(--fs-caption);color:var(--t2);margin-top:6px}
.home-foot-cols{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;margin-top:var(--s-8)}
.home-foot-colhead{font-family:var(--mono);font-size:var(--fs-micro);letter-spacing:.12em;text-transform:uppercase;color:var(--t2);margin-bottom:12px}
.home-foot-link{display:flex;align-items:center;gap:8px;min-height:32px;font-size:var(--fs-body-s);color:var(--t1);text-decoration:none}
.home-foot-link:hover{color:var(--t0);text-decoration:none}
.home-foot-legal{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:var(--s-8);padding-top:24px;border-top:1px solid var(--border)}
.home-foot-brand{display:flex;align-items:center;gap:10px}
.home-foot-copy{font-size:var(--fs-caption);color:var(--t2)}

/* ══ Foundry responsive ══ */
@media(max-width:1180px){
  /* Tight middle ground: the centred menus stay put; the search gives up its
     placeholder and shrinks to the icon so the side columns never clip.
     The base rule's definite 300px comes off with it — and `.is-hot` has to be
     named explicitly, because a media query adds no specificity and
     `.pnav-search.is-hot` would otherwise keep winning down here, where there
     is no hover and no placeholder to expand for. */
  .pnav-search,.pnav-search.is-hot{flex:0 0 auto;width:auto}
  .pnav-search-field{width:40px;padding:0;justify-content:center}
  .pnav-search-ph,.pnav-search-kbd{display:none}
}
@media(max-width:1024px){
  .home-hero{min-height:auto}
  .home-hero-core{margin-top:0}
  .surface-grid{grid-template-columns:repeat(2,1fr)}
}
/* THE PROMO CARD YIELDS TO THE TOOLS, and it has to yield sooner than 1024.
   `.pnav-menu` is capped at `100vw - 32px`, so between 1025 and 1240 the Create
   panel is squeezed below its 1260px design width while the editorial card
   still takes a fixed 260px + 40px gutter. What gives is the tool columns: at a
   1180px viewport they fall to 234px, two pixels short of holding "Component
   Designer" beside its Soon badge, so the row wrapped to two lines and broke
   the rhythm of every column. The card is the decoration and the tools are the
   function, so the card is what goes. */
@media(max-width:1240px){
  .pnav-menu-cols{grid-template-columns:1fr}
  .pnav-promo,.pnav-editorial{display:none}
  /* The divider belongs to the editorial card's edge; with the card gone it
     would draw a rule down the left of the whole panel. */
  .pnav-menu-cols > .pnav-grid{padding-left:0;margin-left:0;border-left:0}
}
/* 769–980 is the band the mega menu opens in on a small laptop and a tablet in
   landscape, and three columns do not fit there: at 834 a column is 227px, of
   which 39px is the icon, leaving 188px for a label plus its Soon badge that
   together need 197. The badge wrapped to a line of its own and made a 77px row
   sit among 52px rows. Two columns give 324px and the rhythm holds. The stacks
   that no longer fit across simply wrap to a second grid row — which is what
   the row-gap above exists to keep legible. */
@media(max-width:980px){
  /* Two columns, but FLOWED rather than gridded. A 2-column grid puts the third
     stack in grid row 2, and grid rows align: the short Colour stack then sat
     above 190px of nothing waiting for the taller stack beside it to finish.
     `columns` balances by height instead, so the groups pack. break-inside
     keeps a group and its eyebrow together. */
  .pnav-menu[data-menu="create"] .pnav-grid,.pnav-menu[data-menu="discover"] .pnav-grid{display:block;columns:2;column-gap:32px}
  .pnav-menu[data-menu="create"] .pnav-colstack,.pnav-menu[data-menu="discover"] .pnav-colstack{break-inside:avoid;margin-bottom:30px}
  /* The inter-column hairline is drawn by each stack against the one before it.
     In a flowed layout a stack's previous sibling may sit in the other column,
     so the rule would be drawn against empty space. */
  .pnav-menu .pnav-colstack + .pnav-colstack::before{display:none}
}
@media(max-width:768px){
  .pnav-items,.pnav-actions .ui-pill-ghost{display:none}
  .pnav-mobile{display:inline-flex}
  /* The centred menus are gone (hamburger sheet takes over), so the grid
     falls back to a simple flex row. Padding is NOT redeclared here — it stays
     on --page-inline from the base rule. It used to hardcode 12px, a copy of
     the old mobile gutter, which silently pinned the nav 4px off the footer and
     the page the moment that token moved. */
  .pnav-inner{display:flex}
  .pnav-lead{flex:1 1 auto}
  /* The base min-width:max-content exists to lift a `1fr` GRID track's floor.
     There is no grid here, so it buys nothing and could only stop the cluster
     yielding on a 320px phone — hand the width back. */
  .pnav-actions{min-width:0}
  /* Search collapses to an icon-only tap target hugging the actions cluster;
     sales routes get it back too — on mobile it's the only way into the
     palette. The bookmark / export icon buttons fold away into the sheet. */
  .pnav-search,.pnav-search.is-hot{flex:0 0 auto;width:auto;margin-left:auto}
  .pnav--sales .pnav-search-field{display:flex}
  .pnav-search-field{width:40px;min-width:0;padding:0;justify-content:center}
  .pnav-search-ph,.pnav-search-kbd{display:none}
  .pnav-iconbtn{display:none}
  /* Touch: the hamburger sheet IS the menu, so the resting 3-dots (a desktop
     hover-state affordance) is redundant — drop it. Signed-in users keep the
     avatar; theme + auth live in the sheet / Settings.
     That last clause was ASPIRATIONAL until 2026-09-03: auth was in the sheet,
     the theme control was not, and this rule was the only thing standing between
     a phone visitor and the one place it existed. The sheet now renders the same
     ThemeChoice control, so the sentence is finally true — if the sheet's theme
     block is ever removed, this rule has to go with it. */
  .pnav-more-wrap{display:none}
  .home-foot-feat{grid-template-columns:repeat(2,1fr)}
  .home-foot-cols{grid-template-columns:repeat(2,1fr);gap:24px 32px}
  .home-hero{padding-top:calc(var(--nav-top) + var(--nav-h) + var(--s-8))}
  .hw-tab{flex:1 1 0;min-width:74px;padding:0 8px;font-size:var(--fs-caption)}
}
@media(max-width:480px){
  /* Phone: a shorter bar. Every offset (menu, sheet, hero padding) derives from
     the token, so one override re-seats them all. */
  :root{--nav-h:52px}
  /* Drop the gear + inline action pills — those live in the sheet — so the
     bar stays to logo · search · avatar · menu. */
  .pnav-actions .ui-pill{display:none}
  .home-hero-cta{flex-direction:column}
  .home-hero-cta .ui-pill{width:100%}
  .home-hero{padding-inline:18px}
  .hw-head .home-h2{font-size:var(--fs-h3)}
  .hw-tabs{padding:6px 6px 0}
  /* 88px, not 72px, and the number is doing real work. At 72 the five tabs
     measured 85 / 95 / 79 / 72 / 114, which lands the fourth tab's right edge
     at 337px inside a 344px content box — a 5px sliver of the fifth tab's own
     padding, so Typography rendered as literally nothing and the rail looked
     like a complete four-tab strip. 88 pushes the FOURTH tab across the edge
     instead (277→365 against 344), leaving ~67px of a real, labelled tab
     sliced by the fade. That is the peek the rail doctrine requires: a
     deliberate straddle, not an arithmetic accident. */
  .hw-tab{flex:1 0 auto;min-width:88px}
  .system-cta{min-height:380px;margin-inline:0;padding:var(--s-7) 18px}
  .system-cta-actions{flex-direction:column;width:100%}
  .system-cta-actions .ui-pill{width:100%}
  .home-foot-feat{grid-template-columns:1fr}
  .home-foot-cols{grid-template-columns:1fr}
  .surface-grid{grid-template-columns:1fr}
}
@media(max-width:380px){
  .home-hero-sub{font-size:var(--fs-body)}
  .hw-panel{padding:14px}
  .hw-tab{flex:0 0 auto;min-width:0;padding:0 12px}
}
/* ─── Tint Scale Generator (/color/tint) — tt- ─── */
