.tt-audience{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin-top:var(--s-7);overflow:hidden;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius-l);box-shadow:var(--ring)}
