.tt-status strong{font-family:var(--mono);font-size:12px;color:var(--t0)}
.tt-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:var(--s-5);align-items:start;min-width:0}
.tt-grid>*{min-width:0}
