.tt-slider-row input[type="range"]{width:100%;accent-color:var(--brand)}
.tt-slider-head{display:flex;justify-content:space-between;align-items:baseline}
.tt-select{width:100%;height:42px;padding:0 12px;font-family:var(--font);font-size:13px;color:var(--t0);background:var(--inp);border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;margin-bottom:14px;transition:border-color var(--t),box-shadow var(--t)}
.tt-select:focus{outline:none;border-color:var(--brand);box-shadow:0 0 0 3px var(--brand-bg)}
.tt-check{display:flex;align-items:flex-start;gap:9px;font-size:12px;line-height:1.45;color:var(--t1);cursor:pointer;margin-bottom:6px}
.tt-check input{margin-top:2px;accent-color:var(--brand);cursor:pointer;flex:0 0 auto}
.tt-reset{align-self:flex-start;min-height:36px;margin-top:4px;padding:8px 12px;font-size:11px;font-weight:600;color:var(--t1);background:transparent;border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;transition:border-color var(--t),background var(--t),color var(--t)}
.tt-reset:hover{border-color:var(--bh);background:var(--hvr);color:var(--t0)}
.tt-reset:focus-visible,.tt-copy-all:focus-visible,.tt-mini:focus-visible,.tt-view-btn:focus-visible,.tt-copy-primary:focus-visible{outline:2px solid var(--brand);outline-offset:2px}
.tt-bases-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:6px}
.tt-bases-actions{display:flex;gap:8px;flex-wrap:wrap}
.tt-ramps{display:flex;flex-direction:column;margin-bottom:4px}
.tt-ramp-block{display:flex;flex-direction:column;gap:10px;padding:18px 0;border-top:1px solid var(--border)}
.tt-ramp-meta{display:flex;align-items:baseline;gap:8px}
.tt-ramp-meta strong{font-size:12px;font-weight:650;color:var(--t0)}
.tt-ramp-meta span{font-family:var(--mono);font-size:10px;color:var(--t2)}
.tt-ramp-block--selected{position:relative}
.tt-ramp-block--selected::before{content:'';position:absolute;top:0;bottom:0;left:-18px;width:2px;background:var(--brand)}
.tt-ramp-select{display:flex;align-items:center;gap:10px;width:100%;min-height:42px;padding:6px 8px;text-align:left;color:var(--t1);background:transparent;border:1px solid transparent;border-radius:var(--radius-s);cursor:pointer;transition:background var(--t),border-color var(--t),color var(--t)}
.tt-ramp-select:hover{color:var(--t0);background:var(--hvr)}
.tt-ramp-select[aria-checked="true"]{color:var(--t0);background:var(--brand-bg);border-color:color-mix(in srgb,var(--brand) 28%,var(--border))}
.tt-ramp-select:focus-visible{outline:2px solid var(--brand);outline-offset:2px}
.tt-ramp-select-dot{width:10px;height:10px;flex:0 0 auto;border:2px solid var(--t3);border-radius:50%;box-shadow:inset 0 0 0 2px var(--card)}
.tt-ramp-select[aria-checked="true"] .tt-ramp-select-dot{background:var(--brand);border-color:var(--brand)}
.tt-ramp-select>span:nth-child(2){display:flex;min-width:0;flex-direction:column;gap:2px}
.tt-ramp-select strong{font-size:12px;font-style:normal;font-weight:650;color:inherit}
.tt-ramp-select small{font-family:var(--mono);font-size:9px;color:var(--t2)}
.tt-ramp-select em{margin-left:auto;font-size:9px;font-style:normal;font-weight:650;letter-spacing:.04em;text-transform:uppercase;color:var(--t3)}
.tt-ramp-select[aria-checked="true"] em{color:var(--accent-strong)}
.tt-ramp-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.tt-ramp-head .tt-hex-input{height:40px;flex:0 1 132px}
.tt-mini,.tt-copy-all{min-height:34px;padding:7px 11px;font-size:10.5px;font-weight:600;color:var(--t1);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;transition:border-color var(--t),background var(--t),color var(--t)}
.tt-mini:hover,.tt-copy-all:hover{border-color:var(--bh);background:var(--hvr);color:var(--t0)}
.tt-mini--x{margin-left:auto;min-width:34px;padding:6px 10px;font-size:15px;line-height:1;color:var(--t2)}
.tt-mini--x:hover{border-color:var(--err);color:var(--err-strong)}
.tt-copy-all:disabled{opacity:.5;cursor:not-allowed}
.tt-copy-all:disabled:hover{border-color:var(--border);background:var(--bg-2)}
.tt-ramp{display:flex;overflow-x:auto;border:1px solid var(--border);border-radius:var(--radius-s);scrollbar-width:thin;scrollbar-color:var(--t3) transparent}
.tt-cell{flex:1 1 0;min-width:60px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-height:76px;padding:8px 4px;background:var(--tt-c);color:var(--tt-ink);border:0;cursor:pointer;transition:filter var(--t-fast),box-shadow var(--t-fast)}
.tt-cell:hover{filter:saturate(1.08);box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--tt-ink) 35%,transparent)}
.tt-cell:focus-visible{position:relative;z-index:1;outline:2px solid var(--brand);outline-offset:-3px}
.tt-cell-step{font-size:11px;font-weight:750;letter-spacing:.02em}
.tt-cell-hex{font-family:var(--mono);font-size:9px;opacity:.84}
.tt-ramp--dense .tt-cell{min-width:6px;min-height:52px;padding:0}
.tt-dense-inspector{display:flex;align-items:center;gap:10px;min-height:34px;padding:7px 10px;border:1px solid var(--border);border-top:0;border-radius:0 0 var(--radius-s) var(--radius-s);background:var(--bg-1);font-size:11px;color:var(--t2)}
.tt-dense-inspector strong,.tt-dense-inspector code{color:var(--t0)}
.tt-dense-inspector code{font-family:var(--mono)}
.tt-dense-inspector span:last-child{margin-left:auto}
.tt-ramp-scroll{display:none;margin:0;font-size:10px;color:var(--t2)}
/* `.tt-delivery` is its own card now, not a block nested in the 01 card - which
   is what made the page number its steps 01, 03, 02 with no CSS able to fix it
   (03 was a CHILD of the first card, 02 was that card's SIBLING). It therefore
   drops the nested block's top rule and spacing and takes the panel's own.
   At >=1344px, where the workbench is two columns, it spans the full width
   beneath the working column and its config rail so the numbers still ascend. */
.tt-delivery{grid-column:1/-1}
.tt-delivery-head{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--s-4);margin-bottom:var(--s-4)}
.tt-delivery-head>div:first-child{display:flex;align-items:flex-start;gap:12px}
.tt-view-switch{display:flex;gap:3px;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.tt-view-btn{min-height:34px;padding:7px 11px;font-size:10.5px;font-weight:600;color:var(--t1);background:transparent;border:1px solid transparent;border-radius:var(--radius-xs);cursor:pointer;transition:background var(--t),border-color var(--t),color var(--t)}
.tt-view-btn:hover{color:var(--t0)}
.tt-view-btn--on{color:var(--t0);background:var(--card);border-color:var(--border);box-shadow:var(--shadow-xs)}
.tt-design-view{display:flex;flex-direction:column;gap:12px}
.tt-preview{overflow:hidden;color:var(--tt-pv-text);background:var(--tt-pv-canvas);border:1px solid var(--tt-pv-border);border-radius:var(--radius-l)}
.tt-preview-bar{display:flex;align-items:center;gap:8px;min-height:44px;padding:0 16px;font-size:10px;font-weight:650;color:var(--tt-pv-text);background:var(--tt-pv-surface);border-bottom:1px solid var(--tt-pv-border)}
.tt-preview-mark{width:12px;height:12px;background:var(--tt-pv-accent);border-radius:var(--radius-xs)}
.tt-preview-status{margin-left:auto;padding:4px 7px;font-size:9px;color:var(--tt-pv-text);background:var(--tt-pv-canvas);border:1px solid var(--tt-pv-border);border-radius:var(--radius-xs)}
.tt-preview-body{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(190px,.7fr);gap:var(--s-5);align-items:end;padding:clamp(24px,4vw,46px)}
.tt-preview-copy{max-width:520px}
.tt-preview-eyebrow{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--tt-pv-accent-hover)}
.tt-preview h3{max-width:480px;margin:10px 0 8px;font-size:clamp(26px,3vw,40px);font-weight:650;line-height:1.04;letter-spacing:-.035em;color:var(--tt-pv-text)}
.tt-preview-copy p{max-width:500px;margin:0;font-size:12px;line-height:1.55;color:var(--tt-pv-muted)}
.tt-preview-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}
.tt-preview-actions span{display:inline-flex;align-items:center;justify-content:center;min-width:0;min-height:38px;padding:8px 14px;font-size:10.5px;font-weight:650;border-radius:var(--radius-s)}
.tt-preview-primary{color:var(--tt-pv-on-accent);background:var(--tt-pv-accent);border:1px solid var(--tt-pv-accent)}
.tt-preview-secondary{color:var(--tt-pv-text);background:var(--tt-pv-surface);border:1px solid var(--tt-pv-border)}
.tt-preview-card{display:flex;flex-direction:column;align-items:flex-start;min-height:150px;padding:18px;color:var(--tt-pv-text);background:var(--tt-pv-surface);border:1px solid var(--tt-pv-border);border-radius:var(--radius)}
.tt-preview-card-k{font-family:var(--mono);font-size:8px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--tt-pv-muted)}
.tt-preview-card strong{margin:18px 0 2px;font-size:25px;letter-spacing:-.025em}
.tt-preview-card>span:not(.tt-preview-card-k){font-size:10px;color:var(--tt-pv-muted)}
.tt-preview-spectrum{display:flex;width:100%;height:8px;margin-top:auto;overflow:hidden;border:1px solid var(--tt-pv-border);border-radius:var(--radius-xs)}
.tt-preview-spectrum span{flex:1;background:var(--tt-c)}
.tt-role-map{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));overflow:hidden;border:1px solid var(--border);border-radius:var(--radius-s)}
.tt-role-sample{display:flex;flex-direction:column;align-items:flex-start;min-width:0;padding:12px;background:var(--tt-c);color:var(--tt-ink);border:0;cursor:pointer;text-align:left}
.tt-role-sample+.tt-role-sample{border-left:1px solid color-mix(in srgb,var(--tt-ink) 14%,transparent)}
.tt-role-sample:hover{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--tt-ink) 28%,transparent)}
.tt-role-sample:focus-visible{position:relative;z-index:1;outline:2px solid var(--brand);outline-offset:-3px}
.tt-role-sample span{font-size:9px;opacity:.8}
.tt-role-sample strong{margin:6px 0 2px;font-size:13px}
.tt-role-sample code{max-width:100%;overflow:hidden;font-family:var(--mono);font-size:8.5px;text-overflow:ellipsis}
.tt-view-note{margin:0;font-size:10px;color:var(--t2)}
.tt-developer-view{display:flex;flex-direction:column}
.tt-code-meta{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:10px}
.tt-code-meta p{margin:2px 0 0;font-size:11px;color:var(--t2)}
.tt-code-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}
.tt-copy-primary{min-height:38px;padding:8px 14px;font-size:11px;font-weight:650;color:var(--accent-fg);background:var(--accent-strong);border:1px solid var(--accent-strong);border-radius:var(--radius-s);cursor:pointer;transition:background var(--t),border-color var(--t)}
.tt-copy-primary:hover{background:var(--brand-soft);border-color:var(--brand-soft)}
.tt-export{max-height:380px;margin:0;padding:18px;font-family:var(--mono);font-size:11px;line-height:1.7;color:var(--t1);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);overflow:auto}
.tt-export:focus-visible{outline:2px solid var(--brand);outline-offset:2px}
.tt-more{display:flex;align-items:center;justify-content:space-between;gap:var(--s-5);margin-top:var(--s-6);padding:var(--s-5) 0;border-top:1px solid var(--border)}
.tt-more>div:first-child{display:flex;flex-direction:column;gap:4px;max-width:470px}
.tt-more-kicker{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong)}
.tt-more strong{font-size:13px;font-weight:600;line-height:1.45;color:var(--t0)}
.tt-more-links{display:flex;justify-content:flex-end;gap:20px;flex-wrap:wrap}
.tt-more-link{font-size:11px;font-weight:600;color:var(--t1);text-decoration:none;transition:color var(--t)}
.tt-more-link:hover{color:var(--accent-strong)}
.tt-more-link:focus-visible{outline:2px solid var(--brand);outline-offset:3px}
@media(max-width:980px){
  .tt-hero-copy{grid-template-columns:1fr;gap:var(--s-4)}
  .tt-grid{grid-template-columns:1fr}
  .tt-config{position:static;max-height:none;overflow-y:hidden}
  .tt-output,.tt-config{grid-column:auto;grid-row:auto}
}
@media(max-width:768px){
  /* Mobile gutter. Was 12px, which only ever applied to the nav, the footer and
     the tool toolbars; the page containers carried their own ~20px. Now that
     every page reads the same token the value has to work for body copy too, so
     it is 16px — still the tightest step on the scale, but text and list
     markers no longer run into the edge of a 390px screen. */
  :root{--page-gutter:16px}
  .tt-audience{grid-template-columns:1fr}
  .tt-audience-tab+.tt-audience-tab{border-left:0;border-top:1px solid var(--border)}
  /* The selection indicator has to rotate with the layout. Stacked, the tabs
     divide top-to-bottom, so a `bottom:0` underline on the FIRST tab lands
     directly on top of the SECOND tab's new 1px top border: a 2px brand line
     welded to a 1px grey line, reading as a rendering artefact rather than as
     selection, and pointing at the tab that is NOT selected. Side-on it becomes
     a left-edge bar, which is the conventional stacked-tab treatment and cannot
     collide with a horizontal divider. */
  .tt-audience-tab::after{top:0;right:auto;bottom:0;left:0;width:2px;height:auto}
  .tt-status{grid-template-columns:repeat(2,minmax(0,1fr))}
  .tt-status span:nth-child(3){border-left:0;border-top:1px solid var(--border)}
  .tt-status span:nth-child(4){border-top:1px solid var(--border)}
  .tt-delivery-head{flex-direction:column}
  .tt-preview-body{grid-template-columns:1fr;align-items:start}
  .tt-preview-card{min-height:132px}
  .tt-role-map{grid-template-columns:repeat(3,minmax(0,1fr))}
  .tt-role-sample:nth-child(4){border-left:0}
  .tt-more{align-items:flex-start;flex-direction:column}
  .tt-more-links{justify-content:flex-start}
}
@media(max-width:560px){
  .tt-hero h1{font-size:36px}
  .tt-hero-copy>p{font-size:13px}
  .tt-audience{margin-top:var(--s-5)}
  .tt-audience-tab{min-height:104px;padding:16px}
  .tt-panel{padding:18px}
  .tt-section-head{margin-bottom:18px}
  .tt-bases-head{align-items:flex-start;flex-direction:column}
  .tt-bases-actions{width:100%}
  .tt-bases-actions .tt-copy-all{flex:1}
  .tt-ramp-head .tt-hex-input{flex:1 1 110px}
  .tt-mini--x{margin-left:0}
  .tt-cell{flex:0 0 74px;min-width:74px}
  .tt-ramp--dense .tt-cell{flex:0 0 8px;min-width:8px}
  .tt-ramp-scroll{display:block}
  .tt-view-switch{width:100%}
  .tt-view-btn{flex:1}
  .tt-preview-body{padding:24px 18px}
  .tt-preview-actions span{flex:1}
  .tt-role-map{grid-template-columns:repeat(2,minmax(0,1fr))}
  .tt-role-sample:nth-child(3),.tt-role-sample:nth-child(5){border-left:0}
  .tt-role-sample:nth-child(4){border-left:1px solid color-mix(in srgb,var(--tt-ink) 14%,transparent)}
  .tt-code-meta{align-items:flex-start;flex-direction:column}
  .tt-copy-primary{width:100%}
  .tt-export{font-size:10px}
}
@media(max-width:380px){
  .tt-status{grid-template-columns:1fr}
  .tt-status span+span{border-left:0;border-top:1px solid var(--border)}
  .tt-status span:nth-child(4){border-top:1px solid var(--border)}
  .tt-panel{padding:16px}
  .tt-ramp-head .tt-hex-input{flex-basis:calc(100% - 48px)}
  .tt-mini{flex:1}
  .tt-mini--x{flex:0 0 34px}
  .tt-role-map{grid-template-columns:1fr}
  .tt-role-sample+.tt-role-sample{border-left:0;border-top:1px solid color-mix(in srgb,var(--tt-ink) 14%,transparent)}
  .tt-more-links{align-items:flex-start;flex-direction:column;gap:12px}
}

/* ─── Colour Contrast Checker (/color/contrast) — cc- ─── */
.cc-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}
.cc-panel{display:flex;flex-direction:column}
.cc-fields{display:flex;gap:12px;align-items:flex-end}
.cc-field{flex:1;min-width:0}
.cc-field-row{display:flex;gap:8px;align-items:center}
.cc-picker{width:42px;height:42px;padding:2px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2);cursor:pointer;flex-shrink:0}
.cc-hex-input{flex:1;min-width:0;height:42px;padding:0 12px;font-family:var(--mono);font-size:13px;color:var(--t0);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);transition:border-color var(--t)}
.cc-hex-input:focus{outline:none;border-color:var(--brand)}
.cc-hex-input--bad{border-color:#D64545}
.cc-swap{width:42px;height:42px;flex-shrink:0;font-size:16px;color:var(--t1);background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer;transition:all var(--t)}
.cc-swap:hover{border-color:var(--brand);color:var(--t0)}
.cc-hint{font-size:12px;color:var(--t2);line-height:1.5;margin:10px 0 0}
.cc-ratio{display:flex;align-items:baseline;gap:14px;margin:24px 0 16px}
.cc-ratio-num{font-family:var(--mono);font-size:36px;font-weight:700;letter-spacing:-.02em;color:var(--t0)}
.cc-ratio-verdict{font-size:13px;font-weight:600}
/* THE CONTRAST CHECKER WAS FAILING ITS OWN TEST. Measured on the white card in
   light theme, against the 4.5:1 that 13px/600 text needs and that this page
   exists to enforce:
       .cc-pass  #2E9E5B  3.41:1
       .cc-mixed #C98A1B  2.94:1   <- the verdict line, the page's headline
       .cc-fail  #D64545  4.38:1
   All three were hard-coded hexes, so they also never responded to the theme -
   and #D64545 measured 3.97:1 on the dark card, failing there too.

   #323 fixed this in two halves: it put the DARK theme on the project's own
   --ok/--warn/--err, and left LIGHT as three hard-coded hexes because no light
   token was dark enough to use. That token now exists, so the halves join up
   and the hexes go. One declaration each, theme-aware, no override block:
       .cc-pass   #1F7040 -> --ok-strong    6.09 -> 7.47 on the white card
       .cc-mixed  #8A5E10 -> --warn-strong  5.69 -> 7.37
       .cc-fail   #C02F2F -> --err-strong   5.69 -> 7.78
   Dark is unchanged in value: --ok-strong and --warn-strong ARE --ok and --warn
   there, and --err-strong is a shade lighter (6.72 on the dark card, was 6.29).
   The page that enforces the standard now states it with the same tokens it
   would tell you to use. */
.cc-pass{color:var(--ok-strong)}
.cc-mixed{color:var(--warn-strong)}
.cc-fail{color:var(--err-strong)}
.cc-checks{list-style:none;margin:0 0 20px;padding:0;display:flex;flex-direction:column;gap:6px}
.cc-check{display:flex;align-items:center;gap:10px;padding:9px 12px;font-size:13px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2)}
.cc-check-mark{width:18px;height:18px;display:flex;align-items:center;justify-content:center;border-radius:50%;font-size:11px;font-weight:700;flex-shrink:0}
/* The glyph sits on its own tint over --bg-2, which is a LIGHTER ground than the
   card - so it needs to be darker than the verdict text, not the same colour.
   Measured before: pass 2.70:1, fail 3.43:1 on those tints. */
.cc-check--pass .cc-check-mark{background:rgba(46,158,91,.14);color:var(--ok-strong)}
.cc-check--fail .cc-check-mark{background:rgba(214,69,69,.12);color:var(--err-strong)}
.cc-check-label{font-weight:600;color:var(--t0)}
.cc-check-min{margin-left:auto;font-family:var(--mono);font-size:11px;color:var(--t2)}
/* Fix rows — chip colour + ink arrive as custom props set via ref */
.cc-fixes{display:flex;flex-direction:column;gap:8px}
.cc-fix{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--border);border-radius:var(--radius-s);background:var(--bg-2)}
.cc-fix-chip{padding:5px 10px;font-family:var(--mono);font-size:11px;font-weight:600;border-radius:var(--radius-s);background:var(--cc-chip);color:var(--cc-chip-ink);flex-shrink:0}
.cc-fix-desc{font-size:12px;color:var(--t1);flex:1;min-width:0}
.cc-fix-apply,.cc-fix-copy{padding:6px 12px;font-size:12px;font-weight:600;background:none;border:1px solid var(--border);border-radius:var(--radius-s);color:var(--t1);cursor:pointer;transition:all var(--t);flex-shrink:0}
.cc-fix-apply:hover,.cc-fix-copy:hover{border-color:var(--brand);color:var(--t0)}
/* Live preview — fg/bg arrive as custom props set via ref */
/* ── The live preview [contrast-checker-overhaul] ──
   The four .cc-preview-* rules this replaces styled four lines that described
   the test instead of being one. The design specification, the Mobbin
   references behind it and the one rule the chips obey are all in the header of
   src/pages/ContrastChecker.jsx — kept there because it is a decision about
   what the page SAYS, not about how it is painted. */
.cc-lede{font-size:12.5px;color:var(--t2);line-height:1.55;margin:0 0 14px}
.cc-preview{display:flex;flex-direction:column;gap:18px;padding:24px;border-radius:var(--radius);border:1px solid var(--border);background:var(--cc-bg);color:var(--cc-fg)}
.cc-spec-row{display:flex;align-items:flex-start;gap:12px}
.cc-spec-row>:first-child{flex:1;min-width:0;margin:0}
.cc-spec-h{font-size:24px;font-weight:700;letter-spacing:-.015em;line-height:1.25}
.cc-spec-body{font-size:16px;line-height:1.55}
.cc-spec-small{font-size:12px;line-height:1.5}
.cc-spec-link{text-decoration:underline}
.cc-spec-actions{display:flex;flex-wrap:wrap;gap:8px}
/* The solid button inverts the pair on purpose — same ratio, read the other way
   round, which is the point the hint under the preview makes. */
.cc-spec-btn{display:inline-block;padding:9px 16px;font-size:14px;font-weight:600;border:2px solid var(--cc-fg);border-radius:var(--radius-s);background:var(--cc-fg);color:var(--cc-bg)}
.cc-spec-btn--ghost{background:transparent;color:var(--cc-fg)}
/* PAGE TOKENS ONLY. A chip painted in the pair under test goes unreadable
   exactly when the pair fails — the moment its reader needs it most. `--bg-1`
   and `--border` are opaque, so the chip stays legible over any --cc-bg, and
   06-colour-tool-workbenches measures these in both themes. */
.cc-verdict{flex-shrink:0;display:inline-flex;align-items:center;gap:5px;padding:4px 8px;font-family:var(--mono);font-size:11px;font-weight:700;line-height:1;white-space:nowrap;border-radius:999px;background:var(--bg-1);border:1px solid var(--border);color:var(--t1)}
.cc-verdict-mark{font-weight:700}
.cc-verdict--pass .cc-verdict-mark{color:var(--ok-strong)}
.cc-verdict--fail .cc-verdict-mark{color:var(--err-strong)}
.cc-more{display:flex;gap:20px;flex-wrap:wrap;margin-top:32px}
.cc-more-link{font-size:13px;font-weight:600;color:var(--t1);text-decoration:none;transition:color var(--t)}
.cc-more-link:hover{color:var(--accent-strong)}
@media(max-width:900px){.cc-grid{grid-template-columns:1fr}}
/* The "make it pass" row stops being a single non-wrapping strip. Chip, copy and
   two buttons in one row left the description ~85px at 390px, so
   "AAA (7:1) — adjust the text" wrapped onto two lines while the buttons either
   side of it stayed on one — the row read as broken rather than tight, and the
   sentence that says WHAT to fix was the only thing squeezed. Two grid rows:
   the chip and its sentence together, then the two actions side by side across
   the full width, which also takes them from ~60px wide to a real touch target. */
@media(max-width:560px){
  .cc-fields{flex-direction:column;align-items:stretch}
  .cc-swap{width:100%}
  .cc-fix{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px}
  .cc-fix-chip{grid-area:1/1}
  .cc-fix-desc{grid-area:1/2;align-self:center}
  .cc-fix-apply{grid-area:2/1}
  .cc-fix-copy{grid-area:2/2}
  .cc-fix-apply,.cc-fix-copy{min-height:40px}
  /* Below ~520px the chip and a 24px heading fight for the same line and the
     heading loses to a 2-3 word wrap. Stack instead: the chip reads as a
     caption on its element, which is still the association that matters. */
  .cc-spec-row{flex-direction:column;align-items:flex-start;gap:8px}
}

/* ══════════ Palette Builder (/color/palette) ══════════ */
/* Full-bleed workbench: the negative margins exactly cancel .rail-content's
   padding (24px / var(--page-inline) / var(--s-9)) so the board runs
   edge-to-edge under the pill nav. Column/ramp colours arrive as custom
   props (--plb-c / --plb-ink / --plb-rc) set via callback refs. */
.plb{display:flex;flex-direction:column;min-height:calc(100vh - var(--nav-top) - var(--nav-h));margin:calc(-24px - var(--nav-clear) + var(--nav-top) + var(--nav-h)) calc(-1*var(--page-inline)) calc(-1*var(--s-9))}
/* Horizontal padding mirrors .pnav-inner (same --page-inline token) so the
   toolbar's content edge lines up with the pill nav's at every width. */
.plb-toolbar{position:sticky;top:calc(var(--nav-top) + var(--nav-h));z-index:30;display:flex;align-items:center;justify-content:space-between;gap:12px 18px;flex-wrap:wrap;padding:10px var(--page-inline);background:var(--bg-0);border-bottom:1px solid var(--border)}
/* Neither group ever shrinks below its content, and the toolbar wraps the action
   group onto a second row when the two no longer share one line. That is the ONLY
   content-aware mechanism CSS offers here, and the width at which they stop
   sharing a line is content-dependent, not viewport-dependent: the harmony
   trigger reads "System · <label>", so the toolbar's natural width is 1123px with
   "Auto" selected and 1180px with "Monochromatic" — no fixed media band can be
   right for both. The previous base rules let the title group shrink below its
   content (flex:0 1 auto + min-width:0) while the action group refused to shrink
   at all; because overflow here must stay visible (popovers open absolutely from
   .plb-menuwrap, so the toolbar must NOT scroll/clip), the squeezed title group
   spilled to the right and the action group painted straight over the System
   button — completely unclickable at 961–1000px. Wrapping trades ~47px of
   toolbar height, in a band that is short of width and not of height, for every
   control staying visible, hit-testable and popover-capable.
   769–960 opts back out of wrapping — see the mid-band block below. */
.plb-toolbar-group{display:flex;align-items:center;gap:10px;flex-wrap:nowrap;position:relative}
.plb-toolbar-group:first-child{min-width:0;flex:0 0 auto}
/* margin-left:auto keeps the action group right-aligned on a row of its own;
   justify-content:space-between only right-aligns it while both groups share a
   line. On a shared line the auto margin eats the free space first and the
   result is identical, so one rule covers both. */
.plb-toolbar-group:last-child{flex:0 0 auto;margin-left:auto}
.plb-toolbar-sep{width:1px;height:22px;background:var(--border)}
.plb-title{font-size:15px;font-weight:700;letter-spacing:-.01em;color:var(--t0);margin:0 6px 0 0}
/* Seed picker: reuses ColorPickerPop; the popover opens left-aligned because the
   trigger sits at the left edge of the toolbar (default .cpk-pop is right:0). */
.plb-seedpick{flex:0 0 auto}
.plb-seedpick .cpk-pop{left:0;right:auto}
.plb-toolbar .btn-s,.plb-seedpick .cpk-trigger,.plb-hexfield{height:36px;min-height:36px;border-radius:var(--radius-s)}
.plb-hexfield{width:96px;padding:0 10px;font-family:var(--mono);font-size:13px;text-transform:uppercase;color:var(--t0);background:var(--inp);border:1px solid var(--border);transition:border-color var(--t)}
.plb-hexfield:focus{outline:none;border-color:var(--brand)}
.plb-hexfield--bad{border-color:#D64545}
/* System + Vision toolbar triggers ride on .btn btn-s; these only add the
   eyebrow label + no-wrap so every toolbar control shares one button system. */
.plb-harm{white-space:nowrap}
.plb-harm-k{font-size:9.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.plb-tab-lock{display:inline-flex;opacity:.55}
.plb-file{display:none}
.plb-random{white-space:nowrap}
.plb-kbd{padding:1px 6px;font-family:var(--mono);font-size:10px;font-weight:600;border:1px solid color-mix(in srgb,currentColor 35%,transparent);border-radius:4px;opacity:.85}
.plb-dark{background:var(--t0);color:var(--bg-0);border-color:var(--t0)}
.plb-dark:hover{background:var(--t0);color:var(--bg-0);opacity:.88}
/* display:flex, not block. The wrapper's only in-flow child is an inline-block
   <button>, so a block wrapper puts it in an inline formatting context: once the
   button is squeezed below its intrinsic width its baseline moves, the line-box
   strut adds a pixel underneath, and the whole toolbar grows 1px. Flex
   blockifies the child and removes the strut. The popover is absolutely
   positioned, so it stays out of flow either way. */
.plb-menuwrap{position:relative;display:flex}
/* max-height + overflow on the menu itself means a mousewheel over ANY part of
   an open popover scrolls its content (not the page behind it); overscroll
   containment stops the scroll from chaining out once the list ends. */
.plb-menu{position:absolute;top:calc(100% + 6px);right:0;z-index:40;min-width:240px;max-height:min(72vh,600px);overflow-y:auto;overscroll-behavior:contain;padding:10px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--warm-shadow-lg)}
.plb-menu-title{font-size:12px;font-weight:700;color:var(--t0);margin:2px 2px 10px}
.plb-menu-row{display:flex;gap:8px}
.plb-menu-row input{flex:1;min-width:0;padding:8px 10px;font-size:13px;color:var(--t0);background:var(--inp);border:1px solid var(--border);border-radius:var(--radius-s)}
.plb-menu-row input:focus{outline:none;border-color:var(--brand)}
.plb-menu-sub{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--t2);margin:12px 2px 6px}
.plb-menu-item{display:block;width:100%;padding:8px 10px;font-size:13px;font-weight:500;text-align:left;color:var(--t1);background:none;border:none;border-radius:var(--radius-s);cursor:pointer;transition:all var(--t);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.plb-menu-item:hover{background:var(--bg-2);color:var(--t0)}
.plb-menu--left{left:0;right:auto}
.plb-harmmenu{min-width:316px}
.plb-harm-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.plb-harm-opt{display:inline-flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 11px;font-size:12px;font-weight:600;color:var(--t1);background:none;border:1px solid var(--border);border-radius:10px;cursor:pointer;transition:all var(--t);white-space:nowrap}
.plb-harm-opt:hover{background:var(--bg-2);color:var(--t0)}
.plb-harm-opt--on{background:var(--bg-2);border-color:var(--t0);color:var(--t0)}
.plb-harm-opt>svg{flex-shrink:0;color:var(--t2)}
.plb-harm-opt--on>svg{color:var(--brand)}
.plb-harm-opt-l{flex:1;text-align:left}
/* Colour-vision preview menu — same option chrome as the harmony grid. */
.plb-vismenu{min-width:220px}
.plb-visopt{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;font-size:13px;font-weight:600;text-align:left;color:var(--t1);background:none;border:1px solid transparent;border-radius:10px;cursor:pointer;transition:all var(--t)}
.plb-visopt>svg{flex-shrink:0;color:var(--t2)}
.plb-visopt:hover{background:var(--bg-2);color:var(--t0)}
.plb-visopt--on{background:var(--bg-2);border-color:var(--t0);color:var(--t0)}
.plb-visopt--on>svg{color:var(--brand)}
.plb-visopt-l{flex:1}
.plb-free{padding:2px 7px;font-size:9px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#16A34A;background:color-mix(in srgb,#22C55E 15%,transparent);border-radius:999px}
.plb-scrolllist{display:flex;flex-direction:column;gap:2px;max-height:min(50vh,380px);overflow-y:auto;overscroll-behavior:contain}
.plb-varrow{display:flex;align-items:center;gap:8px;width:100%;padding:0;background:none;border:none;border-radius:var(--radius-s);text-align:left}
button.plb-varrow{padding:7px 8px;cursor:pointer;transition:background var(--t)}
button.plb-varrow:hover{background:var(--bg-2)}
.plb-varrow--locked{opacity:.55}
.plb-varrow--active{background:var(--brand-weak,var(--bg-2))}
.plb-varrow--active .plb-varrow-name{color:var(--accent-strong)}
.plb-varrow-tick{display:flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--brand)}
.plb-varrow-main{display:flex;align-items:center;gap:8px;flex:1;min-width:0;padding:7px 8px;background:none;border:none;border-radius:var(--radius-s);text-align:left;cursor:pointer;transition:background var(--t)}
.plb-varrow-main:hover{background:var(--bg-2)}
.plb-varrow-name{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;font-size:12.5px;font-weight:600;color:var(--t0)}
.plb-varrow-name small{font-size:10.5px;font-weight:500;color:var(--t2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.plb-varrow-cmp{display:flex;align-items:center;justify-content:center;width:30px;height:30px;flex-shrink:0;color:var(--t1);background:none;border:none;border-radius:8px;cursor:pointer;transition:all var(--t)}
.plb-varrow-cmp:hover{color:var(--t0);background:var(--bg-2)}
.plb-strip{display:inline-flex;gap:2px;flex-shrink:0}
.plb-strip-c{width:12px;height:20px;border-radius:4px;background:var(--plb-rc)}
.plb-score{flex-shrink:0;padding:2px 8px;font-family:var(--mono);font-size:10px;font-weight:700;color:var(--t1);background:var(--bg-2);border-radius:999px}

/* Image picker (Wave 4) — drag-drop dropzone, nested preview with draggable
   picker points, a picked-palette strip and a +/- colour count. Free to use. */
/* The image picker's card. Wide enough that a picker point can be placed
   deliberately rather than guessed at — the founder's report was that the old
   300px dropdown was too small to see where the markers were landing. */
.plb-imgcard{width:min(720px,100%);gap:10px}
.plb-imgdrop{display:flex;flex-direction:column;align-items:center;gap:6px;padding:26px 16px;text-align:center;color:var(--t2);background:var(--bg-1);border:1.5px dashed var(--border);border-radius:var(--radius-s);cursor:pointer;transition:all var(--t)}
.plb-imgdrop:hover,.plb-imgdrop--over{border-color:var(--brand);background:var(--bg-2);color:var(--t1)}
.plb-imgdrop>svg{color:var(--t2)}
.plb-imgdrop-t{font-size:13px;font-weight:600;color:var(--t0)}
.plb-imgdrop-s{font-size:11px;font-weight:500;color:var(--t2)}
.plb-imgerr{margin-top:8px;padding:7px 10px;font-size:11.5px;font-weight:600;color:#B91C1C;background:color-mix(in srgb,#EF4444 12%,transparent);border-radius:var(--radius-s)}
/* THE STAGE BOX MUST HAVE THE IMAGE'S OWN RATIO. Every picker point is stored
   as a normalised coordinate in the SOURCE image and rendered as a percentage
   of this box, so the two only describe the same place while the two shapes
   match. This was a hard 16/10 with `object-fit: cover`: any other shape of
   image was cropped, the markers sat over pixels they had not sampled, and
   dragging one read the colour under a different pixel from the one under the
   cursor. `--plb-img-ar` is set inline from the upload's natural dimensions.

   The max-width is not decoration either: with a definite width, `aspect-ratio`
   derives the height, and a `max-height` alone would clamp the height and
   silently break the ratio again. Capping the WIDTH at the height cap times the
   ratio means whichever limit binds, both stay consistent. */
.plb-imgstage{position:relative;width:100%;aspect-ratio:var(--plb-img-ar,1.6);max-width:calc(min(48vh,420px) * var(--plb-img-ar,1.6));margin-inline:auto;overflow:hidden;border-radius:var(--radius-s);background:var(--bg-2);touch-action:none;user-select:none}
.plb-imgstage-img{width:100%;height:100%;object-fit:cover;display:block;pointer-events:none}
.plb-imghint{margin:0;font-size:11px;font-weight:500;color:var(--t2);text-align:center}
.plb-imgpoint{position:absolute;width:26px;height:26px;transform:translate(-50%,-50%);border-radius:999px;border:3px solid #fff;box-shadow:0 0 0 1.5px rgba(0,0,0,.45),0 2px 6px rgba(0,0,0,.4);cursor:grab;padding:0}
.plb-imgpoint:active{cursor:grabbing}
.plb-imgstrip{display:flex;gap:3px;margin-top:8px}
.plb-imgswatch{flex:1;height:22px;border-radius:5px;border:1px solid color-mix(in srgb,var(--t0) 10%,transparent)}
.plb-imgcount{display:flex;align-items:center;justify-content:space-between;margin-top:10px}
.plb-imgcount-l{font-size:12px;font-weight:600;color:var(--t1)}
.plb-imgcount-ctl{display:flex;align-items:center;gap:4px}
.plb-imgcount-btn{display:flex;align-items:center;justify-content:center;width:26px;height:26px;font-size:16px;font-weight:600;line-height:1;color:var(--t1);background:var(--bg-2);border:1px solid var(--border);border-radius:8px;cursor:pointer;transition:all var(--t)}
.plb-imgcount-btn:hover:not(:disabled){background:var(--bg-1);color:var(--t0);border-color:var(--t0)}
.plb-imgcount-btn:disabled{opacity:.4;cursor:not-allowed}
.plb-imgcount-n{min-width:20px;text-align:center;font-size:13px;font-weight:700;color:var(--t0);font-variant-numeric:tabular-nums}
.plb-imgactions{display:flex;gap:6px;margin-top:12px}
.plb-imgactions .btn{flex:1}
.plb-imgclear{display:block;width:100%;margin-top:8px;padding:6px;font-size:11.5px;font-weight:600;color:var(--t2);background:none;border:none;border-radius:var(--radius-s);cursor:pointer;transition:all var(--t)}
.plb-imgclear:hover{color:#B91C1C;background:var(--bg-2)}
.plb-tgl--on{color:var(--brand);border-color:var(--brand);background:color-mix(in srgb,var(--brand) 8%,transparent)}
/* ── The board ──
   `min-height:auto` is a CONSEQUENCE of the fix below, not the fix itself, and
   the distinction was found by mutation rather than reasoning — restoring the
   old `420px` alone does not bring the defect back.

   While `.plb-col-tools` was out of flow, `420px` was the only thing reserving
   room for the 260px tool stack: a column's own in-flow content is just 170px
   (20 padding + 124 name/hex/ramp + 26 padding), so nothing else was holding
   the board open. It was a hand-tuned stand-in for a height the layout could
   not see, and it was 8px short of the 428px a column actually needs — which
   is the founder's 2026-08-24 report ("still clipping issues on the palette
   builder on smaller desktop screens and other shapes like 4:3").

   With the stack in flow the board's content minimum is real and this floor no
   longer binds. Verified, not assumed: the board measures 436px at 1366x608 and
   688px at 1366x900 with this declaration set to either `auto` or `420px`. It
   is dropped because a stale magic number that currently does nothing is worse
   than none — shorten the tool stack by 17px and 420 silently starts binding
   again, which is precisely how this defect was born. */
.plb-board{display:flex;flex:1;min-height:auto}
.plb-col{position:relative;flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:6px;padding:20px 8px 26px;background:var(--plb-c);color:var(--plb-ink)}
/* Vision type split: top half the real palette colour, bottom half the
   colour-vision simulation. Content sits in the bottom half (justify-end), so
   --plb-ink is computed against --plb-sim. */
.plb-col--split{background:linear-gradient(to bottom,var(--plb-c) 0 50%,var(--plb-sim) 50% 100%)}
/* IN FLOW, not absolute. It was `position:absolute;top:18px;left:50%` with a
   translate to centre it, and out-of-flow content contributes nothing to its
   container's height — so the board's floor could not see the 260px this stack
   occupies and the two ends of the column grew into each other from opposite
   directions (tools down from the top, name/hex/ramp up from the bottom).
   `margin-bottom:auto` on the FIRST child reproduces the same visual placement
   through flex instead: it eats the free space below, pinning the stack to the
   top while `justify-content:flex-end` keeps everything else at the bottom, and
   `.plb-col`'s own `align-items:center` supplies the centring the translate
   used to do. Measured shift at a tall viewport: 18..278 becomes 20..280, i.e.
   2px, which is the difference between `top:18px` and the column's 20px
   padding. The payoff is that the stack is now part of the content minimum, so
   nothing has to assert a floor for it.
   The ≤768px block below returns this to a row and clears the auto margin — in
   a row-direction flex container an auto BLOCK margin would push the stack to
   the top of the cross axis instead of centring it. */
.plb-col-tools{margin-bottom:auto;display:flex;flex-direction:column;gap:6px}
/* The per-swatch controls are visible AT REST by default and hidden only where
   a hover can bring them back. That direction matters: the old rule hid them at
   rest for everyone and corrected it in @media(max-width:768px), which is a
   proxy for "touch" that stops being true at exactly 769px — so every tablet and
   every phone held sideways got a colour picker with no editing controls on it
   at all (S11, mobile-audit-2026-08: 30 buttons measured opacity:0 with
   pointer-events:auto at 834x1194, 1024x768, 1180x820 and 844x390, i.e. live
   32x32 targets with zero paint, where a mis-tap runs Remove or Duplicate with
   nothing on screen to explain it). Guard on the capability, not the width —
   .grg-like at the bottom of this file is the pattern this copies. */
.plb-tool{display:flex;align-items:center;justify-content:center;width:32px;height:32px;color:inherit;background:none;border:none;border-radius:8px;cursor:pointer;transition:opacity var(--t),background var(--t)}
@media(hover:hover){.plb-tool{opacity:0}}
.plb-col:hover .plb-tool,.plb-col:focus-within .plb-tool,.plb-tool--on{opacity:1}
.plb-tool:hover{background:color-mix(in srgb,var(--plb-ink) 14%,transparent)}
.plb-tool--on{background:color-mix(in srgb,var(--plb-ink) 18%,transparent)}
/* ── The 834px anomaly [palette-swatch-actions-tablet] ──
   Two rules that are each correct on their own compose into a third layout
   nobody designed. Above 768px a column is VERTICAL and the tool stack runs
   down it; `@media(hover:hover)` hides that stack at rest. An iPad in landscape
   is 834px wide AND reports hover:none, so it takes the desktop vertical stack
   and the permanent visibility together: seven unlabelled 32px icons stacked
   over roughly 450px of swatch, times five columns — 35 icon buttons sitting on
   top of the colours the page exists to show. Neither of the other two widths
   does this. 1280 hides them until hover, so the palette is the whole screen;
   390 lays them out as a short horizontal row under the name and hex.

   Persistent controls on touch are the right call (founder direction
   2026-09-02) and are not in question — the defect is that the touch treatment
   was never DESIGNED, it is the desktop treatment with the hover guard removed.

   Mobbin, platform web, is unanimous that seven persistent unlabelled per-object
   icons is not a shape anyone ships. Magnific
   (mobbin.com/screens/130b455d-80b8-4971-8cb9-75cf5039d82d) is the closest
   match and the model here: a short horizontal action bar UNDER the object,
   with the long tail behind one "..." that opens a LABELLED menu. Google Drive
   (mobbin.com/screens/f20af80a-306c-498e-af04-6c73c1acd19e) makes the same
   split — a few inline icons for the selection, one overflow for the rest — and
   Cosmos (mobbin.com/screens/13584351-6cb4-47ef-ac9c-02a717c4056e) puts a
   single "..." on the object itself. The note's own references (VEED, Jitter,
   Adobe Express, Slite) reach the same two shapes.

   So: keep the two actions used constantly — Lock and Copy — inline, move the
   rest behind one control, and put the row at the BOTTOM under the name and
   hex, which is where 390 already puts it. The top of the swatch goes back to
   being colour. Three targets replace seven, and the five that leave are not
   lost: `.plb-tool--more` opens `.plb-ctx`, the labelled "Colour actions" menu
   that already existed for right-click, so the touch path gains no second
   surface to keep in sync — and every entry there has a WORD next to its icon,
   which is the actual complaint answered.

   `order:2` with the auto margin cleared is what moves the row: `.plb-col` is
   `justify-content:flex-end`, so once the stack stops eating the free space
   below it, it falls to the bottom of the column with everything else and
   `order` puts it last. Scoped on the CAPABILITY, not a width — the same
   lesson as the base `.plb-tool` rule above, which was born as a
   `max-width:768px` correction that stopped being true at exactly 769px. */
.plb-tool--more{display:none}
@media(min-width:769px) and (hover:none){
  .plb-col-tools{order:2;margin-bottom:0;margin-top:12px;flex-direction:row;flex-wrap:nowrap;justify-content:center;gap:2px}
  .plb-col-tools>*{display:none}
  .plb-col-tools>.plb-tool--key,.plb-col-tools>.plb-tool--more{display:flex}
}
/* The ramp is ONE button (N8, responsive-audit-2026-08). It was five, and the
   five were identical — same label, same handler — so a 14px-wide target that
   also failed 2.5.8's spacing exception (14 + 4 gap = 18px between centres,
   against the 24px the exception needs) was being offered five times over.
   The button is 86x34; the bars inside it are decorative. */
.plb-ramp{display:flex;gap:4px;margin-bottom:10px;padding:0;border:none;background:none;cursor:pointer}
.plb-ramp-bar{width:14px;height:34px;background:var(--plb-rc);border:none;border-radius:4px;transition:transform var(--t)}
.plb-ramp:hover .plb-ramp-bar{transform:translateY(-2px)}
.plb-hex{font-family:var(--mono);font-size:15px;font-weight:700;letter-spacing:.01em;text-transform:uppercase;color:inherit;background:none;border:none;border-radius:6px;padding:3px 8px;cursor:pointer;transition:background var(--t)}
.plb-hex:hover{background:color-mix(in srgb,var(--plb-ink) 12%,transparent)}
/* The column title names the COLOUR (utils/paletteNames.js, deterministic per
   hex); .plb-role under it names the SLOT. Both inherit the column ink. */
.plb-name{max-width:100%;margin-bottom:3px;padding:0 8px;font-size:13.5px;font-weight:600;letter-spacing:-.01em;line-height:1.25;text-align:center;text-wrap:balance;opacity:.95}
.plb-role{font-size:10px;font-weight:700;letter-spacing:.14em;opacity:.6}
.plb-badge{margin-top:4px;padding:3px 9px;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:.04em;border-radius:999px;background:color-mix(in srgb,var(--plb-ink) 12%,transparent)}
.plb-badge--low{outline:1px dashed color-mix(in srgb,var(--plb-ink) 55%,transparent)}
.plb-badges{display:flex;gap:5px;margin-top:4px;flex-wrap:wrap;justify-content:center}
.plb-badges .plb-badge{margin-top:0;display:inline-flex;align-items:center}
.plb-badge-ink{display:inline-block;width:8px;height:8px;border-radius:999px;margin-right:5px;border:1px solid color-mix(in srgb,var(--plb-ink) 30%,transparent)}
.plb-badge-ink--w{background:#fff}
.plb-badge-ink--b{background:#000}

/* Board interactions: insert-grow animation, drag-reorder states, gap inserts */
@keyframes plb-in{from{flex-grow:.02;opacity:.2}to{flex-grow:1;opacity:1}}
.plb-col--in{animation:plb-in var(--dur-4) var(--ease-entrance)}
/* Slide-close: the mirror of plb-in. The removed column collapses shut before
   it leaves the array (removeCol splices it out once this finishes). */
@keyframes plb-out{from{flex-grow:1;opacity:1}to{flex-grow:.02;opacity:.2}}
.plb-col--out{animation:plb-out var(--dur-3) var(--ease-exit) forwards;pointer-events:none;overflow:hidden}
html[data-reduced-motion="true"] .plb-col--in,html[data-reduced-motion="true"] .plb-col--out{animation:none}
@media(prefers-reduced-motion:reduce){html:not([data-reduced-motion="false"]) .plb-col--in,html:not([data-reduced-motion="false"]) .plb-col--out{animation:none}}
.plb-col--over{box-shadow:inset 0 0 0 3px color-mix(in srgb,var(--plb-ink) 55%,transparent)}
.plb-tool--grip{cursor:grab}
/* Whole-swatch drag: the column background reads as grabbable; interactive
   children (buttons, ramp, hex) keep their own pointer cursor. */
.plb-col[draggable="true"]{cursor:grab}
.plb-col[draggable="true"]:active{cursor:grabbing}
/* Insert-between-swatches, on the seam. Same inversion as .plb-tool above, plus
   a size change, because this one had two faults and painting it only fixes one.
   Its resting form on a pointer device is the full column height (measured
   28x990 at 834x1194) — a generous hover target that costs nothing, since
   hovering the seam is what reveals the dot. With no hover it can never reveal
   itself, so all that full-height strip does is sit invisibly over every column
   edge and swallow taps meant for the swatch. So on touch it paints its dot AND
   contracts to the dot: 28x44, still clear of the 24px floor in WCAG 2.5.8. */
.plb-gap{position:absolute;top:50%;right:-14px;height:44px;transform:translateY(-50%);width:28px;display:flex;align-items:center;justify-content:center;background:none;border:none;cursor:pointer;z-index:5;transition:opacity var(--t)}
@media(hover:hover){
  .plb-gap{top:0;bottom:0;height:auto;transform:none;opacity:0}
  .plb-gap:hover,.plb-gap:focus-visible{opacity:1}
}
.plb-gap-dot{display:flex;align-items:center;justify-content:center;width:26px;height:26px;color:var(--t0);background:var(--card);border:1px solid var(--border);border-radius:999px;box-shadow:var(--shadow-xs)}

/* Shared popover shell — columns paint color:var(--plb-ink), so reset to tokens */
.plb-pop{color:var(--t0);background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--warm-shadow-lg);text-align:left;cursor:default}
.plb-pop-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px}
.plb-pop-title{font-size:12px;font-weight:700;color:var(--t0)}
.plb-pop-x{display:flex;align-items:center;justify-content:center;width:26px;height:26px;flex-shrink:0;color:var(--t1);background:none;border:none;border-radius:7px;cursor:pointer;transition:all var(--t)}
.plb-pop-x:hover{color:var(--t0);background:var(--bg-2)}

/* Tints panel + per-column HCT picker (anchored inside the column) */
.plb-tintpop,.plb-picker{position:absolute;bottom:96px;left:50%;transform:translateX(-50%);z-index:45;width:206px;padding:10px}
.plb-picker{width:248px}
.plb-tint-list{display:flex;flex-direction:column;gap:2px;max-height:min(46vh,330px);overflow-y:auto;overscroll-behavior:contain}
.plb-tint-row{display:flex;align-items:center;gap:8px;width:100%;padding:5px 6px;background:none;border:none;border-radius:7px;cursor:pointer;transition:background var(--t)}
.plb-tint-row:hover{background:var(--bg-2)}
.plb-tint-chip{width:24px;height:16px;flex-shrink:0;background:var(--plb-rc);border:1px solid var(--border);border-radius:4px}
.plb-tint-tone{width:30px;flex-shrink:0;font-size:10px;font-weight:700;letter-spacing:.04em;color:var(--t2)}
.plb-tint-hex{font-family:var(--mono);font-size:11.5px;font-weight:600;text-transform:uppercase;color:var(--t0)}
.plb-tintopen{width:100%;justify-content:center;margin-top:8px}
.plb-picker-row{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.plb-picker-row .snapv{flex:1;min-width:0}
.plb-picker-label{width:50px;flex-shrink:0;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t2)}
.plb-picker-hexrow{display:flex;align-items:center;gap:8px;margin-top:8px}
.plb-picker-chip{width:28px;height:28px;flex-shrink:0;background:var(--plb-rc);border:1px solid var(--border);border-radius:8px}
.plb-picker-hex{flex:1;min-width:0;padding:7px 9px;font-family:var(--mono);font-size:12px;text-transform:uppercase;color:var(--t0);background:var(--inp);border:1px solid var(--border);border-radius:var(--radius-s)}
.plb-picker-hex:focus{outline:none;border-color:var(--brand)}
.plb-picker-evidence{display:grid;gap:2px;margin:8px 0 2px;font-size:9px;line-height:1.4;color:var(--t2)}
.plb-picker-evidence strong{font-weight:650;color:#8B5C08}
.plb-help{position:relative;display:inline-flex;margin-left:auto}
.plb-help-btn{display:grid;place-items:center;width:24px;height:24px;padding:0;font-family:var(--mono);font-size:11px;font-weight:750;color:var(--t2);background:var(--bg-2);border:1px solid var(--border);border-radius:50%;cursor:help}
.plb-help-tip{position:absolute;right:-34px;bottom:calc(100% + 8px);z-index:3;width:218px;padding:9px 10px;font-size:11px;font-weight:500;line-height:1.45;color:var(--t1);background:var(--card);border:1px solid var(--border);border-radius:var(--radius-s);box-shadow:var(--shadow-s);opacity:0;transform:translateY(4px);pointer-events:none;transition:opacity var(--dur-1) var(--ease-standard),transform var(--dur-2) var(--ease-entrance)}
.plb-help:hover .plb-help-tip,.plb-help:focus-within .plb-help-tip{opacity:1;transform:none}
.plb-swappop{position:absolute;top:58px;left:50%;z-index:46;display:flex;gap:4px;width:max-content;padding:5px;transform:translateX(-50%)}
.plb-swapdir{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:32px;padding:6px 9px;font-size:11px;font-weight:650;color:var(--t1);background:transparent;border:0;border-radius:var(--radius-xs);cursor:pointer;white-space:nowrap}
.plb-swapdir:hover,.plb-swapdir:focus-visible{color:var(--t0);background:var(--bg-2)}

/* Custom right-click menu (fixed, viewport-clamped via --plb-mx/--plb-my) */
.plb-ctx{position:fixed;left:var(--plb-mx);top:var(--plb-my);z-index:80;min-width:192px;padding:6px}
.plb-ctx-item{display:flex;align-items:center;gap:9px;width:100%;padding:7px 9px;font-size:12.5px;font-weight:600;color:var(--t1);text-align:left;background:none;border:none;border-radius:8px;cursor:pointer;transition:all var(--t);white-space:nowrap}
.plb-ctx-item:hover{background:var(--bg-2);color:var(--t0)}
.plb-ctx-item svg{flex-shrink:0;opacity:.8}
.plb-ctx-item--danger{color:#D64545}
.plb-ctx-item--danger:hover{background:color-mix(in srgb,#D64545 10%,transparent);color:#D64545}
.plb-ctx-sep{height:1px;margin:5px 4px;background:var(--border)}
.plb-ctx-item--muted{color:var(--t3);cursor:default}
.plb-ctx-item--muted:hover{background:none;color:var(--t3)}
.plb-ctx-pro{margin-left:auto;padding:1px 6px;font-size:9px;font-weight:800;letter-spacing:.04em;color:var(--accent-strong);border:1px solid var(--brand);border-radius:var(--radius-pill)}

/* Preview modal + mini UI scene painted from --pv-* role props */
.plb-modal{position:fixed;inset:0;z-index:90;display:flex;align-items:center;justify-content:center;padding:clamp(12px,3vw,32px);background:var(--scrim);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
.plb-modal-card{width:min(960px,100%);max-height:100%;overflow-y:auto;display:flex;flex-direction:column;gap:14px;padding:clamp(14px,2.5vw,22px);background:var(--card);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--warm-shadow-lg)}
.plb-modal-card--previews{width:min(1180px,100%)}
.plb-modal-head{display:flex;align-items:center;gap:12px}
.plb-modal-head .plb-pop-title{font-size:14px;margin-right:auto}
.plb-modal-modes{display:flex;gap:2px;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.plb-mode{padding:5px 13px;font-size:12px;font-weight:600;color:var(--t1);background:none;border:none;border-radius:6px;cursor:pointer;transition:all var(--t)}
.plb-mode:hover{color:var(--t0)}
.plb-mode--on{background:var(--card);color:var(--t0);box-shadow:var(--shadow-xs)}
.plb-modal-body{display:grid;grid-template-columns:1fr;gap:14px}
.plb-modal-body--split{grid-template-columns:1fr 1fr}
.plb-modal-actions{display:flex;justify-content:flex-end}
.plb-preview-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.plb-preview-item{position:relative;min-width:0;padding:12px;background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius)}
.plb-preview-label{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px}
.plb-preview-label strong{font-size:12px;font-weight:700;color:var(--t0)}
.plb-preview-label span{display:inline-flex;align-items:center;gap:4px;font-size:9px;font-weight:750;letter-spacing:.05em;text-transform:uppercase;color:var(--accent-strong)}
.plb-preview-grid .plb-pv{min-height:260px}
.plb-preview-item--locked .plb-pv{opacity:.62}
.plb-preview-gate{position:absolute;right:22px;bottom:22px;z-index:2;display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:6px 10px;font-size:10px;font-weight:700;color:var(--t0);background:var(--card);border:1px solid var(--border);border-radius:var(--radius-s);box-shadow:var(--shadow-s);cursor:pointer}
.plb-preview-gate:hover{color:var(--accent-strong);border-color:var(--brand)}
.plb-pv--v1 .plb-pv-side{order:2;border-right:0;border-left:1px solid var(--pv-border)}
.plb-pv--v2 .plb-pv-cards{grid-template-columns:1fr 1fr}
.plb-pv--v2 .plb-pv-card:last-child{grid-column:1/-1}
.plb-pv--v3 .plb-pv-bars{order:-1;margin-top:0}
.plb-pv--v4 .plb-pv-side{width:78px}
.plb-pv--v4 .plb-pv-main{padding:22px}
.plb-pv--v5 .plb-pv-cards{grid-template-columns:1fr}
.plb-pv--brand.plb-pv--v1 .plb-pvb-hero,.plb-pv--brand.plb-pv--v4 .plb-pvb-hero{align-items:flex-start;text-align:left}
.plb-pv--brand.plb-pv--v2 .plb-pvb-nav{background:var(--pv-primary)}
.plb-pv--brand.plb-pv--v3 .plb-pvb-hero{justify-content:flex-end}
.plb-pv--brand.plb-pv--v5 .plb-pvb-head{font-size:36px}
.plb-pv--graphic.plb-pv--v1 .plb-pvg-circle{right:auto;left:-24px}
.plb-pv--graphic.plb-pv--v2 .plb-pvg-square{right:auto;left:44px;bottom:42px;transform:rotate(45deg)}
.plb-pv--graphic.plb-pv--v3 .plb-pvg-body{text-align:right}
.plb-pv--graphic.plb-pv--v4 .plb-pvg-tri{left:auto;right:32px}
.plb-pv--graphic.plb-pv--v5 .plb-pvg-title{font-size:54px}

/* Authored Palette preview structures. Names and content now match what is
   actually rendered: checkout totals, settings fields, inbox threads, finance
   transactions, editorial lists and packaging provenance are real elements. */
.plb-pv-authored{width:100%;min-height:258px;color:var(--pv-text);background:var(--pv-canvas)}
.plb-pv-authored small{font-size:8px;letter-spacing:.07em;text-transform:uppercase;color:var(--pv-muted)}
.plb-pv-authored p{font-size:9px;line-height:1.4;color:var(--pv-muted)}
.plb-pv-authored .plb-pv-cta{display:inline-flex;align-items:center;justify-content:center;min-height:28px;padding:0 10px}
.plb-pv-checkout{display:grid;grid-template-columns:1.1fr .9fr}
.plb-pv-checkout main,.plb-pv-checkout aside{padding:20px}
.plb-pv-checkout main{display:grid;align-content:start;gap:10px}
.plb-pv-checkout aside{background:var(--pv-surface);border-left:1px solid var(--pv-border)}
.plb-pv-field{display:flex;justify-content:space-between;padding:9px;font-size:8px;color:var(--pv-muted);background:var(--pv-surface);border:1px solid var(--pv-border);border-radius:5px}
.plb-pv-field b{color:var(--pv-text)}
.plb-pv-checkout aside>p{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--pv-border)}
.plb-pv-checkout dl{display:flex;justify-content:space-between;padding:10px 0;font-size:11px;font-weight:750}
.plb-pv-checkout .plb-pv-cta{width:100%}
.plb-pv-workspace{padding:18px}
.plb-pv-workspace header,.plb-pv-finance header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
.plb-pv-board-cols{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:16px}
.plb-pv-board-cols section{padding:8px;background:var(--pv-surface);border:1px solid var(--pv-border);border-radius:5px}
.plb-pv-board-cols strong{font-size:8px}
.plb-pv-board-cols p{padding:8px 6px;margin-top:6px;color:var(--pv-text);background:var(--pv-raised);border:1px solid var(--pv-border);border-radius:4px}
.plb-pv-settings{display:grid;grid-template-columns:120px 1fr}
.plb-pv-settings nav{display:flex;flex-direction:column;gap:7px;padding:18px;background:var(--pv-surface);border-right:1px solid var(--pv-border);font-size:8px}
.plb-pv-settings nav strong{margin-bottom:10px}
.plb-pv-settings nav span{padding:7px;color:var(--pv-muted)}
.plb-pv-settings nav .is-active{color:var(--pv-primary);background:var(--pv-raised)}
.plb-pv-settings form{display:grid;align-content:start;gap:8px;padding:18px}
.plb-pv-settings label{display:flex;justify-content:space-between;padding:8px;font-size:8px;background:var(--pv-surface);border:1px solid var(--pv-border);border-radius:4px}
.plb-pv-settings label i{font-style:normal;color:var(--pv-muted)}
.plb-pv-toggle b{width:22px;height:12px;background:var(--pv-primary);border-radius:99px}
.plb-pv-settings .plb-pv-cta{justify-self:end}
.plb-pv-inbox{display:grid;grid-template-columns:185px 1fr}
.plb-pv-inbox>aside{padding:12px;background:var(--pv-surface);border-right:1px solid var(--pv-border)}
.plb-pv-inbox>aside>strong{display:flex;justify-content:space-between;font-size:10px}
.plb-pv-inbox>aside>p{display:grid;gap:3px;padding:10px 7px;margin-top:4px;color:var(--pv-text);border-bottom:1px solid var(--pv-border)}
.plb-pv-inbox>aside>p small{font-size:7px}
.plb-pv-inbox>aside>p.is-active{background:var(--pv-raised);border-left:3px solid var(--pv-primary)}
.plb-pv-inbox>main{padding:18px}
.plb-pv-message{max-width:250px;padding:12px;margin-top:16px;color:var(--pv-text)!important;background:var(--pv-surface);border:1px solid var(--pv-border);border-radius:5px}
.plb-pv-reply{display:flex;justify-content:space-between;padding:10px;margin-top:16px;font-size:8px;color:var(--pv-muted);border:1px solid var(--pv-border);border-radius:5px}
.plb-pv-reply span{font-weight:750;color:var(--pv-primary)}
.plb-pv-finance{display:grid;grid-template-columns:1fr .75fr;gap:12px;padding:18px}
.plb-pv-finance header{grid-column:1/-1}
.plb-pv-finance-chart{display:flex;align-items:flex-end;gap:5px;height:116px;padding:12px;background:var(--pv-surface);border:1px solid var(--pv-border)}
.plb-pv-finance-chart i{flex:1;height:45%;background:var(--plb-rc);border-radius:3px 3px 0 0}
.plb-pv-finance-chart i:nth-child(2n){height:70%}.plb-pv-finance-chart i:nth-child(3n){height:92%}
.plb-pv-finance section{padding:11px;background:var(--pv-surface);border:1px solid var(--pv-border)}
.plb-pv-finance section>strong{font-size:9px}
.plb-pv-finance section p{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--pv-border)}
.plb-pv-finance section b{color:var(--pv-text)}

.plb-pvb-architecture header,.plb-pvb-portfolio header,.plb-pvb-conference header,.plb-pvb-journal header,.plb-pvb-hospitality header{display:flex;justify-content:space-between;padding:14px 18px;font-size:8px;border-bottom:1px solid var(--pv-border)}
.plb-pvb-architecture main{display:grid;grid-template-columns:1fr .9fr;gap:18px;padding:24px}
.plb-pvb-architecture .plb-pvb-head{font-size:32px}
.plb-pvb-architecture figure i{display:block;height:130px;background:var(--plb-rc)}
.plb-pvb-architecture figcaption{padding-top:5px;font-size:7px;color:var(--pv-muted)}
.plb-pvb-portfolio>div{display:grid;grid-template-columns:1fr 1fr;padding:22px}
.plb-pvb-portfolio .plb-pvb-head{font-size:28px}
.plb-pvb-portfolio ol{list-style:none}
.plb-pvb-portfolio li{display:grid;grid-template-columns:24px 1fr auto;padding:11px 0;font-size:9px;border-bottom:1px solid var(--pv-border)}
.plb-pvb-portfolio li small{color:var(--pv-muted)}
.plb-pvb-conference main{padding:20px}
.plb-pvb-conference .plb-pvb-head{font-size:38px}
.plb-pvb-schedule{display:flex;gap:8px;margin:14px 0}
.plb-pvb-schedule span{display:grid;gap:3px;padding:8px;font-size:8px;background:var(--pv-surface);border:1px solid var(--pv-border)}
.plb-pvb-journal main{display:grid;grid-template-columns:1.25fr .75fr;gap:18px;padding:22px}
.plb-pvb-journal .plb-pvb-head{font-size:34px}
.plb-pvb-journal aside{padding-left:16px;border-left:1px solid var(--pv-border);font-size:9px}
.plb-pvb-journal aside p{padding:9px 0;border-bottom:1px solid var(--pv-border)}
.plb-pvb-hospitality main{display:grid;align-content:end;min-height:210px;padding:22px;background:linear-gradient(110deg,var(--pv-canvas),color-mix(in srgb,var(--pv-primary) 22%,var(--pv-canvas)))}
