.plb-galpopup{width:min(620px,calc(100vw - 32px));max-height:min(78vh,640px);padding:0;overflow:hidden;display:flex;flex-direction:column}
.plb-galpopup-head{flex:0 0 auto;display:flex;align-items:center;gap:10px 14px;flex-wrap:wrap;padding:14px 16px 12px;border-bottom:1px solid var(--border)}
