/* Preview-context tabs in the modal head (UI / Brand / Graphic Design) */
.plb-modal-tabs{display:flex;gap:2px;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.plb-modal-tab{padding:5px 12px;font-size:12px;font-weight:600;color:var(--t1);background:none;border:none;border-radius:6px;cursor:pointer;transition:all var(--t);white-space:nowrap}
.plb-modal-tab:hover{color:var(--t0)}
.plb-modal-tab--on{background:var(--card);color:var(--t0);box-shadow:var(--shadow-xs)}
/* ── Split-screen colour-vision check (community import) ── */
.plb-cvd-row{display:flex;flex-direction:column;gap:8px}
.plb-cvd-label{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:700;color:var(--t1)}
.plb-cvd-label>svg{opacity:.7}
.plb-cvd-strip{display:flex;height:72px;border:1px solid var(--border);border-radius:var(--radius-s);overflow:hidden}
.plb-cvd-sw{flex:1;min-width:0;background:var(--plb-rc)}
.plb-cvd-note{margin:2px 0 0;font-size:12px;line-height:1.5;color:var(--t2)}

.plb-add{flex:0 0 92px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--t1);background:var(--card);border:none;border-left:1px dashed var(--border);cursor:pointer;transition:flex-basis var(--dur-3) var(--ease-out),color var(--t),background var(--t)}
.plb-add:hover{flex-basis:116px;color:var(--t0);background:var(--bg-2)}
.plb-add-dot{display:flex;align-items:center;justify-content:center;width:40px;height:40px;color:inherit;background:var(--bg-2);border:1px dashed var(--border);border-radius:999px;transition:all var(--t)}
.plb-add:hover .plb-add-dot{background:var(--card);border-style:solid}
/* ── Global adjust bar ── */
.plb-adjust{position:sticky;bottom:0;z-index:30;display:flex;align-items:center;gap:12px clamp(12px,2.5vw,28px);flex-wrap:wrap;padding:12px var(--page-inline);background:var(--bg-0);border-top:1px solid var(--border)}
/* EQUAL TRACKS (the "tone and temperature sliders are a different size" bug).
   The four fields share ONE grid and each field is display:contents, so the
   grid's real children are label,slider,label,slider… Each label column is
   `auto` (it takes exactly its own text — "Hue" stays narrow, "Temperature"
   stays wide) and each slider column is `minmax(0,1fr)`. Free space is split
   equally between the fr columns, so every TRACK is the same length however
   long its label is. The old layout gave each field an equal FLEX width and
   let the label eat into it from the inside, which is why a 24px label left a
   205px track and an 86px label left a 143px one.
   minmax(0,…) not 1fr: a bare 1fr floors at the content's min-width, which
   would let one field's readout make its column wider than its siblings. */
.plb-adjust-fields{flex:1 1 auto;min-width:0;display:grid;grid-template-columns:repeat(4,auto minmax(0,1fr));align-items:center;gap:12px 10px}
.plb-adjust-field{display:contents}
.plb-adjust-field .snapv{min-width:0}
.plb-adjust-label{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--t2);white-space:nowrap}
/* The label↔track gap is the grid gap; the wider gap BETWEEN pairs is this
   margin, which lands inside the (auto) label column and so never eats into a
   track. Only fields that are not first in their ROW get it, hence the
   per-breakpoint reset — the row length changes with the column count. */
.plb-adjust-field--edited .plb-adjust-label{color:var(--t0);text-shadow:.35px 0 currentColor,-.35px 0 currentColor}
.plb-adjust-field:not(:first-child) .plb-adjust-label{margin-left:clamp(8px,1.6vw,20px)}
/* Fixed readout width: "0°" and "-180°" are different widths, and a readout
   that grows would shorten its own track. Fixing it keeps all four equal at
   every value, not just at rest. */
.plb-adjust .snapv-value,.plb-adjust .snapv-input{flex:0 0 56px;width:56px;min-width:0}
/* Two pairs per row, then one, so the tracks never squeeze to a stub. Tracks
   stay equal across rows — every fr column in the grid gets the same width. */
@media(max-width:1180px){
  .plb-adjust-fields{grid-template-columns:repeat(2,auto minmax(0,1fr))}
  .plb-adjust-field:not(:first-child) .plb-adjust-label{margin-left:0}
  .plb-adjust-field:nth-child(even) .plb-adjust-label{margin-left:clamp(8px,1.6vw,20px)}
}
@media(max-width:560px){
  .plb-adjust-fields{grid-template-columns:auto minmax(0,1fr)}
  .plb-adjust-field .plb-adjust-label{margin-left:0}
}
.plb-copycss{margin-left:auto;white-space:nowrap}
.plb-adjust-reset{white-space:nowrap}
/* Visibility preserves the button's exact row width while keeping the clean
   state out of both pointer and keyboard interaction. The slider grid no
   longer changes size during the first drag. */
.plb-adjust-reset--idle{visibility:hidden;pointer-events:none}
/* Mid-band (tablet-ish): here the action group carries its labels pinned open
   (see the ≤960 block below), so it holds a fixed ~1116px of controls that won't
   shrink — wider than the whole viewport. Wrapping it onto a second row therefore
   buys nothing: the second row would overflow on its own. So this band alone opts
   out of the base's wrap and keeps the single row, turning ONLY the action group
   into a horizontally swipeable ribbon — the board layout is left untouched.
   Because a scroll container clips overflow on both axes, its dropdowns must
   escape as fixed bottom sheets (same treatment as ≤768).
   The title group's "never yields" rule used to live here; it is now the base
   rule for every width, which is what closed the 961–1079 overlap. */
/* Above the mid-band the action group must NOT be a scroll container. The
   `.rail-overflow` class is on the element in the markup (it is what gives the
   two bands below their peek fade and their visible scrollbar), so it has to be
   switched off here rather than switched on there: at ≥961px every control fits
   on the row, and a scroll container would clip the absolutely-positioned
   dropdowns that hang off these buttons — the same clipping the two bands below
   escape by turning their dropdowns into fixed bottom sheets. */
@media(min-width:961px){
  .plb-toolbar-group.rail-overflow{overflow:visible;scroll-snap-type:none;animation:none;-webkit-mask-image:none;mask-image:none}
}
@media(min-width:769px) and (max-width:960px){
  .plb-toolbar{flex-wrap:nowrap}
  /* overflow / scrollbar / snap-type now come from `.rail-overflow`.
     `scroll-padding-inline` must match the inline padding: the snapport starts
     at the padding edge but the first child starts one padding inside it, so
     without this the engine closes the 4px gap on load — the ribbon arrived
     already scrolled and the left-edge fade lit up claiming there was something
     behind the first button. */
  .plb-toolbar-group:last-child{flex:0 1 auto;min-width:0;margin:0 -4px;padding:2px 4px;scroll-padding-inline:4px}
  .plb-toolbar-group:last-child>*{flex:0 0 auto;scroll-snap-align:start}
  /* THE MISSED BAND. `.plb-random{order:-1}` already existed for ≤768px and was
     never extended here, so at 834px the ribbon opened on Image / Explore /
     Preview / Vision and put Randomise 560px past the right edge — measured 7 of
     11 controls fully off-screen, Randomise among them. It is the primary action
     of the whole tool and it owns the Space-bar shortcut, so a user who never
     scrolls the ribbon never learns the tool's main gesture exists. Pulling it
     to the front costs nothing: the ribbon scrolls either way, and this decides
     only WHICH control the user is given for free.

     THE PROMOTION ITSELF NOW LIVES IN THE SHARED max-width:960px BLOCK BELOW,
     alongside Undo, Reset and Save / export, which the 2026-09-03 audit found
     hidden at every touch width. It was MOVED rather than duplicated because
     the ≤768 block comes AFTER that shared block: a band-local `order` here
     would still win at 769–960 but be overridden at ≤768, which is the same
     one-band-only split that produced "THE MISSED BAND" in the first place. */
}
/* Shared bottom-sheet treatment for every width where the action group scrolls
   internally (mid-band 769–960 AND the ≤768 stack): a scroll container clips its
   dropdowns on both axes, so each escapes as a fixed bottom sheet. Declared once
   here for both ranges instead of duplicated in each query. */
@media(max-width:960px){
  .plb-menu{position:fixed;left:0;right:0;bottom:0;top:auto;width:auto;min-width:0;max-width:none;max-height:min(76dvh,560px);overflow-y:auto;overscroll-behavior:contain;padding:14px 16px calc(16px + env(safe-area-inset-bottom));border-radius:16px 16px 0 0;box-shadow:0 -8px 40px rgba(0,0,0,.28);z-index:70;animation:plb-sheet-up var(--dur-2) var(--ease-entrance)}
  .plb-menu::before{content:'';display:block;width:36px;height:4px;margin:0 auto 12px;border-radius:999px;background:var(--border)}
  .plb-scrolllist{max-height:min(52dvh,420px)}
  .plb-galpopup{padding:0;overflow:hidden;display:flex;flex-direction:column;max-height:min(82dvh,640px)}
  .plb-galpopup::before{margin:10px auto 2px}
  .plb-galpopup-head{padding:8px 16px 12px}
  .plb-galpopup-body .pgal-grid{grid-template-columns:1fr}
  /* …and for the same reason the labels stop being a HOVER reveal here and
     stay open. Three things converge below 961px: the group is a horizontal
     scroller, so a reveal that widens its own button fights the scroll
     position under the pointer; these widths are where touch is likely, and
     touch has no hover at all; and the reveal is driven by interpolating an
     `fr` track, which needs free space the shrink-to-fit chain inside a
     scroll container does not reliably provide — measured: at 900px the track
     stayed at 0px for the whole transition even though :hover matched and the
     final value was correct. Pinning them open removes all three at once, and
     it is what ≤768px already did. */
  /* `flex:0 0 auto` on the button itself, not only on the group's direct
     children: four of these buttons sit inside a .plb-menuwrap, so the group's
     `> *` rule never reached them, and a button that may shrink inside an
     overflowing scroller is squeezed to its min-width with the label spilling
     out of it. The group scrolls instead, which is what it is there for. */
  .plb-icobtn{flex:0 0 auto;min-width:0;padding-inline:12px;gap:7px}
  /* The collapsible grid is taken out of the box tree entirely rather than
     pinned to `1fr`. Nothing animates at these widths, so the track buys
     nothing — and an fr track has to be resolved out of free space that this
     shrink-to-fit chain inside a scroll container does not reliably have:
     measured, it settled at 5px for four of the eight buttons at 960px, and
     `max-content` left the button's own intrinsic width stale across a resize
     so the text spilled past its right edge. With `display:contents` the label
     text is simply another flex item of the button, sized by the same rules as
     the icon beside it, and the button's `gap` provides the spacing the grid's
     padding used to. */
  .plb-icobtn .plb-lbl{display:contents}
  .plb-icobtn .plb-lbl-i{overflow:visible;min-width:max-content}

  /* WHICH FOUR CONTROLS THE USER IS GIVEN FOR FREE.
     #318 established the mechanism here with `.plb-random{order:-1}`, and
     stated the principle: the ribbon scrolls either way, so `order` does not
     decide WHETHER a control is reachable, only which ones need no gesture.
     This extends that one promotion to the set the 2026-09-03 audit measured
     as missing, and it is the audit's own second-choice fix made cheap.

     MEASURED BEFORE, real device metrics, of eleven children:
       390px   4 full, 1 part-cut, 6 hidden (669px of scroll)
       640px   6 full, 1 part-cut, 4 hidden (419px)
       641px   6 full, 1 part-cut, 4 hidden (418px)
       834px   3 full, 1 part-cut, 7 hidden (691px)
     Save / export was hidden at ALL FOUR, and Undo and Reset with it. So the
     control that ends the journey — the only route from a finished palette to
     a file — was off-screen on every phone and every tablet, and a mis-tap
     could not be undone without first discovering that the row scrolls.
     Losing Undo and Reset is the worse half: an export button you cannot find
     is a dead end, but a Reset you cannot find is a palette you cannot get
     back.

     THE ORDER IS DOM ORDER WITHIN THE PROMOTED SET (Undo → Reset → Save), not
     an arbitrary shuffle. `order` moves the box without moving the tab stop,
     so every promotion is a WCAG 2.4.3 cost; keeping the promoted four in
     their own DOM sequence means there is exactly ONE jump boundary — the same
     shape #318 already accepted for Randomise — instead of a new kind of
     mismatch. #298 rejected reordering outright on `.lbry-toolbar`; the
     difference here is that this rail is a scroller by design (pinned by
     tests/user-sim/36-rail-overflow.spec.js and 23-responsive-mid-band.spec.js),
     so SOMETHING is always off-screen and the only question is what.

     UNDO AND RESET GO ICON-ONLY, which is what buys the room: labelled they
     are 73px and 76px, icon-only they are 42px, and that 65px is the
     difference between Save / export being fully visible at 390px and being
     cut. They keep their `aria-label` and their `title`, so the accessible
     name is unchanged — this trades a visible word for a visible BUTTON, and
     an icon you can see beats a label you cannot. Randomise keeps its label
     because it is the primary action, and Save / export keeps its because it
     is the one the audit found missing. */
  .plb-random{order:-4}
  .plb-undo{order:-3}
  .plb-reset{order:-2}
  .plb-savewrap{order:-1}
  .plb-undo .plb-lbl,.plb-reset .plb-lbl{display:none}
  /* The separator sat between History and Save / export. With Save / export
     promoted to the front it divides nothing, so it goes in both bands rather
     than trailing the rail as a stray rule. ≤768 already hid it. */
  .plb-toolbar-sep{display:none}
}
@media(max-width:768px){
  /* Toolbar stacks: an identity row (seed/hex/system) above a horizontally
     swipeable tool ribbon, so all 11 v3 controls stay one tap away instead
     of piling into a tall wrap. */
  .plb-toolbar{position:static;flex-direction:column;align-items:stretch;justify-content:flex-start;gap:10px;padding:10px 12px}
  .plb-toolbar-group{width:100%}
  .plb-toolbar-group:first-child{flex-wrap:wrap;gap:8px}
  .plb-toolbar-group:first-child .plb-menuwrap{flex:1 1 auto}
  .plb-toolbar-group:first-child .plb-harm{width:100%;justify-content:flex-start}
  .plb-hexfield{flex:1 1 90px}
  /* overflow / scrollbar / snap-type now come from `.rail-overflow`.
     `scroll-padding-inline` matches the padding — see the mid-band note. */
  .plb-toolbar-group:last-child{flex-wrap:nowrap;gap:6px;margin:0 -12px;padding:2px 12px;scroll-padding-inline:12px}
  .plb-toolbar-group:last-child>*{flex:0 0 auto;scroll-snap-align:start}
  /* `.plb-random{order:-1}` and `.plb-toolbar-sep{display:none}` moved to the
     shared max-width:960px block above, which covers this band and the
     mid-band together. See the note there for the promoted set. */
  .plb-kbd{display:none}
  /* The bottom-sheet dropdown treatment (.plb-menu / .plb-scrolllist /
     .plb-galpopup*) is shared with the mid-band in the @media(max-width:960px)
     block above — only the ≤768-unique rules live here. */
  /* Labels are already pinned open by the max-width:960px block above. */
  .plb-board{flex-direction:column;min-height:0}
  .plb-col{flex-direction:row;align-items:center;justify-content:flex-start;gap:10px;min-height:64px;padding:10px 16px}
  .plb-col-tools{position:static;transform:none;flex-direction:row;order:2;margin-left:auto;margin-bottom:0}
  /* Redundant on touch now that the base rule is visible-at-rest, but still
     doing work for a HOVER device at this width — a narrowed desktop window, or
     a small laptop — where @media(hover:hover) still hides them and this
     stacked row has no room for a reveal-on-hover affordance. */
  .plb-tool{opacity:1}
  .plb-ramp{display:none}
  .plb-hex{font-size:13px;padding:2px 6px}
  /* The row is 64px tall, so the colour title stays (it is the thing the
     founder asked for) and only the slot eyebrow drops. */
  /* N3 (responsive-audit-2026-08): the swatch name was crushed by the tool row
     beside it. The audit records it at 480px only and calls it cosmetic; it is
     the 431–499px band, and it is not one width — the names are generated per
     load, so which of the five clip changes run to run. Measured: 5 of 5 cut at
     440px ("Antique Bathhouse", 108px into 60px), 4 of 5 at 450, 1–2 of 5 at
     460–480, clean from 500.

     Below 431px the reflow block already wraps the tools onto their own line,
     which is why 430px was clean and 440px was not — the fix simply stopped one
     pixel too early. Rather than extend that band to another hand-picked width,
     the row wraps whenever it has to: `min-width` on the name gives it a floor
     to defend, and `flex-wrap` lets the tool row drop instead of the name
     shrinking. Where there is room nothing moves.

     This is free. Row and board heights are byte-identical before and after at
     every width from 430 to 768 (97/97, 96/96, 100/100, 111/111) — the board's
     flex layout was already that tall, and the tools were simply refusing to
     use the second line. */
  .plb-col{flex-wrap:wrap;row-gap:8px}
  .plb-name{margin-bottom:0;padding:0;min-width:12ch;font-size:12px;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .plb-role{display:none}
  .plb-badge{margin-top:0}
  .plb-gap{display:none}
  .plb-adjust{position:static}
  .plb-add{flex-direction:row;flex-basis:52px;border-left:none;border-top:1px dashed var(--border)}
  .plb-add:hover{flex-basis:52px}
  .plb-modal-body--split{grid-template-columns:1fr}
  .plb-preview-grid{grid-template-columns:1fr}
  .plb-modal-head{flex-wrap:wrap}
  .plb-modal-head .plb-pop-title{flex:1 1 auto}
  .plb-modal-tabs{order:3;flex:1 1 100%;justify-content:center}
  .plb-modal-tab{flex:1;text-align:center}
  .plb-pvb-head{font-size:24px}
  .plb-pvg-title{font-size:36px}
  .plb-tintpop,.plb-picker{left:12px;right:12px;width:auto;transform:none;bottom:auto;top:calc(100% + 4px);z-index:46}
  .plb-swappop{top:calc(100% + 4px)}
  .plb-copycss{margin-left:0;width:100%}
}
/* Reduced motion: drop the action ribbon's scroll snapping. One unscoped pair
   covers BOTH scrolling bands (769–960 and ≤768) — the guard is more specific
   than either `.plb-toolbar-group:last-child` rule, so it wins without being
   nested in, or duplicated across, their media queries.

   `proximity` is gentler than `mandatory`, not exempt from the contract. The
   global clamp at the top of this file zeroes durations and forces
   `scroll-behavior:auto`, but it does NOT touch `scroll-snap-type` — snapping
   is a scroll displacement the engine applies on its own, after the gesture
   ends, and no duration token is involved. Measured on the built app under
   touch device metrics, scrollLeft set to 42px and read back after settling:
   769–960 lands at 4px (a 38px pull), ≤768 lands at 12px (a 30px pull); with
   snapping off it stays at 42px at both. That displacement is the motion. */
html[data-reduced-motion="true"] .plb-toolbar-group:last-child{scroll-snap-type:none}
@media(prefers-reduced-motion:reduce){
  html:not([data-reduced-motion="false"]) .plb-toolbar-group:last-child{scroll-snap-type:none}
}
@keyframes plb-sheet-up{from{transform:translateY(100%)}to{transform:none}}

/* ============================================================
   Canonical modal system — the ONE popup/upgrade/login shell,
   reused app-wide (Image-2 card, Image-3 Pro modal, single-click
   login). Build once here; every gate/login flow inherits it.
   ============================================================ */
/* Topmost interactive layer — canonical modals (incl. the login prompt) must sit
   above every tool overlay (.icust-overlay/.cp-overlay are 9998), or e.g. the
   "log in to continue" popup opened from the icon customizer stacks underneath. */
.ui-modal-overlay{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;padding:clamp(16px,4vw,40px);background:var(--scrim);backdrop-filter:blur(6px);animation:cp-fade var(--dur-1) var(--ease-entrance)}
/* The max-height cap is correct and stays. What was missing is any sign that
   the dialog scrolls when its content exceeds it (S7, mobile-audit-2026-08).
   At 844x390 the login dialog holds 489px of content in 356px: the submit
   button was sliced in half by the bottom edge, and BOTH the sign-up link and
   "Forgot password?" sat below the fold. No scrollbar renders under touch
   emulation, so a signed-out visitor on a landscape phone had no way to know
   account creation existed — the sliced button read as a rendering fault
   rather than as "there is more below".

   This is the pure-CSS scroll shadow: two `local` gradients scroll with the
   content and mask the cue at each extremity, two `scroll` gradients stay put
   and paint it. So the cue appears only when there IS more, on either edge,
   and it costs no JS and no measurement — which matters because these dialogs
   have variable content (the intent block, the reset state, signup vs signin)
   and any fixed height threshold would be wrong for some of them.
   Applied to .ui-modal, not to the login dialog, so all four modals that use
   this shell get it. */
.ui-modal{position:relative;width:100%;max-width:440px;background:linear-gradient(var(--card) 30%,rgba(0,0,0,0)) top/100% 26px no-repeat local,linear-gradient(rgba(0,0,0,0),var(--card) 70%) bottom/100% 26px no-repeat local,radial-gradient(farthest-side at 50% 0,color-mix(in srgb,var(--t0) 18%,transparent),rgba(0,0,0,0)) top/100% 12px no-repeat scroll,radial-gradient(farthest-side at 50% 100%,color-mix(in srgb,var(--t0) 18%,transparent),rgba(0,0,0,0)) bottom/100% 12px no-repeat scroll,var(--card);border:1px solid var(--border);border-radius:var(--radius-xl);box-shadow:var(--warm-shadow-lg);animation:cp-rise var(--dur-2) var(--ease-entrance);max-height:calc(100dvh - 32px);overflow:hidden auto}
.ui-modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:20px 22px 0}
.ui-modal-x{flex:none;display:grid;place-items:center;width:32px;height:32px;border-radius:var(--radius-pill);border:1px solid transparent;background:transparent;color:var(--t2);cursor:pointer;transition:background var(--t),color var(--t)}
.ui-modal-x:hover{background:var(--hvr);color:var(--t0)}
.ui-modal-body{padding:14px 22px 22px}
.ui-modal-title{font-size:19px;font-weight:640;letter-spacing:-.01em;color:var(--t0);margin:0}
.ui-modal-sub{margin:7px 0 0;font-size:13.5px;line-height:1.5;color:var(--t2)}
.ui-modal-actions{display:flex;flex-direction:column;gap:10px;margin-top:18px}
.ui-modal-actions .btn{width:100%;justify-content:center}
.ui-modal-link{display:inline-flex;align-items:center;justify-content:center;gap:6px;width:100%;padding:8px;background:transparent;border:none;color:var(--t2);font-family:var(--font);font-size:12.5px;font-weight:500;cursor:pointer;text-decoration:none;transition:color var(--t)}
.ui-modal-link:hover{color:var(--t0)}
.ui-modal--wide{max-width:560px}
.ui-form{display:flex;flex-direction:column;gap:14px}
.ui-field{display:flex;flex-direction:column;gap:6px}
.ui-field>span{font-size:11.5px;font-weight:600;color:var(--t1)}
.ui-field input,.ui-field select,.ui-field textarea{width:100%}
.ui-modal-note{margin:0;font-size:11.5px;line-height:1.5;color:var(--t3)}
.ui-modal-err{font-size:12px;font-weight:500;color:var(--err-strong)}
.ui-modal-actions--row{flex-direction:row;justify-content:flex-end}
.ui-modal-actions--row .btn{width:auto}
/* Short viewports, keyed on HEIGHT — which is the whole point. The audit found
   this app repeatedly reaching for a width query to solve a height problem (a
   landscape phone is 844-932px WIDE, so every max-width rule misses it). The
   scroll cue above makes the overflow honest; this reduces how much there is to
   scroll, by spending the vertical rhythm that a 390px-tall viewport cannot
   afford. Measured on /login at 844x390: 133px hidden before, 69px after.
   Nothing is removed — the Google button, the divider and both links all stay,
   because dropping a sign-in method to win back pixels is an auth-flow change,
   not a layout one. 460px covers both landscape phones in the matrix (390 and
   430) and leaves every portrait viewport untouched. */
@media(max-height:460px){
  .ui-modal{max-height:calc(100dvh - 16px)}
  .ui-modal-head{padding:12px 18px 0}
  .ui-modal-body{padding:10px 18px 16px}
  .auth-divider{margin:12px 0}
  .auth-form{gap:12px}
  .auth-links{margin-top:10px}
}

/* --- Pro-upgrade modal: see the "W3 - V2 SHARED UI" block at the end of
       this file. The V1 rules that sat here (a #8B5CF6 -> #EC4899 gradient
       art panel and a five-star "Loved by designers" proof strip) are
       deleted rather than overridden: the gradient was off-brand for the
       blue accent, and the star strip was fabricated social proof. Leaving
       either in the stylesheet keeps it one class name away from coming
       back. --- */

/* --- Single-click login popup (reuses .auth-* form styles) --- */
.ui-login .ui-modal-body{padding-top:8px}
.ui-login-note{display:flex;gap:9px;align-items:flex-start;margin:0 0 16px;padding:11px 13px;background:var(--brand-bg);border:1px solid color-mix(in srgb,var(--brand) 26%,transparent);border-radius:var(--radius);font-size:12.5px;line-height:1.45;color:var(--t1)}
.ui-login-note svg{flex:none;margin-top:1px;color:var(--brand)}
.ui-login-err{margin:0 0 12px;padding:9px 12px;background:color-mix(in srgb,var(--err) 12%,transparent);border:1px solid color-mix(in srgb,var(--err) 34%,transparent);border-radius:var(--radius);font-size:12.5px;color:var(--err-strong)}
.ui-login .auth-links{margin-top:14px}
/* "Why we ask first" — the plain-language account rationale on the community
   submission gate. Token-driven, so it follows light/dark like the note above. */
.ui-login-why{margin:0 0 16px;padding:11px 13px;border:1px solid var(--border);border-radius:var(--radius);background:var(--cbg)}
.ui-login-why-h{margin:0 0 6px;font-size:11.5px;font-weight:700;letter-spacing:.02em;text-transform:uppercase;color:var(--t1)}
.ui-login-why-list{margin:0;padding-left:16px;font-size:12.5px;line-height:1.5;color:var(--t1)}
.ui-login-why-list li+li{margin-top:4px}

/* --- User identity: name + owner crown + flair tag (UserName component) --- */
.uname{display:inline-flex;align-items:center;gap:6px;min-width:0;max-width:100%}
.uname-text{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.uname--bold .uname-text{font-weight:700;letter-spacing:-.01em}
.uname-owner{position:relative;display:inline-flex;align-items:center;gap:4px;min-width:0;border-radius:var(--radius-s);outline:none}
.uname-owner .uname-text{color:#F6C453;text-shadow:0 1px 0 color-mix(in srgb,#6B4A00 45%,transparent)}
[data-theme="light"] .uname-owner .uname-text{color:#8A5A00;text-shadow:none}
.uname-owner:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.uname-crown{font-size:.85em;line-height:1;filter:saturate(1.1)}
/* Owner tooltip — hidden until the name is hovered or keyboard-focused. */
.uname-tip{position:absolute;bottom:calc(100% + 7px);left:0;z-index:60;padding:4px 9px;border-radius:var(--radius-s);background:var(--t0);color:var(--bg-1);font-size:11px;font-weight:600;letter-spacing:.01em;white-space:nowrap;box-shadow:var(--shadow-m);opacity:0;transform:translateY(3px);pointer-events:none;transition:opacity var(--dur-2,.14s) var(--ease-out,ease),transform var(--dur-2,.14s) var(--ease-out,ease)}
.uname-tip::after{content:"";position:absolute;top:100%;left:14px;border:5px solid transparent;border-top-color:var(--t0)}

/* ═════════════════════════════════ UI System Builder ═══════════════════════ */
/* This is a dense operating surface, not a gallery of six cards. The scale
   matrix stays one contiguous comparison object; containment is reserved for
   evidence, component-state and scene boundaries that are real objects. */
.plb-mode-switch{display:flex;align-items:center;gap:7px;flex:0 0 auto;white-space:nowrap}
.plb-mode-switch>span{font-size:12px;color:var(--t3)}
.plb-mode-switch>button{padding:2px 0;font:inherit;font-size:13px;font-weight:650;color:var(--t2);background:none;border:0;cursor:pointer}
.plb-mode-switch>button:hover{color:var(--t0)}
.plb-mode-switch>button>span,.uis-mode-switch button>span,.uis-pro-label{display:inline-flex;align-items:center;margin-left:4px;padding:2px 5px;font-size:8px;font-weight:750;line-height:1;letter-spacing:.08em;text-transform:uppercase;color:var(--accent-strong);background:var(--brand-bg);border-radius:var(--radius-xs)}

.plb--ui-system{background:var(--bg-0)}
.uis{width:100%;min-width:0;padding-bottom:var(--s-8);color:var(--t0);background:var(--bg-0)}
.uis-header{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--s-5);padding:var(--s-6) var(--page-inline) var(--s-5);border-bottom:1px solid var(--border)}
.uis-title-block{max-width:760px}
.uis-mode-switch{display:flex;align-items:center;gap:7px;margin-bottom:var(--s-3);font-size:12px;font-weight:650;color:var(--t2)}
.uis-mode-switch>span{color:var(--t3)}
.uis-mode-switch button{padding:0;font:inherit;color:inherit;background:none;border:0;cursor:pointer}
.uis-mode-switch strong{font:inherit;color:var(--t0)}
.uis-title-block h1{font-size:clamp(26px,3vw,42px);line-height:1.02;letter-spacing:-.035em}
.uis-title-block>p{max-width:68ch;margin-top:var(--s-3);font-size:14px;line-height:1.55;color:var(--t2)}
.uis-back{flex:0 0 auto}

.uis-command{position:sticky;top:calc(var(--nav-top) + var(--nav-h));z-index:28;display:flex;align-items:center;gap:var(--s-4);padding:var(--s-3) var(--page-inline);background:color-mix(in srgb,var(--bg-0) 94%,transparent);border-bottom:1px solid var(--border);backdrop-filter:blur(12px)}
.uis-seed-control{display:flex;align-items:center;gap:var(--s-2);flex:0 0 auto}
.uis-seed-control>label,.uis-neutral-control>span{font-size:10px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--t2)}
.uis-seed-picker{width:36px;height:36px;padding:3px;background:var(--inp);border:1px solid var(--border);border-radius:var(--radius-s);cursor:pointer}
.uis-seed-picker::-webkit-color-swatch-wrapper{padding:0}
.uis-seed-picker::-webkit-color-swatch{border:0;border-radius:var(--radius-xs)}
.uis-seed-hex{width:96px;height:36px;padding:0 10px;font-family:var(--mono);font-size:12px;text-transform:uppercase;color:var(--t0);background:var(--inp);border:1px solid var(--border);border-radius:var(--radius-s)}
.uis-seed-hex--error{border-color:#C43D3D}
.uis-seed-control>span{font-size:10px;color:var(--t3)}
.uis-neutral-control{display:flex;align-items:center;gap:4px;padding-left:var(--s-4);border-left:1px solid var(--border)}
.uis-choice{height:32px;padding:0 9px;font-size:11px;font-weight:650;color:var(--t2);background:none;border:1px solid transparent;border-radius:var(--radius-s);cursor:pointer}
.uis-choice:hover{color:var(--t0);background:var(--bg-2)}
.uis-choice--on{color:var(--t0);background:var(--bg-2);border-color:var(--border)}
.uis-command-actions{display:flex;align-items:center;gap:var(--s-2);margin-left:auto}

.uis-error,.uis-plan-note,.uis-warnings{margin:var(--s-4) var(--page-inline) 0;padding:var(--s-3) var(--s-4);font-size:12px;line-height:1.5;border:1px solid var(--border);border-radius:var(--radius-s)}
.uis-error{color:#A72C2C;background:color-mix(in srgb,#D64545 8%,var(--bg-0));border-color:color-mix(in srgb,#D64545 32%,var(--border))}
.uis-plan-note{color:var(--t1);background:var(--bg-1)}
.uis-warnings{display:flex;align-items:flex-start;gap:var(--s-4);color:var(--t1);background:color-mix(in srgb,#D99B18 7%,var(--bg-0));border-color:color-mix(in srgb,#D99B18 30%,var(--border))}
.uis-warnings>strong{white-space:nowrap}
.uis-warnings ul{display:flex;flex-wrap:wrap;gap:4px var(--s-5);list-style-position:inside}

.uis-section{padding:var(--s-7) var(--page-inline) 0}
.uis-section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--s-6);margin-bottom:var(--s-5)}
.uis-section-head>div:first-child{min-width:0}
.uis-section-head h2{font-size:clamp(20px,2.2vw,30px);line-height:1.12;letter-spacing:-.025em}
.uis-section-head>p{max-width:58ch;font-size:12px;line-height:1.5;color:var(--t2)}
.uis-kicker{margin-bottom:6px;font-size:9px;font-weight:750;letter-spacing:.12em;text-transform:uppercase;color:var(--t2)}

.uis-matrix-wrap{width:100%;min-width:0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}
.uis-matrix{min-width:0}
.uis-matrix-head,.uis-matrix-row{display:grid;grid-template-columns:minmax(104px,.75fr) repeat(9,minmax(0,1fr))}
.uis-matrix-head{min-height:34px;align-items:center;font-size:9px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--t2);background:var(--bg-1);border-bottom:1px solid var(--border)}
.uis-matrix-head>span{text-align:center}
.uis-matrix-head>span:first-child{padding-left:var(--s-3);text-align:left}
.uis-matrix-row{min-height:88px;border-bottom:1px solid var(--border)}
.uis-matrix-row:last-child{border-bottom:0}
.uis-rowhead{display:flex;align-items:center;padding:var(--s-3);background:var(--bg-0);border-right:1px solid var(--border)}
.uis-row-label{font-size:12px;font-weight:700}
.uis-disclosure{display:none}
.uis-row-cells{display:contents}
.uis-cell{position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;min-width:0;padding:var(--s-3);text-align:left;color:var(--uis-ink);background:var(--uis-swatch);border:0;border-right:1px solid color-mix(in srgb,var(--uis-ink) 16%,transparent);cursor:pointer;touch-action:manipulation;transition:filter var(--dur-1) var(--ease-standard),box-shadow var(--dur-2) var(--ease-standard)}
.uis-cell:last-child{border-right:0}
.uis-cell:hover{filter:saturate(1.06) brightness(1.03)}
.uis-cell:focus-visible{z-index:2;outline:3px solid var(--uis-ink);outline-offset:-5px}
.uis-cell[aria-selected="true"]{box-shadow:inset 0 -4px 0 var(--uis-ink)}
.uis-cell-step{font-size:9px;font-weight:750;letter-spacing:.08em}
.uis-cell-hex{margin-top:3px;font-family:var(--mono);font-size:10px;font-weight:650}
.uis-cell-limit{position:absolute;top:7px;right:7px;display:grid;place-items:center;width:17px;height:17px;font-size:10px;font-weight:800;color:var(--uis-ink);border:1px solid currentColor;border-radius:50%}

.uis-detail{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,2.2fr);gap:var(--s-6);padding:var(--s-5);background:var(--bg-1);border-bottom:1px solid var(--border)}
.uis-detail-ident{display:flex;align-items:center;gap:var(--s-3);align-self:start}
.uis-detail-ident>div{flex:1;min-width:0}
.uis-detail-ident p{font-size:11px;font-weight:650;color:var(--t2)}
.uis-detail-ident strong{font-family:var(--mono);font-size:14px}
.uis-detail-chip{width:40px;height:40px;flex:0 0 auto;background:var(--uis-swatch);border:1px solid var(--border);border-radius:var(--radius-s)}
.uis-detail-grid{display:grid;grid-template-columns:.8fr 1.25fr 1.2fr;gap:var(--s-5)}
.uis-detail-label{margin-bottom:var(--s-2);font-size:9px;font-weight:750;letter-spacing:.1em;text-transform:uppercase;color:var(--t2)}
.uis-evidence dl{display:grid;gap:5px}
.uis-evidence dl>div{display:flex;justify-content:space-between;gap:var(--s-3);font-size:11px}
.uis-evidence dt{color:var(--t2)}
.uis-evidence dd{font-family:var(--mono);font-weight:650;color:var(--t0)}
.uis-pass-list{display:grid;grid-template-columns:1fr 1fr;gap:5px}
.uis-pass{display:flex;align-items:center;gap:5px;font-size:10px;font-weight:650}
.uis-pass>span{display:grid;place-items:center;width:16px;height:16px;border:1px solid currentColor;border-radius:50%}
.uis-pass--yes{color:#237A4B}
.uis-pass--no{color:#B23838}
.uis-hct-label{display:flex;align-items:center;justify-content:space-between;gap:var(--s-2);margin-bottom:var(--s-2)}
.uis-hct-label .uis-detail-label{margin:0}
.uis-hct-label .uis-help-button{height:24px;padding:0 7px;font-size:9px}
.uis-hct-evidence>p:not(.uis-detail-label){font-size:11px;line-height:1.5;color:var(--t1)}
.uis-limit-note{margin-top:var(--s-2);font-size:10px!important;color:#8B5C08!important}

.uis-role-maps{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--border)}
.uis-role-map{min-width:0;padding:var(--s-5)}
.uis-role-map+article{border-left:1px solid var(--border)}
.uis-role-map h3{margin-bottom:var(--s-4);font-size:14px}
.uis-role-map dl{display:grid;grid-template-columns:1fr 1fr;gap:0 var(--s-4)}
.uis-role-map dl>div{display:flex;align-items:center;justify-content:space-between;gap:var(--s-3);padding:7px 0;font-size:10px;border-bottom:1px solid var(--border)}
.uis-role-map dt{font-weight:650;color:var(--t1)}
.uis-role-map dd{display:flex;align-items:center;gap:6px;min-width:0;font-family:var(--mono);font-size:9px;color:var(--t2);white-space:nowrap}
.uis-role-dot{width:12px;height:12px;flex:0 0 auto;background:var(--uis-role);border:1px solid var(--border);border-radius:50%}
.uis-role-pairs{display:grid;grid-template-columns:1fr 1fr;gap:5px var(--s-4);margin-top:var(--s-4)}
.uis-role-pairs p{display:flex;gap:6px;font-size:10px;color:var(--t2)}
.uis-role-pairs p>span{font-weight:800;color:#237A4B}

.uis-segmented{display:inline-flex;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.uis-segmented button{height:30px;padding:0 10px;font-size:11px;font-weight:650;color:var(--t2);background:none;border:0;border-radius:var(--radius-xs);cursor:pointer}
.uis-segmented button:hover{color:var(--t0)}
.uis-segmented .uis-segmented-on{color:var(--t0);background:var(--card);box-shadow:var(--shadow-xs)}
.uis-lab{display:grid;grid-template-columns:minmax(0,1fr);border:1px solid var(--border)}
.uis-lab--side{grid-template-columns:1fr 1fr}
.uis-lab--side>.uis-lab-canvas+div{border-left:1px solid var(--border)}
.uis-lab-canvas{min-width:0;color:var(--uis-text);background:var(--uis-canvas)}
.uis-lab-bar{display:flex;justify-content:space-between;padding:9px var(--s-4);font-size:9px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--uis-text-muted);background:var(--uis-surface);border-bottom:1px solid var(--uis-border)}
.uis-lab-content{display:grid;gap:var(--s-5);padding:var(--s-5)}
.uis-lab-block h3{margin-bottom:var(--s-3);font-size:11px;color:var(--uis-text-muted)}
.uis-button-states{display:flex;flex-wrap:wrap;gap:var(--s-2)}
.uis-demo-button{min-height:34px;padding:0 12px;font-size:11px;font-weight:700;color:var(--uis-on-primary);background:var(--uis-primary);border:1px solid transparent;border-radius:var(--radius-s)}
.uis-demo-button--hover{filter:brightness(.92)}
.uis-demo-button--pressed{filter:brightness(.82);transform:translateY(1px)}
.uis-demo-button--focus{outline:3px solid var(--uis-on-canvas);outline-offset:2px}
.uis-demo-button:disabled{opacity:.45}
.uis-alert-list{display:grid;grid-template-columns:1fr 1fr;gap:var(--s-2)}
.uis-alert{display:flex;align-items:flex-start;gap:var(--s-2);padding:var(--s-3);font-size:10px;line-height:1.4;border:1px solid currentColor;border-radius:var(--radius-s)}
.uis-alert>span:first-child{display:grid;place-items:center;width:17px;height:17px;flex:0 0 auto;font-weight:800;border:1px solid currentColor;border-radius:50%}
.uis-alert--success{color:var(--uis-on-success-container);background:var(--uis-success-container)}
.uis-alert--warning{color:var(--uis-on-warning-container);background:var(--uis-warning-container)}
.uis-alert--error{color:var(--uis-on-error-container);background:var(--uis-error-container)}
.uis-alert--information{color:var(--uis-on-information-container);background:var(--uis-information-container)}
.uis-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--s-3)}
.uis-form-grid label{display:flex;flex-direction:column;gap:5px;font-size:10px;color:var(--uis-text-muted)}
.uis-form-grid input{height:34px;padding:0 9px;font:inherit;color:var(--uis-text);background:var(--uis-surface);border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-form-grid .uis-input--focus{outline:2px solid var(--uis-primary);outline-offset:1px}
.uis-form-grid .uis-input--invalid{border-color:var(--uis-error)}
.uis-form-grid small{display:flex;gap:4px;color:var(--uis-error)}
.uis-demo-card{grid-column:1/-1;padding:var(--s-4);color:var(--uis-text);background:var(--uis-surface-raised);border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-demo-card-kicker{display:block;margin-bottom:5px;font-size:8px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--uis-text-muted)}
.uis-demo-card strong{font-size:13px}
.uis-demo-card p{margin-top:4px;font-size:10px;line-height:1.45;color:var(--uis-text-muted)}

.uis-scene-tabs{display:flex;gap:4px;margin-bottom:var(--s-3);overflow-x:auto;scrollbar-width:thin}
.uis-scene-tab{flex:0 0 auto;min-height:44px;padding:8px 12px;font-size:10px;font-weight:650;color:var(--t2);background:none;border:1px solid transparent;border-radius:var(--radius-s);cursor:pointer}
.uis-scene-tab:hover{color:var(--t0);background:var(--bg-2)}
.uis-scene-tab--on{color:var(--t0);background:var(--bg-2);border-color:var(--border)}
.uis-scene-preview{display:grid;grid-template-columns:150px 1fr;min-height:420px;color:var(--uis-text);background:var(--uis-canvas);border:1px solid var(--border)}
.uis-scene-nav{display:flex;flex-direction:column;gap:var(--s-4);padding:var(--s-5);background:var(--uis-surface);border-right:1px solid var(--uis-border)}
.uis-scene-nav>span:not(.uis-scene-logo){width:78%;height:8px;background:var(--uis-border);border-radius:var(--radius-xs)}
.uis-scene-logo{width:30px;height:30px;margin-bottom:var(--s-4);background:var(--uis-primary);border-radius:var(--radius-s)}
.uis-scene-main{padding:var(--s-6)}
.uis-scene-main>header{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--s-5)}
.uis-scene-main header p{font-size:9px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:var(--uis-text-muted)}
.uis-scene-main header h3{margin-top:5px;font-size:24px;color:var(--uis-text)}
.uis-scene-main header span{display:block;margin-top:5px;font-size:11px;color:var(--uis-text-muted)}
.uis-scene-main header button{min-height:36px;padding:0 13px;font-size:11px;font-weight:700;color:var(--uis-on-primary);background:var(--uis-primary);border:0;border-radius:var(--radius-s)}
.uis-scene-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--s-3);margin-top:var(--s-6)}
.uis-scene-stats article,.uis-scene-panel{padding:var(--s-4);background:var(--uis-surface-raised);border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-scene-stats span{font-size:9px;color:var(--uis-text-muted)}
.uis-scene-stats strong{display:block;margin-top:6px;font-size:20px}
.uis-scene-panel{margin-top:var(--s-3)}
.uis-scene-panel>div:first-child{display:flex;justify-content:space-between;gap:var(--s-3);font-size:11px}
.uis-scene-panel>p{margin-top:var(--s-3);font-size:10px;color:var(--uis-text-muted)}
.uis-scene-status{display:flex!important;align-items:center;gap:5px!important;margin:0!important;color:var(--uis-on-success-container)!important}
.uis-scene-status i{width:7px;height:7px;background:var(--uis-success);border-radius:50%}
.uis-scene-lines{display:grid;gap:8px;margin-top:var(--s-5)}
.uis-scene-lines span{height:7px;background:var(--uis-border);border-radius:var(--radius-xs)}
.uis-scene-lines span:nth-child(2){width:84%}
.uis-scene-lines span:nth-child(3){width:62%}

/* Each applied scene is an authored interface structure, not a relabelled
   dashboard. They share only semantic role variables and quiet field chrome. */
.uis-scene-preview{display:block;min-height:420px;overflow:hidden}
.uis-scene-preview button{min-height:44px;padding:0 14px;font-size:11px;font-weight:700;color:var(--uis-on-primary);background:var(--uis-primary);border:0;border-radius:var(--radius-s)}
.uis-scene-preview input{height:40px;padding:0 10px;font:inherit;color:var(--uis-text);background:var(--uis-surface);border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-scene-preview small{font-size:9px;color:var(--uis-text-muted)}
.uis-scene-preview h3{font-size:22px;color:var(--uis-text)}
.uis-scene-preview p{font-size:10px;line-height:1.5;color:var(--uis-text-muted)}

.uis-workspace-scene{display:grid;grid-template-columns:150px 1fr;min-height:420px}
.uis-workspace-scene>aside{display:flex;flex-direction:column;gap:18px;padding:24px 20px;background:var(--uis-surface);border-right:1px solid var(--uis-border)}
.uis-workspace-scene>aside strong{margin-bottom:16px;color:var(--uis-primary)}
.uis-workspace-scene>aside span{font-size:10px;color:var(--uis-text-muted)}
.uis-workspace-scene>main{padding:26px}
.uis-workspace-scene header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}
.uis-workspace-scene header small{text-transform:uppercase;letter-spacing:.09em}
.uis-workspace-progress{display:grid;grid-template-columns:1fr auto;gap:5px;margin-top:24px;padding:14px;background:var(--uis-surface-raised);border:1px solid var(--uis-border);border-radius:var(--radius-s);font-size:10px}
.uis-workspace-progress i{grid-column:1/-1;height:6px;overflow:hidden;background:var(--uis-border);border-radius:99px}
.uis-workspace-progress b{display:block;width:81%;height:100%;background:var(--uis-primary)}
.uis-kanban{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}
.uis-kanban section{padding:12px;background:var(--uis-surface);border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-kanban h4{display:flex;justify-content:space-between;margin-bottom:10px;font-size:10px}
.uis-kanban h4 span{color:var(--uis-text-muted)}
.uis-kanban article{display:grid;gap:4px;padding:10px;margin-top:7px;background:var(--uis-surface-raised);border:1px solid var(--uis-border);border-radius:var(--radius-xs);font-size:9px}

.uis-settings-scene{display:grid;grid-template-columns:190px 1fr;min-height:420px}
.uis-settings-scene>aside{display:flex;flex-direction:column;gap:4px;padding:24px 16px;background:var(--uis-surface);border-right:1px solid var(--uis-border)}
.uis-settings-scene>aside strong{margin:0 8px 18px}
.uis-settings-scene>aside button{justify-content:flex-start;color:var(--uis-text-muted);text-align:left;background:transparent}
.uis-settings-scene>aside .is-active{color:var(--uis-primary);background:var(--uis-primary-container)}
.uis-settings-scene>main{max-width:650px;padding:28px}
.uis-settings-scene header{margin-bottom:22px}
.uis-settings-scene form{display:grid;gap:14px}
.uis-settings-scene form>label{display:grid;gap:6px;font-size:10px;font-weight:650}
.uis-prefix-field{display:flex}
.uis-prefix-field i{display:flex;align-items:center;padding:0 9px;font-style:normal;font-size:9px;color:var(--uis-text-muted);background:var(--uis-surface-raised);border:1px solid var(--uis-border);border-right:0;border-radius:var(--radius-s) 0 0 var(--radius-s)}
.uis-prefix-field input{flex:1;border-radius:0 var(--radius-s) var(--radius-s) 0}
.uis-settings-scene fieldset{padding:12px;border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-settings-scene legend{padding:0 4px;font-size:10px;font-weight:650}
.uis-switch-row{display:flex;align-items:center;justify-content:space-between;gap:14px}
.uis-switch-row span{display:grid;gap:3px;font-size:10px}
.uis-switch-row input{width:44px;height:24px;accent-color:var(--uis-primary)}
.uis-settings-scene form>div:last-child{display:flex;justify-content:flex-end;gap:8px}
.uis-settings-scene .uis-secondary-action{color:var(--uis-text);background:transparent;border:1px solid var(--uis-border)}

.uis-commerce-scene>header{display:flex;justify-content:space-between;padding:15px 24px;background:var(--uis-surface);border-bottom:1px solid var(--uis-border);font-size:10px}
.uis-commerce-scene>header span{color:var(--uis-text-muted)}
.uis-checkout-grid{display:grid;grid-template-columns:1.15fr .85fr;max-width:940px;margin:auto}
.uis-checkout-grid>main,.uis-checkout-grid>aside{padding:28px}
.uis-checkout-grid>main{display:grid;gap:13px}
.uis-checkout-grid>main>div{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.uis-checkout-grid label{display:grid;gap:5px;font-size:9px}
.uis-payment-choice{display:flex!important;align-items:center;padding:10px;border:1px solid var(--uis-primary)!important;border-radius:var(--radius-s)}
.uis-payment-choice input{width:20px;height:20px;accent-color:var(--uis-primary)}
.uis-payment-choice span{display:grid;flex:1;gap:2px}
.uis-checkout-grid>aside{background:var(--uis-surface);border-left:1px solid var(--uis-border)}
.uis-checkout-grid>aside article{display:flex;align-items:center;gap:9px;padding:12px 0;border-bottom:1px solid var(--uis-border);font-size:9px}
.uis-checkout-grid>aside article i{width:34px;height:34px;background:var(--uis-primary-container);border-radius:var(--radius-xs)}
.uis-checkout-grid>aside article span{display:grid;flex:1;gap:2px}
.uis-checkout-grid dl{display:grid;gap:8px;padding:14px 0;font-size:10px}
.uis-checkout-grid dl div{display:flex;justify-content:space-between}
.uis-checkout-grid dl div:last-child{padding-top:8px;font-weight:750;border-top:1px solid var(--uis-border)}
.uis-checkout-grid>aside>button{width:100%}

.uis-docs-scene>header{display:flex;align-items:center;gap:18px;padding:12px 20px;background:var(--uis-surface);border-bottom:1px solid var(--uis-border)}
.uis-docs-scene>header strong{color:var(--uis-primary)}
.uis-docs-scene>header label{display:flex;align-items:center;flex:1;font-size:0}
.uis-docs-scene>header input{width:min(360px,100%);margin:auto}
.uis-docs-scene>header span{font-size:9px;color:var(--uis-text-muted)}
.uis-docs-scene>div{display:grid;grid-template-columns:170px minmax(0,1fr) 140px}
.uis-docs-scene nav,.uis-docs-scene>div>aside{display:flex;flex-direction:column;gap:10px;padding:20px;background:var(--uis-surface);font-size:9px}
.uis-docs-scene nav{border-right:1px solid var(--uis-border)}
.uis-docs-scene nav strong{margin-top:8px}
.uis-docs-scene a{color:var(--uis-text-muted)}
.uis-docs-scene a.is-active{font-weight:700;color:var(--uis-primary)}
.uis-docs-scene>div>main{padding:28px}
.uis-docs-scene>div>main>p{max-width:62ch;margin:8px 0 20px}
.uis-docs-scene h4{margin:18px 0 8px;font-size:11px}
.uis-docs-scene pre{position:relative;padding:16px;font-size:10px;color:var(--uis-on-canvas);background:var(--uis-canvas);border:1px solid var(--uis-border);border-radius:var(--radius-s)}
.uis-docs-scene pre button{position:absolute;top:6px;right:6px;min-height:32px}
