.tsc-row-sub{font-family:var(--mono);font-size:9px;color:var(--t3)}
.tsc-row-text{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--t0);font-family:var(--tsc-body-ff);font-size:var(--tsc-fs);font-weight:var(--tsc-body-fw);line-height:var(--tsc-lh);letter-spacing:var(--tsc-body-ls)}
.tsc-row-text--heading{font-family:var(--tsc-heading-ff);font-weight:var(--tsc-heading-fw);letter-spacing:var(--tsc-heading-ls)}
