.tsc-view-switch{display:flex;gap:3px;padding:3px;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius-s)}
.tsc-view-btn{min-height:34px;padding:7px 11px;font-size:10.5px;font-weight:600;color:var(--t1);background:transparent;border:1px solid transparent;border-radius:var(--radius-xs);cursor:pointer;transition:background var(--t),border-color var(--t),color var(--t)}
.tsc-view-btn:hover{color:var(--t0)}
.tsc-view-btn--on{color:var(--t0);background:var(--card);border-color:var(--border);box-shadow:var(--shadow-xs)}
.tsc-view-btn:focus-visible,.tsc-fmt-btn:focus-visible,.tsc-copy-all:focus-visible,.tsc-copy-primary:focus-visible,.tsc-reset:focus-visible,.tsc-handoff:focus-visible,.tsc-weight:focus-visible{outline:2px solid var(--brand);outline-offset:2px}
.tsc-article{padding:clamp(20px,3vw,36px);border:1px solid var(--border);border-radius:var(--radius-l);background:var(--bg-1)}
.tsc-article-eyebrow{font-family:var(--mono);font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-strong)}
.tsc-article-h1,.tsc-article-h2{margin:14px 0 8px;color:var(--t0);font-family:var(--tsc-heading-ff);font-size:var(--tsc-fs);font-weight:var(--tsc-heading-fw);line-height:var(--tsc-lh);letter-spacing:var(--tsc-heading-ls)}
.tsc-article-lede,.tsc-article-body,.tsc-article-small{margin:0 0 14px;max-width:64ch;color:var(--t1);font-family:var(--tsc-body-ff);font-size:var(--tsc-fs);font-weight:var(--tsc-body-fw);line-height:var(--tsc-lh);letter-spacing:var(--tsc-body-ls)}
