.tsc-more-link{font-size:11px;font-weight:600;color:var(--t1);text-decoration:none;transition:color var(--t)}
.tsc-more-link:hover{color:var(--accent-strong)}
.tsc-more-link:focus-visible{outline:2px solid var(--brand);outline-offset:3px}
@media(max-width:980px){
